


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






COMMENT ON SCHEMA "public" IS 'standard public schema';



CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "public";






CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";






CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";






CREATE OR REPLACE FUNCTION "public"."_maria_conf_campos"("p_tabela" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_tabela
    WHEN 'contas_pagar' THEN ARRAY['descricao','unidade','valor','data_lancamento','data_vencimento','competencia','status','plano_conta_id','conta_pagadora_id','metodo_pagamento','tipo_lancamento','created_at']
    WHEN 'maria_conferencias_lancamento' THEN ARRAY['status','aprovado_at','chat_id','created_at']
    WHEN 'maria_conferencia_lancamento_itens' THEN ARRAY['conta_pagar_id','status','plano_codigo','plano_origem','created_at']
    WHEN 'maria_fluxo_caixa_eventos' THEN ARRAY['status','tipo_evento','direcao','unidade','conta_pagar_id','data_operacional','created_at']
    ELSE ARRAY[]::text[] END;
$$;


ALTER FUNCTION "public"."_maria_conf_campos"("p_tabela" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_maria_conf_op"("p_op" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_op WHEN 'eq' THEN '=' WHEN 'neq' THEN '<>' WHEN 'gte' THEN '>=' WHEN 'lte' THEN '<=' ELSE NULL END;
$$;


ALTER FUNCTION "public"."_maria_conf_op"("p_op" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_maria_conf_win"("p_tabela" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE p_tabela
    WHEN 'contas_pagar' THEN 'data_lancamento'
    WHEN 'maria_fluxo_caixa_eventos' THEN 'data_operacional'
    WHEN 'maria_conferencias_lancamento' THEN 'created_at'
    WHEN 'maria_conferencia_lancamento_itens' THEN 'created_at'
    ELSE NULL END;
$$;


ALTER FUNCTION "public"."_maria_conf_win"("p_tabela" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_ajustar_data"("p_data" "date", "p_regra" "text") RETURNS "date"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare v date := p_data;
begin
  if p_data is null then return null; end if;
  if p_regra = 'proximo_dia_util' then
    while extract(isodow from v) in (6, 7) loop v := v + 1; end loop;     -- sab/dom -> proxima segunda
  elsif p_regra = 'dia_util_anterior' then
    while extract(isodow from v) in (6, 7) loop v := v - 1; end loop;     -- sab/dom -> sexta anterior
  end if;                                                                 -- 'manter' (ou nulo): nao mexe
  -- agenda_feriados entra AQUI (spec §5.1): apos o ajuste de fim de semana, repetir o mesmo laco
  -- enquanto v for feriado, na mesma direcao da regra.
  return v;
end $$;


ALTER FUNCTION "public"."agenda_ajustar_data"("p_data" "date", "p_regra" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_brl"("p" numeric) RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $_$
  select 'R$ ' || replace(replace(replace(
           to_char(coalesce(p, 0), 'FM999,999,999,990.00'), ',', '#'), '.', ','), '#', '.');
$_$;


ALTER FUNCTION "public"."agenda_brl"("p" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_destinatarios"("p_tarefa_id" "uuid") RETURNS TABLE("user_id" "uuid", "nome" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v public.tarefas%rowtype;
begin
  select * into v from public.tarefas where id = p_tarefa_id;
  if not found then return; end if;

  if v.responsavel_id is not null then
    return query select p.id, p.nome from public.user_profiles p where p.id = v.responsavel_id;
    return;
  end if;

  if v.lista_id is not null
     and exists (select 1 from public.tarefas_listas_membros m where m.lista_id = v.lista_id) then
    return query
      select p.id, p.nome
        from public.tarefas_listas_membros m
        join public.user_profiles p on p.id = m.user_id
       where m.lista_id = v.lista_id
       order by p.nome;
    return;
  end if;

  if v.created_by is not null then
    return query select p.id, p.nome from public.user_profiles p where p.id = v.created_by;
  end if;
end $$;


ALTER FUNCTION "public"."agenda_destinatarios"("p_tarefa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_lembretes_devidos"("p_ate" timestamp with time zone) RETURNS TABLE("tarefa_id" "uuid", "titulo" "text", "descricao" "text", "prioridade" "text", "categoria" "text", "vencimento_em" timestamp with time zone, "momento" timestamp with time zone, "user_id" "uuid", "nome" "text", "whatsapp_numero" "text", "whatsapp_ativo" boolean, "agenda_lembrete_tarefas_ativo" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select t.id, t.titulo, t.descricao, t.prioridade, t.categoria, t.vencimento_em,
         public.agenda_momento_lembrete(
           t.vencimento_em, t.dia_inteiro,
           coalesce(t.lembrete_minutos[1], nc.lembrete_padrao_minutos, 30)
         ) as momento,
         d.user_id, d.nome,
         nc.whatsapp_numero, coalesce(nc.whatsapp_ativo, false), coalesce(nc.agenda_lembrete_tarefas_ativo, true)
    from public.tarefas t
    cross join lateral public.agenda_destinatarios(t.id) d
    left join public.notificacao_config nc on nc.user_id = d.user_id
   where t.vencimento_em is not null
     and coalesce(t.dia_inteiro, false) = false
     and t.status in ('pendente', 'em_andamento')
     and t.vencimento_em <= p_ate + coalesce(t.lembrete_minutos[1], nc.lembrete_padrao_minutos, 30) * interval '1 minute'
     and t.vencimento_em >= now() - interval '12 hours'
   order by t.vencimento_em, d.nome;
$$;


ALTER FUNCTION "public"."agenda_lembretes_devidos"("p_ate" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_materializar_corrente_e_proximo"("p_origem" "text" DEFAULT 'cron'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_a jsonb; v_b jsonb;
begin
  v_a := public.agenda_rotinas_materializar(date_trunc('month', v_hoje)::date, p_origem);
  v_b := public.agenda_rotinas_materializar((date_trunc('month', v_hoje) + interval '1 month')::date, p_origem);
  delete from public.agenda_materializacoes where executado_em < now() - interval '60 days';
  return jsonb_build_object('hoje', v_hoje, 'corrente', v_a, 'proximo', v_b);
end $$;


ALTER FUNCTION "public"."agenda_materializar_corrente_e_proximo"("p_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_momento_lembrete"("p_vencimento" timestamp with time zone, "p_dia_inteiro" boolean, "p_minutos" integer) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_local timestamp;
  v_dia date;
  v_hora time;
  v_ini constant time := time '07:30';
  v_fim constant time := time '21:00';
begin
  if p_vencimento is null or coalesce(p_dia_inteiro, false) then
    return null;
  end if;
  v_local := (p_vencimento at time zone 'America/Sao_Paulo')
             - make_interval(mins => greatest(coalesce(p_minutos, 0), 0));
  v_dia := v_local::date;
  v_hora := v_local::time;
  if v_hora < v_ini then
    v_local := v_dia + v_ini;
  elsif v_hora > v_fim then
    v_local := (v_dia + 1) + v_ini;
  end if;
  return v_local at time zone 'America/Sao_Paulo';
end $$;


ALTER FUNCTION "public"."agenda_momento_lembrete"("p_vencimento" timestamp with time zone, "p_dia_inteiro" boolean, "p_minutos" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_resolve_dia"("p_competencia" "date", "p_dia_mes" integer, "p_ultimo_dia" boolean) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when coalesce(p_ultimo_dia, false)
      then (date_trunc('month', p_competencia)::date + interval '1 month' - interval '1 day')::date
    else least(
      date_trunc('month', p_competencia)::date + (greatest(coalesce(p_dia_mes, 1), 1) - 1),
      (date_trunc('month', p_competencia)::date + interval '1 month' - interval '1 day')::date
    )
  end;
$$;


ALTER FUNCTION "public"."agenda_resolve_dia"("p_competencia" "date", "p_dia_mes" integer, "p_ultimo_dia" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_resumo_usuario"("p_user_id" "uuid", "p_data" "date", "p_dias" integer DEFAULT 1) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ini timestamptz := (p_data::timestamp) at time zone 'America/Sao_Paulo';
  v_fim timestamptz := ((p_data + greatest(coalesce(p_dias, 1), 1))::timestamp) at time zone 'America/Sao_Paulo';
  v_itens jsonb; v_atr jsonb; v_pagar jsonb; v_pagar_atr jsonb; v_nome text;
  v_atr_total integer;
begin
  select nome into v_nome from public.user_profiles where id = p_user_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'titulo', t.titulo, 'prioridade', t.prioridade,
           'vencimento_em', t.vencimento_em, 'dia_inteiro', t.dia_inteiro, 'parent_id', t.parent_id
         ) order by t.vencimento_em, t.titulo), '[]'::jsonb)
    into v_itens
    from public.tarefas t
   where t.status in ('pendente', 'em_andamento')
     and t.vencimento_em >= v_ini and t.vencimento_em < v_fim
     and coalesce(t.vinculo_tipo, '') <> 'conta_pagar'
     and exists (select 1 from public.agenda_destinatarios(t.id) d where d.user_id = p_user_id);

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'titulo', t.titulo, 'prioridade', t.prioridade, 'vencimento_em', t.vencimento_em
         ) order by t.vencimento_em), '[]'::jsonb)
    into v_atr
    from public.tarefas t
   where t.status in ('pendente', 'em_andamento')
     and t.vencimento_em < v_ini
     and t.vencimento_em >= v_ini - interval '30 days'
     and coalesce(t.vinculo_tipo, '') <> 'conta_pagar'
     and exists (select 1 from public.agenda_destinatarios(t.id) d where d.user_id = p_user_id);

  select count(*)
    into v_atr_total
    from public.tarefas t
   where t.status in ('pendente', 'em_andamento')
     and t.vencimento_em < v_ini
     and coalesce(t.vinculo_tipo, '') <> 'conta_pagar'
     and exists (select 1 from public.agenda_destinatarios(t.id) d where d.user_id = p_user_id);

  select jsonb_build_object('n', count(*), 'total', coalesce(sum(c.valor), 0))
    into v_pagar
    from public.tarefas t join public.contas_pagar c on c.id = t.vinculo_id
   where t.vinculo_tipo = 'conta_pagar' and t.status in ('pendente', 'em_andamento')
     and t.vencimento_em >= v_ini and t.vencimento_em < v_fim
     and exists (select 1 from public.agenda_destinatarios(t.id) d where d.user_id = p_user_id);

  select jsonb_build_object('n', count(*), 'total', coalesce(sum(c.valor), 0))
    into v_pagar_atr
    from public.tarefas t join public.contas_pagar c on c.id = t.vinculo_id
   where t.vinculo_tipo = 'conta_pagar' and t.status in ('pendente', 'em_andamento')
     and t.vencimento_em < v_ini
     and exists (select 1 from public.agenda_destinatarios(t.id) d where d.user_id = p_user_id);

  return jsonb_build_object(
    'nome', v_nome, 'itens', v_itens, 'atrasadas', v_atr, 'atrasadas_total', v_atr_total,
    'pagar', v_pagar, 'pagar_atrasadas', v_pagar_atr
  );
end $$;


ALTER FUNCTION "public"."agenda_resumo_usuario"("p_user_id" "uuid", "p_data" "date", "p_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_rotinas_guard_parent"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare v_pai public.agenda_rotinas%rowtype;
begin
  -- Vale pro pai (parent_rotina_id null) e pra filha: quem tem filhas esta preso a sua lista.
  if tg_op = 'UPDATE' and new.lista_id is distinct from old.lista_id
     and exists (select 1 from public.agenda_rotinas f where f.parent_rotina_id = new.id) then
    raise exception 'rotina com filhas nao muda de lista: encerre e crie outra.' using errcode = 'P0001';
  end if;
  if new.parent_rotina_id is null then return new; end if;
  if new.parent_rotina_id = new.id then
    raise exception 'rotina nao pode ser pai de si mesma.' using errcode = 'P0001';
  end if;
  select * into v_pai from public.agenda_rotinas where id = new.parent_rotina_id;
  if not found then
    raise exception 'rotina pai nao encontrada.' using errcode = 'P0001';
  end if;
  if v_pai.parent_rotina_id is not null then
    raise exception 'profundidade maxima 1: filha nao pode ter filha.' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.agenda_rotinas f where f.parent_rotina_id = new.id) then
    raise exception 'profundidade maxima 1: rotina com filhas nao pode virar filha.' using errcode = 'P0001';
  end if;
  if v_pai.lista_id <> new.lista_id then
    raise exception 'filha deve estar na mesma lista do pai.' using errcode = 'P0001';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."agenda_rotinas_guard_parent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_rotinas_materializar"("p_competencia" "date", "p_origem" "text" DEFAULT 'rpc'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ini timestamptz := clock_timestamp();
  v_comp date;
  v_pai public.agenda_rotinas%rowtype;
  v_filha public.agenda_rotinas%rowtype;
  v_nominal_pai date; v_nominal_f date; v_nominal_max date; v_data date; v_venc timestamptz;
  v_pai_id uuid; v_pai_status text;
  v_pais int := 0; v_filhas int := 0; v_pulados int := 0; v_ins int := 0;
  v_pais_ret int; v_filhas_ret int; v_pulados_ret int;      -- retrato dos contadores antes de cada pai
  v_erros jsonb := '[]'::jsonb;
begin
  if p_competencia is null then
    raise exception 'competencia obrigatoria.' using errcode = '22023';
  end if;
  if coalesce(p_origem, 'rpc') not in ('cron','rpc','sync','manual') then
    raise exception 'origem invalida: %.', p_origem using errcode = '22023';
  end if;
  v_comp := date_trunc('month', p_competencia)::date;

  for v_pai in
    select * from public.agenda_rotinas
     where parent_rotina_id is null and status = 'ativa'
     order by ordem, titulo
  loop
    begin
      -- retrato: o handler abaixo desfaz as LINHAS deste pai, mas nao as variaveis; restauramos na mao.
      v_pais_ret := v_pais; v_filhas_ret := v_filhas; v_pulados_ret := v_pulados;

      v_nominal_pai := public.agenda_resolve_dia(v_comp, v_pai.dia_mes, v_pai.ultimo_dia);
      if v_nominal_pai < v_pai.vigencia_inicio then          -- vigencia contra a NOMINAL
        v_pulados := v_pulados + 1;
        continue;
      end if;

      -- vencimento do pai = max(nominal pai, nominais das filhas elegiveis) — dia_mes do pai e piso
      v_nominal_max := v_nominal_pai;
      for v_filha in select * from public.agenda_rotinas where parent_rotina_id = v_pai.id and status = 'ativa' loop
        v_nominal_f := public.agenda_resolve_dia(v_comp, v_filha.dia_mes, v_filha.ultimo_dia);
        if v_nominal_f >= v_filha.vigencia_inicio and v_nominal_f > v_nominal_max then
          v_nominal_max := v_nominal_f;
        end if;
      end loop;

      v_data := public.agenda_ajustar_data(v_nominal_max, v_pai.se_cair_fim_de_semana);   -- pode sair do mes
      v_venc := (v_data::timestamp + v_pai.hora) at time zone 'America/Sao_Paulo';

      insert into public.tarefas
        (titulo, descricao, lista_id, categoria, prioridade, tags, vencimento_em, dia_inteiro, status,
         rotina_id, competencia, responsavel_id, lembrete_minutos, ordem)
      values
        (v_pai.titulo, v_pai.descricao, v_pai.lista_id, v_pai.categoria, v_pai.prioridade, array['rotina'],
         v_venc, v_pai.dia_inteiro, 'pendente', v_pai.id, v_comp, v_pai.responsavel_id, array[30], v_pai.ordem)
      on conflict (rotina_id, competencia) do nothing;
      get diagnostics v_ins = row_count;
      v_pais := v_pais + v_ins;

      select id, status into v_pai_id, v_pai_status
        from public.tarefas where rotina_id = v_pai.id and competencia = v_comp;

      if v_pai_status in ('concluida','cancelada') then         -- pai fechado nao ganha filha nova
        select count(*) into v_ins
          from public.agenda_rotinas f
         where f.parent_rotina_id = v_pai.id and f.status = 'ativa'
           and not exists (select 1 from public.tarefas t where t.rotina_id = f.id and t.competencia = v_comp);
        v_pulados := v_pulados + v_ins;
        continue;
      end if;

      for v_filha in
        select * from public.agenda_rotinas
         where parent_rotina_id = v_pai.id and status = 'ativa'
         order by ordem, titulo
      loop
        v_nominal_f := public.agenda_resolve_dia(v_comp, v_filha.dia_mes, v_filha.ultimo_dia);
        if v_nominal_f < v_filha.vigencia_inicio then          -- vigencia por linha
          v_pulados := v_pulados + 1;
          continue;
        end if;
        v_data := public.agenda_ajustar_data(v_nominal_f, v_filha.se_cair_fim_de_semana);
        v_venc := (v_data::timestamp + v_filha.hora) at time zone 'America/Sao_Paulo';
        insert into public.tarefas
          (titulo, descricao, lista_id, categoria, prioridade, tags, vencimento_em, dia_inteiro, status,
           rotina_id, competencia, parent_id, responsavel_id, lembrete_minutos, ordem)
        values
          (v_filha.titulo, v_filha.descricao, v_filha.lista_id, v_filha.categoria, v_filha.prioridade, array['rotina'],
           v_venc, v_filha.dia_inteiro, 'pendente', v_filha.id, v_comp, v_pai_id, v_filha.responsavel_id, array[30], v_filha.ordem)
        on conflict (rotina_id, competencia) do nothing;
        get diagnostics v_ins = row_count;
        v_filhas := v_filhas + v_ins;
      end loop;
    exception when others then
      -- as linhas deste pai ja voltaram com a subtransacao; os contadores voltam aqui.
      v_pais := v_pais_ret; v_filhas := v_filhas_ret; v_pulados := v_pulados_ret;
      v_erros := v_erros || jsonb_build_object('rotina_id', v_pai.id, 'titulo', v_pai.titulo, 'erro', sqlerrm, 'sqlstate', sqlstate);
      raise warning 'agenda_rotinas_materializar: % (%) — %', v_pai.titulo, v_pai.id, sqlerrm;
    end;
  end loop;

  insert into public.agenda_materializacoes (origem, competencia, duracao_ms, pais_criados, filhas_criadas, pulados, erros)
  values (coalesce(p_origem, 'rpc'), v_comp, (extract(epoch from clock_timestamp() - v_ini) * 1000)::int, v_pais, v_filhas, v_pulados, v_erros);

  return jsonb_build_object('competencia', v_comp, 'pais_criados', v_pais, 'filhas_criadas', v_filhas, 'pulados', v_pulados, 'erros', v_erros);
end $$;


ALTER FUNCTION "public"."agenda_rotinas_materializar"("p_competencia" "date", "p_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agenda_sync_contas_pagar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ini  timestamptz := clock_timestamp();
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_ini_janela date := v_hoje - 90;
  v_fim  date := v_hoje + 45;
  v_lista uuid;
  v_ins int := 0; v_upd int := 0; v_del int := 0;
begin
  -- Lista Financeiro por nome (nao-smart), criada se faltar — mesmo criterio de ensureListByName.
  select id into v_lista from public.tarefas_listas
   where lower(nome) = 'financeiro' and coalesce(is_smart, false) = false order by ordem limit 1;
  if v_lista is null then
    insert into public.tarefas_listas (nome, cor, icone, ordem, is_smart, is_default)
    values ('Financeiro', '#8b5cf6', '💰', (select coalesce(max(ordem), 0) + 10 from public.tarefas_listas), false, false)
    returning id into v_lista;
  end if;

  with contas as (
    select c.id, c.descricao, c.unidade, c.valor, c.data_vencimento, c.status,
           c.data_pagamento, c.metodo_pagamento,
           pc.codigo as pc_codigo, pc.nome as pc_nome, cc.nome as cc_nome,
           (c.data_vencimento - v_hoje) as dd
      from public.contas_pagar c
      left join public.plano_contas pc on pc.id = c.plano_conta_id
      left join public.centros_custo cc on cc.id = c.centro_custo_id
     where coalesce(c.status,'') not in ('cancelado','finalizado')
       and not c.debito_automatico                                  -- v6: sem espelho para debito automatico
       and c.data_vencimento between v_ini_janela and v_fim
  ), src as (
    select id as vinculo_id,
           'Pagar: ' || descricao as titulo,
           concat_ws(E'\n',
             case when pc_codigo is not null and pc_nome is not null then 'Plano: ' || pc_codigo || ' ' || pc_nome end,
             'Valor: ' || public.agenda_brl(valor),
             case when cc_nome is not null then 'Centro de custo: ' || cc_nome
                  when unidade is not null then 'Centro de custo: ' || upper(unidade) end,
             case when metodo_pagamento is not null then 'Metodo: ' || metodo_pagamento end,
             'Origem: Contas a Pagar (tarefa automatica)'
           ) as descricao,
           case when status = 'pago' then 'baixa'
                when dd < 0 then 'urgente'
                when dd = 0 then 'alta'
                when dd <= 3 then 'media'
                else 'baixa' end as prioridade,
           case when status = 'pago' then 'concluida' else 'pendente' end as st,
           case when status = 'pago' then
             (coalesce((data_pagamento at time zone 'UTC')::date,
                       (now() at time zone 'America/Sao_Paulo')::date)::timestamp + time '12:00') at time zone 'America/Sao_Paulo'
           end as data_conclusao,
           ((data_vencimento::timestamp + time '09:00') at time zone 'America/Sao_Paulo') as vencimento_em,
           unidade
      from contas
  ), upserted as (
    insert into public.tarefas
      (titulo, descricao, lista_id, categoria, prioridade, tags, unidade, vencimento_em, dia_inteiro,
       status, data_conclusao, vinculo_tipo, vinculo_id, lembrete_minutos, ordem)
    select titulo, descricao, v_lista, 'financeiro', prioridade, array['contas-a-pagar','auto'], unidade,
           vencimento_em, true, st, data_conclusao, 'conta_pagar', vinculo_id, array[30], 10
      from src
    on conflict (vinculo_tipo, vinculo_id) do update set
      titulo = excluded.titulo,
      descricao = excluded.descricao,
      lista_id = excluded.lista_id,
      prioridade = excluded.prioridade,
      tags = excluded.tags,
      unidade = excluded.unidade,
      vencimento_em = excluded.vencimento_em,
      status = excluded.status,
      data_conclusao = excluded.data_conclusao,
      updated_at = now()
    where (tarefas.titulo, tarefas.descricao, tarefas.lista_id, tarefas.prioridade, tarefas.tags,
           tarefas.unidade, tarefas.vencimento_em, tarefas.status, tarefas.data_conclusao)
      is distinct from
          (excluded.titulo, excluded.descricao, excluded.lista_id, excluded.prioridade, excluded.tags,
           excluded.unidade, excluded.vencimento_em, excluded.status, excluded.data_conclusao)
    returning (xmax = 0) as inserted
  )
  select count(*) filter (where inserted), count(*) filter (where not inserted)
    into v_ins, v_upd
    from upserted;

  -- Orfa = conta inexistente, cancelada, finalizada ou em debito automatico (v6). Sair da janela NAO e orfa.
  -- Orfa com filha ativa fica de fora: tarefas_guard_delete levantaria P0001 e derrubaria o sync
  -- inteiro. Ela e colhida num ciclo seguinte, assim que as filhas fecharem.
  -- Mesma ideia pro recorrencia_pai_id: a FK e NO ACTION, entao o delete levantaria 23503.
  delete from public.tarefas t
   where t.vinculo_tipo = 'conta_pagar' and t.vinculo_id is not null
     and not exists (
       select 1 from public.contas_pagar c
        where c.id = t.vinculo_id and coalesce(c.status,'') not in ('cancelado','finalizado')
          and not c.debito_automatico                              -- v6
     )
     and not exists (select 1 from public.tarefas f where f.parent_id = t.id and f.status in ('pendente','em_andamento','adiada'))
     and not exists (select 1 from public.tarefas r where r.recorrencia_pai_id = t.id);
  get diagnostics v_del = row_count;

  insert into public.agenda_materializacoes (origem, competencia, duracao_ms, criados, atualizados, removidos, detalhes)
  values ('sync', null, (extract(epoch from clock_timestamp() - v_ini) * 1000)::int, v_ins, v_upd, v_del,
          jsonb_build_object('hoje', v_hoje, 'janela', jsonb_build_array(v_ini_janela, v_fim)));

  return jsonb_build_object(
    'inseridas', v_ins, 'atualizadas', v_upd, 'orfas_removidas', v_del,
    'hoje', v_hoje, 'janela', jsonb_build_array(v_ini_janela, v_fim)
  );
end $$;


ALTER FUNCTION "public"."agenda_sync_contas_pagar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atualizar_status_periodos_ferias"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated INTEGER := 0;
BEGIN
  -- Recalcular flag "esta_vencido" para todos os períodos (depende de CURRENT_DATE)
  UPDATE public.ferias_periodos_aquisitivos
  SET
    esta_vencido = (concessivo_fim < CURRENT_DATE AND (dias_direito - dias_gozados - dias_vendidos) > 0),
    updated_at = NOW();

  -- Marcar como vencido os que passaram do período concessivo com saldo
  UPDATE public.ferias_periodos_aquisitivos
  SET status = 'vencido', updated_at = NOW()
  WHERE status NOT IN ('vencido', 'concluido')
    AND concessivo_fim < CURRENT_DATE
    AND dias_saldo > 0;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  -- Marcar como concluído os que têm saldo zero
  UPDATE public.ferias_periodos_aquisitivos
  SET status = 'concluido', updated_at = NOW()
  WHERE status NOT IN ('concluido', 'vencido')
    AND dias_saldo = 0;

  -- Atualizar status de programações para "em_gozo" (iniciou)
  UPDATE public.ferias_programacoes
  SET status = 'em_gozo', updated_at = NOW()
  WHERE status IN ('programado', 'aprovado')
    AND data_inicio <= CURRENT_DATE
    AND data_fim >= CURRENT_DATE;

  -- Atualizar status de programações para "concluido" (terminou)
  UPDATE public.ferias_programacoes
  SET status = 'concluido', updated_at = NOW()
  WHERE status = 'em_gozo'
    AND data_fim < CURRENT_DATE;

  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."atualizar_status_periodos_ferias"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."atualizar_status_periodos_ferias"() IS 'Atualiza automaticamente status de períodos e programações';



CREATE OR REPLACE FUNCTION "public"."atualizar_totais_folha"("p_folha_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE folhas_mensais
    SET 
        total_geral = (SELECT COALESCE(SUM(total), 0) FROM lancamentos_folha WHERE folha_id = p_folha_id),
        total_cg = (SELECT COALESCE(SUM(total), 0) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'cg'),
        total_rec = (SELECT COALESCE(SUM(total), 0) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'rec'),
        total_bar = (SELECT COALESCE(SUM(total), 0) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'bar'),
        updated_at = NOW()
    WHERE id = p_folha_id;
END;
$$;


ALTER FUNCTION "public"."atualizar_totais_folha"("p_folha_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bistro_consumo_pagamento_direto_salvar"("p_consumo_id" "uuid", "p_valor_pago_direto" numeric, "p_valor_esperado" numeric, "p_ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_ator_tipo text;
  v_ator_ref text;
  v_ator_nome text;
  v_numero_hash text;
  v_last4 text;
  v_consumo record;
  v_before jsonb;
  v_after jsonb;
  v_audit_id uuid;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );

  if v_role = 'authenticated' then
    v_ator_tipo := 'web';
    v_ator_ref := auth.uid()::text;
    v_ator_nome := 'Super Folha Web';
    if v_ator_ref is null then
      raise exception 'usuario autenticado sem auth.uid().' using errcode = '42501';
    end if;
  elsif v_role in ('service_role', 'postgres') then
    v_ator_tipo := coalesce(nullif(p_ator->>'tipo', ''), 'sistema');
    if v_ator_tipo <> 'sistema' then
      raise exception 'ator.tipo nao permitido para service_role nesta fatia.'
        using errcode = '42501';
    end if;
    v_ator_ref := coalesce(nullif(p_ator->>'ref', ''), 'service_role');
    v_ator_nome := coalesce(nullif(p_ator->>'nome', ''), 'Sistema');
  else
    raise exception 'papel nao autorizado para pagamento direto do Bistro: %', v_role
      using errcode = '42501';
  end if;

  if p_valor_pago_direto is null or p_valor_pago_direto < 0 then
    raise exception 'valor_pago_direto deve ser nao negativo.';
  end if;

  select bc.*
    into v_consumo
    from public.bistro_consumos bc
   where bc.id = p_consumo_id
   for update;

  if not found then
    raise exception 'consumo_id % nao encontrado.', p_consumo_id;
  end if;

  if p_valor_esperado is null
     or v_consumo.valor_pago_direto is distinct from p_valor_esperado then
    raise exception 'Os valores mudaram. Atualize o consumo antes de salvar.';
  end if;

  if p_valor_pago_direto > v_consumo.valor then
    raise exception 'valor_pago_direto nao pode exceder o consumo bruto.';
  end if;

  if v_consumo.valor_pago_direto is not distinct from p_valor_pago_direto then
    return jsonb_build_object(
      'success', true,
      'status', 'already_applied',
      'consumo_id', p_consumo_id,
      'valor_pago_direto', v_consumo.valor_pago_direto,
      'audit_id', null
    );
  end if;

  v_before := to_jsonb(v_consumo);

  perform set_config('app.bistro_pagamento_direto_rpc', 'on', true);

  update public.bistro_consumos as bc
     set valor_pago_direto = p_valor_pago_direto,
         updated_at = now()
   where bc.id = p_consumo_id
  returning to_jsonb(bc) into v_after;

  v_numero_hash := encode(
    extensions.digest(coalesce(v_ator_ref, v_ator_tipo), 'sha256'),
    'hex'
  );
  v_last4 := right(regexp_replace(coalesce(v_ator_ref, ''), '\D', '', 'g'), 4);
  if v_last4 = '' then
    v_last4 := 'n/a';
  end if;

  insert into public.maria_audit_log (
    ator_nome, ator_numero, ator_numero_hash, ator_numero_last4,
    papel, origem, canal, invoker_role, tabela, entidade_tipo,
    entidade_id, operacao, antes, depois, motivo, texto_original
  )
  values (
    v_ator_nome, v_ator_ref, v_numero_hash, v_last4,
    v_ator_tipo, 'folha', v_ator_tipo, v_role,
    'bistro_consumos', 'bistro_consumo', p_consumo_id,
    'MARCAR_PAGAMENTO_DIRETO_BISTRO',
    v_before,
    v_after,
    nullif(trim(p_ator->>'motivo'), ''),
    null
  )
  returning id into v_audit_id;

  return jsonb_build_object(
    'success', true,
    'status', 'updated',
    'consumo_id', p_consumo_id,
    'valor_pago_direto', p_valor_pago_direto,
    'audit_id', v_audit_id
  );
end;
$$;


ALTER FUNCTION "public"."bistro_consumo_pagamento_direto_salvar"("p_consumo_id" "uuid", "p_valor_pago_direto" numeric, "p_valor_esperado" numeric, "p_ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bistro_consumo_valor_pago_direto_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.valor_pago_direto is distinct from old.valor_pago_direto
     and current_setting('app.bistro_pagamento_direto_rpc', true) is distinct from 'on' then
    raise exception 'valor_pago_direto deve ser alterado pela RPC auditada.'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."bistro_consumo_valor_pago_direto_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calcular_periodos_aquisitivos"("p_colaborador_id" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_data_admissao DATE;
  v_tipo TEXT;
  v_status TEXT;
  v_periodo_inicio DATE;
  v_periodo_fim DATE;
  v_concessivo_inicio DATE;
  v_concessivo_fim DATE;
  v_count INTEGER := 0;
BEGIN
  -- Validar colaborador CLT ativo
  SELECT data_admissao, tipo, status INTO v_data_admissao, v_tipo, v_status
  FROM public.colaboradores
  WHERE id = p_colaborador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Colaborador % não encontrado', p_colaborador_id;
  END IF;

  IF v_tipo != 'clt' THEN
    RAISE EXCEPTION 'Colaborador % não é CLT (tipo: %)', p_colaborador_id, v_tipo;
  END IF;

  IF v_data_admissao IS NULL THEN
    RAISE EXCEPTION 'Colaborador % não tem data de admissão', p_colaborador_id;
  END IF;

  -- Criar períodos de 12 em 12 meses desde admissão até hoje
  v_periodo_inicio := v_data_admissao;

  WHILE v_periodo_inicio < CURRENT_DATE LOOP
    v_periodo_fim := v_periodo_inicio + INTERVAL '12 months' - INTERVAL '1 day';
    v_concessivo_inicio := v_periodo_fim + INTERVAL '1 day';
    v_concessivo_fim := v_concessivo_inicio + INTERVAL '12 months' - INTERVAL '1 day';

    -- Só criar se o período aquisitivo já completou (12 meses trabalhados)
    IF v_periodo_fim <= CURRENT_DATE THEN
      -- Inserir se não existir (idempotente)
      INSERT INTO public.ferias_periodos_aquisitivos (
        colaborador_id,
        data_inicio,
        data_fim,
        concessivo_inicio,
        concessivo_fim,
        status
      )
      VALUES (
        p_colaborador_id,
        v_periodo_inicio,
        v_periodo_fim,
        v_concessivo_inicio,
        v_concessivo_fim,
        CASE
          WHEN v_concessivo_fim < CURRENT_DATE THEN 'vencido'
          ELSE 'ativo'
        END
      )
      ON CONFLICT (colaborador_id, data_inicio) DO UPDATE
      SET
        status = CASE
          WHEN EXCLUDED.concessivo_fim < CURRENT_DATE AND ferias_periodos_aquisitivos.dias_saldo > 0 THEN 'vencido'
          WHEN ferias_periodos_aquisitivos.dias_saldo = 0 THEN 'concluido'
          ELSE 'ativo'
        END,
        updated_at = NOW();

      v_count := v_count + 1;
    END IF;

    v_periodo_inicio := v_periodo_inicio + INTERVAL '12 months';
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."calcular_periodos_aquisitivos"("p_colaborador_id" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calcular_periodos_aquisitivos"("p_colaborador_id" integer) IS 'Calcula períodos aquisitivos de férias para colaborador CLT';



CREATE OR REPLACE FUNCTION "public"."calcular_valor_ferias"("p_colaborador_id" integer, "p_dias_corridos" integer, "p_dias_abono" integer DEFAULT 0) RETURNS TABLE("salario_base" numeric, "valor_ferias" numeric, "valor_terco" numeric, "valor_abono" numeric, "valor_total" numeric)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_salario_base NUMERIC(10,2);
  v_valor_dia NUMERIC(10,2);
  v_valor_ferias NUMERIC(10,2);
  v_valor_terco NUMERIC(10,2);
  v_valor_abono NUMERIC(10,2);
BEGIN
  SELECT c.salario_base INTO v_salario_base
  FROM public.colaboradores c
  WHERE c.id = p_colaborador_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Colaborador % não encontrado', p_colaborador_id;
  END IF;

  v_valor_dia := v_salario_base / 30;
  v_valor_ferias := v_valor_dia * p_dias_corridos;
  v_valor_terco := v_valor_ferias / 3;
  v_valor_abono := CASE WHEN p_dias_abono > 0 THEN (v_valor_dia * p_dias_abono) + ((v_valor_dia * p_dias_abono) / 3) ELSE 0 END;

  RETURN QUERY
  SELECT
    v_salario_base,
    v_valor_ferias,
    v_valor_terco,
    v_valor_abono,
    v_valor_ferias + v_valor_terco + v_valor_abono;
END;
$$;


ALTER FUNCTION "public"."calcular_valor_ferias"("p_colaborador_id" integer, "p_dias_corridos" integer, "p_dias_abono" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compare_folhas_colaborador"("p_folha_id" integer, "p_prev_folha_id" integer) RETURNS TABLE("colaborador_id" integer, "nome" "text", "funcao" "text", "total_atual" numeric, "total_anterior" numeric, "diff" numeric, "perc" numeric, "status" "text", "salario_atual" numeric, "bonus_atual" numeric, "comissao_atual" numeric, "reembolso_atual" numeric, "passagem_atual" numeric, "inss_atual" numeric, "descontos_atual" numeric, "salario_anterior" numeric, "bonus_anterior" numeric, "comissao_anterior" numeric, "reembolso_anterior" numeric, "passagem_anterior" numeric, "inss_anterior" numeric, "descontos_anterior" numeric, "nota" "text", "nota_updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
WITH curr AS (
  SELECT
    l.colaborador_id,
    MAX(c.nome)::text AS nome,
    MAX(c.funcao)::text AS funcao,
    SUM(l.total)::numeric AS total,
    SUM(l.salario)::numeric AS salario,
    SUM(l.bonus)::numeric AS bonus,
    SUM(l.comissao)::numeric AS comissao,
    SUM(l.reembolso)::numeric AS reembolso,
    SUM(l.passagem)::numeric AS passagem,
    SUM(l.inss)::numeric AS inss,
    SUM(l.descontos)::numeric AS descontos
  FROM lancamentos_folha l
  JOIN colaboradores c ON c.id = l.colaborador_id
  WHERE l.folha_id = p_folha_id
  GROUP BY l.colaborador_id
),
prev AS (
  SELECT
    l.colaborador_id,
    MAX(c.nome)::text AS nome,
    MAX(c.funcao)::text AS funcao,
    SUM(l.total)::numeric AS total,
    SUM(l.salario)::numeric AS salario,
    SUM(l.bonus)::numeric AS bonus,
    SUM(l.comissao)::numeric AS comissao,
    SUM(l.reembolso)::numeric AS reembolso,
    SUM(l.passagem)::numeric AS passagem,
    SUM(l.inss)::numeric AS inss,
    SUM(l.descontos)::numeric AS descontos
  FROM lancamentos_folha l
  JOIN colaboradores c ON c.id = l.colaborador_id
  WHERE l.folha_id = p_prev_folha_id
  GROUP BY l.colaborador_id
),
notes AS (
  SELECT colaborador_id, nota, updated_at
  FROM colaborador_variacao_notas
  WHERE folha_id = p_folha_id
)
SELECT
  COALESCE(curr.colaborador_id, prev.colaborador_id) AS colaborador_id,
  COALESCE(curr.nome, prev.nome) AS nome,
  COALESCE(curr.funcao, prev.funcao) AS funcao,

  COALESCE(curr.total, 0) AS total_atual,
  COALESCE(prev.total, 0) AS total_anterior,
  COALESCE(curr.total, 0) - COALESCE(prev.total, 0) AS diff,
  CASE WHEN COALESCE(prev.total, 0) > 0 THEN ((COALESCE(curr.total, 0) - prev.total) / prev.total) * 100 ELSE 0 END AS perc,
  CASE
    WHEN prev.colaborador_id IS NULL THEN 'NOVO'
    WHEN curr.colaborador_id IS NULL THEN 'SAIU'
    ELSE NULL
  END AS status,

  COALESCE(curr.salario, 0) AS salario_atual,
  COALESCE(curr.bonus, 0) AS bonus_atual,
  COALESCE(curr.comissao, 0) AS comissao_atual,
  COALESCE(curr.reembolso, 0) AS reembolso_atual,
  COALESCE(curr.passagem, 0) AS passagem_atual,
  COALESCE(curr.inss, 0) AS inss_atual,
  COALESCE(curr.descontos, 0) AS descontos_atual,

  COALESCE(prev.salario, 0) AS salario_anterior,
  COALESCE(prev.bonus, 0) AS bonus_anterior,
  COALESCE(prev.comissao, 0) AS comissao_anterior,
  COALESCE(prev.reembolso, 0) AS reembolso_anterior,
  COALESCE(prev.passagem, 0) AS passagem_anterior,
  COALESCE(prev.inss, 0) AS inss_anterior,
  COALESCE(prev.descontos, 0) AS descontos_anterior,

  notes.nota,
  notes.updated_at AS nota_updated_at
FROM curr
FULL OUTER JOIN prev USING (colaborador_id)
LEFT JOIN notes ON notes.colaborador_id = COALESCE(curr.colaborador_id, prev.colaborador_id);
$$;


ALTER FUNCTION "public"."compare_folhas_colaborador"("p_folha_id" integer, "p_prev_folha_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_pagar_ajustar_paga"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_conta_id uuid;
  v_conta_pagadora_id uuid;
  v_plano_conta_id uuid;
  v_before public.contas_pagar%rowtype;
  v_after public.contas_pagar%rowtype;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_centro public.centros_custo%rowtype;
  v_descricao text;
  v_valor numeric;
  v_data_lancamento date;
  v_data_vencimento date;
  v_data_pagamento date;
  v_metodo_pagamento text;
  v_observacoes text;
  v_motivo text;
  v_ator_id uuid;
  v_ator_nome text;
  v_audit_id uuid;
begin
  if not public.financeiro_cartoes_is_admin() then
    raise exception 'Perfil administrativo obrigatorio para ajustar conta paga.' using errcode = '42501';
  end if;

  v_ator_id := auth.uid();
  if v_ator_id is null then
    raise exception 'Usuario autenticado sem auth.uid().' using errcode = '42501';
  end if;

  v_conta_id := nullif(p_payload->>'conta_id', '')::uuid;
  v_conta_pagadora_id := nullif(p_payload->>'conta_pagadora_id', '')::uuid;
  v_plano_conta_id := nullif(p_payload->>'plano_conta_id', '')::uuid;
  v_descricao := nullif(btrim(p_payload->>'descricao'), '');
  if lower(coalesce(p_payload->>'valor', '')) in ('nan', 'infinity', '+infinity', '-infinity') then
    raise exception 'valor deve ser finito para ajustar conta paga.';
  end if;
  v_valor := round(nullif(p_payload->>'valor', '')::numeric, 2);
  v_data_lancamento := nullif(p_payload->>'data_lancamento', '')::date;
  v_data_vencimento := nullif(p_payload->>'data_vencimento', '')::date;
  v_data_pagamento := nullif(p_payload->>'data_pagamento', '')::date;
  v_metodo_pagamento := nullif(btrim(p_payload->>'metodo_pagamento'), '');
  v_observacoes := nullif(btrim(p_payload->>'observacoes'), '');
  v_motivo := coalesce(
    nullif(btrim(p_payload->>'motivo'), ''),
    'Correcao administrativa de conta ja paga.'
  );

  if v_conta_id is null then
    raise exception 'conta_id obrigatorio para ajustar conta paga.';
  end if;
  if v_descricao is null then
    raise exception 'descricao obrigatoria para ajustar conta paga.';
  end if;
  if v_valor is null or v_valor <= 0 or v_valor <> v_valor then
    raise exception 'valor deve ser maior que zero para ajustar conta paga.';
  end if;
  if v_data_lancamento is null or v_data_vencimento is null or v_data_pagamento is null then
    raise exception 'data de lancamento, vencimento e pagamento sao obrigatorias.';
  end if;
  if v_data_pagamento > ((now() at time zone 'America/Sao_Paulo')::date + 1) then
    raise exception 'data de pagamento futura nao permitida.';
  end if;
  if v_metodo_pagamento is null then
    raise exception 'metodo_pagamento obrigatorio para ajustar conta paga.';
  end if;
  if v_conta_pagadora_id is null then
    raise exception 'conta_pagadora_id obrigatoria para ajustar conta paga.';
  end if;
  if v_plano_conta_id is null then
    raise exception 'plano_conta_id obrigatorio para ajustar conta paga.';
  end if;

  select * into v_before
    from public.contas_pagar
   where id = v_conta_id
   for update;
  if not found then
    raise exception 'conta_pagar nao encontrada.';
  end if;
  if v_before.status <> 'pago' then
    raise exception 'somente conta paga pode usar o ajuste administrativo.';
  end if;
  if v_before.tipo_lancamento in ('fatura_cartao', 'folha_pagamento') then
    raise exception 'use o fluxo de origem para ajustar fatura de cartao ou folha de pagamento.';
  end if;

  select * into v_conta_pagadora
    from public.financeiro_contas_bancarias
   where id = v_conta_pagadora_id
     and ativo = true;
  if not found then
    raise exception 'conta pagadora ativa nao encontrada.';
  end if;

  select * into v_empresa
    from public.financeiro_empresas
   where id = v_conta_pagadora.empresa_id
     and ativo = true;
  if not found then
    raise exception 'empresa da conta pagadora nao encontrada ou inativa.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = v_empresa.unidade_id
     and ativo = true;
  if not found then
    raise exception 'centro de custo da empresa pagadora nao encontrado ou inativo.';
  end if;

  if not exists (
    select 1
      from public.plano_contas
     where id = v_plano_conta_id
       and ativo = true
  ) then
    raise exception 'plano de contas ativo nao encontrado.';
  end if;

  update public.contas_pagar
     set descricao = v_descricao,
         valor = v_valor,
         data_lancamento = v_data_lancamento,
         data_vencimento = v_data_vencimento,
         competencia = date_trunc('month', v_data_vencimento)::date,
         data_pagamento = (v_data_pagamento::timestamp at time zone 'America/Sao_Paulo'),
         metodo_pagamento = v_metodo_pagamento,
         conta_pagadora_id = v_conta_pagadora.id,
         empresa_id = v_conta_pagadora.empresa_id,
         centro_custo_id = v_empresa.unidade_id,
         unidade = v_centro.codigo,
         plano_conta_id = v_plano_conta_id,
         observacoes = v_observacoes,
         updated_at = now()
   where id = v_before.id
   returning * into v_after;

  select nome into v_ator_nome
    from public.user_profiles
   where id = v_ator_id;

  insert into public.maria_audit_log (
    ator_nome,
    ator_numero,
    ator_numero_hash,
    ator_numero_last4,
    papel,
    origem,
    canal,
    invoker_role,
    tabela,
    entidade_tipo,
    entidade_id,
    operacao,
    antes,
    depois,
    motivo
  ) values (
    coalesce(nullif(v_ator_nome, ''), 'Admin'),
    v_ator_id::text,
    encode(extensions.digest(v_ator_id::text, 'sha256'), 'hex'),
    right(v_ator_id::text, 4),
    'admin',
    'contas_pagar',
    'web',
    coalesce(nullif(auth.role(), ''), session_user::text),
    'contas_pagar',
    'conta_pagar',
    v_after.id,
    'ajustar_conta_paga',
    to_jsonb(v_before),
    to_jsonb(v_after),
    v_motivo
  ) returning id into v_audit_id;

  return jsonb_build_object(
    'success', true,
    'conta_id', v_after.id,
    'audit_id', v_audit_id,
    'status', v_after.status
  );
end;
$$;


ALTER FUNCTION "public"."contas_pagar_ajustar_paga"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."contas_pagar_ajustar_paga"("p_payload" "jsonb") IS 'Ajuste administrativo auditavel de conta ja paga; preserva a origem de cartao e folha.';



CREATE OR REPLACE FUNCTION "public"."contas_pagar_valida_empresa_centro"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_unidade_empresa uuid;
  v_empresa_conta uuid;
  v_unidade_conta uuid;
  v_codigo_centro text;
begin
  -- Arestas 1 e 2: conta pagadora e a fonte da verdade
  if new.conta_pagadora_id is not null then
    select b.empresa_id, e.unidade_id
      into v_empresa_conta, v_unidade_conta
      from public.financeiro_contas_bancarias b
      join public.financeiro_empresas e on e.id = b.empresa_id
     where b.id = new.conta_pagadora_id;

    if v_empresa_conta is null then
      raise exception 'conta_pagadora_id % nao encontrada em financeiro_contas_bancarias', new.conta_pagadora_id;
    end if;

    if new.empresa_id is not null and v_empresa_conta <> new.empresa_id then
      raise exception 'conta_pagadora_id % pertence a empresa %, nao a empresa %',
        new.conta_pagadora_id, v_empresa_conta, new.empresa_id;
    end if;

    if new.centro_custo_id is not null and v_unidade_conta <> new.centro_custo_id then
      raise exception 'conta_pagadora_id % pertence a unidade %, nao ao centro_custo_id %',
        new.conta_pagadora_id, v_unidade_conta, new.centro_custo_id;
    end if;
  end if;

  -- Aresta 3: empresa <-> centro (cobre o caso sem conta pagadora)
  if new.empresa_id is not null and new.centro_custo_id is not null then
    select unidade_id into v_unidade_empresa
      from public.financeiro_empresas
     where id = new.empresa_id;

    if v_unidade_empresa is null then
      raise exception 'empresa_id % nao encontrada em financeiro_empresas', new.empresa_id;
    end if;

    if v_unidade_empresa <> new.centro_custo_id then
      raise exception 'centro_custo_id % nao corresponde a unidade % da empresa %',
        new.centro_custo_id, v_unidade_empresa, new.empresa_id;
    end if;
  end if;

  -- Aresta 4: unidade text legada <-> codigo do centro (excecao segura: 'todas')
  if new.unidade is not null and new.unidade <> 'todas' and new.centro_custo_id is not null then
    select cc.codigo into v_codigo_centro
      from public.centros_custo cc
     where cc.id = new.centro_custo_id;

    if v_codigo_centro is null then
      raise exception 'centro_custo_id % nao encontrado em centros_custo', new.centro_custo_id;
    end if;

    if new.unidade <> v_codigo_centro then
      raise exception 'unidade (%) nao corresponde ao codigo (%) do centro_custo_id %',
        new.unidade, v_codigo_centro, new.centro_custo_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."contas_pagar_valida_empresa_centro"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_receber_classificar"("p_conta_receber_id" "uuid", "p_plano_conta_id" "uuid" DEFAULT NULL::"uuid", "p_excluido_da_receita" boolean DEFAULT false, "p_motivo_exclusao" "text" DEFAULT NULL::"text", "p_ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_ator_tipo text;
  v_ator_ref text;
  v_conta public.contas_receber%rowtype;
  v_centro_id uuid;
  v_before jsonb;
  v_after jsonb;
  v_numero_hash text;
  v_last4 text;
  v_audit_id uuid;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );
  if v_role = 'authenticated' then
    v_ator_tipo := 'web';
    v_ator_ref := auth.uid()::text;
    if v_ator_ref is null then
      raise exception 'usuario autenticado sem auth.uid().' using errcode = '42501';
    end if;
    if not public.contas_receber_pode_operar() then
      raise exception 'acesso financeiro nao autorizado.' using errcode = '42501';
    end if;
  elsif v_role in ('service_role', 'postgres') then
    v_ator_tipo := 'sistema';
    v_ator_ref := coalesce(nullif(p_ator->>'ref', ''), 'service_role');
  else
    raise exception 'papel nao autorizado para classificar contas a receber.' using errcode = '42501';
  end if;

  select * into v_conta
    from public.contas_receber
   where id = p_conta_receber_id
   for update;
  if not found then
    raise exception 'conta a receber nao encontrada.';
  end if;
  v_before := to_jsonb(v_conta);

  if p_excluido_da_receita then
    if nullif(trim(p_motivo_exclusao), '') is null then
      raise exception 'informe o motivo da exclusao da receita.';
    end if;
    p_plano_conta_id := null;
  else
    if p_plano_conta_id is null then
      raise exception 'plano_conta_id obrigatorio para confirmar a classificacao.';
    end if;
    perform 1
      from public.plano_contas
     where id = p_plano_conta_id
       and nivel = 3
       and natureza = 'entrada'
       and ativo = true;
    if not found then
      raise exception 'plano deve ser uma folha de entrada ativa.';
    end if;
  end if;

  select id into v_centro_id
    from public.centros_custo
   where lower(codigo) = v_conta.unidade
     and ativo = true
   limit 1;
  if v_centro_id is null then
    raise exception 'centro de custo ativo nao encontrado para a unidade %.', v_conta.unidade;
  end if;

  update public.contas_receber
     set plano_conta_id = p_plano_conta_id,
         centro_custo_id = v_centro_id,
         excluido_da_receita = p_excluido_da_receita,
         motivo_exclusao = case when p_excluido_da_receita then trim(p_motivo_exclusao) else null end,
         classificacao_status = case when p_excluido_da_receita then 'excluida' else 'confirmada' end,
         classificacao_origem = 'manual',
         classificado_por = v_ator_ref,
         classificado_em = now(),
         updated_at = now()
   where id = p_conta_receber_id
   returning * into v_conta;
  v_after := to_jsonb(v_conta);

  v_numero_hash := encode(extensions.digest(coalesce(v_ator_ref, v_ator_tipo), 'sha256'), 'hex');
  v_last4 := right(regexp_replace(coalesce(v_ator_ref, ''), '\D', '', 'g'), 4);
  if v_last4 = '' then v_last4 := 'n/a'; end if;

  insert into public.maria_audit_log (
    ator_nome, ator_numero, ator_numero_hash, ator_numero_last4,
    papel, origem, canal, invoker_role, tabela, entidade_tipo,
    entidade_id, operacao, antes, depois, motivo, texto_original
  ) values (
    case when v_ator_tipo = 'web' then 'Super Folha Web' else 'Sistema' end,
    v_ator_ref, v_numero_hash, v_last4, v_ator_tipo, 'contas_receber',
    v_ator_tipo, v_role, 'contas_receber', 'classificacao_receita',
    p_conta_receber_id, 'CLASSIFICAR_RECEITA', v_before, v_after,
    p_motivo_exclusao, null
  ) returning id into v_audit_id;

  return jsonb_build_object('success', true, 'conta', v_after, 'audit_id', v_audit_id);
end;
$$;


ALTER FUNCTION "public"."contas_receber_classificar"("p_conta_receber_id" "uuid", "p_plano_conta_id" "uuid", "p_excluido_da_receita" boolean, "p_motivo_exclusao" "text", "p_ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_receber_pode_operar"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when coalesce(
      nullif(auth.role(), ''),
      nullif(current_setting('request.jwt.claim.role', true), ''),
      session_user::text
    ) in ('service_role', 'postgres') then true
    when auth.role() <> 'authenticated' or auth.uid() is null then false
    else exists (
      select 1
        from public.user_profiles up
       where up.id = auth.uid()
         and up.role = 'admin'
    ) or exists (
      select 1
        from public.contas_receber_operadores op
       where op.user_id = auth.uid()
         and op.ativo = true
    )
  end;
$$;


ALTER FUNCTION "public"."contas_receber_pode_operar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_receber_preflight_obter"("p_preflight_id" "uuid", "p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_prova public.contas_receber_preflight_provas%rowtype;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );
  if v_role not in ('service_role', 'postgres') then
    raise exception 'leitura de preflight exige service_role.' using errcode = '42501';
  end if;

  select * into v_prova
    from public.contas_receber_preflight_provas
   where id = p_preflight_id
     and user_id = p_user_id;
  if not found then
    raise exception 'prova de preflight nao encontrada para este usuario.';
  end if;
  if v_prova.consumed_at is null and v_prova.expires_at <= now() then
    raise exception 'prova de preflight expirada. Execute uma nova conferencia.';
  end if;

  return jsonb_build_object(
    'id', v_prova.id,
    'competencia', v_prova.competencia,
    'sync_run_id', v_prova.sync_run_id,
    'manifest_hash', v_prova.manifest_hash,
    'expires_at', v_prova.expires_at,
    'consumed_at', v_prova.consumed_at,
    'consumed_result', v_prova.consumed_result
  );
end;
$$;


ALTER FUNCTION "public"."contas_receber_preflight_obter"("p_preflight_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_receber_preflight_registrar"("p_user_id" "uuid", "p_competencia" "date", "p_sync_run_id" "uuid", "p_manifest_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_prova public.contas_receber_preflight_provas%rowtype;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );
  if v_role not in ('service_role', 'postgres') then
    raise exception 'registro de preflight exige service_role.' using errcode = '42501';
  end if;
  if p_user_id is null or p_sync_run_id is null or nullif(trim(p_manifest_hash), '') is null then
    raise exception 'usuario, sync_run_id e manifest_hash sao obrigatorios.';
  end if;
  if p_competencia is null or p_competencia <> date_trunc('month', p_competencia)::date then
    raise exception 'competencia deve ser o primeiro dia do mes.';
  end if;

  update public.contas_receber_preflight_provas
     set expires_at = least(expires_at, now())
   where user_id = p_user_id
     and competencia = p_competencia
     and consumed_at is null
     and expires_at > now();

  insert into public.contas_receber_preflight_provas (
    user_id, competencia, sync_run_id, manifest_hash
  ) values (
    p_user_id, p_competencia, p_sync_run_id, trim(p_manifest_hash)
  )
  returning * into v_prova;

  return jsonb_build_object(
    'id', v_prova.id,
    'user_id', v_prova.user_id,
    'competencia', v_prova.competencia,
    'sync_run_id', v_prova.sync_run_id,
    'manifest_hash', v_prova.manifest_hash,
    'expires_at', v_prova.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."contas_receber_preflight_registrar"("p_user_id" "uuid", "p_competencia" "date", "p_sync_run_id" "uuid", "p_manifest_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contas_receber_sync_aplicar"("p_preflight_id" "uuid", "p_user_id" "uuid", "p_competencia" "date", "p_sync_run_id" "uuid", "p_manifest_hash" "text", "p_itens" "jsonb", "p_manifesto" "jsonb", "p_ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_prova public.contas_receber_preflight_provas%rowtype;
  v_item jsonb;
  v_plano_mensalidade uuid;
  v_plano_matricula uuid;
  v_plano_locacao uuid;
  v_descricao_normalizada text;
  v_plano_automatico uuid;
  v_centro_automatico uuid;
  v_excluido_automatico boolean;
  v_motivo_exclusao text;
  v_status text;
  v_classificacao_status text;
  v_classificacao_origem text;
  v_source_missing boolean;
  v_total integer := 0;
  v_inseridos integer := 0;
  v_atualizados integer := 0;
  v_manuais_preservados integer := 0;
  v_existente public.contas_receber%rowtype;
  v_resultado jsonb;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );
  if v_role not in ('service_role', 'postgres') then
    raise exception 'sincronizacao de contas a receber exige service_role.' using errcode = '42501';
  end if;

  select * into v_prova
    from public.contas_receber_preflight_provas
   where id = p_preflight_id
   for update;
  if not found or v_prova.user_id <> p_user_id then
    raise exception 'prova de preflight nao pertence ao usuario autenticado.';
  end if;
  if v_prova.consumed_at is not null then
    if v_prova.consumed_result is null then
      raise exception 'prova consumida sem resultado persistido.';
    end if;
    return v_prova.consumed_result || jsonb_build_object('idempotent_retry', true);
  end if;
  if v_prova.expires_at <= now() then
    raise exception 'prova de preflight expirada. Execute uma nova conferencia.';
  end if;
  if v_prova.competencia <> p_competencia
     or v_prova.sync_run_id <> p_sync_run_id
     or v_prova.manifest_hash <> p_manifest_hash then
    raise exception 'prova de preflight diverge do snapshot solicitado.';
  end if;
  if p_competencia is null or p_competencia <> date_trunc('month', p_competencia)::date then
    raise exception 'competencia deve ser o primeiro dia do mes.';
  end if;
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' then
    raise exception 'itens deve ser um array.';
  end if;
  if p_manifesto is null or jsonb_typeof(p_manifesto) <> 'object' then
    raise exception 'manifesto deve ser um objeto.';
  end if;
  if coalesce(p_manifesto->>'manifest_hash', '') <> p_manifest_hash then
    raise exception 'manifest_hash diverge do manifesto.';
  end if;
  if coalesce((p_manifesto->>'snapshot_complete')::boolean, false) is not true then
    raise exception 'snapshot incompleto nao pode ser aplicado.';
  end if;
  if nullif(p_manifesto->>'sync_run_id', '') is null
     or (p_manifesto->>'sync_run_id')::uuid <> p_sync_run_id then
    raise exception 'sync_run_id diverge do manifesto.';
  end if;
  if jsonb_array_length(p_itens) <> coalesce(
    nullif(p_manifesto->>'total_itens', '')::integer,
    nullif(p_manifesto->>'total_linhas', '')::integer,
    -1
  ) then
    raise exception 'quantidade de itens diverge do manifesto.';
  end if;

  select id into v_plano_mensalidade
    from public.plano_contas
   where codigo = '3.1.1' and nivel = 3 and natureza = 'entrada' and ativo = true;
  select id into v_plano_matricula
    from public.plano_contas
   where codigo = '3.1.2' and nivel = 3 and natureza = 'entrada' and ativo = true;
  select id into v_plano_locacao
    from public.plano_contas
   where codigo = '3.4.1' and nivel = 3 and natureza = 'entrada' and ativo = true;
  if v_plano_mensalidade is null or v_plano_matricula is null or v_plano_locacao is null then
    raise exception 'planos automaticos 3.1.1, 3.1.2 e 3.4.1 precisam estar ativos como folhas de entrada.';
  end if;

  for v_item in select value from jsonb_array_elements(p_itens)
  loop
    if (v_item->>'competencia')::date <> p_competencia then
      raise exception 'item % pertence a outra competencia.', v_item->>'emusys_fatura_id';
    end if;
    if nullif(v_item->>'sync_run_id', '') is null
       or (v_item->>'sync_run_id')::uuid <> p_sync_run_id then
      raise exception 'item % pertence a outro sync_run.', v_item->>'emusys_fatura_id';
    end if;
    if nullif(v_item->>'row_source_hash', '') is null then
      raise exception 'item % nao possui row_source_hash.', v_item->>'emusys_fatura_id';
    end if;

    v_descricao_normalizada := translate(
      lower(coalesce(v_item->>'descricao', '')),
      'Ã¡Ã Ã¢Ã£Ã¤Ã©Ã¨ÃªÃ«Ã­Ã¬Ã®Ã¯Ã³Ã²Ã´ÃµÃ¶ÃºÃ¹Ã»Ã¼Ã§',
      'aaaaaeeeeiiiiooooouuuuc'
    );
    v_plano_automatico := null;
    v_centro_automatico := null;
    v_excluido_automatico := false;
    v_motivo_exclusao := null;
    v_classificacao_status := 'pendente';
    v_classificacao_origem := 'pendente';

    if v_descricao_normalizada ~ '^\s*parcela' then
      v_plano_automatico := v_plano_mensalidade;
      v_classificacao_status := 'confirmada';
      v_classificacao_origem := 'automatica';
    elsif v_descricao_normalizada ~ '(passaporte|matricula)' then
      v_plano_automatico := v_plano_matricula;
      v_classificacao_status := 'confirmada';
      v_classificacao_origem := 'automatica';
    elsif v_descricao_normalizada ~ 'locacao' then
      v_plano_automatico := v_plano_locacao;
      v_classificacao_status := 'confirmada';
      v_classificacao_origem := 'automatica';
    elsif v_descricao_normalizada ~ 'rateio' then
      v_excluido_automatico := true;
      v_motivo_exclusao := 'Rateio interno excluido automaticamente da receita.';
      v_classificacao_status := 'excluida';
      v_classificacao_origem := 'exclusao_automatica';
    end if;

    select id into v_centro_automatico
      from public.centros_custo
     where lower(codigo) = v_item->>'unidade'
       and ativo = true
     limit 1;
    if v_centro_automatico is null then
      raise exception 'centro de custo ativo nao encontrado para a unidade %.', v_item->>'unidade';
    end if;

    v_source_missing := coalesce((v_item->>'source_missing')::boolean, false);
    v_status := case
      when v_source_missing then 'revisar'
      else case lower(coalesce(v_item->>'status_origem', ''))
        when 'paga' then 'recebido'
        when 'pago' then 'recebido'
        when 'aberta' then 'pendente'
        when 'pendente' then 'pendente'
        when 'cancelada' then 'cancelado'
        when 'cancelado' then 'cancelado'
        else 'revisar'
      end
    end;

    select * into v_existente
      from public.contas_receber
     where la_report_unidade_id = (v_item->>'la_report_unidade_id')::uuid
       and emusys_fatura_id = (v_item->>'emusys_fatura_id')::bigint
       and competencia = p_competencia;
    if found then
      v_atualizados := v_atualizados + 1;
      if v_existente.classificacao_origem = 'manual' then
        v_manuais_preservados := v_manuais_preservados + 1;
      end if;
    else
      v_inseridos := v_inseridos + 1;
    end if;

    insert into public.contas_receber (
      la_report_fatura_id, la_report_unidade_id, emusys_fatura_id,
      emusys_matricula_id, emusys_student_id, unidade, descricao,
      aluno_nome, curso_nome, cadastro_match_status, curso_candidatos,
      status_origem, status, competencia, data_vencimento, data_recebimento,
      valor_original, valor_pago, juros_e_multa, desconto_aplicado,
      desconto_fixo, desconto_condicional, valor_liquido,
      plano_conta_id, centro_custo_id, excluido_da_receita, motivo_exclusao,
      classificacao_status, classificacao_origem, classificado_por, classificado_em,
      row_source_hash, manifest_hash, source_updated_at, source_synced_at,
      source_missing, source_missing_reason, source_last_seen_at,
      source_missing_detected_at, source_missing_resolved_at,
      source_sync_run_id, source_sync_run_item_id, imported_at, updated_at
    ) values (
      (v_item->>'la_report_fatura_id')::uuid,
      (v_item->>'la_report_unidade_id')::uuid,
      (v_item->>'emusys_fatura_id')::bigint,
      nullif(v_item->>'emusys_matricula_id', '')::bigint,
      nullif(v_item->>'emusys_student_id', '')::bigint,
      v_item->>'unidade', v_item->>'descricao',
      nullif(v_item->>'aluno_nome', ''), nullif(v_item->>'curso_nome', ''),
      v_item->>'cadastro_match_status', coalesce(v_item->'curso_candidatos', '[]'::jsonb),
      v_item->>'status_origem', v_status, p_competencia,
      nullif(v_item->>'data_vencimento', '')::date,
      nullif(v_item->>'data_recebimento', '')::date,
      coalesce((v_item->>'valor_original')::numeric, 0),
      nullif(v_item->>'valor_pago', '')::numeric,
      coalesce((v_item->>'juros_e_multa')::numeric, 0),
      coalesce((v_item->>'desconto_aplicado')::numeric, 0),
      coalesce((v_item->>'desconto_fixo')::numeric, 0),
      coalesce((v_item->>'desconto_condicional')::numeric, 0),
      coalesce((v_item->>'valor_liquido')::numeric, 0),
      v_plano_automatico, v_centro_automatico, v_excluido_automatico, v_motivo_exclusao,
      v_classificacao_status, v_classificacao_origem,
      case when v_classificacao_status = 'confirmada' then 'sincronizacao-automatica' end,
      case when v_classificacao_status = 'confirmada' then now() end,
      v_item->>'row_source_hash', p_manifest_hash,
      nullif(v_item->>'source_updated_at', '')::timestamptz,
      nullif(v_item->>'source_synced_at', '')::timestamptz,
      v_source_missing, nullif(v_item->>'source_missing_reason', ''),
      nullif(v_item->>'source_last_seen_at', '')::timestamptz,
      nullif(v_item->>'source_missing_detected_at', '')::timestamptz,
      nullif(v_item->>'source_missing_resolved_at', '')::timestamptz,
      p_sync_run_id, nullif(v_item->>'sync_run_item_id', '')::uuid, now(), now()
    )
    on conflict (la_report_unidade_id, emusys_fatura_id, competencia) do update set
      la_report_fatura_id = excluded.la_report_fatura_id,
      emusys_matricula_id = excluded.emusys_matricula_id,
      emusys_student_id = excluded.emusys_student_id,
      unidade = excluded.unidade,
      descricao = excluded.descricao,
      aluno_nome = excluded.aluno_nome,
      curso_nome = excluded.curso_nome,
      cadastro_match_status = excluded.cadastro_match_status,
      curso_candidatos = excluded.curso_candidatos,
      status_origem = excluded.status_origem,
      status = excluded.status,
      data_vencimento = excluded.data_vencimento,
      data_recebimento = excluded.data_recebimento,
      valor_original = excluded.valor_original,
      valor_pago = excluded.valor_pago,
      juros_e_multa = excluded.juros_e_multa,
      desconto_aplicado = excluded.desconto_aplicado,
      desconto_fixo = excluded.desconto_fixo,
      desconto_condicional = excluded.desconto_condicional,
      valor_liquido = excluded.valor_liquido,
      plano_conta_id = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.plano_conta_id else excluded.plano_conta_id end,
      centro_custo_id = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.centro_custo_id else excluded.centro_custo_id end,
      excluido_da_receita = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.excluido_da_receita else excluded.excluido_da_receita end,
      motivo_exclusao = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.motivo_exclusao else excluded.motivo_exclusao end,
      classificacao_status = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.classificacao_status else excluded.classificacao_status end,
      classificacao_origem = case when contas_receber.classificacao_origem = 'manual'
        then 'manual' else excluded.classificacao_origem end,
      classificado_por = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.classificado_por else excluded.classificado_por end,
      classificado_em = case when contas_receber.classificacao_origem = 'manual'
        then contas_receber.classificado_em else excluded.classificado_em end,
      row_source_hash = excluded.row_source_hash,
      manifest_hash = excluded.manifest_hash,
      source_updated_at = excluded.source_updated_at,
      source_synced_at = excluded.source_synced_at,
      source_missing = excluded.source_missing,
      source_missing_reason = excluded.source_missing_reason,
      source_last_seen_at = excluded.source_last_seen_at,
      source_missing_detected_at = excluded.source_missing_detected_at,
      source_missing_resolved_at = excluded.source_missing_resolved_at,
      source_sync_run_id = excluded.source_sync_run_id,
      source_sync_run_item_id = excluded.source_sync_run_item_id,
      imported_at = now(),
      updated_at = now();

    v_total := v_total + 1;
  end loop;

  v_resultado := jsonb_build_object(
    'success', true,
    'competencia', p_competencia,
    'sync_run_id', p_sync_run_id,
    'manifest_hash', p_manifest_hash,
    'preflight_id', p_preflight_id,
    'total', v_total,
    'inseridos', v_inseridos,
    'atualizados', v_atualizados,
    'classificacoes_manuais_preservadas', v_manuais_preservados,
    'idempotent_retry', false
  );

  insert into public.contas_receber_sync_execucoes (
    competencia, manifest_hash, modo, total_itens, manifesto, ator,
    sync_run_id, preflight_id, resultado
  ) values (
    p_competencia, p_manifest_hash, 'apply', v_total, p_manifesto, p_ator,
    p_sync_run_id, p_preflight_id, v_resultado
  )
  on conflict (competencia, manifest_hash) do update set
    sync_run_id = excluded.sync_run_id,
    preflight_id = excluded.preflight_id,
    resultado = excluded.resultado;

  update public.contas_receber_preflight_provas
     set consumed_at = now(),
         consumed_result = v_resultado
   where id = p_preflight_id;

  return v_resultado;
end;
$$;


ALTER FUNCTION "public"."contas_receber_sync_aplicar"("p_preflight_id" "uuid", "p_user_id" "uuid", "p_competencia" "date", "p_sync_run_id" "uuid", "p_manifest_hash" "text", "p_itens" "jsonb", "p_manifesto" "jsonb", "p_ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dre_consultar"("p_competencia" "date", "p_regime" "text", "p_unidade" "text" DEFAULT 'consolidado'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  if p_competencia is null then
    raise exception 'competencia obrigatoria.';
  end if;

  if p_regime is null or p_regime not in ('competencia', 'caixa') then
    raise exception 'regime deve ser competencia ou caixa.';
  end if;

  if p_unidade is null or p_unidade not in ('consolidado', 'cg', 'rec', 'bar') then
    raise exception 'unidade deve ser consolidado, cg, rec ou bar.';
  end if;

  with linhas_base as materialized (
    select *
    from public.dre_linhas_normalizadas(date_trunc('month', p_competencia)::date, p_regime)
  ),
  linhas_filtradas as materialized (
    select *
    from linhas_base
    where p_unidade = 'consolidado'
      or unidade_operacional = p_unidade
  ),
  fontes(fonte, label) as (
    values
      ('contas_receber'::text, 'Contas a Receber'::text),
      ('contas_pagar'::text, 'Contas a Pagar'::text),
      ('cartao'::text, 'Cartões'::text),
      ('folha'::text, 'Folha de Pagamento'::text)
  ),
  grupos_catalogo(codigo, nome, ordem) as (
    values
      ('3'::text, 'Receitas'::text, 1),
      ('4'::text, 'Despesas variáveis'::text, 2),
      ('5'::text, 'Despesas fixas'::text, 3),
      ('6'::text, 'Investimentos'::text, 4),
      ('7'::text, 'Não operacional'::text, 5)
  ),
  kpis as (
    select
      coalesce(sum(valor_resultado) filter (where grupo_codigo = '3'), 0) as receita,
      -coalesce(sum(valor_resultado) filter (where grupo_codigo in ('4', '5')), 0) as despesa,
      coalesce(sum(valor_resultado) filter (where grupo_codigo in ('3', '4', '5')), 0) as lucro_operacional,
      -coalesce(sum(valor_resultado) filter (where grupo_codigo = '6'), 0) as investimentos,
      coalesce(sum(valor_resultado) filter (where grupo_codigo = '7' and natureza = 'entrada'), 0) as entradas_nao_operacionais,
      -coalesce(sum(valor_resultado) filter (where grupo_codigo = '7' and natureza = 'saida'), 0) as saidas_nao_operacionais,
      coalesce(sum(valor_resultado), 0) as lucro_liquido
    from linhas_filtradas
  ),
  grupos as (
    select
      gc.codigo,
      gc.nome,
      gc.ordem,
      coalesce(sum(l.valor_resultado), 0) as valor_resultado,
      count(l.origem_id) filter (where l.status_classificacao = 'classificado_dre') as linhas_classificadas
    from grupos_catalogo gc
    left join linhas_filtradas l
      on l.grupo_codigo = gc.codigo
     and l.status_classificacao = 'classificado_dre'
    group by gc.codigo, gc.nome, gc.ordem
  ),
  planos as (
    select
      l.grupo_codigo,
      l.plano_codigo,
      max(l.plano_nome) as plano_nome,
      max(l.natureza) as natureza,
      sum(l.valor_fonte) as valor_resultado,
      jsonb_object_agg(l.fonte, l.valor_fonte order by l.fonte) as por_fonte
    from (
      select
        grupo_codigo,
        plano_codigo,
        plano_nome,
        natureza,
        fonte,
        sum(valor_resultado) as valor_fonte
      from linhas_filtradas
      where status_classificacao = 'classificado_dre'
        and plano_codigo is not null
      group by grupo_codigo, plano_codigo, plano_nome, natureza, fonte
    ) l
    group by l.grupo_codigo, l.plano_codigo
  ),
  cobertura as (
    select
      f.fonte,
      f.label,
      case when count(l.origem_id) = 0 then 'sem_dados' else 'ok' end as estado,
      count(l.origem_id) as linhas,
      count(l.origem_id) filter (where l.status_classificacao = 'classificado_dre') as classificadas,
      coalesce(sum(l.valor_origem), 0) as total_origem
    from fontes f
    left join linhas_base l on l.fonte = f.fonte
    group by f.fonte, f.label
  ),
  reconciliacao as (
    select
      f.fonte,
      f.label,
      coalesce(sum(l.valor_origem) filter (where l.status_classificacao = 'classificado_dre'), 0) as classificado_dre,
      coalesce(sum(l.valor_origem) filter (where l.status_classificacao = 'em_revisao'), 0) as em_revisao,
      coalesce(sum(l.valor_origem) filter (where l.status_classificacao = 'sem_plano'), 0) as sem_plano,
      coalesce(sum(l.valor_origem) filter (where l.status_classificacao = 'cancelado'), 0) as cancelado,
      coalesce(sum(l.valor_origem) filter (where l.status_classificacao = 'excluido'), 0) as excluido,
      coalesce(sum(l.valor_origem), 0) as total_origem
    from fontes f
    left join linhas_base l on l.fonte = f.fonte
    group by f.fonte, f.label
  ),
  sem_unidade_operacional as (
    select jsonb_build_object(
      'valor_origem', coalesce(sum(l.valor_origem), 0),
      'valor_resultado', coalesce(sum(l.valor_resultado), 0),
      'linhas', count(*),
      'colaboradores_folha', count(distinct l.colaborador_id) filter (where l.fonte = 'folha'),
      'por_motivo', jsonb_build_object(
        'folha_sem_alocacao', jsonb_build_object(
          'valor_origem', coalesce(sum(l.valor_origem) filter (where l.motivo_sem_unidade = 'folha_sem_alocacao'), 0),
          'valor_resultado', coalesce(sum(l.valor_resultado) filter (where l.motivo_sem_unidade = 'folha_sem_alocacao'), 0),
          'linhas', count(*) filter (where l.motivo_sem_unidade = 'folha_sem_alocacao'),
          'colaboradores_folha', count(distinct l.colaborador_id) filter (where l.fonte = 'folha' and l.motivo_sem_unidade = 'folha_sem_alocacao')
        ),
        'folha_desatualizada', jsonb_build_object(
          'valor_origem', coalesce(sum(l.valor_origem) filter (where l.motivo_sem_unidade = 'folha_desatualizada'), 0),
          'valor_resultado', coalesce(sum(l.valor_resultado) filter (where l.motivo_sem_unidade = 'folha_desatualizada'), 0),
          'linhas', count(*) filter (where l.motivo_sem_unidade = 'folha_desatualizada'),
          'colaboradores_folha', count(distinct l.colaborador_id) filter (where l.fonte = 'folha' and l.motivo_sem_unidade = 'folha_desatualizada')
        ),
        'cartao_nao_confirmado', jsonb_build_object(
          'valor_origem', coalesce(sum(l.valor_origem) filter (where l.motivo_sem_unidade = 'cartao_nao_confirmado'), 0),
          'valor_resultado', coalesce(sum(l.valor_resultado) filter (where l.motivo_sem_unidade = 'cartao_nao_confirmado'), 0),
          'linhas', count(*) filter (where l.motivo_sem_unidade = 'cartao_nao_confirmado'),
          'colaboradores_folha', count(distinct l.colaborador_id) filter (where l.fonte = 'folha' and l.motivo_sem_unidade = 'cartao_nao_confirmado')
        ),
        'fonte_sem_unidade', jsonb_build_object(
          'valor_origem', coalesce(sum(l.valor_origem) filter (where l.motivo_sem_unidade = 'fonte_sem_unidade'), 0),
          'valor_resultado', coalesce(sum(l.valor_resultado) filter (where l.motivo_sem_unidade = 'fonte_sem_unidade'), 0),
          'linhas', count(*) filter (where l.motivo_sem_unidade = 'fonte_sem_unidade'),
          'colaboradores_folha', count(distinct l.colaborador_id) filter (where l.fonte = 'folha' and l.motivo_sem_unidade = 'fonte_sem_unidade')
        )
      )
    ) as resumo
    from linhas_base l
    where l.unidade_operacional is null
  )
  select jsonb_build_object(
    'success', true,
    'competencia', date_trunc('month', p_competencia)::date,
    'regime', p_regime,
    'unidade', p_unidade,
    'kpis', jsonb_build_object(
      'receita', k.receita,
      'despesa', k.despesa,
      'lucro_operacional', k.lucro_operacional,
      'investimentos', k.investimentos,
      'entradas_nao_operacionais', k.entradas_nao_operacionais,
      'saidas_nao_operacionais', k.saidas_nao_operacionais,
      'lucro_liquido', k.lucro_liquido
    ),
    'grupos', coalesce((
      select jsonb_agg(to_jsonb(g) - 'ordem' order by g.ordem)
      from grupos g
    ), '[]'::jsonb),
    'planos', coalesce((
      select jsonb_agg(to_jsonb(p) order by p.plano_codigo)
      from planos p
    ), '[]'::jsonb),
    'cobertura', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.fonte)
      from cobertura c
    ), '[]'::jsonb),
    'reconciliacao', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.fonte)
      from reconciliacao r
    ), '[]'::jsonb),
    'sem_unidade_operacional', (
      select s.resumo
      from sem_unidade_operacional s
    )
  )
  into v_result
  from kpis k;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."dre_consultar"("p_competencia" "date", "p_regime" "text", "p_unidade" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dre_consultar"("p_competencia" "date", "p_regime" "text", "p_unidade" "text") IS 'DRE read-only por competencia, regime e unidade, com diagnosticos consolidados.';



CREATE OR REPLACE FUNCTION "public"."dre_detalhes"("p_competencia" "date", "p_regime" "text", "p_plano_codigo" "text" DEFAULT NULL::"text", "p_fonte" "text" DEFAULT NULL::"text", "p_unidade" "text" DEFAULT 'consolidado'::"text", "p_cursor" "jsonb" DEFAULT NULL::"jsonb", "p_limite" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limite integer := least(greatest(coalesce(p_limite, 50), 1), 100);
  v_result jsonb;
begin
  if p_competencia is null then
    raise exception 'competencia obrigatoria.';
  end if;

  if p_regime is null or p_regime not in ('competencia', 'caixa') then
    raise exception 'regime deve ser competencia ou caixa.';
  end if;

  if p_fonte is not null and p_fonte not in ('contas_receber', 'contas_pagar', 'cartao', 'folha') then
    raise exception 'fonte invalida.';
  end if;

  if p_unidade is null or p_unidade not in ('consolidado', 'cg', 'rec', 'bar') then
    raise exception 'unidade deve ser consolidado, cg, rec ou bar.';
  end if;

  with filtradas as (
    select *
    from public.dre_linhas_normalizadas(date_trunc('month', p_competencia)::date, p_regime) l
    where (
      p_plano_codigo is null
      or l.plano_codigo = p_plano_codigo
      or l.plano_codigo like p_plano_codigo || '.%'
    )
      and (p_fonte is null or l.fonte = p_fonte)
      and (p_unidade = 'consolidado' or l.unidade_operacional = p_unidade)
      and (
        p_cursor is null
        or (
          coalesce(l.plano_codigo, '~'),
          l.fonte,
          l.origem_id,
          l.origem_sequencia,
          coalesce(l.unidade_operacional, '~')
        ) > (
          coalesce(p_cursor->>'plano_codigo', '~'),
          coalesce(p_cursor->>'fonte', ''),
          coalesce(p_cursor->>'origem_id', ''),
          coalesce(p_cursor->>'origem_sequencia', ''),
          coalesce(p_cursor->>'unidade_operacional', '~')
        )
      )
  ),
  ordenadas as (
    select *
    from filtradas
    order by coalesce(plano_codigo, '~'), fonte, origem_id, origem_sequencia, coalesce(unidade_operacional, '~')
    limit v_limite + 1
  ),
  pagina as (
    select *, row_number() over (
      order by coalesce(plano_codigo, '~'), fonte, origem_id, origem_sequencia, coalesce(unidade_operacional, '~')
    ) as numero_linha
    from ordenadas
  ),
  ultimo as (
    select *
    from pagina
    where numero_linha <= v_limite
    order by coalesce(plano_codigo, '~') desc, fonte desc, origem_id desc, origem_sequencia desc, coalesce(unidade_operacional, '~') desc
    limit 1
  )
  select jsonb_build_object(
    'success', true,
    'unidade', p_unidade,
    'itens', coalesce((
      select jsonb_agg(
        to_jsonb(p) - 'numero_linha'
        order by coalesce(p.plano_codigo, '~'), p.fonte, p.origem_id, p.origem_sequencia, coalesce(p.unidade_operacional, '~')
      )
      from pagina p
      where p.numero_linha <= v_limite
    ), '[]'::jsonb),
    'next_cursor', case
      when (select count(*) from pagina) <= v_limite then null
      else (
        select jsonb_build_object(
          'plano_codigo', u.plano_codigo,
          'fonte', u.fonte,
          'origem_id', u.origem_id,
          'origem_sequencia', u.origem_sequencia,
          'unidade_operacional', u.unidade_operacional
        )
        from ultimo u
      )
    end
  )
  into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."dre_detalhes"("p_competencia" "date", "p_regime" "text", "p_plano_codigo" "text", "p_fonte" "text", "p_unidade" "text", "p_cursor" "jsonb", "p_limite" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dre_detalhes"("p_competencia" "date", "p_regime" "text", "p_plano_codigo" "text", "p_fonte" "text", "p_unidade" "text", "p_cursor" "jsonb", "p_limite" integer) IS 'Drill-down read-only do DRE por unidade com cursor deterministico.';



CREATE OR REPLACE FUNCTION "public"."dre_linhas_normalizadas"("p_competencia" "date", "p_regime" "text") RETURNS TABLE("fonte" "text", "origem_id" "text", "origem_sequencia" "text", "competencia_origem" "date", "data_caixa" "date", "data_referencia" "date", "conta_pagadora_id" "uuid", "conta_pagadora_label" "text", "descricao" "text", "contraparte" "text", "plano_codigo" "text", "plano_nome" "text", "natureza" "text", "grupo_codigo" "text", "valor_origem" numeric, "valor_resultado" numeric, "escopo_dre" "text", "status_financeiro" "text", "status_classificacao" "text", "colaborador_id" integer, "unidade_operacional" "text", "qualidade_unidade" "text", "motivo_sem_unidade" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
  with parametros as (
    select
      date_trunc('month', p_competencia)::date as inicio,
      (date_trunc('month', p_competencia) + interval '1 month')::date as fim
  ),
  folhas_alvo as (
    select fm.id as folha_id
    from public.folhas_mensais fm
    cross join parametros p
    where p_regime = 'competencia'
      and fm.ano = extract(year from p.inicio)::integer
      and fm.mes = extract(month from p.inicio)::integer

    union

    select distinct
      cp.fonte_identificador::numeric::integer as folha_id
    from public.contas_pagar cp
    join public.folhas_mensais fm
      on fm.id::numeric = case
        when trim(cp.fonte_identificador) ~ '^[0-9]+$'
          then trim(cp.fonte_identificador)::numeric
        else null
      end
    cross join parametros p
    where p_regime = 'caixa'
      and cp.fonte_tipo = 'folha_pagamento'
      and cp.status = 'pago'
      and cp.data_pagamento::date >= p.inicio
      and cp.data_pagamento::date < p.fim
  ),
  folha_raw as (
    select
      'folha'::text as fonte,
      r.lancamento_folha_id::text as origem_id,
      lpad(r.sequencia::text, 6, '0') || ':' || r.componente as origem_sequencia,
      r.competencia as competencia_origem,
      cp_folha.data_pagamento::date as data_caixa,
      case when p_regime = 'caixa' then cp_folha.data_pagamento::date else r.competencia end as data_referencia,
      d.conta_pagadora_id_usada as conta_pagadora_id,
      coalesce(
        nullif(trim(fe.label_operacional), ''),
        nullif(trim(fe.nome_fantasia), ''),
        nullif(trim(fe.razao_social), '')
      ) || case
        when fcb.conta is not null then ' · conta ' || fcb.conta
        else ''
      end as conta_pagadora_label,
      'Folha · ' || r.componente || ' · ' || r.categoria_usada as descricao,
      coalesce(
        nullif(trim(c.nome_completo), ''),
        nullif(trim(c.nome), ''),
        'Colaborador #' || r.colaborador_id::text
      ) as contraparte,
      r.plano_codigo_usado as plano_codigo,
      r.plano_nome_usado as plano_nome,
      case
        when r.plano_codigo_usado = '3' or r.plano_codigo_usado like '3.%' then 'entrada'
        when r.plano_codigo_usado = '7.1' or r.plano_codigo_usado like '7.1.%' then 'entrada'
        when split_part(coalesce(r.plano_codigo_usado, ''), '.', 1) in ('4', '5', '6', '7') then 'saida'
        else null
      end as natureza,
      split_part(coalesce(r.plano_codigo_usado, ''), '.', 1) as grupo_codigo,
      r.valor_assinado_rateado as valor_origem,
      r.escopo_dre,
      coalesce(cp_folha.status, fm.status) as status_financeiro,
      case
        when r.tratamento = 'pendente' then 'em_revisao'
        when r.plano_conta_id is null or r.plano_codigo_usado is null then 'sem_plano'
        when r.escopo_dre = 'nenhum' or r.tratamento in ('excluido', 'liquidacao') then 'excluido'
        when split_part(r.plano_codigo_usado, '.', 1) not in ('3', '4', '5', '6', '7') then 'em_revisao'
        else 'classificado_dre'
      end as status_classificacao,
      r.colaborador_id,
      case
        when r.estado_alocacao = 'pronto' and r.unidade_dre in ('cg', 'rec', 'bar')
          then r.unidade_dre
        else null
      end as unidade_operacional,
      case
        when r.estado_alocacao = 'pronto' and r.unidade_dre in ('cg', 'rec', 'bar')
          then 'exata'
        else null
      end as qualidade_unidade,
      case
        when r.estado_alocacao = 'sem_alocacao' then 'folha_sem_alocacao'
        when r.estado_alocacao = 'desatualizada' then 'folha_desatualizada'
        when r.estado_alocacao = 'pronto'
          and (r.unidade_dre is null or r.unidade_dre not in ('cg', 'rec', 'bar'))
          then 'fonte_sem_unidade'
        when r.estado_alocacao = 'pronto' then null
        else 'fonte_sem_unidade'
      end as motivo_sem_unidade
    from folhas_alvo fa
    join lateral public.folha_alocacao_dre_resolver(fa.folha_id, null) r on true
    join public.folha_classificacao_dre d
      on d.folha_id = r.folha_id
     and d.lancamento_folha_id = r.lancamento_folha_id
     and d.componente = r.componente
     and d.sequencia = r.sequencia
    join public.folhas_mensais fm on fm.id = r.folha_id
    left join public.colaboradores c on c.id = r.colaborador_id
    left join public.financeiro_contas_bancarias fcb on fcb.id = d.conta_pagadora_id_usada
    left join public.financeiro_empresas fe on fe.id = fcb.empresa_id
    cross join parametros p
    left join lateral (
      select cp_folha.*
      from public.contas_pagar cp_folha
      where cp_folha.fonte_tipo = 'folha_pagamento'
        and cp_folha.fonte_identificador = d.folha_id::text
        and cp_folha.conta_pagadora_id = d.conta_pagadora_id_usada
        and cp_folha.status <> 'cancelado'
        and (
          p_regime = 'competencia'
          or (
            p_regime = 'caixa'
            and cp_folha.status = 'pago'
            and cp_folha.data_pagamento::date >= p.inicio
            and cp_folha.data_pagamento::date < p.fim
          )
        )
      order by
        case when cp_folha.status = 'pago' then 0 else 1 end,
        cp_folha.updated_at desc nulls last,
        cp_folha.id
      limit 1
    ) cp_folha on true
    where (
      p_regime = 'competencia'
      and r.competencia >= p.inicio
      and r.competencia < p.fim
    ) or (
      p_regime = 'caixa'
      and cp_folha.status = 'pago'
      and cp_folha.data_pagamento::date >= p.inicio
      and cp_folha.data_pagamento::date < p.fim
    )
  ),
  contas_pagar_raw as (
    select
      'contas_pagar'::text as fonte,
      cp.id::text as origem_id,
      '000001'::text as origem_sequencia,
      cp.competencia as competencia_origem,
      cp.data_pagamento::date as data_caixa,
      case when p_regime = 'caixa' then cp.data_pagamento::date else cp.competencia end as data_referencia,
      cp.conta_pagadora_id,
      coalesce(
        nullif(trim(fe.label_operacional), ''),
        nullif(trim(fe.nome_fantasia), ''),
        nullif(trim(fe.razao_social), '')
      ) || case
        when fcb.conta is not null then ' · conta ' || fcb.conta
        else ''
      end as conta_pagadora_label,
      cp.descricao,
      coalesce(nullif(trim(cp.fonte_identificador), ''), cp.descricao) as contraparte,
      pc.codigo as plano_codigo,
      coalesce(pc.nome_completo, pc.nome) as plano_nome,
      case
        when pc.codigo = '3' or pc.codigo like '3.%' then 'entrada'
        when pc.codigo = '7.1' or pc.codigo like '7.1.%' then 'entrada'
        when split_part(coalesce(pc.codigo, ''), '.', 1) in ('4', '5', '6', '7') then 'saida'
        else null
      end as natureza,
      split_part(coalesce(pc.codigo, ''), '.', 1) as grupo_codigo,
      cp.valor as valor_origem,
      case when pc.codigo = '7' or pc.codigo like '7.%' then 'fora_operacional' else 'operacional' end as escopo_dre,
      cp.status as status_financeiro,
      case
        when cp.status = 'cancelado' then 'cancelado'
        when cp.fonte_tipo in ('folha_pagamento', 'cartao') then 'excluido'::text
        when cp.plano_conta_id is null then 'sem_plano'
        when split_part(coalesce(pc.codigo, ''), '.', 1) not in ('3', '4', '5', '6', '7') then 'em_revisao'
        else 'classificado_dre'
      end as status_classificacao,
      null::integer as colaborador_id,
      case
        when lower(coalesce(nullif(trim(cc_cp.codigo), ''), nullif(trim(cp.unidade), ''))) in ('cg', 'rec', 'bar')
          then lower(coalesce(nullif(trim(cc_cp.codigo), ''), nullif(trim(cp.unidade), '')))
        else null
      end as unidade_operacional,
      case
        when lower(coalesce(nullif(trim(cc_cp.codigo), ''), nullif(trim(cp.unidade), ''))) in ('cg', 'rec', 'bar')
          then 'aproximada_conta_pagadora'
        else null
      end as qualidade_unidade,
      case
        when lower(coalesce(nullif(trim(cc_cp.codigo), ''), nullif(trim(cp.unidade), ''))) is null
          or lower(coalesce(nullif(trim(cc_cp.codigo), ''), nullif(trim(cp.unidade), ''))) not in ('cg', 'rec', 'bar')
          then 'fonte_sem_unidade'
        else null
      end as motivo_sem_unidade
    from public.contas_pagar cp
    left join public.plano_contas pc on pc.id = cp.plano_conta_id
    left join public.centros_custo cc_cp on cc_cp.id = cp.centro_custo_id
    left join public.financeiro_contas_bancarias fcb on fcb.id = cp.conta_pagadora_id
    left join public.financeiro_empresas fe on fe.id = fcb.empresa_id
    cross join parametros p
    where (
      p_regime = 'competencia'
      and cp.competencia >= p.inicio
      and cp.competencia < p.fim
    ) or (
      p_regime = 'caixa'
      and cp.status = 'pago'
      and cp.data_pagamento::date >= p.inicio
      and cp.data_pagamento::date < p.fim
    )
  ),
  cartao_raw as (
    select
      'cartao'::text as fonte,
      t.id::text as origem_id,
      '000001'::text as origem_sequencia,
      f.competencia as competencia_origem,
      cp_cartao.data_pagamento::date as data_caixa,
      case when p_regime = 'caixa' then cp_cartao.data_pagamento::date else f.competencia end as data_referencia,
      ca.conta_pagadora_id,
      coalesce(
        nullif(trim(fe.label_operacional), ''),
        nullif(trim(fe.nome_fantasia), ''),
        nullif(trim(fe.razao_social), '')
      ) || case
        when fcb.conta is not null then ' · conta ' || fcb.conta
        else ''
      end as conta_pagadora_label,
      t.descricao,
      coalesce(nullif(trim(t.estabelecimento), ''), ca.apelido) as contraparte,
      pc.codigo as plano_codigo,
      coalesce(pc.nome_completo, pc.nome) as plano_nome,
      case
        when pc.codigo = '3' or pc.codigo like '3.%' then 'entrada'
        when pc.codigo = '7.1' or pc.codigo like '7.1.%' then 'entrada'
        when split_part(coalesce(pc.codigo, ''), '.', 1) in ('4', '5', '6', '7') then 'saida'
        else null
      end as natureza,
      split_part(coalesce(pc.codigo, ''), '.', 1) as grupo_codigo,
      t.valor as valor_origem,
      case when pc.codigo = '7' or pc.codigo like '7.%' then 'fora_operacional' else 'operacional' end as escopo_dre,
      f.status as status_financeiro,
      case
        when f.status = 'cancelada' then 'cancelado'
        when t.plano_conta_id is null then 'sem_plano'
        when t.classificacao_status is distinct from 'confirmada' then 'em_revisao'
        when split_part(coalesce(pc.codigo, ''), '.', 1) not in ('3', '4', '5', '6', '7') then 'em_revisao'
        else 'classificado_dre'
      end as status_classificacao,
      null::integer as colaborador_id,
      -- O Cartao usa o centro confirmado da propria transacao, estruturalmente
      -- independente da conta pagadora. As 58 transacoes observadas em julho/2026
      -- coincidiram com a conta, mas essa coincidencia nao define a regra.
      case
        when t.classificacao_status = 'confirmada'
          and lower(nullif(trim(cc_cartao.codigo), '')) in ('cg', 'rec', 'bar')
          then lower(nullif(trim(cc_cartao.codigo), ''))
        else null
      end as unidade_operacional,
      case
        when t.classificacao_status = 'confirmada'
          and lower(nullif(trim(cc_cartao.codigo), '')) in ('cg', 'rec', 'bar')
          then 'exata'
        else null
      end as qualidade_unidade,
      case
        when t.classificacao_status is distinct from 'confirmada' then 'cartao_nao_confirmado'
        when t.classificacao_status = 'confirmada'
          and (
            lower(nullif(trim(cc_cartao.codigo), '')) is null
            or lower(nullif(trim(cc_cartao.codigo), '')) not in ('cg', 'rec', 'bar')
          ) then 'fonte_sem_unidade'
        else null
      end as motivo_sem_unidade
    from public.financeiro_cartao_transacoes t
    join public.financeiro_cartao_faturas f on f.id = t.fatura_id
    join public.financeiro_cartoes ca on ca.id = t.cartao_id
    left join public.contas_pagar cp_cartao on f.conta_pagar_id = cp_cartao.id
    left join public.plano_contas pc on pc.id = t.plano_conta_id
    left join public.centros_custo cc_cartao on cc_cartao.id = t.centro_custo_id
    left join public.financeiro_contas_bancarias fcb on fcb.id = ca.conta_pagadora_id
    left join public.financeiro_empresas fe on fe.id = fcb.empresa_id
    cross join parametros p
    where (
      p_regime = 'competencia'
      and f.competencia >= p.inicio
      and f.competencia < p.fim
    ) or (
      p_regime = 'caixa'
      and cp_cartao.status = 'pago'
      and cp_cartao.data_pagamento::date >= p.inicio
      and cp_cartao.data_pagamento::date < p.fim
    )
  ),
  contas_receber_raw as (
    select
      'contas_receber'::text as fonte,
      cr.id::text as origem_id,
      '000001'::text as origem_sequencia,
      cr.competencia as competencia_origem,
      cr.data_recebimento as data_caixa,
      case when p_regime = 'caixa' then cr.data_recebimento else cr.competencia end as data_referencia,
      null::uuid as conta_pagadora_id,
      null::text as conta_pagadora_label,
      cr.descricao,
      coalesce(nullif(trim(cr.aluno_nome), ''), 'Fatura Emusys #' || cr.emusys_fatura_id::text) as contraparte,
      pc.codigo as plano_codigo,
      coalesce(pc.nome_completo, pc.nome) as plano_nome,
      case
        when pc.codigo = '3' or pc.codigo like '3.%' then 'entrada'
        when pc.codigo = '7.1' or pc.codigo like '7.1.%' then 'entrada'
        when split_part(coalesce(pc.codigo, ''), '.', 1) in ('4', '5', '6', '7') then 'saida'
        else null
      end as natureza,
      split_part(coalesce(pc.codigo, ''), '.', 1) as grupo_codigo,
      case
        when p_regime = 'caixa' then coalesce(cr.valor_pago, 0)
        else cr.valor_liquido
      end as valor_origem,
      case when pc.codigo = '7' or pc.codigo like '7.%' then 'fora_operacional' else 'operacional' end as escopo_dre,
      cr.status as status_financeiro,
      case
        when cr.status = 'cancelado' then 'cancelado'
        when cr.excluido_da_receita or cr.classificacao_status = 'excluida' then 'excluido'
        when cr.status = 'revisar' /* source_missing */ then 'em_revisao'
        when cr.classificacao_status is distinct from 'confirmada'
          or cr.cadastro_match_status is distinct from 'unico' then 'em_revisao'
        when cr.plano_conta_id is null then 'sem_plano'
        when split_part(coalesce(pc.codigo, ''), '.', 1) not in ('3', '4', '5', '6', '7') then 'em_revisao'
        else 'classificado_dre'
      end as status_classificacao,
      null::integer as colaborador_id,
      case
        when lower(coalesce(nullif(trim(cc_cr.codigo), ''), nullif(trim(cr.unidade), ''))) in ('cg', 'rec', 'bar')
          then lower(coalesce(nullif(trim(cc_cr.codigo), ''), nullif(trim(cr.unidade), '')))
        else null
      end as unidade_operacional,
      case
        when lower(coalesce(nullif(trim(cc_cr.codigo), ''), nullif(trim(cr.unidade), ''))) in ('cg', 'rec', 'bar')
          then 'exata'
        else null
      end as qualidade_unidade,
      case
        when lower(coalesce(nullif(trim(cc_cr.codigo), ''), nullif(trim(cr.unidade), ''))) is null
          or lower(coalesce(nullif(trim(cc_cr.codigo), ''), nullif(trim(cr.unidade), ''))) not in ('cg', 'rec', 'bar')
          then 'fonte_sem_unidade'
        else null
      end as motivo_sem_unidade
    from public.contas_receber cr
    left join public.plano_contas pc on pc.id = cr.plano_conta_id
    left join public.centros_custo cc_cr on cc_cr.id = cr.centro_custo_id
    cross join parametros p
    where (
      p_regime = 'competencia'
      and cr.competencia >= p.inicio
      and cr.competencia < p.fim
    ) or (
      p_regime = 'caixa'
      and cr.status = 'recebido'
      and cr.data_recebimento >= p.inicio
      and cr.data_recebimento < p.fim
    )
  ),
  raw as (
    select * from folha_raw
    union all
    select * from contas_pagar_raw
    union all
    select * from cartao_raw
    union all
    select * from contas_receber_raw
  )
  select
    raw.fonte,
    raw.origem_id,
    raw.origem_sequencia,
    raw.competencia_origem,
    raw.data_caixa,
    raw.data_referencia,
    raw.conta_pagadora_id,
    raw.conta_pagadora_label,
    raw.descricao,
    raw.contraparte,
    raw.plano_codigo,
    raw.plano_nome,
    raw.natureza,
    raw.grupo_codigo,
    raw.valor_origem,
    case
      when raw.status_classificacao <> 'classificado_dre' then 0::numeric
      when raw.natureza = 'entrada' then raw.valor_origem
      else -raw.valor_origem
    end as valor_resultado,
    raw.escopo_dre,
    raw.status_financeiro,
    raw.status_classificacao,
    raw.colaborador_id,
    case
      when raw.unidade_operacional in ('cg', 'rec', 'bar') then raw.unidade_operacional
      else null
    end as unidade_operacional,
    case
      when raw.unidade_operacional in ('cg', 'rec', 'bar') then raw.qualidade_unidade
      else null
    end as qualidade_unidade,
    case
      when raw.unidade_operacional in ('cg', 'rec', 'bar') then null
      else coalesce(raw.motivo_sem_unidade, 'fonte_sem_unidade')
    end as motivo_sem_unidade
  from raw;
$_$;


