CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_arquivar"("p_payload" "jsonb", "p_ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
  v_ator_tipo text;
  v_ator_ref text;
  v_created_by uuid;
  v_actor jsonb;

  v_cartao_id uuid;
  v_ativo boolean;
  v_before public.financeiro_cartoes%rowtype;
  v_after public.financeiro_cartoes%rowtype;
  v_operacao text;
begin
  v_role := coalesce(nullif(auth.role(), ''), nullif(current_setting('request.jwt.claim.role', true), ''), session_user::text);

  if v_role = 'authenticated' then
    v_ator_tipo := 'web';
    v_created_by := auth.uid();
    v_ator_ref := coalesce(v_created_by::text, nullif(current_setting('request.jwt.claim.email', true), ''), 'authenticated');
  elsif v_role = 'service_role' then
    v_ator_tipo := coalesce(nullif(p_ator->>'ator_tipo', ''), nullif(p_ator->>'tipo', ''), 'sistema');
    if v_ator_tipo not in ('web','maria','openfinance','sistema') then
      raise exception 'ator_tipo nao permitido para service_role.';
    end if;
    v_ator_ref := coalesce(nullif(p_ator->>'ator_ref', ''), nullif(p_ator->>'ref', ''), v_ator_tipo);
  else
    raise exception 'papel nao autorizado para RPC de cartoes: %', v_role using errcode = '42501';
  end if;

  v_actor := jsonb_build_object(
    'role', v_role,
    'ator_tipo', v_ator_tipo,
    'ator_ref', v_ator_ref,
    'created_by', v_created_by
  );

  v_cartao_id := nullif(p_payload->>'cartao_id', '')::uuid;
  if v_cartao_id is null then
    raise exception 'cartao_id obrigatorio para arquivar cartao.';
  end if;

  v_ativo := coalesce(nullif(p_payload->>'ativo', '')::boolean, false);
  v_operacao := case when v_ativo then 'UNARCHIVE' else 'ARCHIVE' end;

  select * into v_before
    from public.financeiro_cartoes
   where id = v_cartao_id
   for update;

  if not found then
    raise exception 'cartao_id nao encontrado.';
  end if;

  update public.financeiro_cartoes
     set ativo = v_ativo,
         updated_at = now()
   where id = v_cartao_id
   returning * into v_after;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartoes',
    'cartao',
    v_after.id,
    case when v_ativo then 'UNARCHIVE' else 'ARCHIVE' end,
    to_jsonb(v_before),
    to_jsonb(v_after),
    p_payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'cartao_id', v_after.id,
    'ativo', v_after.ativo
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_arquivar"("p_payload" "jsonb", "p_ator" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financeiro_cartao_arquivar"("p_payload" "jsonb", "p_ator" "jsonb") IS 'Fase 3 Cartoes: arquiva/desarquiva cartao por toggle ativo, sem DELETE fisico.';



CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_ciclo"("p_cartao_id" "uuid", "p_data" "date") RETURNS TABLE("competencia" "date", "data_fechamento" "date", "data_vencimento" "date")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_dia_fechamento int;
  v_dia_vencimento int;
  v_fechamento_atual date;
  v_data_fechamento date;
  v_vencimento_mes date;
  v_data_vencimento date;
  v_mes_fechamento date;
begin
  if p_data is null then
    raise exception 'data da compra obrigatoria para ciclo de cartao.';
  end if;

  select dia_fechamento, dia_vencimento
    into v_dia_fechamento, v_dia_vencimento
    from public.financeiro_cartoes
   where id = p_cartao_id
     and ativo = true;

  if not found then
    raise exception 'cartao % nao encontrado ou inativo.', p_cartao_id;
  end if;

  if v_dia_fechamento is null or v_dia_vencimento is null then
    raise exception 'cartao % sem dia de fechamento/vencimento configurado.', p_cartao_id;
  end if;

  v_fechamento_atual := public.financeiro_cartao_clamp_dia(
    extract(year from p_data)::int,
    extract(month from p_data)::int,
    v_dia_fechamento
  );

  if p_data <= v_fechamento_atual then
    v_data_fechamento := v_fechamento_atual;
  else
    v_data_fechamento := public.financeiro_cartao_clamp_dia(
      extract(year from (date_trunc('month', p_data) + interval '1 month'))::int,
      extract(month from (date_trunc('month', p_data) + interval '1 month'))::int,
      v_dia_fechamento
    );
  end if;

  v_mes_fechamento := date_trunc('month', v_data_fechamento)::date;
  v_vencimento_mes := public.financeiro_cartao_clamp_dia(
    extract(year from v_mes_fechamento)::int,
    extract(month from v_mes_fechamento)::int,
    v_dia_vencimento
  );

  if v_vencimento_mes > v_data_fechamento then
    v_data_vencimento := v_vencimento_mes;
  else
    v_data_vencimento := public.financeiro_cartao_clamp_dia(
      extract(year from (v_mes_fechamento + interval '1 month'))::int,
      extract(month from (v_mes_fechamento + interval '1 month'))::int,
      v_dia_vencimento
    );
  end if;

  competencia := date_trunc('month', v_data_vencimento)::date;
  data_fechamento := v_data_fechamento;
  data_vencimento := v_data_vencimento;
  return next;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_ciclo"("p_cartao_id" "uuid", "p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_clamp_dia"("p_ano" integer, "p_mes" integer, "p_dia" integer) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select make_date(
    p_ano,
    p_mes,
    least(p_dia, extract(day from (date_trunc('month', make_date(p_ano, p_mes, 1)) + interval '1 month - 1 day'))::int)
  );
$$;


ALTER FUNCTION "public"."financeiro_cartao_clamp_dia"("p_ano" integer, "p_mes" integer, "p_dia" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_data_fechamento_por_competencia"("p_cartao_id" "uuid", "p_competencia" "date") RETURNS "date"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_dia_fechamento int;
  v_dia_vencimento int;
  v_competencia date;
  v_data_vencimento date;
  v_fechamento_mes date;
begin
  select dia_fechamento, dia_vencimento
    into v_dia_fechamento, v_dia_vencimento
    from public.financeiro_cartoes
   where id = p_cartao_id;

  if not found then
    raise exception 'cartao % nao encontrado.', p_cartao_id;
  end if;

  if v_dia_fechamento is null or v_dia_vencimento is null then
    raise exception 'cartao % sem dia de fechamento/vencimento configurado.', p_cartao_id;
  end if;

  v_competencia := date_trunc('month', p_competencia)::date;
  v_data_vencimento := public.financeiro_cartao_clamp_dia(
    extract(year from v_competencia)::int,
    extract(month from v_competencia)::int,
    v_dia_vencimento
  );
  v_fechamento_mes := public.financeiro_cartao_clamp_dia(
    extract(year from v_competencia)::int,
    extract(month from v_competencia)::int,
    v_dia_fechamento
  );

  if v_fechamento_mes < v_data_vencimento then
    return v_fechamento_mes;
  end if;

  return public.financeiro_cartao_clamp_dia(
    extract(year from (v_competencia - interval '1 month'))::int,
    extract(month from (v_competencia - interval '1 month'))::int,
    v_dia_fechamento
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_data_fechamento_por_competencia"("p_cartao_id" "uuid", "p_competencia" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_fatura_abrir"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_cartao_id uuid;
  v_cartao public.financeiro_cartoes%rowtype;
  v_data_compra date;
  v_competencia date;
  v_data_fechamento date;
  v_data_vencimento date;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_inserted int;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_cartao_id := nullif(payload->>'cartao_id', '')::uuid;
  if v_cartao_id is null then
    raise exception 'cartao_id obrigatorio para abrir fatura de cartao.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = v_cartao_id
     and ativo = true;
  if not found then
    raise exception 'cartao nao encontrado ou inativo.';
  end if;

  v_data_compra := nullif(payload->>'data_compra', '')::date;
  v_competencia := nullif(payload->>'competencia', '')::date;
  if v_data_compra is null and v_competencia is null then
    raise exception 'data_compra ou competencia obrigatoria para abrir fatura de cartao.';
  end if;

  if v_data_compra is not null then
    select c.competencia, c.data_fechamento, c.data_vencimento
      into v_competencia, v_data_fechamento, v_data_vencimento
      from public.financeiro_cartao_ciclo(v_cartao_id, v_data_compra) c;
  else
    v_competencia := date_trunc('month', v_competencia)::date;
    v_data_fechamento := public.financeiro_cartao_data_fechamento_por_competencia(v_cartao_id, v_competencia);
    v_data_vencimento := public.financeiro_cartao_clamp_dia(
      extract(year from v_competencia)::int,
      extract(month from v_competencia)::int,
      v_cartao.dia_vencimento
    );
  end if;

  insert into public.financeiro_cartao_faturas (
    cartao_id,
    competencia,
    data_fechamento,
    data_vencimento,
    valor_total,
    status,
    observacoes
  )
  values (
    v_cartao_id,
    v_competencia,
    v_data_fechamento,
    v_data_vencimento,
    0,
    'aberta',
    nullif(payload->>'observacoes', '')
  )
  on conflict (cartao_id, competencia) do nothing;

  get diagnostics v_inserted = row_count;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where cartao_id = v_cartao_id
     and competencia = v_competencia;
  if not found then
    raise exception 'falha ao resolver fatura de cartao.';
  end if;

  if v_inserted = 1 then
    perform public.financeiro_cartoes_audit_insert(
      v_actor,
      'financeiro_cartao_faturas',
      'cartao_fatura',
      v_fatura.id,
      'abrir_fatura_cartao',
      null,
      to_jsonb(v_fatura),
      payload->>'motivo'
    );
  end if;

  perform public.financeiro_cartao_recorrencias_gerar_previsoes(v_fatura.id, v_actor);

  return jsonb_build_object(
    'success', true,
    'fatura_id', v_fatura.id,
    'competencia', v_fatura.competencia,
    'data_fechamento', v_fatura.data_fechamento,
    'data_vencimento', v_fatura.data_vencimento,
    'status', v_fatura.status,
    'criada', v_inserted = 1
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_fatura_abrir"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_fatura_fechar"("p_fatura_id" "uuid", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_cartao public.financeiro_cartoes%rowtype;
  v_conta public.contas_pagar%rowtype;
  v_centro public.centros_custo%rowtype;
  v_total numeric;
  v_count_total int;
  v_count_confirmadas int;
  v_count_sugeridas int;
  v_count_pendentes int;
  v_dre_incompleto boolean;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = p_fatura_id
   for update;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  select
    count(*)::int as total,
    (count(*) filter (where classificacao_status = 'confirmada'))::int as confirmadas,
    (count(*) filter (where classificacao_status = 'sugerida'))::int as sugeridas,
    (count(*) filter (where classificacao_status = 'pendente'))::int as pendentes
    into v_count_total, v_count_confirmadas, v_count_sugeridas, v_count_pendentes
    from public.financeiro_cartao_transacoes
   where fatura_id = v_fatura.id;
  v_dre_incompleto := coalesce(v_count_sugeridas, 0) > 0 or coalesce(v_count_pendentes, 0) > 0;

  if v_fatura.conta_pagar_id is not null then
    select * into v_conta from public.contas_pagar where id = v_fatura.conta_pagar_id;
    return jsonb_build_object(
      'success', true,
      'idempotent', true,
      'fatura_id', v_fatura.id,
      'conta_pagar_id', v_fatura.conta_pagar_id,
      'status', v_fatura.status,
      'classificacao', jsonb_build_object(
        'total', v_count_total,
        'confirmadas', v_count_confirmadas,
        'sugeridas', v_count_sugeridas,
        'pendentes', v_count_pendentes,
        'dre_incompleto', v_dre_incompleto
      )
    );
  end if;

  if v_fatura.status not in ('aberta','fechada') then
    raise exception 'status da fatura nao permite fechamento: %', v_fatura.status;
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = v_fatura.cartao_id
   for update;
  if not found then
    raise exception 'cartao da fatura nao encontrado.';
  end if;

  if v_cartao.empresa_id is null or v_cartao.conta_pagadora_id is null or v_cartao.centro_custo_id is null then
    raise exception 'cartao sem empresa, conta pagadora ou centro; fechamento fiscal bloqueado.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = v_cartao.centro_custo_id;
  if not found then
    raise exception 'centro de custo do cartao nao encontrado.';
  end if;

  select coalesce(sum(valor), 0) into v_total
    from public.financeiro_cartao_transacoes
   where fatura_id = v_fatura.id;

  insert into public.contas_pagar (
    descricao,
    unidade,
    valor,
    data_lancamento,
    data_vencimento,
    competencia,
    status,
    data_pagamento,
    metodo_pagamento,
    tipo_lancamento,
    parcela_atual,
    total_parcelas,
    observacoes,
    fonte_tipo,
    plano_conta_id,
    centro_custo_id,
    empresa_id,
    conta_pagadora_id
  )
  values (
    concat('Fatura ', v_cartao.apelido, ' ', to_char(v_fatura.competencia, 'YYYY-MM')),
    v_centro.codigo,
    round(v_total, 2),
    (now() at time zone 'America/Sao_Paulo')::date,
    v_fatura.data_vencimento,
    date_trunc('month', v_fatura.competencia)::date,
    'pendente',
    null,
    null,
    'fatura_cartao',
    null,
    null,
    'Conta a pagar gerada pelo fechamento de fatura de cartao. DRE/plano somam as transacoes, nao esta fatura.',
    'cartao',
    null,
    v_cartao.centro_custo_id,
    v_cartao.empresa_id,
    v_cartao.conta_pagadora_id
  )
  returning * into v_conta;

  update public.financeiro_cartao_faturas
     set valor_total = round(v_total, 2),
         status = 'fechada',
         conta_pagar_id = v_conta.id,
         updated_at = now()
   where id = v_fatura.id
   returning * into v_fatura;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_faturas',
    'cartao_fatura',
    v_fatura.id,
    'fechar_fatura_cartao',
    null,
    to_jsonb(v_fatura),
    ator->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'fatura_id', v_fatura.id,
    'conta_pagar_id', v_conta.id,
    'valor_total', v_fatura.valor_total,
    'status', v_fatura.status,
    'classificacao', jsonb_build_object(
      'total', v_count_total,
      'confirmadas', v_count_confirmadas,
      'sugeridas', v_count_sugeridas,
      'pendentes', v_count_pendentes,
      'dre_incompleto', v_dre_incompleto
    )
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_fatura_fechar"("p_fatura_id" "uuid", "ator" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financeiro_cartao_fatura_fechar"("p_fatura_id" "uuid", "ator" "jsonb") IS 'Fase 2 Cartoes: fecha fatura e cria uma conta_pagar fatura_cartao, sem dupla contagem no DRE/plano.';



CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_fatura_reabrir"("p_fatura_id" "uuid", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_before public.financeiro_cartao_faturas%rowtype;
  v_after public.financeiro_cartao_faturas%rowtype;
  v_conta public.contas_pagar%rowtype;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);

  select * into v_before
    from public.financeiro_cartao_faturas
   where id = p_fatura_id
   for update;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  if v_before.status = 'paga' then
    raise exception 'fatura paga nao pode ser reaberta.';
  end if;

  if v_before.status <> 'fechada' then
    return jsonb_build_object('success', true, 'idempotent', true, 'fatura_id', v_before.id, 'status', v_before.status);
  end if;

  if v_before.conta_pagar_id is not null then
    select * into v_conta
      from public.contas_pagar
     where id = v_before.conta_pagar_id
     for update;

    if found and v_conta.status = 'pago' then
      raise exception 'conta_pagar da fatura ja esta paga; reabertura bloqueada.';
    end if;

    if found then
      update public.contas_pagar
         set status = 'cancelado',
             updated_at = now()
       where id = v_conta.id;
    end if;
  end if;

  update public.financeiro_cartao_faturas
     set status = 'aberta',
         conta_pagar_id = null,
         updated_at = now()
   where id = v_before.id
   returning * into v_after;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_faturas',
    'cartao_fatura',
    v_after.id,
    'reabrir_fatura_cartao',
    to_jsonb(v_before),
    to_jsonb(v_after),
    ator->>'motivo'
  );

  return jsonb_build_object('success', true, 'fatura_id', v_after.id, 'status', v_after.status);
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_fatura_reabrir"("p_fatura_id" "uuid", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_faturas_recalcula_valor"("p_fatura_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_fatura_id is null then
    return;
  end if;

  update public.financeiro_cartao_faturas
     set valor_total = (
           select round(coalesce(sum(valor), 0), 2)
             from public.financeiro_cartao_transacoes
            where fatura_id = p_fatura_id
         ),
         updated_at = now()
   where id = p_fatura_id;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_faturas_recalcula_valor"("p_fatura_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_faturas_sync_pagamento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.tipo_lancamento = 'fatura_cartao'
     and new.status = 'pago'
     and old.status is distinct from 'pago' then
    update public.financeiro_cartao_faturas
       set status = 'paga',
           updated_at = now()
     where conta_pagar_id = new.id
       and status <> 'paga';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_faturas_sync_pagamento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_faturas_sync_valor_total"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.financeiro_cartao_faturas_recalcula_valor(old.fatura_id);
    return old;
  end if;

  perform public.financeiro_cartao_faturas_recalcula_valor(new.fatura_id);

  if tg_op = 'UPDATE' and old.fatura_id is distinct from new.fatura_id then
    perform public.financeiro_cartao_faturas_recalcula_valor(old.fatura_id);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_faturas_sync_valor_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_lancamento_registrar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_cartao_id uuid;
  v_data_compra date;
  v_descricao text;
  v_estabelecimento text;
  v_tipo_transacao text;
  v_total_parcelas int;
  v_valor_total numeric;
  v_valor_parcela_base numeric;
  v_valor_parcela numeric;
  v_soma_parcial numeric := 0;
  v_idx int;
  v_data_parcela date;
  v_open jsonb;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_compra_parcelada_id uuid;
  v_client_token text;
  v_transacao_payload jsonb;
  v_transacao_result jsonb;
  v_existing_compra_parcelada_id uuid;
  v_parcelas jsonb := '[]'::jsonb;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_cartao_id := nullif(payload->>'cartao_id', '')::uuid;
  v_data_compra := nullif(payload->>'data_compra', '')::date;
  v_descricao := nullif(trim(payload->>'descricao'), '');
  v_estabelecimento := nullif(trim(payload->>'estabelecimento'), '');
  v_tipo_transacao := coalesce(nullif(payload->>'tipo_transacao', ''), 'compra');
  v_total_parcelas := coalesce(nullif(payload->>'total_parcelas', '')::int, 1);
  v_client_token := nullif(trim(payload->>'client_token'), '');

  if v_cartao_id is null then
    raise exception 'cartao_id obrigatorio para lancamento de cartao.';
  end if;
  if v_data_compra is null then
    raise exception 'data_compra obrigatoria para lancamento de cartao.';
  end if;
  if v_descricao is null then
    raise exception 'descricao obrigatoria para lancamento de cartao.';
  end if;
  if v_client_token is null then
    raise exception 'client_token obrigatorio para lancamento de cartao.';
  end if;
  if v_tipo_transacao not in ('compra','estorno','tarifa','anuidade','ajuste') then
    raise exception 'tipo_transacao invalido para lancamento de cartao.';
  end if;
  if v_total_parcelas < 1 then
    raise exception 'total_parcelas deve ser maior ou igual a 1.';
  end if;
  if v_total_parcelas > 1 and v_tipo_transacao <> 'compra' then
    raise exception 'total_parcelas > 1 permitido apenas para compra.';
  end if;

  if nullif(payload->>'valor_total', '') is not null and nullif(payload->>'valor_parcela', '') is not null then
    raise exception 'informe valor_total ou valor_parcela, nao ambos.';
  end if;
  if nullif(payload->>'valor_total', '') is null and nullif(payload->>'valor_parcela', '') is null then
    raise exception 'valor_total ou valor_parcela obrigatorio para lancamento de cartao.';
  end if;

  if nullif(payload->>'valor_total', '') is not null then
    v_valor_total := abs((payload->>'valor_total')::numeric);
    if v_valor_total = 0 then
      raise exception 'valor_total deve ser diferente de zero.';
    end if;
    v_valor_parcela_base := round(v_valor_total / v_total_parcelas, 2);
  else
    v_valor_parcela_base := abs((payload->>'valor_parcela')::numeric);
    if v_valor_parcela_base = 0 then
      raise exception 'valor_parcela deve ser diferente de zero.';
    end if;
    v_valor_total := round(v_valor_parcela_base * v_total_parcelas, 2);
  end if;

  if v_total_parcelas > 1 then
    v_compra_parcelada_id := gen_random_uuid();
  end if;

  for v_idx in 1..v_total_parcelas loop
    v_data_parcela := (v_data_compra + make_interval(months => v_idx - 1))::date;

    if nullif(payload->>'valor_total', '') is not null then
      if v_idx < v_total_parcelas then
        v_valor_parcela := v_valor_parcela_base;
        v_soma_parcial := v_soma_parcial + v_valor_parcela;
      else
        v_valor_parcela := round(v_valor_total - v_soma_parcial, 2);
      end if;
    else
      v_valor_parcela := v_valor_parcela_base;
    end if;

    if v_tipo_transacao = 'estorno' then
      v_valor_parcela := -abs(v_valor_parcela);
    elsif v_tipo_transacao in ('compra','tarifa','anuidade') then
      v_valor_parcela := abs(v_valor_parcela);
    end if;

    v_open := public.financeiro_cartao_fatura_abrir(
      jsonb_build_object('cartao_id', v_cartao_id, 'data_compra', v_data_parcela, 'motivo', payload->>'motivo'),
      ator
    );

    select * into v_fatura
      from public.financeiro_cartao_faturas
     where id = (v_open->>'fatura_id')::uuid
     for update;
    if not found then
      raise exception 'fatura alvo do lancamento de cartao nao encontrada.';
    end if;
    if v_fatura.status <> 'aberta' then
      raise exception 'fatura % nao esta aberta para lancamento de cartao.', v_fatura.id;
    end if;

    v_transacao_payload := jsonb_strip_nulls(jsonb_build_object(
      'fatura_id', v_fatura.id,
      'data_compra', v_data_parcela,
      'descricao', v_descricao,
      'estabelecimento', v_estabelecimento,
      'valor', v_valor_parcela,
      'tipo_transacao', v_tipo_transacao,
      'plano_conta_id', nullif(payload->>'plano_conta_id', ''),
      'centro_custo_id', nullif(payload->>'centro_custo_id', ''),
      'empresa_id', nullif(payload->>'empresa_id', ''),
      'classificacao_status', nullif(payload->>'classificacao_status', ''),
      'compra_parcelada_id', v_compra_parcelada_id,
      'parcela_atual', case when v_total_parcelas > 1 then v_idx else null end,
      'total_parcelas', case when v_total_parcelas > 1 then v_total_parcelas else null end,
      'valor_total_compra', case when v_total_parcelas > 1 then v_valor_total else null end,
      'id_externo', concat(v_client_token, '-', v_idx, '/', v_total_parcelas),
      'fonte_tipo', coalesce(nullif(payload->>'fonte_tipo', ''), v_actor->>'ator_tipo'),
      'observacoes', nullif(payload->>'observacoes', ''),
      'motivo', payload->>'motivo'
    ));

    v_transacao_result := public.financeiro_cartao_transacao_registrar(v_transacao_payload, ator);
    if coalesce((v_transacao_result->>'idempotent')::boolean, false) then
      select compra_parcelada_id
        into v_existing_compra_parcelada_id
        from public.financeiro_cartao_transacoes
       where id = (v_transacao_result->>'transacao_id')::uuid;

      if v_existing_compra_parcelada_id is not null then
        v_compra_parcelada_id := v_existing_compra_parcelada_id;
      end if;
    end if;

    v_parcelas := v_parcelas || jsonb_build_array(jsonb_build_object(
      'parcela', v_idx,
      'fatura_id', v_fatura.id,
      'competencia', v_fatura.competencia,
      'valor', v_valor_parcela,
      'transacao_id', v_transacao_result->>'transacao_id',
      'idempotent', coalesce((v_transacao_result->>'idempotent')::boolean, false)
    ));
  end loop;

  return jsonb_build_object(
    'success', true,
    'compra_parcelada_id', v_compra_parcelada_id,
    'total_parcelas', v_total_parcelas,
    'valor_total', case when v_tipo_transacao = 'estorno' then -abs(v_valor_total) else v_valor_total end,
    'parcelas', v_parcelas
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_lancamento_registrar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_adotar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor jsonb;
  v_transacao public.financeiro_cartao_transacoes%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_recorrencia public.financeiro_cartao_recorrencias%rowtype;
  v_previsao_id uuid;
  v_transacao_id uuid;
  v_data_inicio date;
  v_dia_base smallint;
  v_descricao text;
  v_estabelecimento text;
  v_valor numeric;
  v_empresa_id uuid;
  v_plano_conta_id uuid;
  v_centro_custo_id uuid;
  v_classificacao_status text;
  v_mes_candidato date;
  v_proxima_data date;
  v_candidato_competencia date;
  v_next_open jsonb;
  v_idx integer;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_transacao_id := nullif(payload->>'transacao_id', '')::uuid;
  if v_transacao_id is null then
    raise exception 'transacao_id obrigatorio para tornar compra recorrente.';
  end if;

  select * into v_transacao
    from public.financeiro_cartao_transacoes
   where id = v_transacao_id;
  if not found then
    raise exception 'transacao de cartao nao encontrada.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_transacao.cartao_id::text, 0));

  select * into v_transacao
    from public.financeiro_cartao_transacoes
   where id = v_transacao_id
   for update;
  if not found then
    raise exception 'transacao de cartao nao encontrada.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_transacao.fatura_id
   for update;
  if not found then
    raise exception 'fatura de origem da compra nao encontrada.';
  end if;

  select * into v_recorrencia
    from public.financeiro_cartao_recorrencias
   where transacao_origem_id = v_transacao.id
   for update;
  if found then
    select id into v_previsao_id
      from public.financeiro_cartao_recorrencia_previsoes
     where recorrencia_id = v_recorrencia.id
       and competencia > v_fatura.competencia
     order by competencia
     limit 1;
    return jsonb_build_object(
      'success', true,
      'transacao_id', v_transacao.id,
      'recorrencia_id', v_recorrencia.id,
      'previsao_id', v_previsao_id,
      'idempotent', true
    );
  end if;

  if v_fatura.status <> 'aberta' then
    raise exception 'A fatura precisa estar aberta para criar a recorrencia.';
  end if;
  if v_transacao.tipo_transacao <> 'compra' then
    raise exception 'Somente compras podem ser transformadas em recorrentes.';
  end if;
  if v_transacao.compra_parcelada_id is not null
     or coalesce(v_transacao.total_parcelas, 1) > 1
     or v_transacao.parcela_atual is not null then
    raise exception 'Compras parceladas nao podem ser transformadas em recorrentes.';
  end if;

  v_data_inicio := coalesce(nullif(payload->>'data_inicio', '')::date, v_transacao.data_compra);
  v_dia_base := coalesce(nullif(payload->>'dia_base', '')::smallint, extract(day from v_data_inicio)::smallint);
  if v_dia_base < 1 or v_dia_base > 31 then
    raise exception 'dia_base deve estar entre 1 e 31.';
  end if;

  v_descricao := coalesce(nullif(trim(payload->>'descricao'), ''), nullif(trim(v_transacao.descricao), ''));
  if v_descricao is null then
    raise exception 'descricao obrigatoria para recorrencia de cartao.';
  end if;
  v_estabelecimento := coalesce(
    nullif(trim(payload->>'estabelecimento'), ''),
    nullif(trim(v_transacao.estabelecimento), '')
  );
  if lower(trim(coalesce(payload->>'valor', v_transacao.valor::text))) in ('nan', 'infinity', '+infinity', '-infinity') then
    raise exception 'valor invalido para criar recorrencia.';
  end if;
  v_valor := round(abs(coalesce(nullif(payload->>'valor', '')::numeric, v_transacao.valor)), 2);
  if v_valor is null or v_valor <= 0 then
    raise exception 'valor deve ser maior que zero para recorrencia de cartao.';
  end if;

  v_empresa_id := coalesce(nullif(payload->>'empresa_id', '')::uuid, v_transacao.empresa_id);
  v_plano_conta_id := coalesce(nullif(payload->>'plano_conta_id', '')::uuid, v_transacao.plano_conta_id);
  v_centro_custo_id := coalesce(nullif(payload->>'centro_custo_id', '')::uuid, v_transacao.centro_custo_id);
  v_classificacao_status := coalesce(
    nullif(payload->>'classificacao_status', ''),
    v_transacao.classificacao_status,
    'pendente'
  );
  if v_classificacao_status not in ('pendente', 'sugerida', 'confirmada') then
    raise exception 'classificacao_status invalido para recorrencia de cartao.';
  end if;
  if v_classificacao_status = 'confirmada'
     and (v_empresa_id is null or v_plano_conta_id is null or v_centro_custo_id is null) then
    raise exception 'empresa_id, plano_conta_id e centro_custo_id obrigatorios para classificacao confirmada.';
  end if;

  insert into public.financeiro_cartao_recorrencias (
    cartao_id,
    transacao_origem_id,
    data_inicio,
    dia_base,
    descricao,
    estabelecimento,
    valor,
    empresa_id,
    plano_conta_id,
    centro_custo_id,
    classificacao_status,
    ator_tipo,
    ator_ref,
    created_by
  ) values (
    v_transacao.cartao_id,
    v_transacao.id,
    v_data_inicio,
    v_dia_base,
    v_descricao,
    v_estabelecimento,
    v_valor,
    v_empresa_id,
    v_plano_conta_id,
    v_centro_custo_id,
    v_classificacao_status,
    v_actor->>'ator_tipo',
    v_actor->>'ator_ref',
    nullif(v_actor->>'created_by', '')::uuid
  )
  returning * into v_recorrencia;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_recorrencias',
    'cartao_recorrencia',
    v_recorrencia.id,
    'adotar_recorrencia_cartao',
    null,
    to_jsonb(v_recorrencia),
    payload->>'motivo'
  );

  v_mes_candidato := date_trunc('month', v_data_inicio + interval '1 month')::date;
  for v_idx in 1..24 loop
    v_proxima_data := public.financeiro_cartao_clamp_dia(
      extract(year from v_mes_candidato)::int,
      extract(month from v_mes_candidato)::int,
      v_dia_base
    );
    select c.competencia
      into v_candidato_competencia
      from public.financeiro_cartao_ciclo(v_transacao.cartao_id, v_proxima_data) c;
    if v_candidato_competencia <= v_fatura.competencia then
      v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
      continue;
    end if;

    v_next_open := public.financeiro_cartao_fatura_abrir(
      jsonb_build_object(
        'cartao_id', v_transacao.cartao_id,
        'data_compra', v_proxima_data,
        'motivo', payload->>'motivo'
      ),
      ator
    );
    if coalesce(v_next_open->>'status', '') <> 'aberta' then
      v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
      continue;
    end if;

    select id into v_previsao_id
      from public.financeiro_cartao_recorrencia_previsoes
     where recorrencia_id = v_recorrencia.id
       and fatura_id = nullif(v_next_open->>'fatura_id', '')::uuid
       and competencia > v_fatura.competencia
     limit 1;
    if v_previsao_id is not null then
      exit;
    end if;
    v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
  end loop;

  if v_previsao_id is null then
    raise exception 'nao foi possivel gerar previsao na proxima fatura aberta.';
  end if;

  return jsonb_build_object(
    'success', true,
    'transacao_id', v_transacao.id,
    'recorrencia_id', v_recorrencia.id,
    'previsao_id', v_previsao_id,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_adotar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_alterar_status"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_id uuid;
  v_novo_status text;
  v_motivo text;
  v_before public.financeiro_cartao_recorrencias%rowtype;
  v_recorrencia public.financeiro_cartao_recorrencias%rowtype;
  v_after public.financeiro_cartao_recorrencias%rowtype;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_id := nullif(payload->>'recorrencia_id', '')::uuid;
  if v_id is null then
    raise exception 'recorrencia_id obrigatorio para alterar status.';
  end if;
  v_novo_status := coalesce(nullif(payload->>'status', ''), nullif(payload->>'novo_status', ''));
  if v_novo_status not in ('ativa', 'pausada', 'encerrada') then
    raise exception 'status de recorrencia invalido.';
  end if;
  v_motivo := nullif(trim(payload->>'motivo'), '');

  select * into v_recorrencia
    from public.financeiro_cartao_recorrencias
   where id = v_id;
  if not found then
    raise exception 'recorrencia de cartao nao encontrada.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_recorrencia.cartao_id::text, 0));
  select * into v_before
    from public.financeiro_cartao_recorrencias
   where id = v_id
   for update;
  if not found then
    raise exception 'recorrencia de cartao nao encontrada.';
  end if;
  v_recorrencia := v_before;

  if v_novo_status = 'ativa' then
    if v_recorrencia.status = 'pausada' then
      null;
    else
      raise exception 'somente recorrencia pausada pode ser retomada.';
    end if;
  end if;
  if v_novo_status = 'pausada' and v_recorrencia.status not in ('ativa', 'pausada') then
    raise exception 'recorrencia encerrada nao pode ser pausada.';
  end if;
  if v_novo_status = 'encerrada' and v_recorrencia.status = 'encerrada' then
    return jsonb_build_object('success', true, 'recorrencia_id', v_before.id, 'status', v_before.status, 'idempotent', true);
  end if;

  update public.financeiro_cartao_recorrencias
     set status = v_novo_status,
         pausada_em = case when v_novo_status = 'pausada' then coalesce(pausada_em, now()) else pausada_em end,
         encerrada_em = case when v_novo_status = 'encerrada' then coalesce(encerrada_em, now()) else encerrada_em end,
         motivo_status = coalesce(v_motivo, motivo_status),
         ator_tipo = v_actor->>'ator_tipo',
         ator_ref = v_actor->>'ator_ref',
         updated_at = now()
   where id = v_before.id
   returning * into v_after;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_recorrencias',
    'cartao_recorrencia',
    v_after.id,
    'alterar_status_recorrencia_cartao',
    to_jsonb(v_before),
    to_jsonb(v_after),
    v_motivo
  );

  return jsonb_build_object(
    'success', true,
    'recorrencia_id', v_after.id,
    'status', v_after.status,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_alterar_status"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_atualizar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_id uuid;
  v_competencia_efetiva date;
  v_recorrencia public.financeiro_cartao_recorrencias%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_before public.financeiro_cartao_recorrencias%rowtype;
  v_after public.financeiro_cartao_recorrencias%rowtype;
  v_classificacao_status text;
  v_descricao text;
  v_estabelecimento text;
  v_valor numeric;
  v_dia_base smallint;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_id := nullif(payload->>'recorrencia_id', '')::uuid;
  if v_id is null then
    raise exception 'recorrencia_id obrigatorio para atualizar recorrencia.';
  end if;
  v_competencia_efetiva := date_trunc('month', nullif(payload->>'competencia_efetiva', '')::date)::date;
  if v_competencia_efetiva is null then
    raise exception 'competencia_efetiva obrigatoria para atualizar recorrencia.';
  end if;

  select * into v_recorrencia
    from public.financeiro_cartao_recorrencias
   where id = v_id;
  if not found then
    raise exception 'recorrencia de cartao nao encontrada.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_recorrencia.cartao_id::text, 0));
  select * into v_before
    from public.financeiro_cartao_recorrencias
   where id = v_id
   for update;
  if not found then
    raise exception 'recorrencia de cartao nao encontrada.';
  end if;
  v_recorrencia := v_before;

  if payload ? 'descricao' then
    v_descricao := nullif(trim(payload->>'descricao'), '');
    if v_descricao is null then
      raise exception 'descricao obrigatoria para atualizar recorrencia.';
    end if;
  else
    v_descricao := v_before.descricao;
  end if;
  if payload ? 'estabelecimento' then
    v_estabelecimento := nullif(trim(payload->>'estabelecimento'), '');
  else
    v_estabelecimento := v_before.estabelecimento;
  end if;
  if payload ? 'valor' then
    if lower(trim(coalesce(payload->>'valor', ''))) in ('nan', 'infinity', '+infinity', '-infinity') then
      raise exception 'valor invalido para atualizar recorrencia.';
    end if;
    v_valor := round(nullif(payload->>'valor', '')::numeric, 2);
  else
    v_valor := round(v_before.valor, 2);
  end if;
  if v_valor is null or v_valor <= 0 then
    raise exception 'valor deve ser maior que zero para atualizar recorrencia.';
  end if;
  v_dia_base := coalesce(nullif(payload->>'dia_base', '')::smallint, v_before.dia_base);
  if v_dia_base < 1 or v_dia_base > 31 then
    raise exception 'dia_base deve estar entre 1 e 31.';
  end if;

  v_classificacao_status := coalesce(nullif(payload->>'classificacao_status', ''), v_before.classificacao_status);
  if v_classificacao_status not in ('pendente', 'sugerida', 'confirmada') then
    raise exception 'classificacao_status invalido para recorrencia de cartao.';
  end if;
  if v_classificacao_status = 'confirmada' then
    if (case when payload ? 'empresa_id' then nullif(payload->>'empresa_id', '')::uuid else v_before.empresa_id end) is null
       or (case when payload ? 'plano_conta_id' then nullif(payload->>'plano_conta_id', '')::uuid else v_before.plano_conta_id end) is null
       or (case when payload ? 'centro_custo_id' then nullif(payload->>'centro_custo_id', '')::uuid else v_before.centro_custo_id end) is null then
      raise exception 'empresa_id, plano_conta_id e centro_custo_id obrigatorios para classificacao confirmada.';
    end if;
  end if;

  update public.financeiro_cartao_recorrencias
     set descricao = v_descricao,
         estabelecimento = v_estabelecimento,
         valor = v_valor,
         dia_base = v_dia_base,
         empresa_id = case when payload ? 'empresa_id' then nullif(payload->>'empresa_id', '')::uuid else empresa_id end,
         plano_conta_id = case when payload ? 'plano_conta_id' then nullif(payload->>'plano_conta_id', '')::uuid else plano_conta_id end,
         centro_custo_id = case when payload ? 'centro_custo_id' then nullif(payload->>'centro_custo_id', '')::uuid else centro_custo_id end,
         classificacao_status = v_classificacao_status,
         updated_at = now()
   where id = v_before.id
   returning * into v_after;

  update public.financeiro_cartao_recorrencia_previsoes
     set descricao = v_after.descricao,
         estabelecimento = v_after.estabelecimento,
         valor = v_after.valor,
         empresa_id = v_after.empresa_id,
         plano_conta_id = v_after.plano_conta_id,
         centro_custo_id = v_after.centro_custo_id,
         classificacao_status = v_after.classificacao_status,
         updated_at = now()
   where recorrencia_id = v_recorrencia.id
     and status = 'prevista'
     and fatura_id in (
       select id
         from public.financeiro_cartao_faturas
        where cartao_id = v_recorrencia.cartao_id
          and status = 'aberta'
          and competencia >= v_competencia_efetiva
     );

  for v_fatura in
    select *
      from public.financeiro_cartao_faturas
     where cartao_id = v_recorrencia.cartao_id
       and status = 'aberta'
       and competencia >= v_competencia_efetiva
     order by competencia
  loop
    perform public.financeiro_cartao_recorrencias_gerar_previsoes(v_fatura.id, v_actor);
  end loop;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_recorrencias',
    'cartao_recorrencia',
    v_after.id,
    'atualizar_recorrencia_cartao',
    to_jsonb(v_before),
    to_jsonb(v_after),
    payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'recorrencia_id', v_after.id,
    'competencia_efetiva', v_competencia_efetiva,
    'status', v_after.status
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_atualizar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_criar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_recorrencia public.financeiro_cartao_recorrencias%rowtype;
  v_transacao public.financeiro_cartao_transacoes%rowtype;
  v_transacao_result jsonb;
  v_next_open jsonb;
  v_cartao_id uuid;
  v_fatura_id uuid;
  v_transacao_id uuid;
  v_previsao_id uuid;
  v_data_compra date;
  v_data_compra_competencia date;
  v_proxima_data date;
  v_mes_candidato date;
  v_candidato_competencia date;
  v_descricao text;
  v_estabelecimento text;
  v_tipo text;
  v_valor numeric;
  v_dia_base smallint;
  v_client_token text;
  v_id_externo text;
  v_classificacao_status text;
  v_is_parcela boolean;
  v_idempotent boolean := false;
  v_idx integer;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_fatura_id := nullif(payload->>'fatura_id', '')::uuid;
  if v_fatura_id is null then
    raise exception 'fatura_id obrigatorio para recorrencia de cartao.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_fatura_id;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  v_cartao_id := nullif(payload->>'cartao_id', '')::uuid;
  if v_cartao_id is not null and v_cartao_id <> v_fatura.cartao_id then
    raise exception 'cartao da recorrencia nao corresponde a fatura.';
  end if;
  v_cartao_id := v_fatura.cartao_id;

  perform pg_advisory_xact_lock(hashtextextended(v_cartao_id::text, 0));
  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_fatura_id
   for update;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  v_client_token := nullif(trim(payload->>'client_token'), '');
  if v_client_token is null then
    raise exception 'client_token obrigatorio para recorrencia de cartao.';
  end if;
  if nullif(trim(payload->>'id_externo'), '') is not null
     and nullif(trim(payload->>'id_externo'), '') <> v_client_token then
    raise exception 'id_externo deve ser igual ao client_token para recorrencia de cartao.';
  end if;
  v_id_externo := v_client_token;

  select * into v_transacao
    from public.financeiro_cartao_transacoes
   where cartao_id = v_cartao_id
     and id_externo = v_id_externo
   limit 1;
  if found then
    if v_transacao.fatura_id <> v_fatura.id then
      raise exception 'client_token ja vinculado a outra fatura do mesmo cartao.';
    end if;
    select * into v_recorrencia
      from public.financeiro_cartao_recorrencias
     where transacao_origem_id = v_transacao.id
     for update;
    if found then
      select id into v_previsao_id
        from public.financeiro_cartao_recorrencia_previsoes
       where recorrencia_id = v_recorrencia.id
         and competencia > v_fatura.competencia
       order by competencia
       limit 1;
      return jsonb_build_object(
        'success', true,
        'transacao_id', v_transacao.id,
        'recorrencia_id', v_recorrencia.id,
        'previsao_id', v_previsao_id,
        'idempotent', true
      );
    end if;
  end if;

  if v_fatura.status <> 'aberta' then
    raise exception 'fatura de cartao deve estar aberta para criar recorrencia.';
  end if;

  v_tipo := coalesce(nullif(payload->>'tipo_transacao', ''), 'compra');
  if v_tipo = 'compra' then
    null;
  else
    raise exception 'recorrencia de cartao aceita somente tipo compra.';
  end if;

  v_is_parcela := coalesce(nullif(payload->>'is_parcela', '')::boolean, false)
    or coalesce(nullif(payload->>'total_parcelas', '')::int, 1) > 1
    or nullif(payload->>'compra_parcelada_id', '') is not null
    or nullif(payload->>'parcela_atual', '') is not null;
  if v_is_parcela is not true then
    null;
  else
    raise exception 'recorrencia de cartao nao pode ser parcelada.';
  end if;

  v_data_compra := nullif(payload->>'data_compra', '')::date;
  if v_data_compra is null then
    raise exception 'data_compra obrigatoria para recorrencia de cartao.';
  end if;
  select c.competencia
    into v_data_compra_competencia
    from public.financeiro_cartao_ciclo(v_cartao_id, v_data_compra) c;
  if v_data_compra_competencia is distinct from v_fatura.competencia then
    raise exception 'data_compra nao pertence a competencia da fatura.';
  end if;
  v_descricao := nullif(trim(payload->>'descricao'), '');
  if v_descricao is null then
    raise exception 'descricao obrigatoria para recorrencia de cartao.';
  end if;
  v_estabelecimento := nullif(trim(payload->>'estabelecimento'), '');
  if lower(trim(coalesce(payload->>'valor', ''))) in ('nan', 'infinity', '+infinity', '-infinity') then
    raise exception 'valor invalido para criar recorrencia.';
  end if;
  v_valor := round(nullif(payload->>'valor', '')::numeric, 2);
  if v_valor is null or v_valor <= 0 then
    raise exception 'valor deve ser maior que zero para recorrencia de cartao.';
  end if;
  v_dia_base := coalesce(nullif(payload->>'dia_base', '')::smallint, extract(day from v_data_compra)::smallint);
  if v_dia_base < 1 or v_dia_base > 31 then
    raise exception 'dia_base deve estar entre 1 e 31.';
  end if;

  v_classificacao_status := coalesce(nullif(payload->>'classificacao_status', ''), 'pendente');
  if v_classificacao_status not in ('pendente', 'sugerida', 'confirmada') then
    raise exception 'classificacao_status invalido para recorrencia de cartao.';
  end if;
  if v_classificacao_status = 'confirmada' then
    if nullif(payload->>'empresa_id', '') is null
       or nullif(payload->>'plano_conta_id', '') is null
       or nullif(payload->>'centro_custo_id', '') is null then
      raise exception 'empresa_id, plano_conta_id e centro_custo_id obrigatorios para classificacao confirmada.';
    end if;
  end if;

  v_transacao_result := public.financeiro_cartao_transacao_registrar(
    jsonb_strip_nulls(jsonb_build_object(
      'fatura_id', v_fatura.id,
      'cartao_id', v_cartao_id,
      'data_compra', v_data_compra,
      'descricao', v_descricao,
      'estabelecimento', v_estabelecimento,
      'valor', v_valor,
      'tipo_transacao', v_tipo,
      'empresa_id', nullif(payload->>'empresa_id', ''),
      'plano_conta_id', nullif(payload->>'plano_conta_id', ''),
      'centro_custo_id', nullif(payload->>'centro_custo_id', ''),
      'classificacao_status', v_classificacao_status,
      'id_externo', v_id_externo,
      'fonte_tipo', coalesce(nullif(payload->>'fonte_tipo', ''), v_actor->>'ator_tipo'),
      'observacoes', nullif(payload->>'observacoes', ''),
      'motivo', payload->>'motivo'
    )),
    ator
  );
  v_transacao_id := nullif(v_transacao_result->>'transacao_id', '')::uuid;
  if v_transacao_id is null then
    raise exception 'transacao de origem nao retornada.';
  end if;
  v_idempotent := coalesce((v_transacao_result->>'idempotent')::boolean, false);

  select * into v_recorrencia
    from public.financeiro_cartao_recorrencias
   where transacao_origem_id = v_transacao_id
   for update;
  if found then
    select id into v_previsao_id
      from public.financeiro_cartao_recorrencia_previsoes
     where recorrencia_id = v_recorrencia.id
       and competencia > v_fatura.competencia
     order by competencia
     limit 1;
    return jsonb_build_object(
      'success', true,
      'transacao_id', v_transacao_id,
      'recorrencia_id', v_recorrencia.id,
      'previsao_id', v_previsao_id,
      'idempotent', true
    );
  end if;
  if v_idempotent then
    raise exception 'id_externo ja esta associado a transacao sem recorrencia.';
  end if;

  insert into public.financeiro_cartao_recorrencias (
    cartao_id,
    transacao_origem_id,
    data_inicio,
    dia_base,
    descricao,
    estabelecimento,
    valor,
    empresa_id,
    plano_conta_id,
    centro_custo_id,
    classificacao_status,
    ator_tipo,
    ator_ref,
    created_by
  )
  values (
    v_cartao_id,
    v_transacao_id,
    v_data_compra,
    v_dia_base,
    v_descricao,
    v_estabelecimento,
    v_valor,
    nullif(payload->>'empresa_id', '')::uuid,
    nullif(payload->>'plano_conta_id', '')::uuid,
    nullif(payload->>'centro_custo_id', '')::uuid,
    v_classificacao_status,
    v_actor->>'ator_tipo',
    v_actor->>'ator_ref',
    nullif(v_actor->>'created_by', '')::uuid
  )
  returning * into v_recorrencia;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_recorrencias',
    'cartao_recorrencia',
    v_recorrencia.id,
    'criar_recorrencia_cartao',
    null,
    to_jsonb(v_recorrencia),
    payload->>'motivo'
  );

  v_mes_candidato := date_trunc('month', v_data_compra + interval '1 month')::date;
  v_previsao_id := null;
  for v_idx in 1..24 loop
    v_proxima_data := public.financeiro_cartao_clamp_dia(
      extract(year from v_mes_candidato)::int,
      extract(month from v_mes_candidato)::int,
      v_dia_base
    );
    select c.competencia
      into v_candidato_competencia
      from public.financeiro_cartao_ciclo(v_cartao_id, v_proxima_data) c;
    if v_candidato_competencia <= v_fatura.competencia then
      v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
      continue;
    end if;

    v_next_open := public.financeiro_cartao_fatura_abrir(
      jsonb_build_object(
        'cartao_id', v_cartao_id,
        'data_compra', v_proxima_data,
        'motivo', payload->>'motivo'
      ),
      ator
    );
    if coalesce(v_next_open->>'status', '') <> 'aberta' then
      v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
      continue;
    end if;

    select id into v_previsao_id
      from public.financeiro_cartao_recorrencia_previsoes
     where recorrencia_id = v_recorrencia.id
       and fatura_id = nullif(v_next_open->>'fatura_id', '')::uuid
       and competencia > v_fatura.competencia
     limit 1;
    if v_previsao_id is not null then
      exit;
    end if;
    v_mes_candidato := (v_mes_candidato + interval '1 month')::date;
  end loop;
  if v_previsao_id is null then
    raise exception 'nao foi possivel gerar previsao na proxima fatura aberta.';
  end if;

  return jsonb_build_object(
    'success', true,
    'transacao_id', v_transacao_id,
    'recorrencia_id', v_recorrencia.id,
    'previsao_id', v_previsao_id,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_criar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_origem_bloqueia_cancelamento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if exists (
    select 1
      from public.financeiro_cartao_recorrencias
     where transacao_origem_id = old.id
  ) then
    raise exception 'Compra de origem de recorrÃªncia nÃ£o pode ser cancelada; encerre a regra e registre o ajuste/estorno separadamente.';
  end if;
  return old;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_origem_bloqueia_cancelamento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencia_previsao_decidir_vinculo"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_previsao_id uuid;
  v_transacao_id uuid;
  v_decisao text;
  v_before public.financeiro_cartao_recorrencia_previsoes%rowtype;
  v_after public.financeiro_cartao_recorrencia_previsoes%rowtype;
  v_transacao public.financeiro_cartao_transacoes%rowtype;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_previsao_id := nullif(payload->>'previsao_id', '')::uuid;
  v_transacao_id := nullif(payload->>'transacao_id', '')::uuid;
  v_decisao := nullif(payload->>'decisao', '');
  if v_previsao_id is null or v_transacao_id is null then
    raise exception 'previsao_id e transacao_id obrigatorios para decidir vinculo.';
  end if;
  if v_decisao not in ('confirmar', 'manter_separadas') then
    raise exception 'decisao de vinculo invalida.';
  end if;

  select * into v_before
    from public.financeiro_cartao_recorrencia_previsoes
   where id = v_previsao_id
   for update;
  if not found then
    raise exception 'previsao de recorrencia nao encontrada.';
  end if;
  if v_before.status <> 'prevista' then
    raise exception 'previsao de recorrencia ja foi decidida.';
  end if;

  select * into v_transacao
    from public.financeiro_cartao_transacoes
   where id = v_transacao_id
   for update;
  if not found then
    raise exception 'transacao real nao encontrada para vinculo.';
  end if;
  if v_before.cartao_id <> v_transacao.cartao_id
     or v_before.fatura_id <> v_transacao.fatura_id then
    raise exception 'previsao e transacao devem pertencer a mesma fatura e cartao.';
  end if;

  if v_decisao = 'confirmar' then
    update public.financeiro_cartao_recorrencia_previsoes
       set status = 'confirmada',
           transacao_confirmada_id = v_transacao.id,
           decidida_em = now(),
           decidida_por = v_actor->>'ator_tipo',
           motivo_decisao = nullif(payload->>'motivo', ''),
           updated_at = now()
     where id = v_before.id
     returning * into v_after;
  else
    update public.financeiro_cartao_recorrencia_previsoes
       set status = 'dispensada',
           decidida_em = now(),
           decidida_por = v_actor->>'ator_tipo',
           motivo_decisao = coalesce(nullif(payload->>'motivo', ''), 'Mantidas separadas por decisÃ£o operacional.'),
           updated_at = now()
     where id = v_before.id
     returning * into v_after;
  end if;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_recorrencia_previsoes',
    'cartao_recorrencia_previsao',
    v_after.id,
    case when v_decisao = 'confirmar' then 'confirmar_vinculo_recorrencia' else 'manter_previsao_separada' end,
    to_jsonb(v_before),
    to_jsonb(v_after),
    payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'previsao_id', v_after.id,
    'transacao_id', v_transacao.id,
    'status', v_after.status,
    'decisao', v_decisao
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencia_previsao_decidir_vinculo"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_recorrencias_gerar_previsoes"("p_fatura_id" "uuid", "p_ator" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_recorrencia public.financeiro_cartao_recorrencias%rowtype;
  v_previsao public.financeiro_cartao_recorrencia_previsoes%rowtype;
  v_actor jsonb := coalesce(p_ator, '{}'::jsonb);
  v_competencia_candidata date;
  v_data_ocorrencia date;
  v_competencia_ciclo date;
  v_origem_competencia date;
  v_offset integer;
  v_total integer := 0;
  v_inserted integer;
begin
  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = p_fatura_id;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_fatura.cartao_id::text, 0));
  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = p_fatura_id
   for update;
  if not found then
    raise exception 'fatura de cartao nao encontrada.';
  end if;

  if v_fatura.status <> 'aberta' then
    return 0;
  end if;

  for v_recorrencia in
    select *
      from public.financeiro_cartao_recorrencias
     where cartao_id = v_fatura.cartao_id
       and status = 'ativa'
     order by id
  loop
    select f.competencia
      into v_origem_competencia
      from public.financeiro_cartao_transacoes t
      join public.financeiro_cartao_faturas f on f.id = t.fatura_id
     where t.id = v_recorrencia.transacao_origem_id;
    if v_origem_competencia is null then
      raise exception 'fatura de origem da recorrencia nao encontrada.';
    end if;
    if v_fatura.competencia <= v_origem_competencia then
      continue;
    end if;

    for v_offset in -1..1 loop
      v_competencia_candidata := (
        date_trunc('month', v_fatura.competencia)::date
        + make_interval(months => v_offset)
      )::date;
      v_data_ocorrencia := public.financeiro_cartao_clamp_dia(
        extract(year from v_competencia_candidata)::int,
        extract(month from v_competencia_candidata)::int,
        v_recorrencia.dia_base
      );

      if v_data_ocorrencia < v_recorrencia.data_inicio then
        continue;
      end if;

      select c.competencia
        into v_competencia_ciclo
        from public.financeiro_cartao_ciclo(v_fatura.cartao_id, v_data_ocorrencia) c;
      if v_competencia_ciclo is distinct from v_fatura.competencia then
        continue;
      end if;

      v_previsao := null;
      insert into public.financeiro_cartao_recorrencia_previsoes (
        recorrencia_id,
        fatura_id,
        cartao_id,
        competencia,
        data_compra,
        descricao,
        estabelecimento,
        valor,
        empresa_id,
        plano_conta_id,
        centro_custo_id,
        classificacao_status
      )
      values (
        v_recorrencia.id,
        v_fatura.id,
        v_fatura.cartao_id,
        v_fatura.competencia,
        v_data_ocorrencia,
        v_recorrencia.descricao,
        v_recorrencia.estabelecimento,
        v_recorrencia.valor,
        v_recorrencia.empresa_id,
        v_recorrencia.plano_conta_id,
        v_recorrencia.centro_custo_id,
        v_recorrencia.classificacao_status
      )
      on conflict (recorrencia_id, competencia) do nothing
      returning * into v_previsao;

      get diagnostics v_inserted = row_count;
      if v_inserted = 1 then
        v_total := v_total + 1;
        perform public.financeiro_cartoes_audit_insert(
          v_actor,
          'financeiro_cartao_recorrencia_previsoes',
          'cartao_recorrencia_previsao',
          v_previsao.id,
          'gerar_previsao_recorrencia',
          null,
          to_jsonb(v_previsao),
          null
        );
      end if;
    end loop;
  end loop;

  return v_total;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_recorrencias_gerar_previsoes"("p_fatura_id" "uuid", "p_ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_salvar"("p_payload" "jsonb", "p_ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_role text;
  v_ator_tipo text;
  v_ator_ref text;
  v_created_by uuid;
  v_actor jsonb;

  v_cartao_id uuid;
  v_operacao text;
  v_before public.financeiro_cartoes%rowtype;
  v_after public.financeiro_cartoes%rowtype;

  v_apelido text;
  v_final text;
  v_titularidade_tipo text;
  v_titular text;
  v_bandeira text;
  v_empresa_id uuid;
  v_conta_pagadora_id uuid;
  v_centro_custo_id uuid;
  v_dia_fechamento int;
  v_dia_vencimento int;
  v_limite numeric;
  v_observacoes text;
  v_constraint text;
begin
  v_role := coalesce(nullif(auth.role(), ''), nullif(current_setting('request.jwt.claim.role', true), ''), session_user::text);

  if v_role = 'authenticated' then
    v_ator_tipo := 'web';
    v_created_by := auth.uid();
    v_ator_ref := coalesce(v_created_by::text, nullif(current_setting('request.jwt.claim.email', true), ''), 'authenticated');
  elsif v_role = 'service_role' then
    v_ator_tipo := coalesce(nullif(p_ator->>'ator_tipo', ''), nullif(p_ator->>'tipo', ''), 'sistema');
    if v_ator_tipo not in ('web','maria','openfinance','sistema') then
      raise exception 'ator_tipo nao permitido para service_role.';
    end if;
    v_ator_ref := coalesce(nullif(p_ator->>'ator_ref', ''), nullif(p_ator->>'ref', ''), v_ator_tipo);
  else
    raise exception 'papel nao autorizado para RPC de cartoes: %', v_role using errcode = '42501';
  end if;

  v_actor := jsonb_build_object(
    'role', v_role,
    'ator_tipo', v_ator_tipo,
    'ator_ref', v_ator_ref,
    'created_by', v_created_by
  );

  v_cartao_id := nullif(p_payload->>'cartao_id', '')::uuid;

  if v_cartao_id is not null then
    select * into v_before
      from public.financeiro_cartoes
     where id = v_cartao_id
     for update;

    if not found then
      raise exception 'cartao_id nao encontrado.';
    end if;
  end if;

  v_apelido := case
    when p_payload ? 'apelido' then nullif(trim(p_payload->>'apelido'), '')
    when v_cartao_id is not null then v_before.apelido
    else null
  end;

  v_final := case
    when p_payload ? 'final' then nullif(trim(p_payload->>'final'), '')
    when v_cartao_id is not null then v_before.final
    else null
  end;

  v_titularidade_tipo := case
    when p_payload ? 'titularidade_tipo' then nullif(trim(p_payload->>'titularidade_tipo'), '')
    when v_cartao_id is not null then v_before.titularidade_tipo
    else null
  end;

  if v_apelido is null then
    raise exception 'apelido obrigatorio para cartao.';
  end if;

  if v_final is null then
    raise exception 'final obrigatorio para cartao.';
  end if;

  if v_final !~ '^[0-9]{4}$' then
    raise exception 'final deve conter exatamente 4 digitos.';
  end if;

  if v_titularidade_tipo is null then
    raise exception 'titularidade_tipo obrigatorio para cartao.';
  end if;

  if v_titularidade_tipo not in ('pf','pj') then
    raise exception 'titularidade_tipo invalido.';
  end if;

  v_titular := case
    when p_payload ? 'titular' then nullif(trim(p_payload->>'titular'), '')
    when v_cartao_id is not null then v_before.titular
    else null
  end;

  v_bandeira := case
    when p_payload ? 'bandeira' then nullif(trim(p_payload->>'bandeira'), '')
    when v_cartao_id is not null then v_before.bandeira
    else null
  end;

  v_empresa_id := case
    when p_payload ? 'empresa_id' then nullif(p_payload->>'empresa_id', '')::uuid
    when v_cartao_id is not null then v_before.empresa_id
    else null
  end;

  v_conta_pagadora_id := case
    when p_payload ? 'conta_pagadora_id' then nullif(p_payload->>'conta_pagadora_id', '')::uuid
    when v_cartao_id is not null then v_before.conta_pagadora_id
    else null
  end;

  v_centro_custo_id := case
    when p_payload ? 'centro_custo_id' then nullif(p_payload->>'centro_custo_id', '')::uuid
    when v_cartao_id is not null then v_before.centro_custo_id
    else null
  end;

  v_dia_fechamento := case
    when p_payload ? 'dia_fechamento' then nullif(p_payload->>'dia_fechamento', '')::int
    when v_cartao_id is not null then v_before.dia_fechamento
    else null
  end;

  v_dia_vencimento := case
    when p_payload ? 'dia_vencimento' then nullif(p_payload->>'dia_vencimento', '')::int
    when v_cartao_id is not null then v_before.dia_vencimento
    else null
  end;

  v_limite := case
    when p_payload ? 'limite' then nullif(p_payload->>'limite', '')::numeric
    when v_cartao_id is not null then v_before.limite
    else null
  end;

  v_observacoes := case
    when p_payload ? 'observacoes' then nullif(trim(p_payload->>'observacoes'), '')
    when v_cartao_id is not null then v_before.observacoes
    else null
  end;

  begin
    if v_cartao_id is null then
      v_operacao := 'INSERT';

      insert into public.financeiro_cartoes (
        apelido,
        final,
        titularidade_tipo,
        titular,
        bandeira,
        empresa_id,
        conta_pagadora_id,
        centro_custo_id,
        dia_fechamento,
        dia_vencimento,
        limite,
        observacoes,
        ativo
      )
      values (
        v_apelido,
        v_final,
        v_titularidade_tipo,
        v_titular,
        v_bandeira,
        v_empresa_id,
        v_conta_pagadora_id,
        v_centro_custo_id,
        v_dia_fechamento,
        v_dia_vencimento,
        v_limite,
        v_observacoes,
        true
      )
      returning * into v_after;
    else
      v_operacao := 'UPDATE';

      update public.financeiro_cartoes
         set apelido = v_apelido,
             final = v_final,
             titularidade_tipo = v_titularidade_tipo,
             titular = v_titular,
             bandeira = v_bandeira,
             empresa_id = v_empresa_id,
             conta_pagadora_id = v_conta_pagadora_id,
             centro_custo_id = v_centro_custo_id,
             dia_fechamento = v_dia_fechamento,
             dia_vencimento = v_dia_vencimento,
             limite = v_limite,
             observacoes = v_observacoes,
             ativo = v_before.ativo,
             updated_at = now()
       where id = v_cartao_id
       returning * into v_after;
    end if;
  exception
    when unique_violation then
      get stacked diagnostics v_constraint = constraint_name;
      if coalesce(v_constraint, '') ilike '%apelido%' then
        raise exception 'Ja existe um cartao com esse apelido.' using errcode = '23505';
      end if;
      raise;
  end;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartoes',
    'cartao',
    v_after.id,
    case when v_operacao = 'INSERT' then 'INSERT' else 'UPDATE' end,
    case when v_operacao = 'UPDATE' then to_jsonb(v_before) else null end,
    to_jsonb(v_after),
    p_payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'cartao_id', v_after.id,
    'operacao', v_operacao
  );
end;
$_$;


ALTER FUNCTION "public"."financeiro_cartao_salvar"("p_payload" "jsonb", "p_ator" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financeiro_cartao_salvar"("p_payload" "jsonb", "p_ator" "jsonb") IS 'Fase 3 Cartoes: cria ou edita cadastro de cartao sem alterar ativo; arquivamento fica em financeiro_cartao_arquivar.';



CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacao_cancelar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_transacao_id uuid;
  v_compra_parcelada_id uuid;
  v_ids uuid[];
  v_row public.financeiro_cartao_transacoes%rowtype;
  v_before jsonb;
  v_canceladas int;
  v_bloqueadas jsonb;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_transacao_id := nullif(payload->>'transacao_id', '')::uuid;
  v_compra_parcelada_id := nullif(payload->>'compra_parcelada_id', '')::uuid;

  if v_transacao_id is null and v_compra_parcelada_id is null then
    raise exception 'transacao_id ou compra_parcelada_id obrigatorio para cancelar transacao de cartao.';
  end if;
  if v_transacao_id is not null and v_compra_parcelada_id is not null then
    raise exception 'informe transacao_id ou compra_parcelada_id, nao ambos.';
  end if;

  with alvo as (
    select t.*
      from public.financeiro_cartao_transacoes t
     where (v_transacao_id is not null and t.id = v_transacao_id)
        or (v_compra_parcelada_id is not null and t.compra_parcelada_id = v_compra_parcelada_id)
     for update
  )
  select array_agg(alvo.id order by alvo.data_compra, alvo.parcela_atual nulls first),
         jsonb_agg(to_jsonb(alvo) order by alvo.data_compra, alvo.parcela_atual nulls first)
    into v_ids, v_before
    from alvo;

  if v_ids is null or array_length(v_ids, 1) is null then
    raise exception 'transacao de cartao nao encontrada para cancelamento.';
  end if;

  if exists (
    select 1
      from public.financeiro_cartao_transacoes t
      join public.financeiro_cartao_faturas f on f.id = t.fatura_id
     where t.id = any(v_ids)
       and f.status <> 'aberta'
  ) then
    select jsonb_agg(jsonb_build_object('transacao_id', t.id, 'fatura_id', f.id, 'status', f.status))
      into v_bloqueadas
      from public.financeiro_cartao_transacoes t
      join public.financeiro_cartao_faturas f on f.id = t.fatura_id
     where t.id = any(v_ids)
       and f.status <> 'aberta';

    raise exception 'parcelas em fatura nao-aberta impedem cancelamento: %', v_bloqueadas;
  end if;

  for v_row in
    select *
      from public.financeiro_cartao_transacoes
     where id = any(v_ids)
  loop
    perform public.financeiro_cartoes_audit_insert(
      v_actor,
      'financeiro_cartao_transacoes',
      'cartao_transacao',
      v_row.id,
      'cancelar_transacao_cartao',
      to_jsonb(v_row),
      null,
      payload->>'motivo'
    );
  end loop;

  delete from public.financeiro_cartao_transacoes
   where id = any(v_ids);

  get diagnostics v_canceladas = row_count;

  return jsonb_build_object(
    'success', true,
    'canceladas', v_canceladas,
    'transacao_ids', to_jsonb(v_ids),
    'antes', v_before
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacao_cancelar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacao_classificar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_transacao_id uuid;
  v_before public.financeiro_cartao_transacoes%rowtype;
  v_after public.financeiro_cartao_transacoes%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_status text;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_transacao_id := nullif(payload->>'transacao_id', '')::uuid;
  if v_transacao_id is null then
    raise exception 'transacao_id obrigatorio para classificar transacao de cartao.';
  end if;

  v_status := coalesce(nullif(payload->>'classificacao_status', ''), 'confirmada');
  if v_status not in ('pendente','sugerida','confirmada') then
    raise exception 'classificacao_status invalido.';
  end if;

  select * into v_before
    from public.financeiro_cartao_transacoes
   where id = v_transacao_id
   for update;
  if not found then
    raise exception 'transacao de cartao nao encontrada.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_before.fatura_id;
  if not found then
    raise exception 'fatura da transacao nao encontrada.';
  end if;
  if v_fatura.status = 'cancelada' then
    raise exception 'fatura cancelada nao permite reclassificacao.';
  end if;

  update public.financeiro_cartao_transacoes
     set plano_conta_id = coalesce(nullif(payload->>'plano_conta_id', '')::uuid, plano_conta_id),
         centro_custo_id = coalesce(nullif(payload->>'centro_custo_id', '')::uuid, centro_custo_id),
         empresa_id = coalesce(nullif(payload->>'empresa_id', '')::uuid, empresa_id),
         classificacao_status = v_status,
         classificado_por = v_actor->>'ator_tipo',
         classificado_em = now()
   where id = v_transacao_id
   returning * into v_after;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_transacoes',
    'cartao_transacao',
    v_after.id,
    'classificar_transacao_cartao',
    to_jsonb(v_before),
    to_jsonb(v_after),
    payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'transacao_id', v_after.id,
    'classificacao_status', v_after.classificacao_status
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacao_classificar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacao_editar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_transacao_id uuid;
  v_before public.financeiro_cartao_transacoes%rowtype;
  v_after public.financeiro_cartao_transacoes%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_nova_data date;
  v_nova_competencia date;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);
  v_transacao_id := nullif(payload->>'transacao_id', '')::uuid;
  if v_transacao_id is null then
    raise exception 'transacao_id obrigatorio para editar transacao de cartao.';
  end if;

  select * into v_before
    from public.financeiro_cartao_transacoes
   where id = v_transacao_id
   for update;
  if not found then
    raise exception 'transacao de cartao nao encontrada.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_before.fatura_id
   for update;
  if not found then
    raise exception 'fatura da transacao nao encontrada.';
  end if;
  if v_fatura.status <> 'aberta' then
    raise exception 'transacao so pode ser editada com fatura aberta.';
  end if;

  if v_before.compra_parcelada_id is not null then
    raise exception 'transacao parcelada deve ser cancelada e relancada para alterar dados factuais.';
  end if;

  if payload ? 'data_compra' then
    v_nova_data := nullif(payload->>'data_compra', '')::date;
    if v_nova_data is null then
      raise exception 'data_compra invalida.';
    end if;

    select c.competencia into v_nova_competencia
      from public.financeiro_cartao_ciclo(v_before.cartao_id, v_nova_data) c;

    if v_nova_competencia <> v_fatura.competencia then
      raise exception 'mudar data_compra para outra competencia exige cancelar e relancar.';
    end if;
  else
    v_nova_data := v_before.data_compra;
  end if;

  update public.financeiro_cartao_transacoes
     set data_compra = v_nova_data,
         descricao = coalesce(nullif(trim(payload->>'descricao'), ''), descricao),
         estabelecimento = case
           when payload ? 'estabelecimento' then nullif(trim(payload->>'estabelecimento'), '')
           else estabelecimento
         end,
         valor = case
           when payload ? 'valor' then round(nullif(payload->>'valor', '')::numeric, 2)
           else valor
         end
   where id = v_transacao_id
   returning * into v_after;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_transacoes',
    'cartao_transacao',
    v_after.id,
    'editar_transacao_cartao',
    to_jsonb(v_before),
    to_jsonb(v_after),
    payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'transacao_id', v_after.id
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacao_editar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacao_registrar"("payload" "jsonb", "ator" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor jsonb;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_cartao public.financeiro_cartoes%rowtype;
  v_existing public.financeiro_cartao_transacoes%rowtype;
  v_after public.financeiro_cartao_transacoes%rowtype;
  v_fatura_id uuid;
  v_importacao_id uuid;
  v_plano_conta_id uuid;
  v_centro_custo_id uuid;
  v_empresa_id uuid;
  v_id_externo text;
  v_fingerprint text;
  v_numero_linha text;
  v_descricao text;
  v_data_compra date;
  v_valor numeric;
  v_tipo_transacao text;
  v_classificacao_status text;
  v_possivel_duplicata boolean;
begin
  v_actor := public.financeiro_cartoes_resolve_ator(ator);

  v_fatura_id := nullif(payload->>'fatura_id', '')::uuid;
  if v_fatura_id is null then
    raise exception 'fatura_id obrigatorio para transacao de cartao.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = v_fatura_id;
  if not found then
    raise exception 'fatura_id nao encontrada.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = v_fatura.cartao_id;
  if not found then
    raise exception 'cartao da fatura nao encontrado.';
  end if;

  v_descricao := nullif(trim(payload->>'descricao'), '');
  if v_descricao is null then
    raise exception 'descricao obrigatoria para transacao de cartao.';
  end if;

  v_data_compra := nullif(payload->>'data_compra', '')::date;
  if v_data_compra is null then
    raise exception 'data_compra obrigatoria para transacao de cartao.';
  end if;

  v_valor := nullif(payload->>'valor', '')::numeric;
  if v_valor is null or v_valor = 0 then
    raise exception 'valor obrigatorio e diferente de zero para transacao de cartao.';
  end if;

  v_tipo_transacao := coalesce(nullif(payload->>'tipo_transacao', ''), 'compra');
  if v_tipo_transacao not in ('compra','estorno','tarifa','anuidade','ajuste') then
    raise exception 'tipo_transacao invalido.';
  end if;

  v_importacao_id := nullif(payload->>'importacao_id', '')::uuid;
  v_plano_conta_id := nullif(payload->>'plano_conta_id', '')::uuid;
  v_centro_custo_id := nullif(payload->>'centro_custo_id', '')::uuid;
  v_empresa_id := nullif(payload->>'empresa_id', '')::uuid;
  v_id_externo := nullif(trim(payload->>'id_externo'), '');
  v_numero_linha := coalesce(nullif(trim(payload->>'numero_linha'), ''), '');

  if v_id_externo is not null then
    select * into v_existing
      from public.financeiro_cartao_transacoes
     where cartao_id = v_fatura.cartao_id
       and id_externo = v_id_externo
     limit 1;

    if found then
      return jsonb_build_object(
        'success', true,
        'idempotent', true,
        'transacao_id', v_existing.id,
        'ator_tipo', v_existing.ator_tipo
      );
    end if;
  end if;

  v_fingerprint := encode(extensions.digest(
    concat_ws('|',
      v_fatura.cartao_id::text,
      v_fatura.competencia::text,
      v_numero_linha,
      v_data_compra::text,
      round(v_valor, 2)::text,
      lower(regexp_replace(v_descricao, '\s+', ' ', 'g'))
    ),
    'sha256'
  ), 'hex');

  v_possivel_duplicata := exists (
    select 1
      from public.financeiro_cartao_transacoes t
     where t.fatura_id = v_fatura.id
       and t.fingerprint = v_fingerprint
  );

  v_classificacao_status := coalesce(
    nullif(payload->>'classificacao_status', ''),
    case when v_plano_conta_id is not null then 'sugerida' else 'pendente' end
  );

  if v_classificacao_status not in ('pendente','sugerida','confirmada') then
    raise exception 'classificacao_status invalido.';
  end if;

  insert into public.financeiro_cartao_transacoes (
    fatura_id,
    cartao_id,
    importacao_id,
    data_compra,
    descricao,
    estabelecimento,
    valor,
    tipo_transacao,
    empresa_id,
    plano_conta_id,
    centro_custo_id,
    classificacao_status,
    classificado_por,
    classificado_em,
    compra_parcelada_id,
    parcela_atual,
    total_parcelas,
    valor_total_compra,
    fingerprint,
    possivel_duplicata,
    id_externo,
    fonte_tipo,
    ator_tipo,
    ator_ref,
    created_by,
    observacoes
  )
  values (
    v_fatura.id,
    v_fatura.cartao_id,
    v_importacao_id,
    v_data_compra,
    v_descricao,
    nullif(payload->>'estabelecimento', ''),
    round(v_valor, 2),
    v_tipo_transacao,
    v_empresa_id,
    v_plano_conta_id,
    v_centro_custo_id,
    v_classificacao_status,
    case when v_classificacao_status in ('sugerida','confirmada') then v_actor->>'ator_tipo' else null end,
    case when v_classificacao_status in ('sugerida','confirmada') then now() else null end,
    nullif(payload->>'compra_parcelada_id', '')::uuid,
    nullif(payload->>'parcela_atual', '')::int,
    nullif(payload->>'total_parcelas', '')::int,
    nullif(payload->>'valor_total_compra', '')::numeric,
    v_fingerprint,
    v_possivel_duplicata,
    v_id_externo,
    coalesce(nullif(payload->>'fonte_tipo', ''), v_actor->>'ator_tipo'),
    v_actor->>'ator_tipo',
    v_actor->>'ator_ref',
    nullif(v_actor->>'created_by', '')::uuid,
    nullif(payload->>'observacoes', '')
  )
  returning * into v_after;

  if v_importacao_id is not null then
    update public.financeiro_cartao_importacoes i
       set linhas_importadas = stats.total,
           linhas_classificadas = stats.classificadas,
           linhas_pendentes = stats.pendentes,
           status = case
             when stats.total = 0 then i.status
             when stats.pendentes > 0 then 'parcial'
             else 'concluida'
           end,
           updated_at = now()
      from (
        select
          count(*)::int as total,
          count(*) filter (where classificacao_status = 'confirmada')::int as classificadas,
          count(*) filter (where classificacao_status <> 'confirmada')::int as pendentes
        from public.financeiro_cartao_transacoes
        where importacao_id = v_importacao_id
      ) stats
     where i.id = v_importacao_id;
  end if;

  perform public.financeiro_cartoes_audit_insert(
    v_actor,
    'financeiro_cartao_transacoes',
    'cartao_transacao',
    v_after.id,
    'registrar_transacao_cartao',
    null,
    to_jsonb(v_after),
    payload->>'motivo'
  );

  return jsonb_build_object(
    'success', true,
    'transacao_id', v_after.id,
    'classificacao_status', v_after.classificacao_status,
    'possivel_duplicata', v_after.possivel_duplicata,
    'ator_tipo', v_after.ator_tipo
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacao_registrar"("payload" "jsonb", "ator" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financeiro_cartao_transacao_registrar"("payload" "jsonb", "ator" "jsonb") IS 'Fase 2 Cartoes: registra transacao por porta unica com ator derivado do papel, dedupe forte por id_externo e alerta heuristico por fingerprint.';



CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacoes_bloqueia_fatura_fechada"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_fatura_id uuid;
  v_status text;
  v_apenas_reclassificacao boolean;
begin
  v_fatura_id := coalesce(new.fatura_id, old.fatura_id);

  select status into v_status
    from public.financeiro_cartao_faturas
   where id = v_fatura_id;

  if v_status is null then
    raise exception 'fatura % nao encontrada para transacao de cartao.', v_fatura_id;
  end if;

  if v_status = 'aberta' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if v_status = 'cancelada' then
    raise exception 'fatura % nao permite alterar transacoes quando status = %', v_fatura_id, v_status;
  end if;

  if tg_op = 'UPDATE' and v_status in ('fechada','paga') then
    v_apenas_reclassificacao :=
      new.fatura_id is not distinct from old.fatura_id and
      new.cartao_id is not distinct from old.cartao_id and
      new.importacao_id is not distinct from old.importacao_id and
      new.data_compra is not distinct from old.data_compra and
      new.descricao is not distinct from old.descricao and
      new.estabelecimento is not distinct from old.estabelecimento and
      new.valor is not distinct from old.valor and
      new.tipo_transacao is not distinct from old.tipo_transacao and
      new.compra_parcelada_id is not distinct from old.compra_parcelada_id and
      new.parcela_atual is not distinct from old.parcela_atual and
      new.total_parcelas is not distinct from old.total_parcelas and
      new.valor_total_compra is not distinct from old.valor_total_compra and
      new.fingerprint is not distinct from old.fingerprint and
      new.possivel_duplicata is not distinct from old.possivel_duplicata and
      new.id_externo is not distinct from old.id_externo and
      new.fonte_tipo is not distinct from old.fonte_tipo and
      new.ator_tipo is not distinct from old.ator_tipo and
      new.ator_ref is not distinct from old.ator_ref and
      new.created_by is not distinct from old.created_by and
      new.observacoes is not distinct from old.observacoes;

    if v_apenas_reclassificacao then
      return new;
    end if;

    raise exception 'fatura % permite apenas reclassificacao quando status = %', v_fatura_id, v_status;
  end if;

  raise exception 'fatura % nao permite alterar transacoes quando status = %', v_fatura_id, v_status;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacoes_bloqueia_fatura_fechada"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartao_transacoes_valida_classificacao"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_plano_ok boolean;
  v_unidade_empresa uuid;
begin
  if new.classificacao_status = 'confirmada' then
    if new.plano_conta_id is null then
      raise exception 'plano_conta_id obrigatorio para classificacao confirmada.';
    end if;

    if new.centro_custo_id is null then
      raise exception 'centro_custo_id obrigatorio para classificacao confirmada.';
    end if;

    if new.empresa_id is null then
      raise exception 'empresa_id obrigatorio para classificacao confirmada.';
    end if;

    select unidade_id into v_unidade_empresa
      from public.financeiro_empresas
     where id = new.empresa_id;

    if v_unidade_empresa is null or v_unidade_empresa <> new.centro_custo_id then
      raise exception 'centro_custo_id incoerente com a empresa para classificacao confirmada.';
    end if;

    select true into v_plano_ok
      from public.plano_contas p
     where p.id = new.plano_conta_id
       and p.nivel = 3
       and p.natureza = 'saida'
       and p.ativo = true;

    if coalesce(v_plano_ok, false) is not true then
      raise exception 'plano_conta_id deve ser folha de saida ativa para classificacao confirmada.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartao_transacoes_valida_classificacao"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartoes_audit_insert"("p_ator" "jsonb", "p_tabela" "text", "p_entidade_tipo" "text", "p_entidade_id" "uuid", "p_operacao" "text", "p_antes" "jsonb", "p_depois" "jsonb", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_ator_tipo text;
  v_ator_ref text;
  v_numero_hash text;
  v_last4 text;
begin
  v_ator_tipo := coalesce(nullif(p_ator->>'ator_tipo', ''), 'sistema');
  v_ator_ref := coalesce(nullif(p_ator->>'ator_ref', ''), v_ator_tipo);
  v_numero_hash := encode(extensions.digest(v_ator_ref, 'sha256'), 'hex');
  v_last4 := right(regexp_replace(v_ator_ref, '\D', '', 'g'), 4);
  if v_last4 = '' then
    v_last4 := 'n/a';
  end if;

  insert into public.maria_audit_log (
    ator_nome,
    ator_numero,
    ator_numero_hash,
    ator_numero_last4,
    papel,
    origem,
    canal,
    invoker_role,
    tabela,
    entidade_tipo,
    entidade_id,
    operacao,
    antes,
    depois,
    motivo,
    texto_original
  )
  values (
    case v_ator_tipo
      when 'web' then 'Super Folha Web'
      when 'maria' then 'Maria'
      when 'openfinance' then 'Open Finance'
      else 'Sistema'
    end,
    v_ator_ref,
    v_numero_hash,
    v_last4,
    v_ator_tipo,
    'cartoes',
    v_ator_tipo,
    coalesce(nullif(p_ator->>'role', ''), nullif(auth.role(), ''), session_user::text),
    p_tabela,
    p_entidade_tipo,
    p_entidade_id,
    p_operacao,
    p_antes,
    p_depois,
    nullif(p_motivo, ''),
    null
  )
  returning id into v_id;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartoes_audit_insert"("p_ator" "jsonb", "p_tabela" "text", "p_entidade_tipo" "text", "p_entidade_id" "uuid", "p_operacao" "text", "p_antes" "jsonb", "p_depois" "jsonb", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartoes_is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
      from public.user_profiles up
     where up.id = (select auth.uid())
       and up.role = 'admin'
  );
$$;


ALTER FUNCTION "public"."financeiro_cartoes_is_admin"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartoes_resolve_ator"("ator" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_role text;
  v_ator_tipo text;
  v_ator_ref text;
  v_created_by uuid;
begin
  v_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );

  if v_role = 'authenticated' then
    if not public.financeiro_cartoes_is_admin() then
      raise exception 'Perfil administrativo obrigatorio para operar cartoes.' using errcode = '42501';
    end if;
    v_ator_tipo := 'web';
    v_created_by := auth.uid();
    if v_created_by is null then
      raise exception 'Usuario autenticado sem auth.uid().' using errcode = '42501';
    end if;
    v_ator_ref := v_created_by::text;
  elsif v_role = 'service_role' then
    v_ator_tipo := coalesce(nullif(ator->>'tipo', ''), 'sistema');
    if v_ator_tipo not in ('maria','openfinance','sistema') then
      raise exception 'ator.tipo nao permitido para service_role.';
    end if;
    v_ator_ref := nullif(ator->>'ref', '');
  elsif v_role = 'maria_operacional' then
    v_ator_tipo := coalesce(nullif(ator->>'tipo', ''), 'maria');
    if v_ator_tipo <> 'maria' then
      raise exception 'ator.tipo nao permitido para maria_operacional.' using errcode = '42501';
    end if;
    v_ator_ref := nullif(ator->>'ref', '');
    if v_ator_ref is null then
      raise exception 'ator.ref obrigatorio para maria_operacional.' using errcode = '42501';
    end if;
  else
    raise exception 'papel nao autorizado para RPC de cartoes: %', v_role using errcode = '42501';
  end if;

  return jsonb_build_object(
    'role', v_role,
    'ator_tipo', v_ator_tipo,
    'ator_ref', v_ator_ref,
    'created_by', v_created_by
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_cartoes_resolve_ator"("ator" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_cartoes_valida_coerencia"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_empresa_conta uuid;
  v_unidade_conta uuid;
  v_unidade_empresa uuid;
begin
  if new.conta_pagadora_id is not null then
    select b.empresa_id, e.unidade_id
      into v_empresa_conta, v_unidade_conta
      from public.financeiro_contas_bancarias b
      join public.financeiro_empresas e on e.id = b.empresa_id
     where b.id = new.conta_pagadora_id;

    if v_empresa_conta is null then
      raise exception 'conta_pagadora_id % nao encontrada em financeiro_contas_bancarias', new.conta_pagadora_id;
    end if;

    if new.empresa_id is not null and v_empresa_conta <> new.empresa_id then
      raise exception 'conta_pagadora_id % pertence a empresa %, nao a empresa %',
        new.conta_pagadora_id, v_empresa_conta, new.empresa_id;
    end if;

    if new.centro_custo_id is not null and v_unidade_conta <> new.centro_custo_id then
      raise exception 'conta_pagadora_id % pertence a unidade %, nao ao centro_custo_id %',
        new.conta_pagadora_id, v_unidade_conta, new.centro_custo_id;
    end if;
  end if;

  if new.empresa_id is not null and new.centro_custo_id is not null then
    select unidade_id into v_unidade_empresa
      from public.financeiro_empresas
     where id = new.empresa_id;

    if v_unidade_empresa is null then
      raise exception 'empresa_id % nao encontrada em financeiro_empresas', new.empresa_id;
    end if;

    if v_unidade_empresa <> new.centro_custo_id then
      raise exception 'centro_custo_id % nao corresponde a unidade % da empresa %',
        new.centro_custo_id, v_unidade_empresa, new.empresa_id;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."financeiro_cartoes_valida_coerencia"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."financeiro_documento_rejeitar_ui"("p_documento_id" "uuid", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_profile public.user_profiles%rowtype;
  v_before public.financeiro_documentos%rowtype;
  v_after public.financeiro_documentos%rowtype;
  v_motivo text;
  v_audit_id uuid;
  v_invoker_role text;
  v_ator_numero text;
  v_ator_hash text;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'usuario autenticado obrigatorio para rejeitar comprovante.' using errcode = '42501';
  end if;

  v_motivo := nullif(trim(p_motivo), '');
  if v_motivo is null then
    raise exception 'motivo obrigatorio para rejeitar comprovante.';
  end if;

  select * into v_profile
    from public.user_profiles
   where id = v_uid;

  select * into v_before
    from public.financeiro_documentos
   where id = p_documento_id
   for update;

  if not found then
    raise exception 'financeiro_documento nao encontrado para rejeicao.';
  end if;

  if v_before.status_documento = 'rejeitado' then
    return jsonb_build_object(
      'ok', true,
      'success', true,
      'duplicate', true,
      'documento_id', v_before.id,
      'status_documento', v_before.status_documento,
      'message', 'comprovante_ja_estava_rejeitado'
    );
  end if;

  update public.financeiro_documentos
     set status_documento = 'rejeitado',
         rejeitado_em = now(),
         rejeitado_por = coalesce(nullif(v_profile.nome, ''), v_uid::text),
         rejeitado_motivo = public.maria_contas_observacao_sanitizada(v_motivo),
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
           'rejeitado_por_user_id', v_uid,
           'rejeitado_por_nome', nullif(v_profile.nome, ''),
           'canal_rejeicao', 'super_folha_ui',
           'pagamento_executado_pela_maria', false
         ))
   where id = p_documento_id
   returning * into v_after;

  v_invoker_role := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    session_user::text
  );
  v_ator_numero := 'auth:' || v_uid::text;
  v_ator_hash := encode(extensions.digest(v_ator_numero, 'sha256'), 'hex');

  insert into public.maria_audit_log (
    ator_nome,
    ator_numero,
    ator_numero_hash,
    ator_numero_last4,
    papel,
    origem,
    canal,
    invoker_role,
    tabela,
    entidade_tipo,
    entidade_id,
    operacao,
    antes,
    depois,
    motivo,
    texto_original
  ) values (
    coalesce(nullif(v_profile.nome, ''), v_uid::text),
    v_ator_numero,
    v_ator_hash,
    right(v_uid::text, 4),
    'super_folha_ui',
    'super_folha',
    'web',
    v_invoker_role,
    'financeiro_documentos',
    'financeiro_documento',
    v_after.id,
    'rejeitar_comprovante_ui',
    to_jsonb(v_before),
    to_jsonb(v_after),
    v_motivo,
    null
  ) returning id into v_audit_id;

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'documento_id', v_after.id,
    'status_documento', v_after.status_documento,
    'vinculo_tipo', v_after.vinculo_tipo,
    'vinculo_id', v_after.vinculo_id,
    'rejeitado_em', v_after.rejeitado_em,
    'rejeitado_por', v_after.rejeitado_por,
    'audit_id', v_audit_id,
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."financeiro_documento_rejeitar_ui"("p_documento_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."financeiro_documento_rejeitar_ui"("p_documento_id" "uuid", "p_motivo" "text") IS 'Rejeita comprovante financeiro pela UI autenticada, preservando evidência e registrando auditoria.';



CREATE OR REPLACE FUNCTION "public"."financeiro_documentos_guard_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  -- Comprovante/documento financeiro não deve ser apagado diretamente.
  -- Correção operacional: rejeitar por RPC auditada e anexar novo registro.
  if tg_op = 'DELETE' then
    raise exception 'financeiro_documento_delete_bloqueado';
  end if;

  -- Rejeitado é estado terminal: não pode ser reativado, repontado, nem trocar evidência.
  if old.status_documento = 'rejeitado' then
    if new.status_documento is distinct from old.status_documento
       or new.vinculo_id is distinct from old.vinculo_id
       or new.vinculo_tipo is distinct from old.vinculo_tipo
       or new.storage_ref is distinct from old.storage_ref
       or new.hash is distinct from old.hash then
      raise exception 'financeiro_documento_rejeitado_imutavel';
    end if;
  end if;

  -- Não permitir downgrade ativo -> pendente_vinculo para burlar imutabilidade e repontar depois.
  if old.status_documento = 'ativo' and new.status_documento = 'pendente_vinculo' then
    raise exception 'financeiro_documento_status_retrocesso_bloqueado';
  end if;

  -- Documento já vinculado e não pendente não deve ser repontado silenciosamente.
  if old.vinculo_id is not null and old.status_documento <> 'pendente_vinculo' then
    if new.vinculo_id is distinct from old.vinculo_id
       or new.vinculo_tipo is distinct from old.vinculo_tipo then
      raise exception 'financeiro_documento_vinculo_imutavel';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."financeiro_documentos_guard_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."folha_alocacao_dre_allocation_hash"("p_fatias" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_hash text;
begin
  if p_fatias is null or jsonb_typeof(p_fatias) <> 'array' then
    raise exception 'p_fatias deve ser um array.';
  end if;

  select encode(
    extensions.digest(
      convert_to(
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'categoria', nullif(trim(x.categoria), ''),
              'componente', nullif(trim(x.componente), ''),
              'unidade', lower(trim(x.unidade)),
              'percentual', x.percentual
            )
            order by
              coalesce(nullif(trim(x.categoria), ''), ''),
              coalesce(nullif(trim(x.componente), ''), ''),
              lower(trim(x.unidade))
          ),
          '[]'::jsonb
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  )
    into v_hash
    from jsonb_to_recordset(p_fatias) as x(
      categoria text,
      componente text,
      unidade text,
      percentual numeric(9,6)
    );

  return v_hash;
end;
$$;


ALTER FUNCTION "public"."folha_alocacao_dre_allocation_hash"("p_fatias" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."folha_alocacao_dre_confirmacao_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'historico de alocacao DRE e imutavel.' using errcode = '42501';
  end if;

  if current_setting('app.folha_alocacao_dre_rpc', true) <> 'on'
     or old.ativa <> true
     or new.ativa <> false
     or (to_jsonb(new) - 'ativa') is distinct from (to_jsonb(old) - 'ativa') then
    raise exception 'confirmacao de alocacao DRE so pode ser desativada pela RPC versionada.'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


