    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'fatias de alocacao DRE sao imutaveis; crie uma nova versao.'
    using errcode = '42501';
end;
$$;


