CREATE TABLE IF NOT EXISTS "public"."maria_whatsapp_atores" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nome" "text" NOT NULL,
    "papel" "text" NOT NULL,
    "numero_hash" "text" NOT NULL,
    "numero_last4" "text" NOT NULL,
    "ativo" boolean DEFAULT true NOT NULL,
    "observacao" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid",
    CONSTRAINT "maria_whatsapp_atores_papel_check" CHECK (("papel" = ANY (ARRAY['owner_full'::"text", 'finance_ops_write_safe'::"text", 'finance_assistant_write_safe'::"text", 'strategic_read_prepare'::"text", 'gov_agent_tecnico'::"text"])))
);


ALTER TABLE "public"."maria_whatsapp_atores" OWNER TO "postgres";


COMMENT ON TABLE "public"."maria_whatsapp_atores" IS 'Allowlist de remetentes WhatsApp da Maria. Numeros sao armazenados por hash; RPCs recebem o sender real e registram auditoria.';



CREATE OR REPLACE FUNCTION "public"."maria_agenda_assert"("p_ator_numero" "text", "p_papel" "text", "p_lista_id" "uuid", "p_escrita" boolean) RETURNS "public"."maria_whatsapp_atores"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_lista_nome text;
begin
  if p_escrita then
    v_actor := public.maria_assert_actor(p_ator_numero, p_papel,
      array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);
  else
    v_actor := public.maria_assert_actor(p_ator_numero, p_papel,
      array['owner_full','finance_ops_write_safe','finance_assistant_write_safe','strategic_read_prepare','gov_agent_tecnico']);
  end if;
  if v_actor.papel = 'owner_full' then return v_actor; end if;
  if p_escrita and v_actor.user_id is null then
    raise exception 'ator sem usuario vinculado (user_id).'
      using errcode = '42501', hint = 'vincular maria_whatsapp_atores.user_id';
  end if;
  if p_lista_id is not null and v_actor.user_id is not null then
    if not exists (select 1 from public.tarefas_listas_membros m
                    where m.lista_id = p_lista_id and m.user_id = v_actor.user_id) then
      select l.nome into v_lista_nome from public.tarefas_listas l where l.id = p_lista_id;
      raise exception 'ator nao e membro da lista %.', coalesce(v_lista_nome, p_lista_id::text)
        using errcode = '42501';
    end if;
  end if;
  return v_actor;
end $$;


ALTER FUNCTION "public"."maria_agenda_assert"("p_ator_numero" "text", "p_papel" "text", "p_lista_id" "uuid", "p_escrita" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."tarefas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "titulo" "text" NOT NULL,
    "descricao" "text",
    "lista_id" "uuid",
    "prioridade" "text" DEFAULT 'media'::"text",
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "categoria" "text" DEFAULT 'geral'::"text",
    "unidade" "text",
    "vencimento_em" timestamp with time zone,
    "dia_inteiro" boolean DEFAULT false,
    "data_conclusao" timestamp with time zone,
    "is_recorrente" boolean DEFAULT false,
    "recorrencia" "jsonb",
    "recorrencia_pai_id" "uuid",
    "lembrete_minutos" integer[] DEFAULT ARRAY[30],
    "status" "text" DEFAULT 'pendente'::"text",
    "vinculo_tipo" "text",
    "vinculo_id" "uuid",
    "google_event_id" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "ordem" integer DEFAULT 0,
    "parent_id" "uuid",
    "responsavel_id" "uuid",
    "concluida_por" "uuid",
    "mensagem_origem_id" "text",
    "rotina_id" "uuid",
    "competencia" "date",
    CONSTRAINT "tarefas_categoria_check" CHECK (("categoria" = ANY (ARRAY['financeiro'::"text", 'rh'::"text", 'administrativo'::"text", 'pessoal'::"text", 'geral'::"text"]))),
    CONSTRAINT "tarefas_prioridade_check" CHECK (("prioridade" = ANY (ARRAY['baixa'::"text", 'media'::"text", 'alta'::"text", 'urgente'::"text"]))),
    CONSTRAINT "tarefas_rotina_competencia_check" CHECK ((("rotina_id" IS NULL) OR ("competencia" IS NOT NULL))),
    CONSTRAINT "tarefas_status_check" CHECK (("status" = ANY (ARRAY['pendente'::"text", 'em_andamento'::"text", 'concluida'::"text", 'cancelada'::"text", 'adiada'::"text"]))),
    CONSTRAINT "tarefas_unidade_check" CHECK (("unidade" = ANY (ARRAY['cg'::"text", 'rec'::"text", 'bar'::"text", 'todas'::"text"]))),
    CONSTRAINT "tarefas_vinculo_tipo_check" CHECK ((("vinculo_tipo" IS NULL) OR ("vinculo_tipo" = ANY (ARRAY['conta_pagar'::"text", 'folha_pagamento'::"text", 'reuniao'::"text", 'rh_processo'::"text", 'rh_etapa'::"text", 'rh_pdi_checkpoint'::"text"]))))
);


ALTER TABLE "public"."tarefas" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_assert_tarefa"("a" "public"."maria_whatsapp_atores", "t" "public"."tarefas") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_lista_nome text;
begin
  if a.papel = 'owner_full' then return; end if;
  if a.user_id is null then
    raise exception 'ator sem usuario vinculado (user_id).' using errcode = '42501', hint = 'vincular maria_whatsapp_atores.user_id';
  end if;
  if not public.maria_agenda_pode_ver(a, t) then
    select l.nome into v_lista_nome from public.tarefas_listas l where l.id = t.lista_id;
    raise exception 'ator nao e membro da lista %.', coalesce(v_lista_nome, '(sem lista)') using errcode = '42501';
  end if;
end $$;


ALTER FUNCTION "public"."maria_agenda_assert_tarefa"("a" "public"."maria_whatsapp_atores", "t" "public"."tarefas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_cancelar"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; t public.tarefas%rowtype; v_audit uuid;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'motivo obrigatorio para cancelar.' using errcode = '22023'; end if;
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' then
    raise exception 'espelho de conta a pagar: remarque/cancele a conta, nao a tarefa.' using errcode = 'P0001', hint = 'maria_contas_*';
  end if;
  if v_antes.status = 'cancelada' then
    return jsonb_build_object('success', true, 'id', v_antes.id, 'idempotente', true,
                              'resumo', public.maria_agenda_resumo_linha('Ja estava cancelada', v_antes), 'tarefa', public.maria_agenda_tarefa_json(v_antes));
  end if;
  if exists (select 1 from public.tarefas f where f.parent_id = v_antes.id and f.status in ('pendente','em_andamento','adiada')) then
    raise exception 'pai com filha ativa nao pode ser excluido/cancelado.' using errcode = 'P0001';
  end if;
  update public.tarefas set status = 'cancelada', updated_at = now(),
         descricao = concat_ws(E'\n', descricao, format('[Cancelada pela Maria em %s] %s', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), trim(p_motivo)))
   where id = p_tarefa_id returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_cancelar', to_jsonb(v_antes), to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_resumo_linha('Cancelada', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_cancelar"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_categoria_da_lista"("p_lista_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case lower(coalesce(l.nome, ''))
           when 'financeiro' then 'financeiro'
           when 'rh' then 'rh'
           when 'adm' then 'administrativo'
           when 'pessoal' then 'pessoal'
           else 'geral' end
    from public.tarefas_listas l where l.id = p_lista_id
$$;


ALTER FUNCTION "public"."maria_agenda_categoria_da_lista"("p_lista_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_concluir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; t public.tarefas%rowtype; v_audit uuid; v_pend text;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' then
    raise exception 'tarefa vinculada a conta a pagar: conclua pela baixa da conta.'
      using errcode = 'P0001', hint = format('maria_contas_dar_baixa(p_conta_id=%s)', v_antes.vinculo_id);
  end if;
  if v_antes.status = 'concluida' then
    return jsonb_build_object('success', true, 'id', v_antes.id, 'idempotente', true,
                              'resumo', public.maria_agenda_resumo_linha('Ja estava concluida', v_antes), 'tarefa', public.maria_agenda_tarefa_json(v_antes));
  end if;
  select string_agg(f.titulo, '; ' order by f.titulo) into v_pend
    from public.tarefas f where f.parent_id = v_antes.id and f.status in ('pendente','em_andamento','adiada');
  if v_pend is not null then
    raise exception 'pai com filhas pendentes: %.', v_pend using errcode = 'P0001', hint = 'conclua ou cancele as filhas';
  end if;
  update public.tarefas set status = 'concluida', data_conclusao = now(), concluida_por = v_actor.user_id, updated_at = now()
   where id = p_tarefa_id returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_concluir', to_jsonb(v_antes), to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'progresso_pai', case when t.parent_id is not null then public.maria_agenda_progresso_pai(t.parent_id) end,
                            'resumo', public.maria_agenda_resumo_linha('Concluida', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_concluir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_criar"("p_titulo" "text", "p_lista_id" "uuid", "p_data" "date", "p_dia_inteiro" boolean, "p_hora" time without time zone, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_parent_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype; v_pai public.tarefas%rowtype; t public.tarefas%rowtype;
  v_prio text := coalesce(nullif(trim(p_prioridade), ''), 'media'); v_audit uuid;
begin
  if p_lista_id is null then raise exception 'lista obrigatoria' using errcode = '22023'; end if;
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, p_lista_id, true);
  if nullif(trim(coalesce(p_titulo, '')), '') is null then raise exception 'titulo obrigatorio' using errcode = '22023'; end if;
  if p_data is null then raise exception 'data invalida' using errcode = '22023'; end if;
  if v_prio not in ('baixa','media','alta','urgente') then raise exception 'prioridade invalida' using errcode = '22023', hint = 'baixa | media | alta | urgente'; end if;
  if not exists (select 1 from public.tarefas_listas l where l.id = p_lista_id) then raise exception 'lista nao encontrada.' using errcode = '22023'; end if;
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  if p_parent_id is not null then
    select * into v_pai from public.tarefas where id = p_parent_id;
    if not found then raise exception 'pai nao encontrado.' using errcode = 'P0001'; end if;
    if v_pai.parent_id is not null then raise exception 'profundidade maxima 1: filha nao pode ter filha.' using errcode = 'P0001'; end if;
    perform public.maria_agenda_assert_tarefa(v_actor, v_pai);
  end if;
  if nullif(trim(coalesce(p_mensagem_origem_id, '')), '') is not null then
    select * into t from public.tarefas
     where mensagem_origem_id = p_mensagem_origem_id and titulo = trim(p_titulo)
       and coalesce(parent_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_parent_id, '00000000-0000-0000-0000-000000000000'::uuid)
     order by created_at limit 1;
    if found then
      return jsonb_build_object('success', true, 'id', t.id, 'idempotente', true,
                                'resumo', public.maria_agenda_resumo_linha('Ja existia', t), 'tarefa', public.maria_agenda_tarefa_json(t));
    end if;
  end if;
  insert into public.tarefas (titulo, descricao, lista_id, categoria, prioridade, tags, vencimento_em, dia_inteiro, status,
                              responsavel_id, parent_id, created_by, mensagem_origem_id)
  values (trim(p_titulo), nullif(trim(coalesce(p_descricao, '')), ''), p_lista_id,
          coalesce(public.maria_agenda_categoria_da_lista(p_lista_id), 'geral'), v_prio, array['maria'],
          public.maria_agenda_montar_vencimento(p_data, coalesce(p_dia_inteiro, true), p_hora), coalesce(p_dia_inteiro, true), 'pendente',
          p_responsavel_id, p_parent_id, v_actor.user_id, nullif(trim(coalesce(p_mensagem_origem_id, '')), ''))
  returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_criar', null, to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_resumo_linha('Criada', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_criar"("p_titulo" "text", "p_lista_id" "uuid", "p_data" "date", "p_dia_inteiro" boolean, "p_hora" time without time zone, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_parent_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_detalhar"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; t public.tarefas%rowtype; v_filhas jsonb;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, false);
  select * into t from public.tarefas where id = p_tarefa_id;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  if not public.maria_agenda_pode_ver(v_actor, t) then
    raise exception 'ator nao e membro da lista %.', coalesce((select l.nome from public.tarefas_listas l where l.id = t.lista_id), '(sem lista)') using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(public.maria_agenda_tarefa_json(f) order by f.vencimento_em nulls last, f.ordem, f.titulo), '[]'::jsonb)
    into v_filhas from public.tarefas f where f.parent_id = t.id;
  return jsonb_build_object('success', true, 'tarefa', public.maria_agenda_tarefa_json(t), 'filhas', v_filhas,
                            'resumo', public.maria_agenda_resumo_linha('Tarefa', t));
end $$;


ALTER FUNCTION "public"."maria_agenda_detalhar"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_digest_grupo"("p_lista_id" "uuid", "p_data" "date", "p_horizonte_dias" integer DEFAULT 6) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_data date := coalesce(p_data, (now() at time zone 'America/Sao_Paulo')::date);
  v_h int := greatest(coalesce(p_horizonte_dias, 6), 0);
  v_lista jsonb; v_hoje jsonb; v_atr jsonb; v_atr_total int; v_prox jsonb; v_ids uuid[];
  v_c_hoje jsonb; v_c_atr jsonb; v_c_prox jsonb; v_c_deb jsonb;
  v_dias text[] := array['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
begin
  if p_lista_id is null then raise exception 'lista obrigatoria' using errcode = '22023'; end if;
  select jsonb_build_object('id', l.id, 'nome', l.nome) into v_lista from public.tarefas_listas l where l.id = p_lista_id;
  if v_lista is null then raise exception 'lista nao encontrada.' using errcode = '22023'; end if;

  with base as (
    select t.*, (t.vencimento_em at time zone 'America/Sao_Paulo')::date as dl
      from public.tarefas t
     where t.lista_id = p_lista_id and t.status in ('pendente','em_andamento','adiada') and t.vencimento_em is not null
       and t.vinculo_tipo is distinct from 'conta_pagar'),
  item as (
    select b.id, b.dl, b.parent_id, jsonb_build_object(
      'id', b.id, 'titulo', b.titulo, 'data_local', to_char(b.dl, 'YYYY-MM-DD'),
      'created_local', to_char((b.created_at at time zone 'America/Sao_Paulo')::date, 'YYYY-MM-DD'),
      'hora_local', case when b.dia_inteiro then null else to_char(b.vencimento_em at time zone 'America/Sao_Paulo', 'HH24:MI') end,
      'prioridade', b.prioridade, 'status', b.status, 'parent_id', b.parent_id,
      'parent_titulo', (select p.titulo from public.tarefas p where p.id = b.parent_id),
      'rotina_id', b.rotina_id,
      'responsavel', (select p.nome from public.user_profiles p where p.id = b.responsavel_id),
      'destinatarios', coalesce((select string_agg(d.nome, ', ' order by d.nome) from public.agenda_destinatarios(b.id) d), ''),
      'filhas_pendentes', (select count(*) from public.tarefas f where f.parent_id = b.id and f.status in ('pendente','em_andamento','adiada')),
      'filhas_total', (select count(*) from public.tarefas f where f.parent_id = b.id and f.status <> 'cancelada')) as j
      from base b)
  select
    coalesce((select jsonb_agg(i.j order by i.parent_id nulls first, i.j->>'hora_local' nulls first, i.j->>'titulo') from item i where i.dl = v_data), '[]'::jsonb),
    coalesce((select jsonb_agg(i.j order by i.dl desc, i.j->>'titulo') from (select * from item where dl < v_data order by dl desc limit 15) i), '[]'::jsonb),
    (select count(*) from item i where i.dl < v_data),
    coalesce((select jsonb_agg(i.j order by i.dl, i.j->>'titulo') from (select * from item where dl > v_data and dl <= v_data + v_h order by dl limit 40) i), '[]'::jsonb),
    coalesce((select array_agg(i.id) from item i where i.dl <= v_data + v_h), '{}'::uuid[])
    into v_hoje, v_atr, v_atr_total, v_prox, v_ids;

  with esp as (
    select t.id, t.titulo, (t.vencimento_em at time zone 'America/Sao_Paulo')::date as dl, c.valor, c.descricao, t.unidade
      from public.tarefas t left join public.contas_pagar c on c.id = t.vinculo_id
     where t.lista_id = p_lista_id and t.vinculo_tipo = 'conta_pagar' and t.status in ('pendente','em_andamento','adiada') and t.vencimento_em is not null)
  select
    jsonb_build_object('n', count(*) filter (where dl = v_data), 'total', coalesce(sum(valor) filter (where dl = v_data), 0),
                       'itens', coalesce(jsonb_agg(jsonb_build_object('id', id, 'titulo', titulo, 'valor', valor, 'unidade', unidade) order by valor desc) filter (where dl = v_data), '[]'::jsonb)),
    jsonb_build_object('n', count(*) filter (where dl < v_data), 'total', coalesce(sum(valor) filter (where dl < v_data), 0),
                       'itens', coalesce(jsonb_agg(jsonb_build_object('id', id, 'titulo', titulo, 'valor', valor, 'data_local', to_char(dl, 'YYYY-MM-DD')) order by dl) filter (where dl < v_data), '[]'::jsonb)),
    jsonb_build_object('n', count(*) filter (where dl > v_data and dl <= v_data + v_h), 'total', coalesce(sum(valor) filter (where dl > v_data and dl <= v_data + v_h), 0))
    into v_c_hoje, v_c_atr, v_c_prox from esp;
  v_ids := v_ids || coalesce((select array_agg(t.id) from public.tarefas t where t.lista_id = p_lista_id and t.vinculo_tipo = 'conta_pagar'
                               and t.status in ('pendente','em_andamento','adiada') and (t.vencimento_em at time zone 'America/Sao_Paulo')::date <= v_data + v_h), '{}'::uuid[]);

  -- fase 2 debito automatico (02/09/2026): sem espelho na agenda, a conta flagada entra aqui direto de contas_pagar.
  select jsonb_build_object(
      'n', count(*) filter (where c.data_vencimento between v_data and v_data + v_h),
      'total', coalesce(sum(c.valor) filter (where c.data_vencimento between v_data and v_data + v_h), 0),
      'itens', coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'titulo', c.descricao, 'valor', c.valor, 'unidade', c.unidade,
                        'data_local', to_char(c.data_vencimento, 'YYYY-MM-DD')) order by c.data_vencimento, c.valor desc)
                        filter (where c.data_vencimento between v_data and v_data + v_h), '[]'::jsonb),
      'sem_baixa', jsonb_build_object(
        'n', count(*) filter (where c.data_vencimento < v_data),
        'total', coalesce(sum(c.valor) filter (where c.data_vencimento < v_data), 0),
        'itens', coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'titulo', c.descricao, 'valor', c.valor, 'unidade', c.unidade,
                          'data_local', to_char(c.data_vencimento, 'YYYY-MM-DD')) order by c.data_vencimento)
                          filter (where c.data_vencimento < v_data), '[]'::jsonb)))
    into v_c_deb
    from public.contas_pagar c
   where c.debito_automatico and c.status = 'pendente' and c.data_vencimento <= v_data + v_h;

  return jsonb_build_object(
    'success', true, 'data', v_data, 'horizonte_dias', v_h,
    'data_br', v_dias[extract(dow from v_data)::int + 1] || ', ' || to_char(v_data, 'DD/MM'),
    'mes_br', to_char(v_data, 'MM/YYYY'),
    'lista', v_lista, 'hoje', v_hoje, 'atrasadas', v_atr, 'atrasadas_total', v_atr_total, 'proximos', v_prox,
    'contas_hoje', v_c_hoje, 'contas_atrasadas', v_c_atr, 'contas_proximas', v_c_prox, 'contas_debito_automatico', v_c_deb, 'tarefa_ids', to_jsonb(v_ids));
end $$;


ALTER FUNCTION "public"."maria_agenda_digest_grupo"("p_lista_id" "uuid", "p_data" "date", "p_horizonte_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_editar"("p_tarefa_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_prioridade" "text", "p_lista_id" "uuid", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; t public.tarefas%rowtype; v_audit uuid;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' and (p_titulo is not null or p_descricao is not null or p_prioridade is not null or p_lista_id is not null) then
    raise exception 'espelho de conta a pagar: so o responsavel pode ser alterado; o resto vem da conta.' using errcode = 'P0001', hint = 'maria_contas_*';
  end if;
  if p_prioridade is not null and p_prioridade not in ('baixa','media','alta','urgente') then raise exception 'prioridade invalida' using errcode = '22023'; end if;
  if p_lista_id is not null then
    if not exists (select 1 from public.tarefas_listas l where l.id = p_lista_id) then raise exception 'lista nao encontrada.' using errcode = '22023'; end if;
    perform public.maria_agenda_assert(p_ator_numero, p_papel, p_lista_id, true);
  end if;
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  update public.tarefas set
    titulo = coalesce(nullif(trim(coalesce(p_titulo, '')), ''), titulo),
    descricao = coalesce(p_descricao, descricao),
    prioridade = coalesce(p_prioridade, prioridade),
    lista_id = coalesce(p_lista_id, lista_id),
    categoria = case when p_lista_id is not null then coalesce(public.maria_agenda_categoria_da_lista(p_lista_id), categoria) else categoria end,
    responsavel_id = case when coalesce(p_limpar_responsavel, false) then null else coalesce(p_responsavel_id, responsavel_id) end,
    updated_at = now()
  where id = p_tarefa_id returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_editar', to_jsonb(v_antes), to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_resumo_linha('Editada', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_editar"("p_tarefa_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_prioridade" "text", "p_lista_id" "uuid", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_excluir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; v_audit uuid; v_resumo text;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'motivo obrigatorio para excluir.' using errcode = '22023'; end if;
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' or v_antes.vinculo_id is not null then
    raise exception 'espelho de conta a pagar: remarque/cancele a conta, nao a tarefa.' using errcode = 'P0001', hint = 'maria_contas_*';
  end if;
  if (to_jsonb(v_antes) ->> 'rotina_id') is not null or v_antes.recorrencia_pai_id is not null then
    raise exception 'instancia de rotina nao se exclui: use cancelar.' using errcode = 'P0001', hint = 'maria_agenda_cancelar';
  end if;
  if exists (select 1 from public.tarefas f where f.parent_id = v_antes.id and f.status in ('pendente','em_andamento','adiada')) then
    raise exception 'pai com filha ativa nao pode ser excluido/cancelado.' using errcode = 'P0001';
  end if;
  v_resumo := public.maria_agenda_resumo_linha('Excluida', v_antes);
  delete from public.tarefas where id = p_tarefa_id;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', v_antes.id, 'agenda_excluir', to_jsonb(v_antes), null,
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', v_antes.id, 'audit_id', v_audit, 'resumo', v_resumo,
                            'tarefa', public.maria_agenda_tarefa_json(v_antes));
end $$;


ALTER FUNCTION "public"."maria_agenda_excluir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_listar"("p_escopo" "text", "p_data" "date", "p_data_fim" "date", "p_lista_id" "uuid", "p_responsavel_id" "uuid", "p_busca" "text", "p_incluir_concluidas" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_ini date; v_fim date; v_itens jsonb; v_total int; v_resumo text;
  v_contas jsonb; v_contas_total int; v_contas_valor numeric;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, p_lista_id, false);
  if p_escopo is null or p_escopo not in ('dia','semana','atrasadas','periodo','busca') then
    raise exception 'escopo invalido' using errcode = '22023', hint = 'dia | semana | atrasadas | periodo | busca';
  end if;
  if p_escopo = 'busca' and nullif(trim(coalesce(p_busca, '')), '') is null then
    raise exception 'escopo busca exige p_busca' using errcode = '22023';
  end if;
  v_ini := coalesce(p_data, v_hoje);
  case p_escopo
    when 'dia' then v_fim := v_ini;
    when 'semana' then v_fim := v_ini + 6;
    when 'periodo' then v_fim := coalesce(p_data_fim, v_ini);
    when 'atrasadas' then v_ini := null; v_fim := v_hoje - 1;
    else v_ini := null; v_fim := null;
  end case;
  if v_ini is not null and v_fim < v_ini then raise exception 'data invalida' using errcode = '22023'; end if;

  with sel as (
    select t.*
      from public.tarefas t
     where (p_escopo = 'atrasadas' and t.status in ('pendente','em_andamento','adiada')
              or p_escopo <> 'atrasadas' and (p_incluir_concluidas and t.status <> 'cancelada'
                                              or not p_incluir_concluidas and t.status in ('pendente','em_andamento','adiada')))
       and (p_escopo = 'busca'
            or (t.vencimento_em is not null
                and (v_ini is null or (t.vencimento_em at time zone 'America/Sao_Paulo')::date >= v_ini)
                and (t.vencimento_em at time zone 'America/Sao_Paulo')::date <= v_fim))
       and (p_lista_id is null or t.lista_id = p_lista_id)
       and (p_responsavel_id is null or t.responsavel_id = p_responsavel_id)
       and (p_busca is null or t.titulo ilike '%' || p_busca || '%')
       and public.maria_agenda_pode_ver(v_actor, t)
     order by t.vencimento_em nulls last, t.ordem, t.titulo
     limit 300),
  -- espelho de conta a pagar: a conta manda. Ja paga/cancelada -> fora da lista, mesmo sem o sync ter rodado.
  esp as (
    select s.*, c.id as conta_id, c.descricao as conta_descricao, c.valor as conta_valor,
           c.status as conta_status, c.data_vencimento as conta_venc, c.unidade as conta_unidade,
           c.debito_automatico as conta_debito_automatico
      from sel s left join public.contas_pagar c on c.id = s.vinculo_id
     where s.vinculo_tipo = 'conta_pagar'
       and (c.id is null or c.status = 'pendente')),
  tar as (select s.* from sel s where s.vinculo_tipo is distinct from 'conta_pagar')
  select
    coalesce((select jsonb_agg(public.maria_agenda_tarefa_json(t) order by t.vencimento_em nulls last, t.ordem, t.titulo) from tar t), '[]'::jsonb),
    (select count(*) from tar),
    coalesce((select jsonb_agg(jsonb_build_object(
        'tarefa_id', e.id, 'conta_id', e.conta_id,
        'titulo', coalesce(e.conta_descricao, regexp_replace(e.titulo, '^Pagar:\s*', '')),
        'valor', e.conta_valor, 'unidade', e.conta_unidade,
        'data_local', to_char(coalesce(e.conta_venc, (e.vencimento_em at time zone 'America/Sao_Paulo')::date), 'YYYY-MM-DD'),
        'status_conta', coalesce(e.conta_status, 'sem_conta'),
        'debito_automatico', coalesce(e.conta_debito_automatico, false))
      order by coalesce(e.conta_venc, (e.vencimento_em at time zone 'America/Sao_Paulo')::date), e.titulo) from esp e), '[]'::jsonb),
    (select count(*) from esp),
    coalesce((select sum(e.conta_valor) from esp e), 0)
    into v_itens, v_total, v_contas, v_contas_total, v_contas_valor;

  v_resumo := format('%s tarefa(s) e %s conta(s) a pagar — escopo %s%s', v_total, v_contas_total, p_escopo,
                     case when v_ini is not null then format(' %s a %s', to_char(v_ini,'DD/MM'), to_char(v_fim,'DD/MM'))
                          when p_escopo = 'atrasadas' then format(' (antes de %s)', to_char(v_hoje,'DD/MM')) else '' end);
  return jsonb_build_object('success', true, 'escopo', p_escopo, 'data_inicio', v_ini, 'data_fim', v_fim,
                            'total', v_total, 'itens', v_itens,
                            'contas', jsonb_build_object('total', v_contas_total, 'valor_total', round(coalesce(v_contas_valor,0), 2), 'itens', v_contas),
                            'resumo', v_resumo,
                            'contrato', 'itens = TAREFA da agenda; contas = conta a pagar (espelho "Pagar: ..."). '
                                     || 'Nunca repita o mesmo item nos dois blocos: conta a pagar entra so em contas. '
                                     || 'Conta ja paga/cancelada nao aparece aqui, mesmo que o espelho ainda exista.');
end $$;


ALTER FUNCTION "public"."maria_agenda_listar"("p_escopo" "text", "p_data" "date", "p_data_fim" "date", "p_lista_id" "uuid", "p_responsavel_id" "uuid", "p_busca" "text", "p_incluir_concluidas" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_listas"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v jsonb;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, false);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', l.id, 'nome', l.nome,
           'membro', (v_actor.user_id is not null and exists (select 1 from public.tarefas_listas_membros m where m.lista_id = l.id and m.user_id = v_actor.user_id)),
           'membros', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'nome', p.nome) order by p.nome)
                                  from public.tarefas_listas_membros m join public.user_profiles p on p.id = m.user_id where m.lista_id = l.id), '[]'::jsonb),
           'pendentes', (select count(*) from public.tarefas t where t.lista_id = l.id and t.status in ('pendente','em_andamento','adiada'))
         ) order by l.nome), '[]'::jsonb)
    into v from public.tarefas_listas l;
  return jsonb_build_object('success', true, 'ator', jsonb_build_object('nome', v_actor.nome, 'papel', v_actor.papel, 'user_id', v_actor.user_id), 'listas', v);
end $$;


ALTER FUNCTION "public"."maria_agenda_listas"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_montar_vencimento"("p_data" "date", "p_dia_inteiro" boolean, "p_hora" time without time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    AS $$
  select ((p_data::timestamp + case when p_dia_inteiro then time '09:00' else coalesce(p_hora, time '09:00') end)
          at time zone 'America/Sao_Paulo')
$$;


ALTER FUNCTION "public"."maria_agenda_montar_vencimento"("p_data" "date", "p_dia_inteiro" boolean, "p_hora" time without time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_pode_ver"("a" "public"."maria_whatsapp_atores", "t" "public"."tarefas") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select a.papel = 'owner_full'
      or a.user_id is null
      or (t.lista_id is not null and exists (
            select 1 from public.tarefas_listas_membros m where m.lista_id = t.lista_id and m.user_id = a.user_id))
      or t.responsavel_id = a.user_id
      or t.created_by = a.user_id
$$;


ALTER FUNCTION "public"."maria_agenda_pode_ver"("a" "public"."maria_whatsapp_atores", "t" "public"."tarefas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_progresso_pai"("p_pai_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case when count(*) = 0 then null
              else jsonb_build_object('feitas', count(*) filter (where status = 'concluida'),
                                      'total',  count(*) filter (where status <> 'cancelada')) end
    from public.tarefas where parent_id = p_pai_id
$$;


ALTER FUNCTION "public"."maria_agenda_progresso_pai"("p_pai_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_reabrir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; t public.tarefas%rowtype; v_audit uuid; v_pai_status text;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' then
    raise exception 'espelho de conta a pagar: remarque/cancele a conta, nao a tarefa.' using errcode = 'P0001', hint = 'maria_contas_*';
  end if;
  if v_antes.status not in ('concluida','cancelada') then
    raise exception 'tarefa nao esta concluida nem cancelada (status %).', v_antes.status using errcode = 'P0001';
  end if;
  if v_antes.parent_id is not null then
    select status into v_pai_status from public.tarefas where id = v_antes.parent_id;
    if v_pai_status = 'concluida' then
      raise exception 'filha de pai concluido: reabra o pai primeiro.' using errcode = 'P0001', hint = format('maria_agenda_reabrir(%s)', v_antes.parent_id);
    end if;
  end if;
  update public.tarefas set status = 'pendente', data_conclusao = null, concluida_por = null, updated_at = now()
   where id = p_tarefa_id returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_reabrir', to_jsonb(v_antes), to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_resumo_linha('Reaberta', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_reabrir"("p_tarefa_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_remarcar"("p_tarefa_id" "uuid", "p_nova_data" "date", "p_hora" time without time zone, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.tarefas%rowtype; t public.tarefas%rowtype; v_audit uuid; v_hora time;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if p_nova_data is null then raise exception 'data invalida' using errcode = '22023'; end if;
  select * into v_antes from public.tarefas where id = p_tarefa_id for update;
  if not found then raise exception 'tarefa nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert_tarefa(v_actor, v_antes);
  if v_antes.vinculo_tipo = 'conta_pagar' then
    raise exception 'espelho de conta a pagar: remarque/cancele a conta, nao a tarefa.'
      using errcode = 'P0001', hint = format('maria_contas_alterar_vencimento(conta_id=%s)', v_antes.vinculo_id);
  end if;
  v_hora := coalesce(p_hora, case when v_antes.dia_inteiro or v_antes.vencimento_em is null then null
                                  else (v_antes.vencimento_em at time zone 'America/Sao_Paulo')::time end);
  update public.tarefas set vencimento_em = public.maria_agenda_montar_vencimento(p_nova_data, v_antes.dia_inteiro, v_hora), updated_at = now()
   where id = p_tarefa_id returning * into t;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'tarefas', 'tarefa', t.id, 'agenda_remarcar', to_jsonb(v_antes), to_jsonb(t),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', t.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_resumo_linha('Remarcada', t), 'tarefa', public.maria_agenda_tarefa_json(t));
end $$;


ALTER FUNCTION "public"."maria_agenda_remarcar"("p_tarefa_id" "uuid", "p_nova_data" "date", "p_hora" time without time zone, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_resumo_linha"("p_acao" "text", "t" "public"."tarefas") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select format('%s: %s (%s) — %s%s%s',
    p_acao, t.titulo,
    coalesce((select l.nome from public.tarefas_listas l where l.id = t.lista_id), 'sem lista'),
    coalesce(to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'DD/MM'), 'sem data'),
    case when t.dia_inteiro or t.vencimento_em is null then '' else ' ' || to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'HH24:MI') end,
    case when t.parent_id is not null then
      coalesce((select ' — pai ' || p.titulo || ' ' || (public.maria_agenda_progresso_pai(p.id)->>'feitas') || '/' || (public.maria_agenda_progresso_pai(p.id)->>'total')
                  from public.tarefas p where p.id = t.parent_id), '')
      else '' end)
$$;


ALTER FUNCTION "public"."maria_agenda_resumo_linha"("p_acao" "text", "t" "public"."tarefas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_criar"("p_titulo" "text", "p_lista_id" "uuid", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_hora" time without time zone, "p_dia_inteiro" boolean, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_vigencia_inicio" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid; v_mat jsonb;
  v_regra text := coalesce(nullif(trim(p_se_cair_fim_de_semana), ''), 'manter');
  v_prio text := coalesce(nullif(trim(p_prioridade), ''), 'media');
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  if p_lista_id is null then raise exception 'lista obrigatoria' using errcode = '22023'; end if;
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, p_lista_id, true);
  if nullif(trim(coalesce(p_titulo, '')), '') is null then raise exception 'titulo obrigatorio' using errcode = '22023'; end if;
  perform public.maria_agenda_validar_rotina(p_dia_mes, p_ultimo_dia, v_regra, v_prio);
  if not exists (select 1 from public.tarefas_listas l where l.id = p_lista_id) then raise exception 'lista nao encontrada.' using errcode = '22023'; end if;
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_mensagem_origem_id, '')), '') is not null then
    select * into r from public.agenda_rotinas
     where mensagem_origem_id = p_mensagem_origem_id and titulo = trim(p_titulo) and parent_rotina_id is null
     order by created_at limit 1;
    if found then
      return jsonb_build_object('success', true, 'id', r.id, 'idempotente', true,
                                'resumo', public.maria_agenda_rotina_resumo('Ja existia', r), 'rotina', public.maria_agenda_rotina_json(r));
    end if;
  end if;
  insert into public.agenda_rotinas (titulo, descricao, lista_id, categoria, prioridade, responsavel_id, dia_mes, ultimo_dia,
                                     se_cair_fim_de_semana, hora, dia_inteiro, status, vigencia_inicio, mensagem_origem_id, created_by)
  values (trim(p_titulo), nullif(trim(coalesce(p_descricao, '')), ''), p_lista_id,
          coalesce(public.maria_agenda_categoria_da_lista(p_lista_id), 'geral'), v_prio, p_responsavel_id,
          p_dia_mes, coalesce(p_ultimo_dia, false), v_regra, coalesce(p_hora, time '09:00'), coalesce(p_dia_inteiro, true), 'ativa',
          coalesce(p_vigencia_inicio, v_hoje), nullif(trim(coalesce(p_mensagem_origem_id, '')), ''), v_actor.user_id)
  returning * into r;
  v_mat := public.agenda_materializar_corrente_e_proximo('rpc');
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_criar', null, to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit, 'pai_id', r.id,
                            'resumo', public.maria_agenda_rotina_resumo('Rotina criada', r),
                            'rotina', public.maria_agenda_rotina_json(r), 'materializacao', v_mat - 'hoje');
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_criar"("p_titulo" "text", "p_lista_id" "uuid", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_hora" time without time zone, "p_dia_inteiro" boolean, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_vigencia_inicio" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_editar"("p_rotina_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_hora" time without time zone, "p_dia_inteiro" boolean, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid;
        v_dia int; v_ult boolean;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.agenda_rotinas where id = p_rotina_id for update;
  if not found then raise exception 'rotina nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.parent_rotina_id is not null then
    raise exception 'alvo e filha: use maria_agenda_rotina_filha_editar.' using errcode = 'P0001', hint = 'maria_agenda_rotina_filha_editar';
  end if;
  if v_antes.status = 'encerrada' then
    raise exception 'rotina encerrada nao aceita edicao nem reativacao.' using errcode = 'P0001', hint = 'maria_agenda_rotina_criar';
  end if;
  v_dia := coalesce(p_dia_mes, v_antes.dia_mes);
  v_ult := coalesce(p_ultimo_dia, case when p_dia_mes is not null then false else v_antes.ultimo_dia end);
  perform public.maria_agenda_validar_rotina(v_dia, v_ult, coalesce(p_se_cair_fim_de_semana, v_antes.se_cair_fim_de_semana), coalesce(p_prioridade, v_antes.prioridade));
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  update public.agenda_rotinas set
    titulo = coalesce(nullif(trim(coalesce(p_titulo, '')), ''), titulo),
    descricao = coalesce(p_descricao, descricao),
    dia_mes = v_dia, ultimo_dia = v_ult,
    se_cair_fim_de_semana = coalesce(p_se_cair_fim_de_semana, se_cair_fim_de_semana),
    hora = coalesce(p_hora, hora), dia_inteiro = coalesce(p_dia_inteiro, dia_inteiro),
    prioridade = coalesce(p_prioridade, prioridade),
    responsavel_id = case when coalesce(p_limpar_responsavel, false) then null else coalesce(p_responsavel_id, responsavel_id) end,
    updated_at = now()
  where id = p_rotina_id returning * into r;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_editar', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_rotina_resumo('Rotina editada (vale dos proximos meses em diante; instancia ja criada nao se move)', r),
                            'rotina', public.maria_agenda_rotina_json(r));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_editar"("p_rotina_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_hora" time without time zone, "p_dia_inteiro" boolean, "p_prioridade" "text", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_encerrar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid;
        v_canc int := 0; v_filhas int := 0; f record;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'motivo obrigatorio para encerrar.' using errcode = '22023'; end if;
  select * into v_antes from public.agenda_rotinas where id = p_rotina_id for update;
  if not found then raise exception 'rotina nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.status = 'encerrada' then
    return jsonb_build_object('success', true, 'id', v_antes.id, 'idempotente', true, 'resumo', public.maria_agenda_rotina_resumo('Ja estava encerrada', v_antes), 'rotina', public.maria_agenda_rotina_json(v_antes));
  end if;
  for f in select id from public.agenda_rotinas where parent_rotina_id = v_antes.id and status <> 'encerrada' loop
    v_canc := v_canc + public.maria_agenda_rotina_encerrar_linha(f.id, trim(p_motivo)); v_filhas := v_filhas + 1;
  end loop;
  v_canc := v_canc + public.maria_agenda_rotina_encerrar_linha(v_antes.id, trim(p_motivo));
  select * into r from public.agenda_rotinas where id = p_rotina_id;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_encerrar', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit, 'filhas_encerradas', v_filhas, 'instancias_futuras_canceladas', v_canc,
                            'resumo', public.maria_agenda_rotina_resumo(format('Rotina encerrada (%s filha(s) encerrada(s); %s instancia(s) futura(s) cancelada(s); o mes corrente fica)', v_filhas, v_canc), r),
                            'rotina', public.maria_agenda_rotina_json(r));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_encerrar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_encerrar_linha"("p_id" "uuid", "p_motivo" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_mes date := date_trunc('month', (now() at time zone 'America/Sao_Paulo')::date)::date; v_n int;
begin
  update public.agenda_rotinas
     set status = 'encerrada', encerrada_em = coalesce(encerrada_em, now()), updated_at = now(),
         observacao = concat_ws(E'\n', observacao, format('[Encerrada pela Maria em %s] %s', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), p_motivo))
   where id = p_id and status <> 'encerrada';
  update public.tarefas
     set status = 'cancelada', updated_at = now(),
         descricao = concat_ws(E'\n', descricao, format('[Cancelada: rotina encerrada em %s] %s', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY'), p_motivo))
   where rotina_id = p_id and competencia > v_mes and status in ('pendente','em_andamento','adiada');
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_encerrar_linha"("p_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_filha_adicionar"("p_rotina_pai_id" "uuid", "p_titulo" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_pai public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid; v_mat jsonb;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_pai from public.agenda_rotinas where id = p_rotina_pai_id for update;
  if not found then raise exception 'rotina pai nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_pai.lista_id, true);
  if v_pai.parent_rotina_id is not null then
    raise exception 'alvo ja e filha: adicione filhas ao pai.' using errcode = 'P0001', hint = format('maria_agenda_rotina_filha_adicionar(p_rotina_pai_id=%s)', v_pai.parent_rotina_id);
  end if;
  if v_pai.status = 'encerrada' then
    raise exception 'rotina encerrada nao aceita edicao nem reativacao.' using errcode = 'P0001', hint = 'maria_agenda_rotina_criar';
  end if;
  if nullif(trim(coalesce(p_titulo, '')), '') is null then raise exception 'titulo obrigatorio' using errcode = '22023'; end if;
  perform public.maria_agenda_validar_rotina(p_dia_mes, p_ultimo_dia, coalesce(p_se_cair_fim_de_semana, v_pai.se_cair_fim_de_semana), coalesce(p_prioridade, v_pai.prioridade));
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_mensagem_origem_id, '')), '') is not null then
    select * into r from public.agenda_rotinas
     where mensagem_origem_id = p_mensagem_origem_id and titulo = trim(p_titulo) and parent_rotina_id = v_pai.id
     order by created_at limit 1;
    if found then
      return jsonb_build_object('success', true, 'id', r.id, 'pai_id', v_pai.id, 'idempotente', true,
                                'resumo', public.maria_agenda_rotina_resumo('Ja existia', r), 'rotina', public.maria_agenda_rotina_json(r));
    end if;
  end if;
  insert into public.agenda_rotinas (parent_rotina_id, titulo, descricao, lista_id, categoria, prioridade, responsavel_id, dia_mes, ultimo_dia,
                                     se_cair_fim_de_semana, hora, dia_inteiro, status, vigencia_inicio, mensagem_origem_id, created_by, ordem)
  values (v_pai.id, trim(p_titulo), nullif(trim(coalesce(p_descricao, '')), ''), v_pai.lista_id, v_pai.categoria,
          coalesce(p_prioridade, v_pai.prioridade), p_responsavel_id, p_dia_mes, coalesce(p_ultimo_dia, false),
          coalesce(p_se_cair_fim_de_semana, v_pai.se_cair_fim_de_semana), v_pai.hora, v_pai.dia_inteiro, 'ativa',
          greatest(v_pai.vigencia_inicio, (now() at time zone 'America/Sao_Paulo')::date), nullif(trim(coalesce(p_mensagem_origem_id, '')), ''), v_actor.user_id,
          coalesce((select max(f.ordem) + 1 from public.agenda_rotinas f where f.parent_rotina_id = v_pai.id), v_pai.ordem))
  returning * into r;
  v_mat := public.agenda_materializar_corrente_e_proximo('rpc');
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_filha_adicionar', null, to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit, 'pai_id', v_pai.id,
                            'resumo', public.maria_agenda_rotina_resumo('Filha adicionada', r),
                            'rotina', public.maria_agenda_rotina_json(r), 'materializacao', v_mat - 'hoje');
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_filha_adicionar"("p_rotina_pai_id" "uuid", "p_titulo" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_prioridade" "text", "p_responsavel_id" "uuid", "p_descricao" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_filha_editar"("p_rotina_filha_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_prioridade" "text", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid;
        v_dia int; v_ult boolean;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.agenda_rotinas where id = p_rotina_filha_id for update;
  if not found then raise exception 'rotina filha nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.parent_rotina_id is null then
    raise exception 'alvo e pai: use maria_agenda_rotina_editar.' using errcode = 'P0001', hint = 'maria_agenda_rotina_editar';
  end if;
  if v_antes.status = 'encerrada' then
    raise exception 'rotina encerrada nao aceita edicao nem reativacao.' using errcode = 'P0001', hint = 'maria_agenda_rotina_filha_adicionar';
  end if;
  v_dia := coalesce(p_dia_mes, v_antes.dia_mes);
  v_ult := coalesce(p_ultimo_dia, case when p_dia_mes is not null then false else v_antes.ultimo_dia end);
  perform public.maria_agenda_validar_rotina(v_dia, v_ult, coalesce(p_se_cair_fim_de_semana, v_antes.se_cair_fim_de_semana), coalesce(p_prioridade, v_antes.prioridade));
  if p_responsavel_id is not null and not exists (select 1 from public.user_profiles p where p.id = p_responsavel_id) then
    raise exception 'responsavel nao encontrado.' using errcode = '22023';
  end if;
  update public.agenda_rotinas set
    titulo = coalesce(nullif(trim(coalesce(p_titulo, '')), ''), titulo),
    descricao = coalesce(p_descricao, descricao),
    dia_mes = v_dia, ultimo_dia = v_ult,
    se_cair_fim_de_semana = coalesce(p_se_cair_fim_de_semana, se_cair_fim_de_semana),
    prioridade = coalesce(p_prioridade, prioridade),
    responsavel_id = case when coalesce(p_limpar_responsavel, false) then null else coalesce(p_responsavel_id, responsavel_id) end,
    updated_at = now()
  where id = p_rotina_filha_id returning * into r;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_filha_editar', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit, 'pai_id', r.parent_rotina_id,
                            'resumo', public.maria_agenda_rotina_resumo('Filha editada (vale dos proximos meses em diante)', r),
                            'rotina', public.maria_agenda_rotina_json(r));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_filha_editar"("p_rotina_filha_id" "uuid", "p_titulo" "text", "p_descricao" "text", "p_dia_mes" integer, "p_ultimo_dia" boolean, "p_se_cair_fim_de_semana" "text", "p_prioridade" "text", "p_responsavel_id" "uuid", "p_limpar_responsavel" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_filha_remover"("p_rotina_filha_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid; v_canc int;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'motivo obrigatorio para remover.' using errcode = '22023'; end if;
  select * into v_antes from public.agenda_rotinas where id = p_rotina_filha_id for update;
  if not found then raise exception 'rotina filha nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.parent_rotina_id is null then
    raise exception 'alvo e pai: use maria_agenda_rotina_encerrar.' using errcode = 'P0001', hint = 'maria_agenda_rotina_encerrar';
  end if;
  if v_antes.status = 'encerrada' then
    select * into r from public.agenda_rotinas where id = p_rotina_filha_id;
    return jsonb_build_object('success', true, 'id', r.id, 'idempotente', true, 'resumo', public.maria_agenda_rotina_resumo('Ja estava encerrada', r), 'rotina', public.maria_agenda_rotina_json(r));
  end if;
  v_canc := public.maria_agenda_rotina_encerrar_linha(p_rotina_filha_id, trim(p_motivo));
  select * into r from public.agenda_rotinas where id = p_rotina_filha_id;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_filha_remover', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit, 'pai_id', r.parent_rotina_id, 'instancias_futuras_canceladas', v_canc,
                            'resumo', public.maria_agenda_rotina_resumo(format('Filha removida (encerrada; %s instancia(s) futura(s) cancelada(s), o mes corrente fica)', v_canc), r),
                            'rotina', public.maria_agenda_rotina_json(r));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_filha_remover"("p_rotina_filha_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."agenda_rotinas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "parent_rotina_id" "uuid",
    "titulo" "text" NOT NULL,
    "descricao" "text",
    "lista_id" "uuid" NOT NULL,
    "categoria" "text" DEFAULT 'geral'::"text" NOT NULL,
    "prioridade" "text" DEFAULT 'media'::"text" NOT NULL,
    "responsavel_id" "uuid",
    "frequencia" "text" DEFAULT 'mensal'::"text" NOT NULL,
    "dia_mes" smallint,
    "ultimo_dia" boolean DEFAULT false NOT NULL,
    "se_cair_fim_de_semana" "text" DEFAULT 'manter'::"text" NOT NULL,
    "hora" time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    "dia_inteiro" boolean DEFAULT true NOT NULL,
    "status" "text" DEFAULT 'ativa'::"text" NOT NULL,
    "vigencia_inicio" "date" DEFAULT (("now"() AT TIME ZONE 'America/Sao_Paulo'::"text"))::"date" NOT NULL,
    "encerrada_em" timestamp with time zone,
    "observacao" "text",
    "ordem" integer DEFAULT 0 NOT NULL,
    "mensagem_origem_id" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "agenda_rotinas_categoria_check" CHECK (("categoria" = ANY (ARRAY['financeiro'::"text", 'rh'::"text", 'administrativo'::"text", 'pessoal'::"text", 'geral'::"text"]))),
    CONSTRAINT "agenda_rotinas_dia_check" CHECK (("ultimo_dia" OR ("dia_mes" IS NOT NULL))),
    CONSTRAINT "agenda_rotinas_dia_mes_check" CHECK ((("dia_mes" >= 1) AND ("dia_mes" <= 31))),
    CONSTRAINT "agenda_rotinas_frequencia_check" CHECK (("frequencia" = 'mensal'::"text")),
    CONSTRAINT "agenda_rotinas_prioridade_check" CHECK (("prioridade" = ANY (ARRAY['baixa'::"text", 'media'::"text", 'alta'::"text", 'urgente'::"text"]))),
    CONSTRAINT "agenda_rotinas_se_cair_fim_de_semana_check" CHECK (("se_cair_fim_de_semana" = ANY (ARRAY['manter'::"text", 'proximo_dia_util'::"text", 'dia_util_anterior'::"text"]))),
    CONSTRAINT "agenda_rotinas_status_check" CHECK (("status" = ANY (ARRAY['ativa'::"text", 'pausada'::"text", 'encerrada'::"text"])))
);


ALTER TABLE "public"."agenda_rotinas" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_json"("r" "public"."agenda_rotinas") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.maria_agenda_rotina_json_base(r)
      || jsonb_build_object('filhas', case when r.parent_rotina_id is null then
           coalesce((select jsonb_agg(public.maria_agenda_rotina_json_base(f) order by f.ordem, f.titulo) from public.agenda_rotinas f where f.parent_rotina_id = r.id), '[]'::jsonb)
           else null end)
$$;


ALTER FUNCTION "public"."maria_agenda_rotina_json"("r" "public"."agenda_rotinas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_json_base"("r" "public"."agenda_rotinas") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id', r.id, 'titulo', r.titulo, 'descricao', r.descricao,
    'lista', (select jsonb_build_object('id', l.id, 'nome', l.nome) from public.tarefas_listas l where l.id = r.lista_id),
    'categoria', r.categoria, 'frequencia', r.frequencia, 'dia_mes', r.dia_mes, 'ultimo_dia', r.ultimo_dia,
    'se_cair_fim_de_semana', r.se_cair_fim_de_semana, 'hora', to_char(r.hora, 'HH24:MI'), 'dia_inteiro', r.dia_inteiro,
    'prioridade', r.prioridade,
    'responsavel', (select jsonb_build_object('id', p.id, 'nome', p.nome) from public.user_profiles p where p.id = r.responsavel_id),
    'status', r.status, 'vigencia_inicio', r.vigencia_inicio, 'encerrada_em', r.encerrada_em,
    'parent_rotina_id', r.parent_rotina_id, 'ordem', r.ordem,
    'proxima_data', public.maria_agenda_rotina_proxima_data(r),
    'instancias', jsonb_build_object(
      'corrente', (select jsonb_build_object('id', t.id, 'status', t.status, 'data_local', to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'YYYY-MM-DD'))
                     from public.tarefas t where t.rotina_id = r.id and t.competencia = date_trunc('month', (now() at time zone 'America/Sao_Paulo')::date)::date),
      'proxima',  (select jsonb_build_object('id', t.id, 'status', t.status, 'data_local', to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'YYYY-MM-DD'))
                     from public.tarefas t where t.rotina_id = r.id and t.competencia = (date_trunc('month', (now() at time zone 'America/Sao_Paulo')::date) + interval '1 month')::date)))
$$;


ALTER FUNCTION "public"."maria_agenda_rotina_json_base"("r" "public"."agenda_rotinas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_pausar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  if nullif(trim(coalesce(p_motivo, '')), '') is null then raise exception 'motivo obrigatorio para pausar.' using errcode = '22023'; end if;
  select * into v_antes from public.agenda_rotinas where id = p_rotina_id for update;
  if not found then raise exception 'rotina nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.status = 'encerrada' then
    raise exception 'rotina encerrada nao aceita edicao nem reativacao.' using errcode = 'P0001', hint = 'maria_agenda_rotina_criar';
  end if;
  if v_antes.status = 'pausada' then
    return jsonb_build_object('success', true, 'id', v_antes.id, 'idempotente', true, 'resumo', public.maria_agenda_rotina_resumo('Ja estava pausada', v_antes), 'rotina', public.maria_agenda_rotina_json(v_antes));
  end if;
  update public.agenda_rotinas set status = 'pausada', updated_at = now(),
         observacao = concat_ws(E'\n', observacao, format('[Pausada pela Maria em %s] %s', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), trim(p_motivo)))
   where id = p_rotina_id returning * into r;
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_pausar', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_rotina_resumo(case when r.parent_rotina_id is null then 'Rotina pausada (pacote inteiro deixa de nascer; instancias existentes ficam)' else 'Filha pausada (so ela deixa de nascer)' end, r),
                            'rotina', public.maria_agenda_rotina_json(r));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_pausar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_proxima_data"("r" "public"."agenda_rotinas") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_hoje date := (now() at time zone 'America/Sao_Paulo')::date; v_comp date; v_d date; i int;
begin
  if r.status <> 'ativa' then return null; end if;
  v_comp := date_trunc('month', v_hoje)::date;
  for i in 0..2 loop
    v_d := public.agenda_ajustar_data(public.agenda_resolve_dia((v_comp + (i || ' month')::interval)::date, r.dia_mes, r.ultimo_dia), r.se_cair_fim_de_semana);
    if v_d >= v_hoje and v_d >= r.vigencia_inicio then return v_d; end if;
  end loop;
  return null;
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_proxima_data"("r" "public"."agenda_rotinas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_reativar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_antes public.agenda_rotinas%rowtype; r public.agenda_rotinas%rowtype; v_audit uuid; v_mat jsonb;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, null, true);
  select * into v_antes from public.agenda_rotinas where id = p_rotina_id for update;
  if not found then raise exception 'rotina nao encontrada.' using errcode = 'P0001'; end if;
  perform public.maria_agenda_assert(p_ator_numero, p_papel, v_antes.lista_id, true);
  if v_antes.status = 'encerrada' then
    raise exception 'rotina encerrada nao aceita edicao nem reativacao.' using errcode = 'P0001', hint = 'maria_agenda_rotina_criar';
  end if;
  if v_antes.status = 'ativa' then
    return jsonb_build_object('success', true, 'id', v_antes.id, 'idempotente', true, 'resumo', public.maria_agenda_rotina_resumo('Ja estava ativa', v_antes), 'rotina', public.maria_agenda_rotina_json(v_antes));
  end if;
  update public.agenda_rotinas set status = 'ativa', updated_at = now(),
         observacao = concat_ws(E'\n', observacao, format('[Reativada pela Maria em %s]%s', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), coalesce(' ' || nullif(trim(coalesce(p_motivo, '')), ''), '')))
   where id = p_rotina_id returning * into r;
  v_mat := public.agenda_materializar_corrente_e_proximo('rpc');
  v_audit := public.maria_audit_insert(v_actor, p_ator_numero, p_canal, 'agenda_rotinas', 'rotina', r.id, 'agenda_rotina_reativar', to_jsonb(v_antes), to_jsonb(r),
               concat_ws(' | ', p_motivo, nullif('canal_origem=' || coalesce(p_canal_origem, ''), 'canal_origem=')), p_texto_original);
  return jsonb_build_object('success', true, 'id', r.id, 'audit_id', v_audit,
                            'resumo', public.maria_agenda_rotina_resumo('Rotina reativada', r),
                            'rotina', public.maria_agenda_rotina_json(r), 'materializacao', v_mat - 'hoje');
end $$;


ALTER FUNCTION "public"."maria_agenda_rotina_reativar"("p_rotina_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotina_resumo"("p_acao" "text", "r" "public"."agenda_rotinas") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select format('%s: %s (%s) — %s, %s%s',
    p_acao, r.titulo,
    coalesce((select l.nome from public.tarefas_listas l where l.id = r.lista_id), 'sem lista'),
    case when r.ultimo_dia then 'ultimo dia do mes' else 'dia ' || coalesce(r.dia_mes::text, '?') end,
    r.se_cair_fim_de_semana,
    case when r.parent_rotina_id is not null then coalesce((select ' — filha de ' || p.titulo from public.agenda_rotinas p where p.id = r.parent_rotina_id), '') else '' end)
$$;


ALTER FUNCTION "public"."maria_agenda_rotina_resumo"("p_acao" "text", "r" "public"."agenda_rotinas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_rotinas_listar"("p_lista_id" "uuid", "p_status" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v jsonb; v_total int;
begin
  v_actor := public.maria_agenda_assert(p_ator_numero, p_papel, p_lista_id, false);
  if p_status is not null and p_status not in ('ativa','pausada','encerrada') then
    raise exception 'status invalido' using errcode = '22023', hint = 'ativa | pausada | encerrada';
  end if;
  with pais as (
    select r.* from public.agenda_rotinas r
     where r.parent_rotina_id is null
       and (p_lista_id is null or r.lista_id = p_lista_id)
       and (p_status is null or r.status = p_status)
       and (v_actor.papel = 'owner_full' or v_actor.user_id is null
            or exists (select 1 from public.tarefas_listas_membros m where m.lista_id = r.lista_id and m.user_id = v_actor.user_id))
     order by (r.status = 'encerrada'), r.ordem, r.titulo)
  select coalesce(jsonb_agg(public.maria_agenda_rotina_json(p)), '[]'::jsonb), count(*) into v, v_total from pais p;
  return jsonb_build_object('success', true, 'total', v_total, 'rotinas', v,
                            'resumo', format('%s rotina(s)%s', v_total, case when p_status is not null then ' ' || p_status else '' end));
end $$;


ALTER FUNCTION "public"."maria_agenda_rotinas_listar"("p_lista_id" "uuid", "p_status" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_saude"("p_dias" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_hoje date := (now() at time zone 'America/Sao_Paulo')::date;
  v_hora time := (now() at time zone 'America/Sao_Paulo')::time;
  v_mes date := date_trunc('month', (now() at time zone 'America/Sao_Paulo')::date)::date;
  v_dias int := greatest(coalesce(p_dias, 7), 1);
  v_mat jsonb; v_erros24 int; v_cron_hoje boolean; v_digest jsonb; v_inst jsonb; v_rot jsonb; v_atr jsonb;
  v_faltantes int; v_alertas text[] := '{}'; v_deb jsonb; v_esp_deb int;
begin
  select coalesce(jsonb_agg(jsonb_build_object('em', to_char(m.executado_em at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI'), 'origem', m.origem,
           'competencia', m.competencia, 'pais', m.pais_criados, 'filhas', m.filhas_criadas, 'pulados', m.pulados, 'erros', coalesce(jsonb_array_length(m.erros), 0)) order by m.executado_em desc), '[]'::jsonb)
    into v_mat
    from (select * from public.agenda_materializacoes where executado_em >= now() - (v_dias || ' days')::interval and origem <> 'sync' order by executado_em desc limit 20) m;
  select coalesce(sum(jsonb_array_length(coalesce(erros, '[]'::jsonb))), 0) into v_erros24 from public.agenda_materializacoes where executado_em >= now() - interval '24 hours';
  select exists (select 1 from public.agenda_materializacoes where origem = 'cron' and (executado_em at time zone 'America/Sao_Paulo')::date = v_hoje) into v_cron_hoje;
  select jsonb_build_object('hoje_enviado', exists (select 1 from public.maria_agenda_envios where tipo in ('digest','manha') and data_local = v_hoje),
                            'ultimo', (select to_char(max(created_at) at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI') from public.maria_agenda_envios where tipo in ('digest','manha')))
    into v_digest;
  -- moldes ativos que deviam ter instancia no mes (regra do materializador: nominal >= vigencia) e nao tem
  select count(*) into v_faltantes
    from public.agenda_rotinas r
   where r.status = 'ativa'
     and public.agenda_resolve_dia(v_mes, r.dia_mes, r.ultimo_dia) >= r.vigencia_inicio
     and (r.parent_rotina_id is null or exists (select 1 from public.agenda_rotinas p where p.id = r.parent_rotina_id and p.status = 'ativa'))
     and not exists (select 1 from public.tarefas t where t.rotina_id = r.id and t.competencia = v_mes)
     and not exists (select 1 from public.tarefas pt where r.parent_rotina_id is not null and pt.rotina_id = r.parent_rotina_id and pt.competencia = v_mes and pt.status in ('concluida','cancelada'));
  select jsonb_build_object('criadas', count(*), 'pendentes', count(*) filter (where status in ('pendente','em_andamento','adiada')),
                            'concluidas', count(*) filter (where status = 'concluida'), 'canceladas', count(*) filter (where status = 'cancelada'), 'faltantes', v_faltantes)
    into v_inst from public.tarefas where rotina_id is not null and competencia = v_mes;
  select jsonb_build_object('ativas', count(*) filter (where status = 'ativa'), 'pausadas', count(*) filter (where status = 'pausada'), 'encerradas', count(*) filter (where status = 'encerrada'))
    into v_rot from public.agenda_rotinas;
  select coalesce(jsonb_agg(jsonb_build_object('lista', l.nome, 'tarefas', x.t, 'contas', x.c, 'contas_total', x.v) order by l.nome), '[]'::jsonb) into v_atr
    from (select t.lista_id,
                 count(*) filter (where t.vinculo_tipo is distinct from 'conta_pagar') as t,
                 count(*) filter (where t.vinculo_tipo = 'conta_pagar') as c,
                 coalesce(sum(cp.valor) filter (where t.vinculo_tipo = 'conta_pagar'), 0) as v
            from public.tarefas t left join public.contas_pagar cp on cp.id = t.vinculo_id
           where t.status in ('pendente','em_andamento','adiada') and t.vencimento_em is not null
             and (t.vencimento_em at time zone 'America/Sao_Paulo')::date < v_hoje and t.lista_id is not null
           group by t.lista_id) x join public.tarefas_listas l on l.id = x.lista_id;
  -- debito automatico (fase 2, 02/09/2026): conta flagada nao tem espelho "Pagar:" (sync v6 apaga em <=10 min); espelho vivo = defeito.
  select count(*) into v_esp_deb
    from public.tarefas t join public.contas_pagar c on c.id = t.vinculo_id
   where t.vinculo_tipo = 'conta_pagar' and t.status in ('pendente','em_andamento','adiada') and c.debito_automatico
     and c.updated_at < now() - interval '30 minutes';
  select jsonb_build_object('pendentes', count(*), 'total', coalesce(sum(valor), 0),
                            'sem_baixa_vencidas', count(*) filter (where data_vencimento < v_hoje),
                            'sem_baixa_total', coalesce(sum(valor) filter (where data_vencimento < v_hoje), 0),
                            'espelhos_vivos', v_esp_deb)
    into v_deb from public.contas_pagar where debito_automatico and status = 'pendente';
  if v_esp_deb > 0 then v_alertas := v_alertas || format('%s conta(s) em debito automatico ainda com espelho "Pagar:" na agenda (sync v6 deveria ter apagado)', v_esp_deb); end if;
  if v_erros24 > 0 then v_alertas := v_alertas || format('%s erro(s) de materializacao nas ultimas 24h', v_erros24); end if;
  if not v_cron_hoje and v_hora >= time '07:45' then v_alertas := v_alertas || 'materializador (cron 07:30) nao rodou hoje'; end if;
  if not (v_digest->>'hoje_enviado')::boolean and v_hora >= time '08:30' and extract(dow from v_hoje) between 1 and 6 then
    v_alertas := v_alertas || 'digest de agenda nao enviado no grupo hoje ate 08:30';
  end if;
  if v_faltantes > 0 and v_hora >= time '07:45' then v_alertas := v_alertas || format('%s molde(s) ativo(s) sem instancia no mes', v_faltantes); end if;
  return jsonb_build_object('success', true, 'data', v_hoje, 'hora', to_char(v_hora, 'HH24:MI'),
                            'materializacoes', v_mat, 'erros_24h', v_erros24, 'cron_rodou_hoje', v_cron_hoje, 'digest', v_digest,
                            'instancias_mes', v_inst, 'rotinas', v_rot, 'atrasadas_por_lista', v_atr, 'debito_automatico', v_deb,
                            'alertas', to_jsonb(v_alertas), 'problemas', coalesce(array_length(v_alertas, 1), 0));
end $$;


ALTER FUNCTION "public"."maria_agenda_saude"("p_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_tarefa_json"("t" "public"."tarefas") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id', t.id, 'titulo', t.titulo, 'descricao', t.descricao, 'status', t.status, 'prioridade', t.prioridade,
    'vencimento_em', t.vencimento_em,
    'data_local', to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'YYYY-MM-DD'),
    'hora_local', case when t.dia_inteiro or t.vencimento_em is null then null
                       else to_char(t.vencimento_em at time zone 'America/Sao_Paulo', 'HH24:MI') end,
    'dia_inteiro', t.dia_inteiro,
    'lista', (select jsonb_build_object('id', l.id, 'nome', l.nome) from public.tarefas_listas l where l.id = t.lista_id),
    'responsavel', (select jsonb_build_object('id', p.id, 'nome', p.nome) from public.user_profiles p where p.id = t.responsavel_id),
    'destinatarios', coalesce((select jsonb_agg(jsonb_build_object('id', d.user_id, 'nome', d.nome)) from public.agenda_destinatarios(t.id) d), '[]'::jsonb),
    'rotina_id', to_jsonb(t) -> 'rotina_id',
    'competencia', to_jsonb(t) -> 'competencia',
    'parent_id', t.parent_id, 'vinculo_tipo', t.vinculo_tipo, 'vinculo_id', t.vinculo_id,
    'progresso_pai', public.maria_agenda_progresso_pai(coalesce(t.parent_id, t.id)),
    'concluida_por', (select jsonb_build_object('id', p.id, 'nome', p.nome) from public.user_profiles p where p.id = t.concluida_por),
    'data_conclusao', t.data_conclusao,
    'categoria', t.categoria, 'unidade', t.unidade, 'tags', to_jsonb(t.tags),
    'created_at', t.created_at, 'updated_at', t.updated_at)
$$;


ALTER FUNCTION "public"."maria_agenda_tarefa_json"("t" "public"."tarefas") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agenda_validar_rotina"("p_dia_mes" integer, "p_ultimo_dia" boolean, "p_regra" "text", "p_prioridade" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
begin
  if p_dia_mes is null and not coalesce(p_ultimo_dia, false) then
    raise exception 'informe dia_mes ou ultimo_dia' using errcode = '22023';
  end if;
  if p_dia_mes is not null and (p_dia_mes < 1 or p_dia_mes > 31) then
    raise exception 'dia_mes fora de 1..31' using errcode = '22023';
  end if;
  if p_regra is not null and p_regra not in ('manter','proximo_dia_util','dia_util_anterior') then
    raise exception 'regra de fim de semana invalida' using errcode = '22023', hint = 'manter | proximo_dia_util | dia_util_anterior';
  end if;
  if p_prioridade is not null and p_prioridade not in ('baixa','media','alta','urgente') then
    raise exception 'prioridade invalida' using errcode = '22023', hint = 'baixa | media | alta | urgente';
  end if;
end $$;


ALTER FUNCTION "public"."maria_agenda_validar_rotina"("p_dia_mes" integer, "p_ultimo_dia" boolean, "p_regra" "text", "p_prioridade" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_atualizar_status"("p_id" "uuid", "p_status" "text", "p_resolved_by_nome" "text" DEFAULT NULL::"text", "p_ator_numero" "text" DEFAULT NULL::"text", "p_papel" "text" DEFAULT NULL::"text", "p_canal" "text" DEFAULT 'whatsapp'::"text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_resumo_extra" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_before public.maria_agent_memory_events%rowtype;
  v_after public.maria_agent_memory_events%rowtype;
  v_status text := lower(trim(coalesce(p_status,'')));
begin
  if v_status not in ('aberto','em_andamento','resolvido','cancelado','expirado') then
    raise exception 'status invalido: %', p_status;
  end if;
  select * into v_before from public.maria_agent_memory_events where id = p_id for update;
  if not found then
    raise exception 'memory event nao encontrado: %', p_id;
  end if;

  update public.maria_agent_memory_events set
    status = v_status,
    updated_at = now(),
    resolved_at = case when v_status in ('resolvido','cancelado','expirado') then now() else null end,
    resolved_by_nome = case when v_status in ('resolvido','cancelado','expirado')
      then coalesce(nullif(trim(coalesce(p_resolved_by_nome,'')),''), resolved_by_nome)
      else resolved_by_nome end,
    resumo = case when p_resumo_extra is not null and length(trim(p_resumo_extra))>0
      then left(resumo || E'\n' || public.maria_agent_memory_sanitize_text(p_resumo_extra), 2000)
      else resumo end
  where id = p_id
  returning * into v_after;

  begin
    insert into public.maria_audit_log (
      ator_nome, ator_numero, papel, origem, canal, invoker_role,
      tabela, entidade_tipo, entidade_id, operacao, antes, depois, motivo, texto_original
    ) values (
      coalesce(p_resolved_by_nome, 'Maria'),
      p_ator_numero,
      p_papel,
      'whatsapp',
      coalesce(p_canal,'whatsapp'),
      current_user,
      'maria_agent_memory_events',
      'memory_event',
      v_after.id,
      'memory_atualizar_status',
      jsonb_build_object('id', v_before.id, 'status', v_before.status, 'titulo', v_before.titulo),
      jsonb_build_object('id', v_after.id, 'status', v_after.status, 'titulo', v_after.titulo, 'resolved_at', v_after.resolved_at),
      public.maria_agent_memory_sanitize_text(coalesce(p_motivo, 'atualizacao de status')),
      public.maria_agent_memory_sanitize_text(p_texto_original)
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'id', v_after.id,
    'status_anterior', v_before.status,
    'status_novo', v_after.status,
    'titulo', v_after.titulo,
    'resolved_at', v_after.resolved_at
  );
end;
$$;


ALTER FUNCTION "public"."maria_agent_memory_atualizar_status"("p_id" "uuid", "p_status" "text", "p_resolved_by_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_resumo_extra" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_contar"("p_status" "text" DEFAULT 'aberto'::"text", "p_tipo" "text" DEFAULT NULL::"text", "p_unidade" "text" DEFAULT NULL::"text", "p_conta_pagar_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)::int
  from public.maria_agent_memory_filtrar(p_status, p_tipo, p_unidade, p_conta_pagar_id);
$$;


ALTER FUNCTION "public"."maria_agent_memory_contar"("p_status" "text", "p_tipo" "text", "p_unidade" "text", "p_conta_pagar_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."maria_agent_memory_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tipo" "text" NOT NULL,
    "status" "text" DEFAULT 'aberto'::"text" NOT NULL,
    "titulo" "text" NOT NULL,
    "resumo" "text" NOT NULL,
    "detalhes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "conta_pagar_id" "uuid",
    "unidade" "text",
    "chat_id" "text",
    "mensagem_origem_id" "text",
    "solicitado_por_nome" "text",
    "agente_nome" "text" DEFAULT 'Maria'::"text" NOT NULL,
    "ator_numero" "text",
    "papel" "text",
    "canal" "text" DEFAULT 'whatsapp'::"text",
    "origem" "text" DEFAULT 'whatsapp'::"text",
    "prioridade" integer DEFAULT 3 NOT NULL,
    "due_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "resolved_by_nome" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    CONSTRAINT "maria_agent_memory_events_prioridade_check" CHECK ((("prioridade" >= 1) AND ("prioridade" <= 5))),
    CONSTRAINT "maria_agent_memory_events_resumo_len" CHECK (("char_length"("resumo") <= 2000)),
    CONSTRAINT "maria_agent_memory_events_status_check" CHECK (("status" = ANY (ARRAY['aberto'::"text", 'em_andamento'::"text", 'resolvido'::"text", 'cancelado'::"text", 'expirado'::"text"]))),
    CONSTRAINT "maria_agent_memory_events_tipo_check" CHECK (("tipo" = ANY (ARRAY['hold'::"text", 'decisao'::"text", 'pendencia'::"text", 'preferencia'::"text", 'licao'::"text", 'contexto'::"text"]))),
    CONSTRAINT "maria_agent_memory_events_titulo_len" CHECK (("char_length"("titulo") <= 240))
);


ALTER TABLE "public"."maria_agent_memory_events" OWNER TO "postgres";


COMMENT ON TABLE "public"."maria_agent_memory_events" IS 'Memoria operacional leve da Maria: holds, decisoes, pendencias. Sem dump de chat/codigo bancario bruto.';



