    "agente_nome",
    "papel",
    "canal",
    "origem",
    "prioridade",
    "due_at",
    "resolved_at",
    "resolved_by_nome",
    "tags"
   FROM "public"."maria_agent_memory_events";


ALTER VIEW "public"."vw_maria_agent_memory_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_filtrar"("p_status" "text" DEFAULT 'aberto'::"text", "p_tipo" "text" DEFAULT NULL::"text", "p_unidade" "text" DEFAULT NULL::"text", "p_conta_pagar_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."vw_maria_agent_memory_events"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.vw_maria_agent_memory_events
  where (p_status is null or status = lower(p_status))
    and (p_tipo is null or tipo = lower(p_tipo))
    and (p_unidade is null or unidade ilike p_unidade)
    and (p_conta_pagar_id is null or conta_pagar_id = p_conta_pagar_id);
$$;


ALTER FUNCTION "public"."maria_agent_memory_filtrar"("p_status" "text", "p_tipo" "text", "p_unidade" "text", "p_conta_pagar_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_listar"("p_status" "text" DEFAULT 'aberto'::"text", "p_tipo" "text" DEFAULT NULL::"text", "p_unidade" "text" DEFAULT NULL::"text", "p_conta_pagar_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS SETOF "public"."vw_maria_agent_memory_events"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.maria_agent_memory_filtrar(p_status, p_tipo, p_unidade, p_conta_pagar_id)
  order by
    case status when 'aberto' then 0 when 'em_andamento' then 1 else 2 end,
    prioridade asc,
    created_at desc
  limit least(greatest(coalesce(p_limit,20),1),100);
$$;


ALTER FUNCTION "public"."maria_agent_memory_listar"("p_status" "text", "p_tipo" "text", "p_unidade" "text", "p_conta_pagar_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_registrar"("p_tipo" "text", "p_titulo" "text", "p_resumo" "text", "p_status" "text" DEFAULT 'aberto'::"text", "p_detalhes" "jsonb" DEFAULT '{}'::"jsonb", "p_conta_pagar_id" "uuid" DEFAULT NULL::"uuid", "p_unidade" "text" DEFAULT NULL::"text", "p_chat_id" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_solicitado_por_nome" "text" DEFAULT NULL::"text", "p_agente_nome" "text" DEFAULT 'Maria'::"text", "p_ator_numero" "text" DEFAULT NULL::"text", "p_papel" "text" DEFAULT NULL::"text", "p_canal" "text" DEFAULT 'whatsapp'::"text", "p_origem" "text" DEFAULT 'whatsapp'::"text", "p_prioridade" integer DEFAULT 3, "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_tags" "text"[] DEFAULT '{}'::"text"[], "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_titulo text := public.maria_agent_memory_sanitize_text(p_titulo);
  v_resumo text := public.maria_agent_memory_sanitize_text(p_resumo);
  v_tipo text := lower(trim(coalesce(p_tipo,'')));
  v_status text := lower(trim(coalesce(p_status,'aberto')));
  v_row public.maria_agent_memory_events%rowtype;
begin
  if v_tipo not in ('hold','decisao','pendencia','preferencia','licao','contexto') then
    raise exception 'tipo invalido: %', p_tipo;
  end if;
  if v_status not in ('aberto','em_andamento','resolvido','cancelado','expirado') then
    raise exception 'status invalido: %', p_status;
  end if;
  if v_titulo is null or length(trim(v_titulo)) < 3 then
    raise exception 'titulo obrigatorio';
  end if;
  if v_resumo is null or length(trim(v_resumo)) < 3 then
    raise exception 'resumo obrigatorio';
  end if;

  insert into public.maria_agent_memory_events (
    tipo, status, titulo, resumo, detalhes, conta_pagar_id, unidade, chat_id,
    mensagem_origem_id, solicitado_por_nome, agente_nome, ator_numero, papel,
    canal, origem, prioridade, due_at, tags,
    resolved_at, resolved_by_nome
  ) values (
    v_tipo, v_status, v_titulo, v_resumo, coalesce(p_detalhes,'{}'::jsonb), p_conta_pagar_id,
    nullif(trim(coalesce(p_unidade,'')),''), nullif(trim(coalesce(p_chat_id,'')),''),
    nullif(trim(coalesce(p_mensagem_origem_id,'')),''), nullif(trim(coalesce(p_solicitado_por_nome,'')),''),
    coalesce(nullif(trim(coalesce(p_agente_nome,'')),''),'Maria'),
    nullif(trim(coalesce(p_ator_numero,'')),''), nullif(trim(coalesce(p_papel,'')),''),
    coalesce(nullif(trim(coalesce(p_canal,'')),''),'whatsapp'),
    coalesce(nullif(trim(coalesce(p_origem,'')),''),'whatsapp'),
    greatest(1, least(5, coalesce(p_prioridade,3))),
    p_due_at,
    coalesce(p_tags,'{}'),
    case when v_status in ('resolvido','cancelado','expirado') then now() else null end,
    case when v_status in ('resolvido','cancelado','expirado') then nullif(trim(coalesce(p_solicitado_por_nome,'')),'') else null end
  ) returning * into v_row;

  -- audit trail (best effort; table exists)
  begin
    insert into public.maria_audit_log (
      ator_nome, ator_numero, papel, origem, canal, invoker_role,
      tabela, entidade_tipo, entidade_id, operacao, antes, depois, motivo, texto_original
    ) values (
      coalesce(p_solicitado_por_nome, p_agente_nome, 'Maria'),
      p_ator_numero,
      p_papel,
      coalesce(p_origem,'whatsapp'),
      coalesce(p_canal,'whatsapp'),
      current_user,
      'maria_agent_memory_events',
      'memory_event',
      v_row.id,
      'memory_registrar',
      null,
      jsonb_build_object(
        'id', v_row.id,
        'tipo', v_row.tipo,
        'status', v_row.status,
        'titulo', v_row.titulo,
        'resumo', v_row.resumo,
        'conta_pagar_id', v_row.conta_pagar_id,
        'unidade', v_row.unidade
      ),
      public.maria_agent_memory_sanitize_text(coalesce(p_motivo, p_resumo)),
      public.maria_agent_memory_sanitize_text(p_texto_original)
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'id', v_row.id,
    'tipo', v_row.tipo,
    'status', v_row.status,
    'titulo', v_row.titulo,
    'resumo', v_row.resumo,
    'conta_pagar_id', v_row.conta_pagar_id,
    'unidade', v_row.unidade,
    'prioridade', v_row.prioridade,
    'due_at', v_row.due_at,
    'created_at', v_row.created_at
  );
end;
$$;


ALTER FUNCTION "public"."maria_agent_memory_registrar"("p_tipo" "text", "p_titulo" "text", "p_resumo" "text", "p_status" "text", "p_detalhes" "jsonb", "p_conta_pagar_id" "uuid", "p_unidade" "text", "p_chat_id" "text", "p_mensagem_origem_id" "text", "p_solicitado_por_nome" "text", "p_agente_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_origem" "text", "p_prioridade" integer, "p_due_at" timestamp with time zone, "p_tags" "text"[], "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_agent_memory_sanitize_text"("p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  t text := coalesce(p_text, '');
begin
  -- long digit sequences (barcode / linha digitavel-ish)
  t := regexp_replace(t, '\d[\d\s\.\-]{18,}\d', '[codigo-redigido]', 'g');
  -- pix payload markers
  t := regexp_replace(t, '000201.+', '[pix-payload-redigido]', 'g');
  return left(t, 2000);
end;
$$;


ALTER FUNCTION "public"."maria_agent_memory_sanitize_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_assert_actor"("p_ator_numero" "text", "p_papel" "text", "p_allowed_papeis" "text"[]) RETURNS "public"."maria_whatsapp_atores"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_numero text;
  v_hash text;
  v_actor public.maria_whatsapp_atores%rowtype;
begin
  v_numero := public.maria_normalizar_numero(p_ator_numero);
  if v_numero = '' then
    raise exception 'sender ausente.' using errcode = '42501';
  end if;

  v_hash := encode(extensions.digest(v_numero, 'sha256'), 'hex');

  select *
    into v_actor
    from public.maria_whatsapp_atores
   where numero_hash = v_hash
     and ativo = true;

  if not found then
    raise exception 'sender nao autorizado para a Maria.' using errcode = '42501';
  end if;

  if v_actor.papel <> p_papel then
    raise exception 'papel informado nao confere com o sender.' using errcode = '42501';
  end if;

  if not (v_actor.papel = any(p_allowed_papeis)) then
    raise exception 'papel nao autorizado para esta operacao.' using errcode = '42501';
  end if;

  return v_actor;
end;
$$;


ALTER FUNCTION "public"."maria_assert_actor"("p_ator_numero" "text", "p_papel" "text", "p_allowed_papeis" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_audit_insert"("p_actor" "public"."maria_whatsapp_atores", "p_ator_numero" "text", "p_canal" "text", "p_tabela" "text", "p_entidade_tipo" "text", "p_entidade_id" "uuid", "p_operacao" "text", "p_antes" "jsonb", "p_depois" "jsonb", "p_motivo" "text", "p_texto_original" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_audit_id uuid;
  v_numero text;
begin
  v_numero := public.maria_normalizar_numero(p_ator_numero);

  insert into public.maria_audit_log (
    ator_nome,
    ator_numero,
    ator_numero_hash,
    ator_numero_last4,
    papel,
    origem,
    canal,
    invoker_role,
    tabela,
    entidade_tipo,
    entidade_id,
    operacao,
    antes,
    depois,
    motivo,
    texto_original
  )
  values (
    p_actor.nome,
    v_numero,
    p_actor.numero_hash,
    p_actor.numero_last4,
    p_actor.papel,
    'whatsapp',
    nullif(p_canal, ''),
    public.maria_invoker_role(),
    p_tabela,
    p_entidade_tipo,
    p_entidade_id,
    p_operacao,
    p_antes,
    p_depois,
    nullif(p_motivo, ''),
    nullif(p_texto_original, '')
  )
  returning id into v_audit_id;

  return v_audit_id;
end;
$$;


ALTER FUNCTION "public"."maria_audit_insert"("p_actor" "public"."maria_whatsapp_atores", "p_ator_numero" "text", "p_canal" "text", "p_tabela" "text", "p_entidade_tipo" "text", "p_entidade_id" "uuid", "p_operacao" "text", "p_antes" "jsonb", "p_depois" "jsonb", "p_motivo" "text", "p_texto_original" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartao_fatura_lancar_itens"("p_cartao_id" "uuid", "p_competencia" "date", "p_itens" "jsonb", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_confirmar_duplicidade" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_cartao public.financeiro_cartoes%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_fatura_criada boolean := false;
  v_importacao public.financeiro_cartao_importacoes%rowtype;
  v_item jsonb;
  v_idx integer := 0;
  v_total integer;
  v_descricao text;
  v_data_compra date;
  v_valor numeric;
  v_tipo_transacao text;
  v_plano_id uuid;
  v_centro_id uuid;
  v_empresa_id uuid;
  v_estabelecimento text;
  v_observacoes text;
  v_id_externo text;
  v_numero_linha text;
  v_fingerprint text;
  v_duplicate public.financeiro_cartao_transacoes%rowtype;
  v_after public.financeiro_cartao_transacoes%rowtype;
  v_results jsonb := '[]'::jsonb;
  v_duplicadas integer := 0;
  v_parc_atual integer;
  v_parc_total integer;
  v_parc_m text[];
  v_confirmado_por text;
  v_motivo text;
  v_canal text;
  v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_cartao_id is null then
    raise exception 'cartao_id obrigatorio para lancar itens de cartao.';
  end if;
  if p_competencia is null then
    raise exception 'competencia obrigatoria para lancar itens de cartao.';
  end if;
  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    raise exception 'itens obrigatorios para lancar fatura de cartao.';
  end if;
  if jsonb_array_length(p_itens) > 50 then
    raise exception 'limite operacional: no maximo 50 itens por lancamento de cartao.';
  end if;

  v_motivo := public.maria_contas_observacao_sanitizada(p_motivo);
  if v_motivo is null then
    raise exception 'motivo obrigatorio para lancar itens de cartao.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = p_cartao_id
     and ativo = true;
  if not found then
    raise exception 'cartao nao encontrado ou inativo.';
  end if;

  if v_cartao.empresa_id is null or v_cartao.centro_custo_id is null then
    raise exception 'cartao sem empresa/centro de custo padrao; ajuste cadastro antes de lancar.';
  end if;

  insert into public.financeiro_cartao_faturas (
    cartao_id,
    competencia,
    data_fechamento,
    data_vencimento,
    valor_total,
    status,
    observacoes
  ) values (
    p_cartao_id,
    date_trunc('month', p_competencia)::date,
    public.financeiro_cartao_data_fechamento_por_competencia(p_cartao_id, date_trunc('month', p_competencia)::date),
    public.financeiro_cartao_clamp_dia(
      extract(year from date_trunc('month', p_competencia))::int,
      extract(month from date_trunc('month', p_competencia))::int,
      v_cartao.dia_vencimento
    ),
    0,
    'aberta',
    concat_ws(E'\n',
      'Fatura aberta pela Maria para lancamento de itens conferidos.',
      public.maria_contas_observacao_sanitizada(p_motivo)
    )
  ) on conflict (cartao_id, competencia) do nothing;

  get diagnostics v_total = row_count;
  v_fatura_criada := v_total = 1;

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where cartao_id = p_cartao_id
     and competencia = date_trunc('month', p_competencia)::date
   for update;
  if not found then
    raise exception 'falha ao resolver fatura de cartao.';
  end if;

  if v_fatura.status <> 'aberta' then
    raise exception 'fatura nao esta aberta; status atual: %. Maria nao lanca item em fatura fechada/paga/cancelada.', v_fatura.status;
  end if;

  insert into public.financeiro_cartao_importacoes (
    cartao_id,
    fatura_id,
    origem,
    status,
    total_linhas,
    linhas_importadas,
    linhas_classificadas,
    linhas_pendentes,
    linhas_erro,
    linhas_duplicadas,
    ator_tipo,
    ator_ref,
    mensagem_erro
  ) values (
    p_cartao_id,
    v_fatura.id,
    'maria',
    'processando',
    jsonb_array_length(p_itens),
    0,
    0,
    0,
    0,
    0,
    'maria',
    public.maria_normalizar_numero(p_ator_numero),
    null
  ) returning * into v_importacao;

  v_confirmado_por := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal := coalesce(nullif(trim(p_canal), ''), 'whatsapp');

  for v_item in select * from jsonb_array_elements(p_itens)
  loop
    v_idx := v_idx + 1;
    v_numero_linha := v_idx::text;
    v_descricao := nullif(trim(v_item->>'descricao'), '');
    v_data_compra := nullif(v_item->>'data_compra', '')::date;
    v_valor := nullif(v_item->>'valor', '')::numeric;
    v_tipo_transacao := coalesce(nullif(v_item->>'tipo_transacao', ''), 'compra');
    -- 02/09/2026: estorno e sempre negativo (o app grava assim; a fatura recalcula por sum(valor)).
    if v_tipo_transacao = 'estorno' and v_valor > 0 then v_valor := -v_valor; end if;
    -- 02/09/2026: parcela em campo, nao so no texto ("PARC 02/06" / "(parc 2/6)").
    v_parc_atual := nullif(v_item->>'parcela_atual', '')::int;
    v_parc_total := nullif(v_item->>'total_parcelas', '')::int;
    if v_parc_atual is null or v_parc_total is null then
      v_parc_m := regexp_match(coalesce(v_descricao, ''), '(?:parc(?:ela)?\.?)\s*(\d{1,2})\s*/\s*(\d{1,2})', 'i');
      if v_parc_m is not null then
        v_parc_atual := coalesce(v_parc_atual, v_parc_m[1]::int);
        v_parc_total := coalesce(v_parc_total, v_parc_m[2]::int);
      end if;
    end if;
    v_plano_id := nullif(v_item->>'plano_conta_id', '')::uuid;
    v_centro_id := coalesce(nullif(v_item->>'centro_custo_id', '')::uuid, v_cartao.centro_custo_id);
    v_empresa_id := coalesce(nullif(v_item->>'empresa_id', '')::uuid, v_cartao.empresa_id);
    v_estabelecimento := nullif(trim(v_item->>'estabelecimento'), '');
    v_observacoes := public.maria_contas_observacao_sanitizada(v_item->>'observacoes');
    v_id_externo := coalesce(nullif(trim(v_item->>'id_externo'), ''), case when nullif(trim(p_mensagem_origem_id), '') is not null then concat('maria:', p_mensagem_origem_id, ':', v_idx) end);

    if v_descricao is null then
      raise exception 'item % sem descricao.', v_idx;
    end if;
    if v_data_compra is null then
      raise exception 'item % sem data_compra.', v_idx;
    end if;
    if v_valor is null or v_valor = 0 then
      raise exception 'item % sem valor valido.', v_idx;
    end if;
    if v_tipo_transacao not in ('compra','estorno','tarifa','anuidade','ajuste') then
      raise exception 'item % com tipo_transacao invalido.', v_idx;
    end if;
    if v_plano_id is null then
      raise exception 'item % sem plano_conta_id.', v_idx;
    end if;

    if not exists (select 1 from public.plano_contas where id = v_plano_id and ativo = true and natureza = 'saida' and nivel = 3) then
      raise exception 'item % com plano_conta_id invalido/inativo.', v_idx;
    end if;

    if not exists (
      select 1 from public.financeiro_empresas e
      where e.id = v_empresa_id and e.ativo = true and e.unidade_id = v_centro_id
    ) then
      raise exception 'item % com empresa/centro incoerentes.', v_idx;
    end if;

    if v_id_externo is not null and exists (
      select 1 from public.financeiro_cartao_transacoes
      where cartao_id = p_cartao_id and id_externo = v_id_externo
    ) then
      if not coalesce(p_confirmar_duplicidade, false) then
        raise exception 'item % ja foi lancado por id_externo; confirme duplicidade explicitamente para continuar.', v_idx;
      end if;
      v_duplicadas := v_duplicadas + 1;
    end if;

    v_fingerprint := encode(extensions.digest(
      concat_ws('|',
        p_cartao_id::text,
        v_fatura.competencia::text,
        v_numero_linha,
        v_data_compra::text,
        round(v_valor, 2)::text,
        lower(regexp_replace(v_descricao, '\s+', ' ', 'g'))
      ),
      'sha256'
    ), 'hex');

    select * into v_duplicate
      from public.financeiro_cartao_transacoes
     where fatura_id = v_fatura.id
       and fingerprint = v_fingerprint
     limit 1;

    if found then
      if not coalesce(p_confirmar_duplicidade, false) then
        raise exception 'possivel duplicidade no item %: "%" %. Confirme explicitamente para continuar.', v_idx, v_duplicate.descricao, v_duplicate.valor;
      end if;
      v_duplicadas := v_duplicadas + 1;
    end if;

    insert into public.financeiro_cartao_transacoes (
      fatura_id,
      cartao_id,
      importacao_id,
      data_compra,
      descricao,
      estabelecimento,
      valor, tipo_transacao, parcela_atual, total_parcelas, empresa_id, plano_conta_id,
      centro_custo_id,
      classificacao_status,
      classificado_por,
      classificado_em,
      fingerprint,
      possivel_duplicata,
      id_externo,
      fonte_tipo,
      ator_tipo,
      ator_ref,
      observacoes
    ) values (
      v_fatura.id,
      p_cartao_id,
      v_importacao.id,
      v_data_compra,
      v_descricao,
      v_estabelecimento,
      round(v_valor, 2), v_tipo_transacao, v_parc_atual, v_parc_total, v_empresa_id, v_plano_id,
      v_centro_id,
      'confirmada',
      'maria',
      now(),
      v_fingerprint,
      found,
      v_id_externo,
      'maria',
      'maria',
      public.maria_normalizar_numero(p_ator_numero),
      concat_ws(E'\n',
        v_observacoes,
        concat('Lancado pela Maria apos confirmacao de ', v_confirmado_por, ' em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '. Sem fechar fatura, sem pagar e sem executar transacao financeira real.'),
        concat('Motivo: ', v_motivo)
      )
    ) returning * into v_after;

    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'transacao_id', v_after.id,
      'descricao', v_after.descricao,
      'valor', v_after.valor,
      'data_compra', v_after.data_compra,
      'tipo_transacao', v_after.tipo_transacao,
      'classificacao_status', v_after.classificacao_status,
      'possivel_duplicata', v_after.possivel_duplicata
    ));
  end loop;

  update public.financeiro_cartao_importacoes
     set status = 'concluida',
         linhas_importadas = jsonb_array_length(p_itens),
         linhas_classificadas = jsonb_array_length(p_itens),
         linhas_pendentes = 0,
         linhas_erro = 0,
         linhas_duplicadas = v_duplicadas,
         updated_at = now()
   where id = v_importacao.id;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal,
    'financeiro_cartao_transacoes',
    'cartao_fatura_lancamento_maria',
    v_fatura.id,
    'lancar_itens_fatura_cartao',
    null,
    jsonb_build_object(
      'cartao_id', p_cartao_id,
      'cartao_apelido', v_cartao.apelido,
      'fatura_id', v_fatura.id,
      'competencia', v_fatura.competencia,
      'fatura_criada', v_fatura_criada,
      'importacao_id', v_importacao.id,
      'itens_lancados', jsonb_array_length(p_itens),
      'linhas_duplicadas', v_duplicadas,
      'itens', v_results,
      'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), '')
    ),
    v_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'cartao', v_cartao.apelido,
    'fatura_id', v_fatura.id,
    'competencia', v_fatura.competencia,
    'status_fatura', v_fatura.status,
    'fatura_criada', v_fatura_criada,
    'importacao_id', v_importacao.id,
    'itens_lancados', jsonb_array_length(p_itens),
    'linhas_duplicadas', v_duplicadas,
    'itens', v_results,
    'audit_id', v_audit_id,
    'confirmado_por', v_confirmado_por,
    'fatura_fechada_pela_maria', false,
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_cartao_fatura_lancar_itens"("p_cartao_id" "uuid", "p_competencia" "date", "p_itens" "jsonb", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_confirmar_duplicidade" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_alias_estabelecimento_match"("p_parser_descricao" "text", "p_existente_descricao" "text", "p_existente_estabelecimento" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_parser text := public.maria_cartoes_normalizar_texto(p_parser_descricao);
  v_existente text := public.maria_cartoes_normalizar_texto(concat_ws(' ', p_existente_descricao, p_existente_estabelecimento));
begin
  if v_parser = '' or v_existente = '' then
    return false;
  end if;

  return case
    when v_parser in ('OPENAI', 'OPEN AI')
      then v_existente similar to '%(OPENAI|OPEN AI|CHAT GPT|CHATGPT)%'
    when v_parser = 'IOF DESPESA NO EXTERIOR'
      then v_existente similar to '%(IOF|IOF CHAT GPT|IOF DESPESA NO EXTERIOR)%'
    when v_parser in ('FORNECEDORA CHATUBA DE', 'FORNECEDORA CHATUBA')
      then v_existente similar to '%(FORNECEDORA CHATUBA|CHATUBA|MATERIAL OBRA RECREIO)%'
    when v_parser = 'SUL AMERICA DECORACOES'
      then v_existente similar to '%(SUL AMERICA DECORACOES|SULAMERICA DECORACOES|PISO LAMINADO|SONORAMENTE)%'
    when v_parser in ('BEL LIVERPOOL', 'BELLIVERPOOL')
      then v_existente similar to '%(BEL LIVERPOOL|LIVERPOOL|BAQUETAS)%'
    when v_parser = 'QUATRO CANTOS'
      then v_existente similar to '%(QUATRO CANTOS)%'
    else
      v_existente like '%' || v_parser || '%'
  end;
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_alias_estabelecimento_match"("p_parser_descricao" "text", "p_existente_descricao" "text", "p_existente_estabelecimento" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_aplicar_sugestao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric DEFAULT 0.80, "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_ator_numero text;
  v_cartao_ator jsonb;
  v_calc jsonb;
  v_linhas_publicas jsonb;
  v_classificar_result jsonb;
  v_linha record;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_ator_numero := public.maria_normalizar_numero(p_ator_numero);
  v_cartao_ator := jsonb_build_object('tipo', 'maria', 'ref', v_ator_numero);

  v_calc := public.maria_cartoes_classificacao_sugestoes_calcular(
    p_cartao_id,
    p_competencia,
    p_limiar_confianca
  );

  for v_linha in
    select *
      from jsonb_to_recordset(v_calc->'linhas') as item(
        ordem int,
        transacao_id uuid,
        descricao text,
        acao text,
        plano_conta_id uuid,
        plano_sugerido_codigo text,
        confianca numeric,
        origem text
      )
     where item.acao = 'sugerida'
     order by item.ordem
  loop
    v_classificar_result := public.financeiro_cartao_transacao_classificar(
      jsonb_build_object(
        'transacao_id', v_linha.transacao_id,
        'classificacao_status', 'sugerida',
        'plano_conta_id', v_linha.plano_conta_id,
        'empresa_id', (v_calc->>'empresa_id')::uuid,
        'centro_custo_id', (v_calc->>'centro_custo_id')::uuid,
        'motivo', coalesce(nullif(p_motivo, ''), 'Sugestao de classificacao da Maria')
      ),
      v_cartao_ator
    );
  end loop;

  if (v_calc->>'fatura_id') is not null then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      p_canal,
      'financeiro_cartao_faturas',
      'cartao_fatura',
      (v_calc->>'fatura_id')::uuid,
      'aplicar_sugestao_classificacao_cartao',
      null,
      jsonb_build_object(
        'cartao_id', p_cartao_id,
        'competencia', (v_calc->>'competencia')::date,
        'total_pendentes', (v_calc->>'total_pendentes')::int,
        'sugeridas', (v_calc->>'sugeridas')::int,
        'pendentes', (v_calc->>'pendentes')::int,
        'conflitos', (v_calc->>'conflitos')::int,
        'aplicado', true
      ),
      p_motivo,
      p_texto_original
    );
  end if;

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'transacao_id', item.transacao_id,
    'descricao', item.descricao,
    'acao', item.acao,
    'plano_sugerido_codigo', case when item.acao = 'sugerida' then item.plano_sugerido_codigo else null end,
    'confianca', case when item.acao = 'sugerida' then item.confianca else null end,
    'origem', item.origem
  )) order by item.ordem), '[]'::jsonb)
    into v_linhas_publicas
    from jsonb_to_recordset(v_calc->'linhas') as item(
      ordem int,
      transacao_id uuid,
      descricao text,
      acao text,
      plano_conta_id uuid,
      plano_sugerido_codigo text,
      confianca numeric,
      origem text
    );

  return jsonb_build_object(
    'success', true,
    'fatura_id', v_calc->>'fatura_id',
    'total_pendentes', (v_calc->>'total_pendentes')::int,
    'sugeridas', (v_calc->>'sugeridas')::int,
    'pendentes', (v_calc->>'pendentes')::int,
    'conflitos', (v_calc->>'conflitos')::int,
    'aplicado', true,
    'linhas', v_linhas_publicas
  );
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_aplicar_sugestao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_cartoes_aplicar_sugestao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: aplica sugestoes de classificacao de cartao via financeiro_cartao_transacao_classificar; nunca confirma automaticamente.';



CREATE OR REPLACE FUNCTION "public"."maria_cartoes_catalogo"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text" DEFAULT 'whatsapp'::"text", "p_busca" "text" DEFAULT NULL::"text", "p_ativos" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_busca text;
  v_result jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe',
    'strategic_read_prepare'
  ]);

  v_busca := lower(nullif(trim(p_busca), ''));

  select coalesce(jsonb_agg(jsonb_build_object(
    'cartao_id', c.id,
    'apelido', c.apelido,
    'final', c.final,
    'bandeira', c.bandeira,
    'ativo', c.ativo,
    'centro_custo_id', c.centro_custo_id,
    'centro', cc.nome,
    'unidade_codigo', cc.codigo,
    'empresa_id', c.empresa_id,
    'empresa', coalesce(e.label_operacional, e.nome_fantasia, e.razao_social),
    'conta_pagadora_id', c.conta_pagadora_id,
    'conta_pagadora', cb.apelido,
    'dia_fechamento', c.dia_fechamento,
    'dia_vencimento', c.dia_vencimento
  ) order by c.ativo desc, c.apelido), '[]'::jsonb)
    into v_result
    from public.financeiro_cartoes c
    left join public.centros_custo cc on cc.id = c.centro_custo_id
    left join public.financeiro_empresas e on e.id = c.empresa_id
    left join public.financeiro_contas_bancarias cb on cb.id = c.conta_pagadora_id
   where (p_ativos is not true or c.ativo = true)
     and (
       v_busca is null
       or lower(c.apelido) like '%' || v_busca || '%'
       or c.final like '%' || regexp_replace(v_busca, '\D', '', 'g') || '%'
       or lower(coalesce(e.label_operacional, e.nome_fantasia, e.razao_social, '')) like '%' || v_busca || '%'
       or lower(coalesce(cc.nome, cc.codigo, '')) like '%' || v_busca || '%'
     );

  return jsonb_build_object('success', true, 'cartoes', v_result);
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_catalogo"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_busca" "text", "p_ativos" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_classificacao_sugestoes_calcular"("p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric DEFAULT 0.80) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_cartao public.financeiro_cartoes%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_fatura_id uuid;
  v_empresa_id uuid;
  v_centro_custo_id uuid;
  v_total_pendentes int := 0;
  v_sugeridas int := 0;
  v_pendentes int := 0;
  v_conflitos int := 0;
  v_linhas jsonb := '[]'::jsonb;
  v_ordem int := 0;
  v_transacao record;
  v_texto_norm text;
  v_regra record;
  v_regra_encontrada boolean;
  v_regra_sem_sugestao boolean;
  v_historico_plano_id uuid;
  v_historico_top_count int;
  v_historico_total int;
  v_historico_second_count int;
  v_historico_conflito boolean;
  v_plano_id uuid;
  v_plano_codigo text;
  v_confianca numeric;
  v_origem text;
  v_acao text;
  v_triade_valida boolean;
begin
  if p_cartao_id is null then
    raise exception 'p_cartao_id obrigatorio.';
  end if;

  if p_competencia is null then
    raise exception 'p_competencia obrigatoria.';
  end if;

  if p_limiar_confianca is null or p_limiar_confianca < 0 or p_limiar_confianca > 1 then
    raise exception 'p_limiar_confianca deve estar entre 0 e 1.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = p_cartao_id
     and ativo = true;

  if not found then
    raise exception 'cartao nao encontrado ou inativo.';
  end if;

  v_empresa_id := v_cartao.empresa_id;
  v_centro_custo_id := v_cartao.centro_custo_id;

  select * into v_fatura
    from public.financeiro_cartao_faturas f
   where f.cartao_id = p_cartao_id
     and f.competencia = date_trunc('month', p_competencia)::date;

  if not found then
    return jsonb_build_object(
      'success', true,
      'fatura_id', null,
      'cartao_id', p_cartao_id,
      'competencia', date_trunc('month', p_competencia)::date,
      'empresa_id', v_empresa_id,
      'centro_custo_id', v_centro_custo_id,
      'total_pendentes', 0,
      'sugeridas', 0,
      'pendentes', 0,
      'conflitos', 0,
      'aplicado', false,
      'linhas', '[]'::jsonb
    );
  end if;

  v_fatura_id := v_fatura.id;

  for v_transacao in
    select t.id, t.descricao, t.estabelecimento
      from public.financeiro_cartao_transacoes t
     where t.fatura_id = v_fatura_id
       -- confirmadas permanecem fora do conjunto calculado e aplicavel.
       and t.classificacao_status = 'pendente'
     order by t.data_compra, t.created_at, t.id
  loop
    v_total_pendentes := v_total_pendentes + 1;
    v_ordem := v_ordem + 1;
    v_texto_norm := public.maria_cartoes_normalizar_texto(
      coalesce(v_transacao.descricao, '') || ' ' || coalesce(v_transacao.estabelecimento, '')
    );

    v_regra_encontrada := false;
    v_regra_sem_sugestao := false;
    v_historico_conflito := false;
    v_plano_id := null;
    v_plano_codigo := null;
    v_confianca := null;
    v_origem := null;
    v_acao := 'pendente';
    v_triade_valida := false;
    v_historico_plano_id := null;
    v_historico_top_count := 0;
    v_historico_total := 0;
    v_historico_second_count := 0;

    -- Regra ativa tem precedencia sobre historico. Regra NULL e uma decisao explicita de nao sugerir.
    select
      r.id,
      r.palavra_chave,
      r.plano_conta_id,
      r.confianca_base,
      r.prioridade,
      p.codigo as plano_codigo
      into v_regra
      from public.maria_classificacao_regras r
      left join public.plano_contas p on p.id = r.plano_conta_id
     where r.ativo = true
       and r.escopo in ('cartao','geral')
       and position(r.palavra_chave in v_texto_norm) > 0
     order by r.prioridade desc, r.confianca_base desc, r.created_at asc
     limit 1;

    v_regra_encontrada := found;

    if v_regra_encontrada and v_regra.plano_conta_id is null then
      v_regra_sem_sugestao := true;
    end if;

    if v_regra_sem_sugestao then
      v_acao := 'pendente';
      v_origem := 'regra_sem_sugestao';
    elsif v_regra_encontrada then
      v_plano_id := v_regra.plano_conta_id;
      v_plano_codigo := v_regra.plano_codigo;
      v_confianca := v_regra.confianca_base;
      v_origem := 'regra';
    end if;

    if v_plano_id is null and not v_regra_sem_sugestao then
      with tokens as (
        select distinct token
          from regexp_split_to_table(v_texto_norm, ' ') as token
         where length(token) >= 4
      ),
      historico_plano as (
        select ht.plano_conta_id, count(*)::int as ocorrencias
          from public.financeiro_cartao_transacoes ht
         where ht.plano_conta_id is not null
           and ht.classificacao_status = 'confirmada'
           and ht.id <> v_transacao.id
           and (
                 -- token-cabeca (02/09/2026): nome do estabelecimento, nao qualquer token
                 public.maria_cartoes_token_cabeca(v_texto_norm) in (
                   public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(ht.descricao, ''))),
                   public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(ht.estabelecimento, '')))
                 )
               )
         group by ht.plano_conta_id
        union all
        select cp.plano_conta_id, count(*)::int as ocorrencias
          from public.contas_pagar cp
         where cp.plano_conta_id is not null
           and coalesce(cp.status, '') <> 'cancelado'
           and (
                 public.maria_cartoes_token_cabeca(v_texto_norm)
                   = public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(cp.descricao, '')))
               )
         group by cp.plano_conta_id
      ),
      historico_agg as (
        select plano_conta_id, sum(ocorrencias)::int as ocorrencias
          from historico_plano
         group by plano_conta_id
      ),
      ranked as (
        select
          plano_conta_id,
          ocorrencias,
          sum(ocorrencias) over ()::int as total,
          row_number() over (order by ocorrencias desc, plano_conta_id) as rn
        from historico_agg
      )
      select r1.plano_conta_id,
             r1.ocorrencias,
             r1.total,
             coalesce(r2.ocorrencias, 0)
        into v_historico_plano_id,
             v_historico_top_count,
             v_historico_total,
             v_historico_second_count
        from ranked r1
        left join ranked r2 on r2.rn = 2
       where r1.rn = 1;

      if v_historico_plano_id is not null then
        if v_historico_second_count > 0
           and (v_historico_second_count::numeric / greatest(v_historico_total, 1)) >= 0.35 then
          v_historico_conflito := true;
          v_acao := 'conflito';
          v_origem := 'historico_conflito';
        else
          v_plano_id := v_historico_plano_id;
          v_confianca := round(least(0.90, 0.65 + (v_historico_top_count::numeric / greatest(v_historico_total, 1)) * 0.25), 2);
          v_origem := 'historico';

          select p.codigo into v_plano_codigo
            from public.plano_contas p
           where p.id = v_plano_id;
        end if;
      else
        v_origem := coalesce(v_origem, 'sem_historico');
      end if;
    end if;

    if v_plano_id is not null and not v_historico_conflito then
      select exists (
        select 1
          from public.plano_contas p
          join public.financeiro_empresas e on e.id = v_empresa_id
         where p.id = v_plano_id
           and p.nivel = 3
           and p.natureza = 'saida'
           and p.ativo = true
           and e.ativo = true
           and e.unidade_id = v_centro_custo_id
      ) into v_triade_valida;

      if v_triade_valida and v_confianca >= p_limiar_confianca then
        v_acao := 'sugerida';
      elsif v_confianca < p_limiar_confianca then
        v_acao := 'pendente';
        v_origem := coalesce(v_origem, 'baixa_confianca');
      else
        v_acao := 'pendente';
        v_origem := coalesce(v_origem, 'triade_invalida');
      end if;
    end if;

    if v_acao = 'sugerida' then
      v_sugeridas := v_sugeridas + 1;
    elsif v_acao = 'conflito' then
      v_conflitos := v_conflitos + 1;
    else
      v_pendentes := v_pendentes + 1;
    end if;

    v_linhas := v_linhas || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'ordem', v_ordem,
      'transacao_id', v_transacao.id,
      'descricao', v_transacao.descricao,
      'acao', v_acao,
      'plano_conta_id', case when v_acao = 'sugerida' then v_plano_id else null end,
      'plano_sugerido_codigo', case when v_acao = 'sugerida' then v_plano_codigo else null end,
      'confianca', case when v_acao = 'sugerida' then v_confianca else null end,
      'origem', v_origem
    )));
  end loop;

  return jsonb_build_object(
    'success', true,
    'fatura_id', v_fatura_id,
    'cartao_id', p_cartao_id,
    'competencia', date_trunc('month', p_competencia)::date,
    'empresa_id', v_empresa_id,
    'centro_custo_id', v_centro_custo_id,
    'total_pendentes', v_total_pendentes,
    'sugeridas', v_sugeridas,
    'pendentes', v_pendentes,
    'conflitos', v_conflitos,
    'aplicado', false,
    'linhas', v_linhas
  );
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_classificacao_sugestoes_calcular"("p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_cartoes_classificacao_sugestoes_calcular"("p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric) IS 'Helper interno da Maria: calcula sugestoes de classificacao de cartao sem gravar; sem grant operacional direto.';



CREATE OR REPLACE FUNCTION "public"."maria_cartoes_fatura_conferencia"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_result jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  select * into v_fatura
    from public.financeiro_cartao_faturas f
   where f.cartao_id = p_cartao_id
     and f.competencia = date_trunc('month', p_competencia)::date
   order by f.created_at desc
   limit 1;

  if not found then
    return jsonb_build_object(
      'success', false,
      'error', 'fatura_nao_encontrada',
      'cartao_id', p_cartao_id,
      'competencia', date_trunc('month', p_competencia)::date
    );
  end if;

  with linhas as (
    select
      t.id,
      t.data_compra,
      t.descricao,
      t.estabelecimento,
      t.valor,
      t.tipo_transacao,
      t.classificacao_status,
      pc.codigo as plano_codigo,
      pc.nome as plano_nome
    from public.financeiro_cartao_transacoes t
    left join public.plano_contas pc on pc.id = t.plano_conta_id
    where t.fatura_id = v_fatura.id
  ), agregados as (
    select
      count(*)::int as linhas_total,
      coalesce(round(sum(valor), 2), 0)::numeric as soma_transacoes,
      count(*) filter (where classificacao_status = 'pendente')::int as pendentes,
      count(*) filter (where classificacao_status = 'sugerida')::int as sugeridas,
      count(*) filter (where classificacao_status = 'conflito')::int as conflitos,
      coalesce(round(sum(valor) filter (where classificacao_status = 'pendente'), 2), 0)::numeric as subtotal_pendente,
      coalesce(round(sum(valor) filter (where classificacao_status = 'sugerida'), 2), 0)::numeric as subtotal_sugerido,
      coalesce(round(sum(valor) filter (where classificacao_status = 'conflito'), 2), 0)::numeric as subtotal_conflito
    from linhas
  )
  select jsonb_build_object(
    'success', true,
    'fatura', jsonb_build_object(
      'id', v_fatura.id,
      'competencia', v_fatura.competencia,
      'status', v_fatura.status,
      'valor_total', v_fatura.valor_total
    ),
    'resumo', to_jsonb(a),
    'linhas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', id,
        'data_compra', data_compra,
        'descricao', descricao,
        'estabelecimento', estabelecimento,
        'valor', valor,
        'tipo_transacao', tipo_transacao,
        'classificacao_status', classificacao_status,
        'plano_codigo', plano_codigo,
        'plano_nome', plano_nome
      ) order by data_compra, descricao, valor)
      from linhas
    ), '[]'::jsonb)
  ) into v_result
  from agregados a;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_fatura_conferencia"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_fatura_produtos_ml"("p_cartao_id" "uuid", "p_competencia" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'descricao', t.descricao, 'valor', t.valor,
           'produto', case when t.descricao ~* 'mercado ?livre|mercadolivre'
                           then (maria_ml_identificar_compra(
                                  t.descricao, t.valor, t.data_compra,
                                  'd4264a77-e7eb-48e0-bdae-d16c0d8bcd8e'::uuid, 5, 0.80,
                                  case when t.parcela_atual is not null and t.total_parcelas is not null
                                       then round(t.valor * t.total_parcelas, 2) else null end
                                )->'produto'->>'produto_titulo')
                           else null end
         )), '[]'::jsonb)
  from financeiro_cartao_faturas f
  join financeiro_cartao_transacoes t on t.fatura_id = f.id
  where f.cartao_id = p_cartao_id and f.competencia = p_competencia;
$$;


ALTER FUNCTION "public"."maria_cartoes_fatura_produtos_ml"("p_cartao_id" "uuid", "p_competencia" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_fatura_reclassificar"("p_ator_numero" "text", "p_papel" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_tokens" "text"[], "p_data" "date", "p_valor" numeric, "p_plano_destino" "text", "p_aprender" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor maria_whatsapp_atores%rowtype;
  v_fatura financeiro_cartao_faturas%rowtype;
  v_rec record; v_cnt int; v_n int;
  v_plano_id uuid; v_plano_cod text; v_plano_nome text;
  v_old_cod text; v_old_nome text;
  v_kw text; v_aprendeu text := 'nao_tentou'; v_cands jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel,
    array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);

  select * into v_fatura from financeiro_cartao_faturas f
   where f.cartao_id=p_cartao_id and f.competencia=date_trunc('month',p_competencia)::date
   order by f.created_at desc limit 1;
  if not found then return jsonb_build_object('success',false,'error','fatura_nao_encontrada'); end if;

  select id,codigo,nome into v_plano_id,v_plano_cod,v_plano_nome
    from plano_contas where natureza='saida' and nivel=3
      and lower(btrim(codigo))=lower(btrim(coalesce(p_plano_destino,''))) limit 1;
  if v_plano_id is null then
    select count(*) into v_n from plano_contas
      where natureza='saida' and nivel=3 and length(coalesce(p_plano_destino,''))>=4
        and public.maria_cartoes_normalizar_texto(nome) like '%'||public.maria_cartoes_normalizar_texto(coalesce(p_plano_destino,''))||'%';
    if v_n=1 then
      select id,codigo,nome into v_plano_id,v_plano_cod,v_plano_nome from plano_contas
       where natureza='saida' and nivel=3
         and public.maria_cartoes_normalizar_texto(nome) like '%'||public.maria_cartoes_normalizar_texto(p_plano_destino)||'%' limit 1;
    end if;
  end if;
  if v_plano_id is null then return jsonb_build_object('success',false,'error','plano_nao_resolvido','plano_destino',p_plano_destino); end if;

  select q.cnt, q.id, q.data_compra, q.descricao, q.estabelecimento, q.valor, q.plano_conta_id into v_rec
  from (
    select t.*, count(*) over() as cnt from financeiro_cartao_transacoes t
    left join lateral (
      select string_agg(p.produto_titulo||' '||coalesce(p.produtos_extra,''),' ') as ml_prod
      from ml_pedidos p where round(p.valor_total,2)=round(t.valor,2)
        and (t.descricao ~* 'mercado ?livre|mercadolivre' or coalesce(t.estabelecimento,'') ~* 'mercado ?livre|mercadolivre')
    ) mlp on true
    where t.fatura_id=v_fatura.id
      and (p_data is null or t.data_compra=p_data)
      and (p_valor is null or round(t.valor,2)=round(p_valor,2))
      and (cardinality(coalesce(p_tokens,'{}'::text[]))=0 or (
          select bool_and(public.maria_cartoes_normalizar_texto(coalesce(t.descricao,'')||' '||coalesce(t.estabelecimento,'')||' '||coalesce(mlp.ml_prod,''))
                          like '%'||public.maria_cartoes_normalizar_texto(tok)||'%')
          from unnest(p_tokens) tok where length(tok)>=2))
  ) q order by q.data_compra, q.valor limit 1;

  v_cnt := coalesce(v_rec.cnt, 0);
  if v_cnt=0 then return jsonb_build_object('success',false,'error','linha_nao_encontrada'); end if;
  if v_cnt>1 then
    select jsonb_agg(jsonb_build_object('data',x.data_compra,'descricao',x.descricao,'valor',x.valor,
             'plano',(select codigo from plano_contas where id=x.plano_conta_id)) order by x.data_compra, x.valor)
      into v_cands
    from ( select t.* from financeiro_cartao_transacoes t
      left join lateral (
        select string_agg(p.produto_titulo||' '||coalesce(p.produtos_extra,''),' ') as ml_prod
        from ml_pedidos p where round(p.valor_total,2)=round(t.valor,2)
          and (t.descricao ~* 'mercado ?livre|mercadolivre' or coalesce(t.estabelecimento,'') ~* 'mercado ?livre|mercadolivre')
      ) mlp on true
      where t.fatura_id=v_fatura.id
        and (p_data is null or t.data_compra=p_data)
        and (p_valor is null or round(t.valor,2)=round(p_valor,2))
        and (cardinality(coalesce(p_tokens,'{}'::text[]))=0 or (
            select bool_and(public.maria_cartoes_normalizar_texto(coalesce(t.descricao,'')||' '||coalesce(t.estabelecimento,'')||' '||coalesce(mlp.ml_prod,''))
                            like '%'||public.maria_cartoes_normalizar_texto(tok)||'%')
            from unnest(p_tokens) tok where length(tok)>=2))
      limit 10 ) x;
    return jsonb_build_object('success',false,'error','linha_ambigua','candidatos',coalesce(v_cands,'[]'::jsonb));
  end if;

  select codigo,nome into v_old_cod,v_old_nome from plano_contas where id=v_rec.plano_conta_id;

  update financeiro_cartao_transacoes
     set plano_conta_id=v_plano_id, classificacao_status='confirmada',
         centro_custo_id=coalesce(centro_custo_id,(select c.centro_custo_id from public.financeiro_cartoes c where c.id=p_cartao_id)),
         empresa_id=coalesce(empresa_id,(select c.empresa_id from public.financeiro_cartoes c where c.id=p_cartao_id)),
         classificado_por='correcao_wa:'||right(regexp_replace(coalesce(p_ator_numero,''),'[^0-9]','','g'),4),
         classificado_em=now(), updated_at=now()
   where id=v_rec.id;

  if coalesce(p_aprender,true) then
    v_kw := btrim(regexp_replace(public.maria_cartoes_normalizar_texto(coalesce(v_rec.descricao,'')),
                 '^(MERCADO ?LIVRE|MERCADO ?PAGO|MERCADOPAGO|MP)[^A-Z0-9]*', ''));
    if v_kw is null or length(v_kw)<4 then
      v_kw := btrim(regexp_replace(public.maria_cartoes_normalizar_texto(coalesce(nullif(v_rec.estabelecimento,''),'')),
                   '^(MERCADO ?LIVRE|MERCADO ?PAGO|MERCADOPAGO|MP)[^A-Z0-9]*', ''));
    end if;
    if length(coalesce(v_kw,''))>=4 and v_kw !~ 'MERCADO|LIVRE' and v_kw !~ '^(COMPRA|COMPRAS|DIVERSOS|PAGAMENTO|PAGO)$' then
      update maria_classificacao_regras set ativo=false, updated_at=now()
        where ativo and palavra_chave=v_kw and escopo in ('cartao','geral') and plano_conta_id<>v_plano_id;
      if exists (select 1 from maria_classificacao_regras where ativo and palavra_chave=v_kw and plano_conta_id=v_plano_id) then
        v_aprendeu := 'idempotente';
      else
        insert into maria_classificacao_regras(palavra_chave, plano_conta_id, escopo, prioridade, confianca_base, ativo, origem, aprovado_por, aprovado_em, observacao)
          values (v_kw, v_plano_id, 'cartao', 250, 0.99, true, 'correcao-humana-wa', p_papel, now(),
                  'Correcao humana WhatsApp - fatura '||to_char(v_fatura.competencia,'YYYY-MM'));
        v_aprendeu := 'aprendida';
      end if;
    else
      v_aprendeu := 'keyword_generica_pulou';
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'linha', jsonb_build_object('id',v_rec.id,'data_compra',v_rec.data_compra,'descricao',v_rec.descricao,'estabelecimento',v_rec.estabelecimento,'valor',v_rec.valor),
    'plano_antigo', coalesce(v_old_cod||' '||v_old_nome,'sem plano'),
    'plano_novo', v_plano_cod||' '||v_plano_nome,
    'mudou', (v_old_cod is distinct from v_plano_cod),
    'aprendizado', jsonb_build_object('status',v_aprendeu,'palavra_chave',v_kw),
    'competencia', to_char(v_fatura.competencia,'YYYY-MM')
  );
end $_$;


ALTER FUNCTION "public"."maria_cartoes_fatura_reclassificar"("p_ator_numero" "text", "p_papel" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_tokens" "text"[], "p_data" "date", "p_valor" numeric, "p_plano_destino" "text", "p_aprender" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_importacao_preconciliar_lote"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_linhas" "jsonb", "p_limiar_match" numeric DEFAULT 0.85, "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_total int;
  v_result jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_limiar_match is null or p_limiar_match < 0 or p_limiar_match > 1 then
    raise exception 'p_limiar_match deve estar entre 0 e 1.';
  end if;

  if p_linhas is null or jsonb_typeof(p_linhas) <> 'array' then
    raise exception 'p_linhas deve ser um array json.';
  end if;

  v_total := jsonb_array_length(p_linhas);
  if v_total = 0 then
    raise exception 'p_linhas deve conter ao menos uma linha.';
  end if;

  select * into v_fatura
    from public.financeiro_cartao_faturas f
   where f.cartao_id = p_cartao_id
     and f.competencia = date_trunc('month', p_competencia)::date
   limit 1;

  if not found then
    return jsonb_build_object(
      'success', true,
      'fatura_id', null,
      'parser_lines', v_total,
      'existing_lines', 0,
      'matched_existing', 0,
      'manual_review', 0,
      'new_lines_count', v_total,
      'new_total', (
        select coalesce(round(sum(abs(nullif(l.value->>'valor', '')::numeric)), 2), 0)
          from jsonb_array_elements(p_linhas) l(value)
      ),
      'matches', '[]'::jsonb,
      'manual_review_lines', '[]'::jsonb,
      'new_lines', p_linhas,
      'warning', 'fatura inexistente; todas as linhas retornadas como novas'
    );
  end if;

  with input_lines as (
    select
      value as linha,
      ordinality::int as ord,
      coalesce(nullif(value->>'numero_linha', '')::int, ordinality::int) as numero_linha,
      nullif(value->>'data_compra', '')::date as data_compra,
      public.maria_cartoes_normalizar_texto(value->>'descricao') as descricao_norm,
      public.maria_cartoes_normalizar_texto(value->>'estabelecimento') as estabelecimento_norm,
      nullif(value->>'valor', '')::numeric as valor,
      nullif(value->>'tipo_transacao', '') as tipo_transacao,
      nullif(value->>'parcela_atual', '')::int as parcela_atual,
      nullif(value->>'total_parcelas', '')::int as total_parcelas
    from jsonb_array_elements(p_linhas) with ordinality
  ), existing as (
    select
      t.id,
      t.data_compra,
      t.descricao,
      t.estabelecimento,
      t.valor,
      t.tipo_transacao,
      t.parcela_atual,
      t.total_parcelas,
      t.classificacao_status,
      t.fingerprint,
      t.id_externo,
      t.fonte_tipo,
      t.ator_tipo,
      t.compra_parcelada_id
    from public.financeiro_cartao_transacoes t
    where t.fatura_id = v_fatura.id
  ), candidates as (
    select
      i.*,
      e.id as existente_id,
      e.data_compra as existente_data_compra,
      e.descricao as existente_descricao,
      e.estabelecimento as existente_estabelecimento,
      e.valor as existente_valor,
      e.tipo_transacao as existente_tipo_transacao,
      e.parcela_atual as existente_parcela_atual,
      e.total_parcelas as existente_total_parcelas,
      e.classificacao_status as existente_classificacao_status,
      e.fingerprint as existente_fingerprint,
      e.id_externo as existente_id_externo,
      e.fonte_tipo as existente_fonte_tipo,
      e.ator_tipo as existente_ator_tipo,
      public.maria_cartoes_alias_estabelecimento_match(i.linha->>'descricao', e.descricao, e.estabelecimento) as alias_match,
      abs(i.data_compra - e.data_compra) as dias_diff,
      (
        60
        + case
            when (i.parcela_atual is not null or e.parcela_atual is not null)
             and i.parcela_atual = e.parcela_atual
             and i.total_parcelas = e.total_parcelas then 20
            when (i.parcela_atual is not null or e.parcela_atual is not null) then -30
            else 0
          end
        + case
            when i.data_compra = e.data_compra then 15
            when abs(i.data_compra - e.data_compra) <= 45 then 5
            else 0
          end
        + case when public.maria_cartoes_alias_estabelecimento_match(i.linha->>'descricao', e.descricao, e.estabelecimento) then 25 else 0 end
        + case when coalesce(i.tipo_transacao, '') = coalesce(e.tipo_transacao, '') then 5 else 0 end
      ) as score
    from input_lines i
    join existing e on (
      round(abs(e.valor), 2) = round(abs(i.valor), 2)
      -- Projecao de parcela (compra parcelada lancada no app) x linha do PDF: o banco arredonda a
      -- parcela por centavos (Baquetas 550,32 no app x 550,31 na fatura 2270 de 09/2026). Sem
      -- tolerancia a projecao nunca casa e a importacao duplica a parcela. (01/09/2026)
      or ((e.parcela_atual is not null or e.compra_parcelada_id is not null)
          and abs(abs(e.valor) - abs(i.valor)) <= 0.05)
    )
  ), ranked as (
    select
      c.*,
      row_number() over (partition by c.numero_linha order by c.score desc, c.dias_diff asc, c.existente_id) as rn,
      lead(c.score) over (partition by c.numero_linha order by c.score desc, c.dias_diff asc, c.existente_id) as second_score
    from candidates c
    where c.score >= 70
  ), best as (
    select * from ranked where rn = 1
  ), selected_counts as (
    select existente_id, count(*) as qtd
      from best
     where (
       score >= (p_limiar_match * 100)
       or (score >= 80 and alias_match)
     )
     group by existente_id
  ), decisions as (
    select
      i.linha,
      i.ord,
      i.numero_linha,
      b.existente_id,
      b.existente_data_compra,
      b.existente_descricao,
      b.existente_estabelecimento,
      b.existente_valor,
      b.existente_tipo_transacao,
      b.existente_parcela_atual,
      b.existente_total_parcelas,
      b.existente_classificacao_status,
      b.existente_fingerprint,
      b.existente_id_externo,
      b.existente_fonte_tipo,
      b.existente_ator_tipo,
      b.score,
      b.alias_match,
      b.second_score,
      coalesce(sc.qtd, 0) as selected_same_existing_count,
      case
        when b.existente_id is null then 'new'
        when coalesce(sc.qtd, 0) > 1 then 'manual_review'
        when (b.second_score is not null and b.score - b.second_score < 15) then 'manual_review'
        when (b.score >= (p_limiar_match * 100) or (b.score >= 80 and b.alias_match)) then 'skip_existing'
        when b.score >= 70 then 'manual_review'
        else 'new'
      end as action,
      jsonb_strip_nulls(jsonb_build_object(
        'valor_exato', b.existente_id is not null,
        'parcela_igual', case when b.existente_id is not null and (i.parcela_atual is not null or b.existente_parcela_atual is not null) then i.parcela_atual = b.existente_parcela_atual and i.total_parcelas = b.existente_total_parcelas end,
        'data_igual', case when b.existente_id is not null then i.data_compra = b.existente_data_compra end,
        'data_diff_dias', b.dias_diff,
        'alias_estabelecimento', b.alias_match,
        'tipo_igual', case when b.existente_id is not null then coalesce(i.tipo_transacao, '') = coalesce(b.existente_tipo_transacao, '') end,
        'score_segundo_candidato', b.second_score,
        'mesmo_existente_selecionado_por', nullif(coalesce(sc.qtd, 0), 0)
      )) as reasons
    from input_lines i
    left join best b on b.numero_linha = i.numero_linha
    left join selected_counts sc on sc.existente_id = b.existente_id
  )
  select jsonb_build_object(
    'success', true,
    'fatura_id', v_fatura.id,
    'parser_lines', v_total,
    'existing_lines', (select count(*) from existing),
    'matched_existing', (select count(*) from decisions where action = 'skip_existing'),
    'manual_review', (select count(*) from decisions where action = 'manual_review'),
    'new_lines_count', (select count(*) from decisions where action = 'new'),
    'new_total', (select coalesce(round(sum(abs(nullif(linha->>'valor', '')::numeric)), 2), 0) from decisions where action = 'new'),
    'matches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'parser_numero_linha', numero_linha,
        'score', score,
        'action', action,
        'reasons', reasons,
        'parser', linha,
        'existing', jsonb_strip_nulls(jsonb_build_object(
          'id', existente_id,
          'data_compra', existente_data_compra,
          'descricao', existente_descricao,
          'estabelecimento', existente_estabelecimento,
          'valor', existente_valor,
          'tipo_transacao', existente_tipo_transacao,
          'parcela_atual', existente_parcela_atual,
          'total_parcelas', existente_total_parcelas,
          'classificacao_status', existente_classificacao_status,
          'fingerprint', existente_fingerprint,
          'id_externo', existente_id_externo,
          'fonte_tipo', existente_fonte_tipo,
          'ator_tipo', existente_ator_tipo
        ))
      ) order by ord)
      from decisions
      where action = 'skip_existing'
    ), '[]'::jsonb),
    'manual_review_lines', coalesce((
      select jsonb_agg(jsonb_build_object(
        'parser_numero_linha', numero_linha,
        'score', score,
        'action', action,
        'reasons', reasons,
        'parser', linha,
        'candidate', jsonb_strip_nulls(jsonb_build_object(
          'id', existente_id,
          'data_compra', existente_data_compra,
          'descricao', existente_descricao,
          'estabelecimento', existente_estabelecimento,
          'valor', existente_valor,
          'tipo_transacao', existente_tipo_transacao,
          'parcela_atual', existente_parcela_atual,
          'total_parcelas', existente_total_parcelas
        ))
      ) order by ord)
      from decisions
      where action = 'manual_review'
    ), '[]'::jsonb),
    'new_lines', coalesce((
      select jsonb_agg(linha order by ord)
        from decisions
       where action = 'new'
    ), '[]'::jsonb)
  ) into v_result;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    p_canal,
    'financeiro_cartao_faturas',
    'preconciliacao',
    v_fatura.id,
    'preconciliar_lote',
    null,
    jsonb_build_object(
      'cartao_id', p_cartao_id,
      'competencia', date_trunc('month', p_competencia)::date,
      'parser_lines', v_total,
      'existing_lines', v_result->'existing_lines',
      'matched_existing', v_result->'matched_existing',
      'manual_review', v_result->'manual_review',
      'new_lines_count', v_result->'new_lines_count',
      'new_total', v_result->'new_total',
      'motivo', p_motivo
    ),
    p_motivo,
    null
  );

  return v_result;
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_importacao_preconciliar_lote"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_linhas" "jsonb", "p_limiar_match" numeric, "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_importacao_registrar_lote"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_documento" "jsonb", "p_linhas" "jsonb", "p_limiar_confianca" numeric DEFAULT 0.80, "p_texto_original" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_ator_numero text;
  v_cartao public.financeiro_cartoes%rowtype;
  v_cartao_ator jsonb;
  v_open jsonb;
  v_fatura public.financeiro_cartao_faturas%rowtype;
  v_documento public.financeiro_documentos%rowtype;
  v_documento_tipo text;
  v_documento_origem text;
  v_documento_hash text;
  v_importacao public.financeiro_cartao_importacoes%rowtype;
  v_importacao_existente public.financeiro_cartao_importacoes%rowtype;
  v_total int;
  v_importadas int := 0;
  v_duplicadas int := 0;
  v_sugeridas int := 0;
  v_pendentes int := 0;
  v_linhas_erro int := 0;
  v_linhas_resultado jsonb := '[]'::jsonb;
  v_linha jsonb;
  v_linha_idx int;
  v_linha_numero int;
  v_linha_data date;
  v_linha_descricao text;
  v_linha_estabelecimento text;
  v_linha_valor numeric;
  v_linha_tipo_transacao text;
  v_linha_parcela_atual int;
  v_linha_total_parcelas int;
  v_confianca numeric;
  v_classificacao jsonb;
  v_linha_plano_conta_id uuid;
  v_linha_empresa_id uuid;
  v_linha_centro_custo_id uuid;
  v_linha_classificacao_status text;
  v_triade_valida boolean;
  v_id_externo_base text;
  v_id_externo text;
  v_fingerprint text;
  v_duplicada_id uuid;
  v_transacao_payload jsonb;
  v_transacao_result jsonb;
  v_transacao_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_ator_numero := public.maria_normalizar_numero(p_ator_numero);
  v_cartao_ator := jsonb_build_object('tipo', 'maria', 'ref', v_ator_numero);

  if p_limiar_confianca is null or p_limiar_confianca < 0 or p_limiar_confianca > 1 then
    raise exception 'p_limiar_confianca deve estar entre 0 e 1.';
  end if;

  if p_documento is null or jsonb_typeof(p_documento) <> 'object' then
    raise exception 'p_documento deve ser um objeto json.';
  end if;

  if p_linhas is null or jsonb_typeof(p_linhas) <> 'array' then
    raise exception 'p_linhas deve ser um array json.';
  end if;

  v_total := jsonb_array_length(p_linhas);
  if v_total = 0 then
    raise exception 'p_linhas deve conter ao menos uma linha.';
  end if;

  v_documento_hash := nullif(trim(p_documento->>'hash'), '');
  if v_documento_hash is null then
    raise exception 'p_documento.hash obrigatorio para dedupe de importacao.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = p_cartao_id
     and ativo = true;

  if not found then
    raise exception 'cartao nao encontrado ou inativo.';
  end if;

  v_open := public.financeiro_cartao_fatura_abrir(
    jsonb_build_object(
      'cartao_id', p_cartao_id,
      'competencia', date_trunc('month', p_competencia)::date,
      'motivo', p_motivo
    ),
    v_cartao_ator
  );

  select * into v_fatura
    from public.financeiro_cartao_faturas
   where id = (v_open->>'fatura_id')::uuid
   for update;

  if not found then
    raise exception 'fatura alvo da importacao nao encontrada.';
  end if;

  if v_fatura.status <> 'aberta' then
    raise exception 'fatura nao esta aberta; reabra para importar.';
  end if;

  select * into v_documento
    from public.financeiro_documentos d
   where d.hash = v_documento_hash
   order by d.created_at
   limit 1;

  if found then
    select * into v_importacao_existente
      from public.financeiro_cartao_importacoes i
     where i.documento_id = v_documento.id
       and i.fatura_id = v_fatura.id
       and i.status = 'concluida'
     order by i.created_at desc
     limit 1;

    if found then
      return jsonb_build_object(
        'success', true,
        'ja_importado', true,
        'importacao_id', v_importacao_existente.id,
        'fatura_id', v_fatura.id,
        'total', v_importacao_existente.total_linhas,
        'importadas', 0,
        'duplicadas', v_importacao_existente.linhas_duplicadas,
        'com_sugestao', v_importacao_existente.linhas_classificadas,
        'pendentes', v_importacao_existente.linhas_pendentes,
        'erros', v_importacao_existente.linhas_erro,
        'linhas', '[]'::jsonb
      );
    end if;
  else
    v_documento_tipo := coalesce(nullif(trim(p_documento->>'tipo'), ''), 'fatura');
    if v_documento_tipo not in ('comprovante','fatura','nota','boleto','outro') then
      raise exception 'p_documento.tipo invalido.';
    end if;

    v_documento_origem := coalesce(nullif(trim(p_documento->>'origem'), ''), 'whatsapp');
    if v_documento_origem not in ('whatsapp','upload','email','manual','asaas') then
      raise exception 'p_documento.origem invalida.';
    end if;

    insert into public.financeiro_documentos (
      tipo,
      storage_ref,
      origem,
      vinculo_tipo,
      vinculo_id,
      hash,
      observacoes
    )
    values (
      v_documento_tipo,
      nullif(trim(p_documento->>'storage_ref'), ''),
      v_documento_origem,
      'cartao_fatura',
      v_fatura.id,
      v_documento_hash,
      nullif(trim(p_documento->>'observacao'), '')
    )
    returning * into v_documento;
  end if;

  insert into public.financeiro_cartao_importacoes (
    documento_id,
    cartao_id,
    fatura_id,
    origem,
    status,
    total_linhas,
    linhas_importadas,
    linhas_classificadas,
    linhas_pendentes,
    linhas_erro,
    linhas_duplicadas,
    ator_tipo,
    ator_ref,
    created_by,
    mensagem_erro
  )
  values (
    v_documento.id,
    p_cartao_id,
    v_fatura.id,
    'maria',
    'processando',
    v_total,
    0,
    0,
    0,
    0,
    0,
    'maria',
    v_ator_numero,
    null,
    null
  )
  returning * into v_importacao;

  for v_linha, v_linha_idx in
    select value, ordinality::int
      from jsonb_array_elements(p_linhas) with ordinality
  loop
    begin
      v_linha_numero := null;
      v_linha_data := null;
      v_linha_descricao := null;
      v_linha_estabelecimento := null;
      v_linha_valor := null;
      v_linha_tipo_transacao := null;
      v_linha_parcela_atual := null;
      v_linha_total_parcelas := null;
      v_confianca := null;
      v_linha_plano_conta_id := null;
      v_linha_empresa_id := null;
      v_linha_centro_custo_id := null;
      v_linha_classificacao_status := 'pendente';
      v_triade_valida := false;
      v_duplicada_id := null;
      v_transacao_id := null;

      v_linha_numero := coalesce(nullif(v_linha->>'numero_linha', '')::int, v_linha_idx);
      if v_linha_numero <= 0 then
        raise exception 'numero_linha invalido.';
      end if;

      v_linha_data := nullif(v_linha->>'data_compra', '')::date;
      if v_linha_data is null then
        raise exception 'data_compra obrigatoria.';
      end if;

      v_linha_descricao := nullif(trim(v_linha->>'descricao'), '');
      if v_linha_descricao is null then
        raise exception 'descricao obrigatoria.';
      end if;

      v_linha_estabelecimento := nullif(trim(v_linha->>'estabelecimento'), '');
      v_linha_valor := nullif(v_linha->>'valor', '')::numeric;
      if v_linha_valor is null or v_linha_valor = 0 then
        raise exception 'valor obrigatorio e diferente de zero.';
      end if;

      v_linha_tipo_transacao := coalesce(nullif(trim(v_linha->>'tipo_transacao'), ''), 'compra');
      if v_linha_tipo_transacao not in ('compra','estorno','tarifa','anuidade','ajuste') then
        raise exception 'tipo_transacao invalido.';
      end if;

      if v_linha_tipo_transacao = 'estorno' then
        v_linha_valor := -abs(v_linha_valor);
      elsif v_linha_tipo_transacao in ('compra','tarifa','anuidade','ajuste') then
        v_linha_valor := abs(v_linha_valor);
      end if;

      v_linha_parcela_atual := nullif(v_linha->>'parcela_atual', '')::int;
      v_linha_total_parcelas := nullif(v_linha->>'total_parcelas', '')::int;
      if (v_linha_parcela_atual is null) <> (v_linha_total_parcelas is null) then
        raise exception 'parcela_atual e total_parcelas devem vir juntos.';
      end if;
      if v_linha_parcela_atual is not null and (
        v_linha_parcela_atual <= 0
        or v_linha_total_parcelas <= 0
        or v_linha_parcela_atual > v_linha_total_parcelas
      ) then
        raise exception 'parcelamento invalido.';
      end if;

      v_confianca := coalesce(nullif(v_linha->>'confianca', '')::numeric, 0);
      if v_confianca < 0 or v_confianca > 1 then
        raise exception 'confianca deve estar entre 0 e 1.';
      end if;

      v_linha_plano_conta_id := null;
      v_linha_empresa_id := null;
      v_linha_centro_custo_id := null;
      v_linha_classificacao_status := 'pendente';
      v_triade_valida := false;
      v_classificacao := v_linha->'classificacao_sugerida';

      if v_classificacao is not null and jsonb_typeof(v_classificacao) = 'object' and v_confianca >= p_limiar_confianca then
        if coalesce(v_classificacao->>'plano_conta_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          v_linha_plano_conta_id := (v_classificacao->>'plano_conta_id')::uuid;
        end if;
        if coalesce(v_classificacao->>'empresa_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          v_linha_empresa_id := (v_classificacao->>'empresa_id')::uuid;
        end if;
        if coalesce(v_classificacao->>'centro_custo_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
          v_linha_centro_custo_id := (v_classificacao->>'centro_custo_id')::uuid;
        end if;

        if v_linha_plano_conta_id is not null
           and v_linha_empresa_id is not null
           and v_linha_centro_custo_id is not null then
          select exists (
            select 1
              from public.plano_contas p
              join public.financeiro_empresas e on e.id = v_linha_empresa_id
             where p.id = v_linha_plano_conta_id
               and p.nivel = 3
               and p.natureza = 'saida'
               and p.ativo = true
               and e.ativo = true
               and e.unidade_id = v_linha_centro_custo_id
          ) into v_triade_valida;
        end if;

        if v_triade_valida then
          v_linha_classificacao_status := 'sugerida';
        else
          v_linha_plano_conta_id := null;
          v_linha_empresa_id := null;
          v_linha_centro_custo_id := null;
          v_linha_classificacao_status := 'pendente';
        end if;
      end if;

      v_id_externo_base := coalesce(nullif(trim(p_mensagem_origem_id), ''), v_documento_hash, v_fatura.id::text);
      v_id_externo := coalesce(
        nullif(trim(v_linha->>'id_externo'), ''),
        concat(v_id_externo_base, ':', v_fatura.id::text, ':', v_linha_numero)
      );

      v_fingerprint := encode(extensions.digest(
        concat_ws('|',
          v_fatura.cartao_id::text,
          v_fatura.competencia::text,
          v_linha_numero::text,
          v_linha_data::text,
          round(v_linha_valor, 2)::text,
          lower(regexp_replace(v_linha_descricao, '\s+', ' ', 'g'))
        ),
        'sha256'
      ), 'hex');

      select t.id into v_duplicada_id
        from public.financeiro_cartao_transacoes t
       where t.fatura_id = v_fatura.id
         and t.fingerprint = v_fingerprint
       limit 1;

      if v_duplicada_id is null then
        select t.id into v_duplicada_id
          from public.financeiro_cartao_transacoes t
         where t.fatura_id = v_fatura.id
           and t.id_externo = v_id_externo
         limit 1;
      end if;

      if v_duplicada_id is not null then
        v_duplicadas := v_duplicadas + 1;
        v_linhas_resultado := v_linhas_resultado || jsonb_build_array(jsonb_build_object(
          'numero_linha', v_linha_numero,
          'status', 'duplicada',
          'transacao_id', v_duplicada_id
        ));
        continue;
      end if;

      v_transacao_payload := jsonb_strip_nulls(jsonb_build_object(
        'fatura_id', v_fatura.id,
        'importacao_id', v_importacao.id,
        'numero_linha', v_linha_numero,
        'data_compra', v_linha_data,
        'descricao', v_linha_descricao,
        'estabelecimento', v_linha_estabelecimento,
        'valor', v_linha_valor,
        'tipo_transacao', v_linha_tipo_transacao,
        'plano_conta_id', v_linha_plano_conta_id,
        'centro_custo_id', v_linha_centro_custo_id,
        'empresa_id', v_linha_empresa_id,
        'classificacao_status', v_linha_classificacao_status,
        'parcela_atual', v_linha_parcela_atual,
        'total_parcelas', v_linha_total_parcelas,
        'id_externo', v_id_externo,
        'fonte_tipo', 'maria',
        'observacoes', nullif(trim(v_linha->>'observacoes'), ''),
        'motivo', p_motivo
      ));

      v_transacao_result := public.financeiro_cartao_transacao_registrar(v_transacao_payload, v_cartao_ator);
      v_transacao_id := nullif(v_transacao_result->>'transacao_id', '')::uuid;

      if coalesce((v_transacao_result->>'idempotent')::boolean, false) then
        v_duplicadas := v_duplicadas + 1;
        v_linhas_resultado := v_linhas_resultado || jsonb_build_array(jsonb_build_object(
          'numero_linha', v_linha_numero,
          'status', 'duplicada',
          'transacao_id', v_transacao_id
        ));
      else
        v_importadas := v_importadas + 1;
        if v_linha_classificacao_status = 'sugerida' then
          v_sugeridas := v_sugeridas + 1;
        else
          v_pendentes := v_pendentes + 1;
        end if;

        v_linhas_resultado := v_linhas_resultado || jsonb_build_array(jsonb_build_object(
          'numero_linha', v_linha_numero,
          'status', v_linha_classificacao_status,
          'transacao_id', v_transacao_id
        ));
      end if;
    exception when others then
      v_linhas_erro := v_linhas_erro + 1;
      v_linhas_resultado := v_linhas_resultado || jsonb_build_array(jsonb_build_object(
        'numero_linha', coalesce(v_linha_numero, v_linha_idx),
        'status', 'erro',
        'motivo', sqlerrm
      ));
    end;
  end loop;

  update public.financeiro_cartao_importacoes
     set linhas_importadas = v_importadas,
         linhas_classificadas = v_sugeridas,
         linhas_pendentes = v_pendentes,
         linhas_erro = v_linhas_erro,
         linhas_duplicadas = v_duplicadas,
         status = 'concluida',
         mensagem_erro = case when v_linhas_erro > 0 then concat(v_linhas_erro, ' linha(s) com erro.') else null end,
         updated_at = now()
   where id = v_importacao.id
   returning * into v_importacao;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    p_canal,
    'financeiro_cartao_importacoes',
    'importacao',
    v_importacao.id,
    'registrar_lote',
    null,
    jsonb_build_object(
      'id', v_importacao.id,
      'cartao_id', v_importacao.cartao_id,
      'fatura_id', v_importacao.fatura_id,
      'documento_id', v_importacao.documento_id,
      'total_linhas', v_importacao.total_linhas,
      'linhas_importadas', v_importacao.linhas_importadas,
      'linhas_classificadas', v_importacao.linhas_classificadas,
      'linhas_pendentes', v_importacao.linhas_pendentes,
      'linhas_erro', v_importacao.linhas_erro,
      'linhas_duplicadas', v_importacao.linhas_duplicadas,
      'status', v_importacao.status
    ),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'importacao_id', v_importacao.id,
    'fatura_id', v_fatura.id,
    'total', v_total,
    'importadas', v_importadas,
    'duplicadas', v_duplicadas,
    'com_sugestao', v_sugeridas,
    'pendentes', v_pendentes,
    'erros', v_linhas_erro,
    'linhas', v_linhas_resultado
  );
end;
$_$;


ALTER FUNCTION "public"."maria_cartoes_importacao_registrar_lote"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_documento" "jsonb", "p_linhas" "jsonb", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_mensagem_origem_id" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_cartoes_importacao_registrar_lote"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_documento" "jsonb", "p_linhas" "jsonb", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_mensagem_origem_id" "text", "p_motivo" "text") IS 'Maria operational RPC: registra lote normalizado de transacoes de cartao em fatura aberta, com dedupe, sugestoes fiscais e audit log sanitizado.';



CREATE OR REPLACE FUNCTION "public"."maria_cartoes_normalizar_texto"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select trim(
    regexp_replace(
      translate(
        upper(coalesce(p_texto, '')),
        U&'\00C1\00C0\00C3\00C2\00C4\00C9\00C8\00CA\00CB\00CD\00CC\00CE\00CF\00D3\00D2\00D5\00D4\00D6\00DA\00D9\00DB\00DC\00C7' || '*./_-',
        'AAAAAEEEEIIIIOOOOOUUUUC     '
      ),
      '[^A-Z0-9]+',
      ' ',
      'g'
    )
  );
$$;


ALTER FUNCTION "public"."maria_cartoes_normalizar_texto"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_cartoes_preview_classificar_linhas"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_linhas" "jsonb", "p_limiar_confianca" numeric DEFAULT 0.80) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_cartao public.financeiro_cartoes%rowtype;
  v_empresa_id uuid;
  v_centro_custo_id uuid;
  v_linha record;
  v_ordem int := 0;
  v_total int := 0;
  v_sugeridas int := 0;
  v_pendentes int := 0;
  v_conflitos int := 0;
  v_result jsonb := '[]'::jsonb;
  v_texto_norm text;
  v_regra record;
  v_regra_encontrada boolean;
  v_regra_sem_sugestao boolean;
  v_historico_plano_id uuid;
  v_historico_top_count int;
  v_historico_total int;
  v_historico_second_count int;
  v_historico_conflito boolean;
  v_plano_id uuid;
  v_plano_codigo text;
  v_plano_nome text;
  v_confianca numeric;
  v_origem text;
  v_acao text;
  v_triade_valida boolean;
  v_ml jsonb;
  v_ml_produto text;
  v_valor_parcelado_total numeric;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_cartao_id is null then
    raise exception 'p_cartao_id obrigatorio.';
  end if;

  if p_linhas is null or jsonb_typeof(p_linhas) <> 'array' then
    raise exception 'p_linhas deve ser array jsonb.';
  end if;

  if p_limiar_confianca is null or p_limiar_confianca < 0 or p_limiar_confianca > 1 then
    raise exception 'p_limiar_confianca deve estar entre 0 e 1.';
  end if;

  select * into v_cartao
    from public.financeiro_cartoes
   where id = p_cartao_id
     and ativo = true;

  if not found then
    raise exception 'cartao nao encontrado ou inativo.';
  end if;

  v_empresa_id := v_cartao.empresa_id;
  v_centro_custo_id := v_cartao.centro_custo_id;

  for v_linha in
    select *
      from jsonb_to_recordset(p_linhas) as x(
        numero_linha int,
        descricao text,
        estabelecimento text,
        valor numeric,
        data_compra date,
        tipo_transacao text,
        parcela_atual int,
        total_parcelas int
      )
  loop
    v_ordem := v_ordem + 1;
    v_total := v_total + 1;
    v_texto_norm := public.maria_cartoes_normalizar_texto(
      coalesce(v_linha.descricao, '') || ' ' || coalesce(v_linha.estabelecimento, '')
    );
    v_valor_parcelado_total := case
      when v_linha.parcela_atual is not null and v_linha.total_parcelas is not null and v_linha.valor is not null
      then round(v_linha.valor * v_linha.total_parcelas, 2)
      else null
    end;

    v_regra_encontrada := false;
    v_regra_sem_sugestao := false;
    v_historico_conflito := false;
    v_plano_id := null;
    v_plano_codigo := null;
    v_plano_nome := null;
    v_confianca := null;
    v_origem := null;
    v_acao := 'pendente';
    v_triade_valida := false;
    v_historico_plano_id := null;
    v_historico_top_count := 0;
    v_historico_total := 0;
    v_historico_second_count := 0;
    v_ml := null;
    v_ml_produto := null;

    select
      r.id,
      r.palavra_chave,
      r.plano_conta_id,
      r.confianca_base,
      r.prioridade,
      p.codigo as plano_codigo,
      p.nome as plano_nome
      into v_regra
      from public.maria_classificacao_regras r
      left join public.plano_contas p on p.id = r.plano_conta_id
     where r.ativo = true
       and r.escopo in ('cartao','geral')
       and position(r.palavra_chave in v_texto_norm) > 0
     order by r.prioridade desc, r.confianca_base desc, r.created_at asc
     limit 1;

    v_regra_encontrada := found;

    if v_regra_encontrada and v_regra.plano_conta_id is null then
      v_regra_sem_sugestao := true;
    end if;

    if v_regra_sem_sugestao then
      v_acao := 'pendente';
      v_origem := 'regra_sem_sugestao';
    elsif v_regra_encontrada then
      v_plano_id := v_regra.plano_conta_id;
      v_plano_codigo := v_regra.plano_codigo;
      v_plano_nome := v_regra.plano_nome;
      v_confianca := v_regra.confianca_base;
      v_origem := 'regra';
    end if;

    -- ===== TIER ML (deterministico via categoria da order) — Alf 24/08 =====
    -- Aditivo: so afeta linha do Mercado Livre. Fail-safe: qualquer erro cai no historico.
    if v_plano_id is null and not v_regra_sem_sugestao
       and (v_texto_norm like '%MERCADOLIVRE%' or coalesce(v_linha.estabelecimento,'') ~* 'mercado ?livre') then
      begin
        v_ml := public.maria_ml_identificar_compra(coalesce(v_linha.descricao,''), v_linha.valor, v_linha.data_compra, 'd4264a77-e7eb-48e0-bdae-d16c0d8bcd8e'::uuid, 5, 0.80, v_valor_parcelado_total);
        if (v_ml->'plano_provavel'->>'codigo') is not null then
          select p.id, p.codigo, p.nome
            into v_plano_id, v_plano_codigo, v_plano_nome
            from public.plano_contas p
           where p.codigo = (v_ml->'plano_provavel'->>'codigo')
             and p.nivel = 3 and p.natureza = 'saida' and p.ativo = true
           limit 1;
          if v_plano_id is not null then
            v_confianca := 0.90;
            v_origem := 'ml_categoria';
            v_ml_produto := v_ml->'produto'->>'produto_titulo';
          end if;
        elsif (v_ml->'produto'->>'produto_titulo') is not null then
          -- Produto identificado mas sem plano_sugerido no ml_pedidos: ainda assim mostra o
          -- nome do produto pra Rose (nao inventa plano), so nao entra na acao 'sugerida'.
          v_ml_produto := v_ml->'produto'->>'produto_titulo';
        end if;
      exception when others then
        v_plano_id := null; v_plano_codigo := null; v_plano_nome := null; v_ml_produto := null;
      end;
    end if;

    if v_plano_id is null and not v_regra_sem_sugestao then
      with tokens as (
        select distinct token
          from regexp_split_to_table(v_texto_norm, ' ') as token
         where length(token) >= 4
      ),
      historico_plano as (
        select ht.plano_conta_id, count(*)::int as ocorrencias
          from public.financeiro_cartao_transacoes ht
         where ht.plano_conta_id is not null
           and ht.classificacao_status = 'confirmada'
           and (
                 -- token-cabeca (01/09/2026): nome do estabelecimento, nao qualquer token
                 public.maria_cartoes_token_cabeca(v_texto_norm) in (
                   public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(ht.descricao, ''))),
                   public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(ht.estabelecimento, '')))
                 )
               )
         group by ht.plano_conta_id
        union all
        select cp.plano_conta_id, count(*)::int as ocorrencias
          from public.contas_pagar cp
         where cp.plano_conta_id is not null
           and coalesce(cp.status, '') <> 'cancelado'
           and (
                 public.maria_cartoes_token_cabeca(v_texto_norm)
                   = public.maria_cartoes_token_cabeca(public.maria_cartoes_normalizar_texto(coalesce(cp.descricao, '')))
               )
         group by cp.plano_conta_id
      ),
      historico_agg as (
        select plano_conta_id, sum(ocorrencias)::int as ocorrencias
          from historico_plano
         group by plano_conta_id
      ),
      ranked as (
        select
          plano_conta_id,
          ocorrencias,
          sum(ocorrencias) over ()::int as total,
          row_number() over (order by ocorrencias desc, plano_conta_id) as rn
        from historico_agg
      )
      select r1.plano_conta_id,
             r1.ocorrencias,
             r1.total,
             coalesce(r2.ocorrencias, 0)
        into v_historico_plano_id,
             v_historico_top_count,
             v_historico_total,
             v_historico_second_count
        from ranked r1
        left join ranked r2 on r2.rn = 2
       where r1.rn = 1;

      if v_historico_plano_id is not null then
        if v_historico_second_count > 0
           and (v_historico_second_count::numeric / greatest(v_historico_total, 1)) >= 0.35 then
          v_historico_conflito := true;
          v_acao := 'conflito';
          v_origem := 'historico_conflito';
        else
          v_plano_id := v_historico_plano_id;
          v_confianca := round(least(0.90, 0.65 + (v_historico_top_count::numeric / greatest(v_historico_total, 1)) * 0.25), 2);
          v_origem := 'historico';

          select p.codigo, p.nome
            into v_plano_codigo, v_plano_nome
            from public.plano_contas p
           where p.id = v_plano_id;
        end if;
      else
        v_origem := coalesce(v_origem, 'sem_historico');
      end if;
    end if;

    if v_plano_id is not null and not v_historico_conflito then
      select exists (
        select 1
          from public.plano_contas p
          join public.financeiro_empresas e on e.id = v_empresa_id
         where p.id = v_plano_id
           and p.nivel = 3
           and p.natureza = 'saida'
           and p.ativo = true
           and e.ativo = true
           and e.unidade_id = v_centro_custo_id
      ) into v_triade_valida;

      if v_triade_valida and v_confianca >= p_limiar_confianca then
        v_acao := 'sugerida';
      elsif v_confianca < p_limiar_confianca then
        v_acao := 'pendente';
        v_origem := coalesce(v_origem, 'baixa_confianca');
      else
        v_acao := 'pendente';
        v_origem := coalesce(v_origem, 'triade_invalida');
      end if;
    end if;

    if v_acao = 'sugerida' then
      v_sugeridas := v_sugeridas + 1;
    elsif v_acao = 'conflito' then
      v_conflitos := v_conflitos + 1;
    else
      v_pendentes := v_pendentes + 1;
    end if;

    v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'numero_linha', coalesce(v_linha.numero_linha, v_ordem),
      'descricao', v_linha.descricao,
      'produto_ml', v_ml_produto,
      'valor', v_linha.valor,
      'acao', v_acao,
      'plano_sugerido_id', case when v_acao = 'sugerida' then v_plano_id else null end,
      'plano_sugerido_codigo', case when v_acao = 'sugerida' then v_plano_codigo else null end,
      'plano_sugerido_nome', case when v_acao = 'sugerida' then v_plano_nome else null end,
      'confianca', case when v_acao = 'sugerida' then v_confianca else null end,
      'origem', v_origem
    )));
  end loop;

  return jsonb_build_object(
    'success', true,
    'total_linhas', v_total,
    'sugeridas', v_sugeridas,
    'pendentes', v_pendentes,
    'conflitos', v_conflitos,
    'linhas', v_result
  );
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_preview_classificar_linhas"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_linhas" "jsonb", "p_limiar_confianca" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_cartoes_preview_classificar_linhas"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_linhas" "jsonb", "p_limiar_confianca" numeric) IS 'Maria operational RPC read-only: classifica linhas de preview de fatura de cartão por regras e histórico confirmado; não grava e nunca confirma automaticamente.';



CREATE OR REPLACE FUNCTION "public"."maria_cartoes_sugerir_classificacao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric DEFAULT 0.80, "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_calc jsonb;
  v_linhas_publicas jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_calc := public.maria_cartoes_classificacao_sugestoes_calcular(
    p_cartao_id,
    p_competencia,
    p_limiar_confianca
  );

  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'transacao_id', linha.transacao_id,
    'descricao', linha.descricao,
    'acao', linha.acao,
    'plano_sugerido_codigo', case when linha.acao = 'sugerida' then linha.plano_sugerido_codigo else null end,
    'confianca', case when linha.acao = 'sugerida' then linha.confianca else null end,
    'origem', linha.origem
  )) order by linha.ordem), '[]'::jsonb)
    into v_linhas_publicas
    from jsonb_to_recordset(v_calc->'linhas') as linha(
      ordem int,
      transacao_id uuid,
      descricao text,
      acao text,
      plano_conta_id uuid,
      plano_sugerido_codigo text,
      confianca numeric,
      origem text
    );

  return jsonb_build_object(
    'success', true,
    'fatura_id', v_calc->>'fatura_id',
    'total_pendentes', (v_calc->>'total_pendentes')::int,
    'sugeridas', (v_calc->>'sugeridas')::int,
    'pendentes', (v_calc->>'pendentes')::int,
    'conflitos', (v_calc->>'conflitos')::int,
    'aplicado', false,
    'linhas', v_linhas_publicas
  );
end;
$$;


ALTER FUNCTION "public"."maria_cartoes_sugerir_classificacao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_cartoes_sugerir_classificacao"("p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_cartao_id" "uuid", "p_competencia" "date", "p_limiar_confianca" numeric, "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC read-only: calcula sugestoes de classificacao de cartao sem gravar e sem audit.';



CREATE OR REPLACE FUNCTION "public"."maria_cartoes_token_cabeca"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    AS $$
  select coalesce(
    (select t.token from regexp_split_to_table(p_texto, ' ') with ordinality as t(token, ord)
      where length(t.token) >= 4 order by t.ord limit 1),
    (select t.token from regexp_split_to_table(p_texto, ' ') with ordinality as t(token, ord)
      where length(t.token) > 0 order by length(t.token) desc, t.ord limit 1)
  )
$$;


ALTER FUNCTION "public"."maria_cartoes_token_cabeca"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_classificacao_regras_before_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.palavra_chave := public.maria_cartoes_normalizar_texto(new.palavra_chave);
  if new.palavra_chave = '' then
    raise exception 'palavra_chave obrigatoria para regra de classificacao.';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."maria_classificacao_regras_before_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_codigo_barras_texto_valido"("p_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_codigo text;
  v_digitos text;
begin
  v_codigo := nullif(trim(p_text), '');
  if v_codigo is null then
    return true;
  end if;

  if v_codigo ~ E'[\r\n]' then
    return false;
  end if;

  if v_codigo !~ '^[0-9 .-]+$' then
    return false;
  end if;

  v_digitos := regexp_replace(v_codigo, '\D', '', 'g');
  return length(v_digitos) in (44, 47, 48);
end;
$_$;


ALTER FUNCTION "public"."maria_codigo_barras_texto_valido"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_codigo_mes_public_json"("p_codigo_mes_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object(
    'id', c.id,
    'conta_pagar_id', c.conta_pagar_id,
    'competencia', c.competencia,
    'valor_coletado', c.valor_coletado,
    'coletado_em', c.coletado_em,
    'coletado_por', c.coletado_por,
    'status_coleta', c.status_coleta,
    'created_at', c.created_at,
    'updated_at', c.updated_at
  )
  from public.contas_pagar_codigo_mes c
  where c.id = p_codigo_mes_id;
$$;


ALTER FUNCTION "public"."maria_codigo_mes_public_json"("p_codigo_mes_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_conferencia_eventuais_criar"("p_conferencia_id" "uuid", "p_status" "text", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_janela_dias" integer DEFAULT 3) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_conf public.maria_conferencias_lancamento%rowtype;
  v_item public.maria_conferencia_lancamento_itens%rowtype;
  v_pre record;
  v_resolved jsonb;
  v_plano_id uuid;
  v_centro_id uuid;
  v_conta_id uuid;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
  v_status text;
  v_metodo text;
  v_data_pagamento date;
  v_valor numeric;
  v_count integer := 0;
  v_before jsonb;
  v_after jsonb;
  v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_conferencia_id is null then
    raise exception 'conferencia_id obrigatorio.';
  end if;

  select * into v_conf
  from public.maria_conferencias_lancamento
  where id = p_conferencia_id
  for update;

  if not found then
    raise exception 'conferencia nao encontrada.';
  end if;

  if v_conf.status <> 'aprovada' then
    raise exception 'conferencia precisa estar aprovada antes de criar lancamentos eventuais. status atual: %', v_conf.status;
  end if;

  v_status := lower(coalesce(nullif(trim(p_status), ''), 'pago'));
  if v_status not in ('pago', 'pendente') then
    raise exception 'status permitido: pago ou pendente.';
  end if;

  v_metodo := nullif(trim(p_metodo_pagamento), '');
  if v_status = 'pago' and v_metodo is null then
    raise exception 'metodo_pagamento obrigatorio quando status=pago.';
  end if;

  if exists (
    select 1 from public.maria_conferencia_lancamento_itens
    where conferencia_id = p_conferencia_id
      and conta_pagar_id is not null
  ) then
    raise exception 'conferencia possui item ja vinculado a conta_pagar; bloqueado para evitar duplicidade.';
  end if;

  if exists (
    select 1 from public.maria_conferencia_lancamento_preflight(p_conferencia_id, coalesce(p_janela_dias, 3)) pf
    where pf.pode_lancar is not true
  ) then
    raise exception 'preflight bloqueou a conferencia: ha pendencias ou candidatos de duplicidade.';
  end if;

  v_before := jsonb_build_object(
    'conferencia_id', v_conf.id,
    'status', v_conf.status,
    'versao', v_conf.versao
  );

  for v_item in
    select *
    from public.maria_conferencia_lancamento_itens
    where conferencia_id = p_conferencia_id
    order by item_numero
  loop
    if v_item.data_operacional is null then
      raise exception 'item % sem data_operacional.', v_item.item_numero;
    end if;

    if v_item.valor_centavos is null or v_item.valor_centavos <= 0 then
      raise exception 'item % sem valor valido.', v_item.item_numero;
    end if;

    v_resolved := public.maria_lancamento_eventual_resolver_ids(
      v_item.unidade,
      v_item.conta_origem,
      v_item.plano_codigo,
      v_item.plano_nome
    );

    if coalesce((v_resolved->>'ok')::boolean, false) is not true then
      raise exception 'item % com IDs nao resolvidos: %', v_item.item_numero, v_resolved->'bloqueios';
    end if;

    v_plano_id := nullif(v_resolved #>> '{plano,plano_conta_id}', '')::uuid;
    v_centro_id := nullif(v_resolved #>> '{centro_custo,centro_custo_id}', '')::uuid;
    v_conta_id := nullif(v_resolved #>> '{conta_pagadora,conta_pagadora_id}', '')::uuid;

    if v_plano_id is null or v_centro_id is null or v_conta_id is null then
      raise exception 'item % sem UUID resolvido para plano/centro/conta.', v_item.item_numero;
    end if;

    v_valor := round((v_item.valor_centavos::numeric / 100), 2);
    v_data_pagamento := case when v_status = 'pago' then v_item.data_operacional else null end;

    v_result := public.maria_contas_eventual_criar(
      v_item.descricao,
      v_valor,
      v_item.data_operacional,
      v_plano_id,
      v_centro_id,
      v_conta_id,
      v_status,
      v_data_pagamento,
      v_metodo,
      coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome),
      p_ator_numero,
      p_papel,
      coalesce(nullif(trim(p_canal), ''), 'whatsapp-grupo-financeiro'),
      p_texto_original,
      concat_ws(E'\n',
        nullif(trim(p_motivo), ''),
        concat('Criado a partir da conferencia Maria ', p_conferencia_id, ', item ', v_item.item_numero, '.')
      ),
      coalesce(v_item.fluxo_evento_id::text, v_item.id::text),
      null,
      concat_ws(E'\n',
        v_item.observacoes,
        concat('conferencia_id=', p_conferencia_id),
        concat('conferencia_item_id=', v_item.id),
        case when v_item.fluxo_evento_id is not null then concat('fluxo_evento_id=', v_item.fluxo_evento_id) end
      )
    );

    update public.maria_conferencia_lancamento_itens
       set conta_pagar_id = (v_result->>'conta_id')::uuid,
           status = 'lancado',
           observacoes = concat_ws(E'\n', observacoes, concat('Lancado no Super Folha pela Maria em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '.'))
     where id = v_item.id;

    v_results := v_results || jsonb_build_array(jsonb_build_object(
      'item_id', v_item.id,
      'item_numero', v_item.item_numero,
      'descricao', v_item.descricao,
      'valor_centavos', v_item.valor_centavos,
      'conta_id', v_result->>'conta_id',
      'audit_id', v_result->>'audit_id',
      'resultado', v_result
    ));

    v_count := v_count + 1;
  end loop;

  if v_count = 0 then
    raise exception 'conferencia sem itens para lancar.';
  end if;

  update public.maria_conferencias_lancamento
     set status = 'lancada',
         motivo = concat_ws(E'\n', motivo, nullif(trim(p_motivo), ''), concat('Lancamentos eventuais criados pela Maria em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '.')),
         aprovado_por_nome = coalesce(aprovado_por_nome, coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome)),
         aprovado_at = coalesce(aprovado_at, now())
   where id = p_conferencia_id;

  v_after := jsonb_build_object(
    'conferencia_id', p_conferencia_id,
    'status', 'lancada',
    'itens_lancados', v_count,
    'resultados', v_results,
    'pagamento_executado_pela_maria', false,
    'lancamento_executado_pela_maria', true
  );

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    coalesce(nullif(trim(p_canal), ''), 'whatsapp-grupo-financeiro'),
    'maria_conferencias_lancamento',
    'conferencia_lancamento',
    p_conferencia_id,
    'criar_lancamentos_eventuais_da_conferencia',
    v_before,
    v_after,
    p_motivo,
    p_texto_original
  );

  return v_after || jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'confirmado_por', coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome)
  );
end;
$$;


ALTER FUNCTION "public"."maria_conferencia_eventuais_criar"("p_conferencia_id" "uuid", "p_status" "text", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_janela_dias" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_conferencia_eventuais_criar"("p_conferencia_id" "uuid", "p_status" "text", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_janela_dias" integer) IS 'Maria operational wrapper: cria contas_pagar eventuais a partir de conferencia aprovada, passando por preflight e resolver IDs. Nao executa pagamento real.';



CREATE OR REPLACE FUNCTION "public"."maria_conferencia_lancamento_preflight"("p_conferencia_id" "uuid", "p_janela_dias" integer DEFAULT 3) RETURNS TABLE("item_id" "uuid", "item_numero" integer, "descricao" "text", "data_operacional" "date", "valor_centavos" integer, "unidade" "text", "plano_codigo" "text", "plano_nome" "text", "plano_origem" "text", "item_status" "text", "pendencias" "text"[], "duplicidade_candidatos" "jsonb", "duplicidade_count" integer, "pode_lancar" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with itens as (
    select
      i.*,
      coalesce(p_janela_dias, 3) as janela_dias,
      case
        when lower(trim(coalesce(i.unidade, ''))) in ('rec', 'recreio', 'la kids recreio') then 'rec'
        when lower(trim(coalesce(i.unidade, ''))) in ('bar', 'barra') then 'bar'
        when lower(trim(coalesce(i.unidade, ''))) in ('cg', 'campo grande', 'campo_grande', 'emla cg', 'emla_cg', 'kids cg', 'kids_cg') then 'cg'
        else lower(trim(coalesce(i.unidade, '')))
      end as unidade_codigo
    from public.maria_conferencia_lancamento_itens i
    where i.conferencia_id = p_conferencia_id
  ), avaliados as (
    select
      i.id as item_id,
      i.item_numero,
      i.descricao,
      i.data_operacional,
      i.valor_centavos,
      i.unidade,
      i.plano_codigo,
      i.plano_nome,
      i.plano_origem,
      i.status as item_status,
      array_remove(array[
        case when i.data_operacional is null then 'data_operacional ausente' end,
        case when i.valor_centavos is null or i.valor_centavos <= 0 then 'valor ausente/invalido' end,
        case when nullif(trim(i.descricao), '') is null then 'descricao ausente' end,
        case when i.plano_codigo is null and i.plano_nome is null then 'plano de contas pendente' end,
        case when i.plano_origem not in ('humano', 'regra_aprendida', 'ledger') then 'origem do plano nao confiavel' end
      ], null)::text[] as pendencias,
      coalesce(c.candidatos, '[]'::jsonb) as duplicidade_candidatos,
      coalesce(jsonb_array_length(c.candidatos), 0) as duplicidade_count
    from itens i
    left join lateral (
      select jsonb_agg(
        jsonb_build_object(
          'conta_id', cp.id,
          'descricao', cp.descricao,
          'valor', cp.valor,
          'valor_centavos', public.maria_fluxo_valor_para_centavos(cp.valor),
          'data_lancamento', cp.data_lancamento,
          'data_vencimento', cp.data_vencimento,
          'data_pagamento', cp.data_pagamento,
          'status', cp.status,
          'tipo_lancamento', cp.tipo_lancamento,
          'unidade', cp.unidade,
          'created_at', cp.created_at,
          'motivo_match', concat_ws('; ',
            'mesmo valor',
            case when cp.v_descricao_match then 'descricao/fornecedor compativel' end,
            case when cp.v_unidade_match then 'mesma unidade/centro' end,
            case when cp.v_data_match then 'data/competencia proxima' end,
            case when cp.v_tipo_match then 'tipo_lancamento compativel' end
          )
        ) order by cp.created_at desc
      ) as candidatos
      from (
        select matched.*
        from (
          select
            cp.*,
            norm.v_item_descricao_norm,
            norm.v_cp_descricao_norm,
            flags.v_descricao_match,
            flags.v_unidade_match,
            flags.v_data_match,
            flags.v_tipo_match
          from public.contas_pagar cp
          left join public.centros_custo cc on cc.id = cp.centro_custo_id
          cross join lateral (
            select
              public.maria_cartoes_normalizar_texto(i.descricao) as v_item_descricao_norm,
              public.maria_cartoes_normalizar_texto(cp.descricao) as v_cp_descricao_norm,
              public.maria_cartoes_normalizar_texto(i.conta_origem) as v_item_fornecedor_norm,
              public.maria_cartoes_normalizar_texto(cp.fonte_identificador) as v_cp_fornecedor_norm,
              coalesce(nullif(lower(trim(coalesce(cp.unidade, ''))), ''), lower(trim(coalesce(cc.codigo, '')))) as v_cp_unidade_codigo
          ) norm
          cross join lateral (
            select
              (
                (
                  length(norm.v_item_descricao_norm) >= 8
                  and length(norm.v_cp_descricao_norm) >= 8
                  and (
                    position(norm.v_item_descricao_norm in norm.v_cp_descricao_norm) > 0
                    or position(norm.v_cp_descricao_norm in norm.v_item_descricao_norm) > 0
                  )
                )
                or (
                  length(norm.v_item_fornecedor_norm) >= 4
                  and norm.v_item_fornecedor_norm = norm.v_cp_fornecedor_norm
                )
              ) as v_descricao_match,
              (
                i.unidade_codigo <> ''
                and norm.v_cp_unidade_codigo = i.unidade_codigo
              ) as v_unidade_match,
              (
                i.data_operacional is not null
                and (
                  (cp.data_vencimento is not null and abs(cp.data_vencimento - i.data_operacional) <= i.janela_dias)
                  or (cp.data_lancamento is not null and abs(cp.data_lancamento - i.data_operacional) <= i.janela_dias)
                  or (cp.data_pagamento is not null and abs((cp.data_pagamento at time zone 'America/Sao_Paulo')::date - i.data_operacional) <= i.janela_dias)
                  or (
                    coalesce(cp.tipo_lancamento, '') not in ('eventual', 'unica')
                    and cp.competencia is not null
                    and cp.competencia = date_trunc('month', i.data_operacional)::date
                  )
                )
              ) as v_data_match,
              (
                coalesce(cp.tipo_lancamento, '') in ('eventual', 'unica')
                or (
                  coalesce(cp.tipo_lancamento, '') = 'recorrente'
                  and norm.v_cp_unidade_codigo = i.unidade_codigo
                  and (
                    (
                      length(norm.v_item_descricao_norm) >= 8
                      and length(norm.v_cp_descricao_norm) >= 8
                      and (
                        position(norm.v_item_descricao_norm in norm.v_cp_descricao_norm) > 0
                        or position(norm.v_cp_descricao_norm in norm.v_item_descricao_norm) > 0
                      )
                    )
                    or (
                      length(norm.v_item_fornecedor_norm) >= 4
                      and norm.v_item_fornecedor_norm = norm.v_cp_fornecedor_norm
                    )
                  )
                )
              ) as v_tipo_match
          ) flags
          where i.valor_centavos is not null
            and public.maria_fluxo_valor_para_centavos(cp.valor) = i.valor_centavos
        ) matched
        where matched.v_descricao_match
          and matched.v_unidade_match
          and matched.v_data_match
          and matched.v_tipo_match
          -- Um eventual novo contra recorrente so bloqueia quando tambem bate descricao/fornecedor,
          -- unidade e data. Valor/plano isolados nao sao duplicidade forte.
        order by matched.created_at desc
        limit 5
      ) cp
    ) c on true
  )
  select
    a.item_id,
    a.item_numero,
    a.descricao,
    a.data_operacional,
    a.valor_centavos,
    a.unidade,
    a.plano_codigo,
    a.plano_nome,
    a.plano_origem,
    a.item_status,
    a.pendencias,
    a.duplicidade_candidatos,
    a.duplicidade_count,
    cardinality(a.pendencias) = 0 and a.duplicidade_count = 0 as pode_lancar
  from avaliados a
  order by a.item_numero;
$$;


ALTER FUNCTION "public"."maria_conferencia_lancamento_preflight"("p_conferencia_id" "uuid", "p_janela_dias" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_conferencia_lancamento_preflight"("p_conferencia_id" "uuid", "p_janela_dias" integer) IS 'Preflight de conferencia de lancamento: pendencias + duplicidade. Para eventual/unica, mesma competencia isolada nao bloqueia; exige data operacional real proxima.';



CREATE OR REPLACE FUNCTION "public"."maria_conferencia_lancamento_salvar"("p_chat_id" "text", "p_titulo" "text", "p_status" "text", "p_itens" "jsonb", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_parent_conferencia_id" "uuid" DEFAULT NULL::"uuid", "p_aprovado_por_nome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_conferencia_id uuid;
  v_status text;
  v_titulo text;
  v_versao integer;
  v_count integer;
  v_item jsonb;
  v_item_numero integer;
  v_audit_id uuid;
  v_after jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_chat_id), '') is null then
    raise exception 'chat_id obrigatorio para conferencia.';
  end if;

  v_titulo := coalesce(nullif(trim(p_titulo), ''), 'Conferencia de lancamentos avulsos');
  v_status := lower(coalesce(nullif(trim(p_status), ''), 'rascunho'));
  if v_status not in ('rascunho', 'corrigida', 'aprovada', 'lancada', 'cancelada') then
    raise exception 'status de conferencia invalido.';
  end if;

  if p_itens is null or jsonb_typeof(p_itens) <> 'array' or jsonb_array_length(p_itens) = 0 then
    raise exception 'itens da conferencia devem ser array jsonb nao vazio.';
  end if;

  if jsonb_array_length(p_itens) > 80 then
    raise exception 'conferencia com itens demais; limite operacional 80.';
  end if;

  if p_parent_conferencia_id is not null then
    select coalesce(max(versao), 0) + 1 into v_versao
      from public.maria_conferencias_lancamento
     where id = p_parent_conferencia_id
        or parent_conferencia_id = p_parent_conferencia_id;
  else
    v_versao := 1;
  end if;

  insert into public.maria_conferencias_lancamento (
    parent_conferencia_id,
    chat_id,
    titulo,
    status,
    versao,
    origem,
    texto_original,
    motivo,
    criado_por_nome,
    aprovado_por_nome,
    aprovado_at
  ) values (
    p_parent_conferencia_id,
    trim(p_chat_id),
    v_titulo,
    v_status,
    v_versao,
    coalesce(nullif(trim(p_canal), ''), 'whatsapp-grupo-financeiro'),
    nullif(trim(p_texto_original), ''),
    nullif(trim(p_motivo), ''),
    v_actor.nome,
    case when v_status in ('aprovada', 'lancada') then coalesce(nullif(trim(p_aprovado_por_nome), ''), v_actor.nome) else null end,
    case when v_status in ('aprovada', 'lancada') then now() else null end
  ) returning id into v_conferencia_id;

  for v_item, v_count in
    select value, ordinality::integer
      from jsonb_array_elements(p_itens) with ordinality
  loop
    v_item_numero := coalesce(nullif(v_item->>'item_numero', '')::integer, nullif(v_item->>'numero', '')::integer, v_count);

    if nullif(trim(coalesce(v_item->>'descricao', '')), '') is null then
      raise exception 'descricao obrigatoria no item %.', v_item_numero;
    end if;

    insert into public.maria_conferencia_lancamento_itens (
      conferencia_id,
      item_numero,
      fluxo_evento_id,
      conta_pagar_id,
      data_operacional,
      descricao,
      valor_centavos,
      unidade,
      conta_origem,
      plano_codigo,
      plano_nome,
      plano_origem,
      status,
      observacoes,
      raw_item
    ) values (
      v_conferencia_id,
      v_item_numero,
      nullif(v_item->>'fluxo_evento_id', '')::uuid,
      nullif(v_item->>'conta_pagar_id', '')::uuid,
      nullif(v_item->>'data_operacional', '')::date,
      trim(v_item->>'descricao'),
      coalesce(
        nullif(v_item->>'valor_centavos', '')::integer,
        public.maria_fluxo_valor_para_centavos(nullif(v_item->>'valor', '')::numeric)
      ),
      nullif(lower(trim(v_item->>'unidade')), ''),
      nullif(trim(v_item->>'conta_origem'), ''),
      nullif(trim(v_item->>'plano_codigo'), ''),
      nullif(trim(v_item->>'plano_nome'), ''),
      lower(coalesce(nullif(trim(v_item->>'plano_origem'), ''), 'pendente')),
      lower(coalesce(nullif(trim(v_item->>'status'), ''), 'pendente')),
      nullif(trim(v_item->>'observacoes'), ''),
      v_item
    );
  end loop;

  select count(*) into v_count
    from public.maria_conferencia_lancamento_itens
   where conferencia_id = v_conferencia_id;

  v_after := jsonb_build_object(
    'conferencia_id', v_conferencia_id,
    'chat_id', trim(p_chat_id),
    'titulo', v_titulo,
    'status', v_status,
    'versao', v_versao,
    'itens_total', v_count
  );

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    coalesce(nullif(trim(p_canal), ''), 'whatsapp-grupo-financeiro'),
    'maria_conferencias_lancamento',
    'conferencia_lancamento',
    v_conferencia_id,
    'salvar_conferencia_lancamento',
    null,
    v_after,
    p_motivo,
    p_texto_original
  );

  return v_after || jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'pagamento_executado_pela_maria', false,
    'lancamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_conferencia_lancamento_salvar"("p_chat_id" "text", "p_titulo" "text", "p_status" "text", "p_itens" "jsonb", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_parent_conferencia_id" "uuid", "p_aprovado_por_nome" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_conferencia_lancamento_salvar"("p_chat_id" "text", "p_titulo" "text", "p_status" "text", "p_itens" "jsonb", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_parent_conferencia_id" "uuid", "p_aprovado_por_nome" "text") IS 'Maria operational RPC: salva conferencia versionada de lancamentos avulsos/eventuais, sem criar conta_pagar e sem executar pagamento real.';



CREATE OR REPLACE FUNCTION "public"."maria_conformidade_campo_presente"("p_tabela" "text", "p_campo_alvo" "text", "p_filtro_campo" "text", "p_filtro_op" "text", "p_filtro_valor" "text", "p_janela_dias" integer) RETURNS TABLE("total" bigint, "desvio" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_win text; v_op text; v_sql text; v_cond text;
BEGIN
  v_win := public._maria_conf_win(p_tabela);
  IF v_win IS NULL THEN RAISE EXCEPTION 'tabela nao suportada'; END IF;
  IF NOT (p_campo_alvo = ANY(public._maria_conf_campos(p_tabela))) THEN RAISE EXCEPTION 'campo_alvo nao permitido'; END IF;
  IF p_filtro_campo IS NOT NULL AND p_filtro_campo <> '' THEN
    IF NOT (p_filtro_campo = ANY(public._maria_conf_campos(p_tabela))) THEN RAISE EXCEPTION 'filtro campo nao permitido'; END IF;
    v_op := public._maria_conf_op(p_filtro_op);
    IF v_op IS NULL THEN
      IF p_filtro_op = 'notnull' THEN v_cond := format(' AND t.%I IS NOT NULL', p_filtro_campo);
      ELSIF p_filtro_op = 'isnull' THEN v_cond := format(' AND t.%I IS NULL', p_filtro_campo);
      ELSE RAISE EXCEPTION 'op nao permitido'; END IF;
    ELSE v_cond := format(' AND t.%I::text %s $2', p_filtro_campo, v_op);
    END IF;
  ELSE v_cond := ''; END IF;
  v_sql := format(
    'SELECT count(*)::bigint, count(*) FILTER (WHERE t.%I IS NULL)::bigint FROM %I t WHERE t.%I >= (current_date - $1)%s',
    p_campo_alvo, p_tabela, v_win, v_cond);
  RETURN QUERY EXECUTE v_sql USING p_janela_dias, p_filtro_valor;
END; $_$;


ALTER FUNCTION "public"."maria_conformidade_campo_presente"("p_tabela" "text", "p_campo_alvo" "text", "p_filtro_campo" "text", "p_filtro_op" "text", "p_filtro_valor" "text", "p_janela_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_conformidade_sem_duplicata"("p_tabela" "text", "p_chave" "text"[], "p_janela_dias" integer) RETURNS TABLE("total" bigint, "desvio" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_win text; v_key text; v_sql text; c text;
BEGIN
  v_win := public._maria_conf_win(p_tabela);
  IF v_win IS NULL THEN RAISE EXCEPTION 'tabela nao suportada'; END IF;
  IF p_chave IS NULL OR array_length(p_chave,1) IS NULL THEN RAISE EXCEPTION 'chave vazia'; END IF;
  FOREACH c IN ARRAY p_chave LOOP
    IF NOT (c = ANY(public._maria_conf_campos(p_tabela))) THEN RAISE EXCEPTION 'chave campo nao permitido: %', c; END IF;
  END LOOP;
  SELECT string_agg(format('t.%I::text', k), ' || ''|'' || ') INTO v_key FROM unnest(p_chave) k;
  v_sql := format(
    'WITH base AS (SELECT %s AS kk FROM %I t WHERE t.%I >= (current_date - $1) AND coalesce(t.status::text,%L) <> %L),
          grp AS (SELECT kk, count(*) c FROM base GROUP BY kk)
     SELECT (SELECT count(*) FROM base)::bigint, coalesce((SELECT sum(c) FROM grp WHERE c > 1),0)::bigint',
    v_key, p_tabela, v_win, '', 'cancelado');
  RETURN QUERY EXECUTE v_sql USING p_janela_dias;
END; $_$;


ALTER FUNCTION "public"."maria_conformidade_sem_duplicata"("p_tabela" "text", "p_chave" "text"[], "p_janela_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_conformidade_tem_vinculo"("p_tabela" "text", "p_ligadora" "text", "p_fk" "text", "p_filtro_campo" "text", "p_filtro_valor" "text", "p_janela_dias" integer) RETURNS TABLE("total" bigint, "desvio" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
DECLARE v_win text; v_sql text;
BEGIN
  v_win := public._maria_conf_win(p_tabela);
  IF v_win IS NULL THEN RAISE EXCEPTION 'tabela nao suportada: %', p_tabela; END IF;
  IF NOT ((p_tabela='contas_pagar' AND p_ligadora='maria_conferencia_lancamento_itens' AND p_fk='conta_pagar_id')
       OR (p_tabela='contas_pagar' AND p_ligadora='maria_fluxo_caixa_eventos' AND p_fk='conta_pagar_id')) THEN
    RAISE EXCEPTION 'vinculo nao permitido';
  END IF;
  IF NOT (p_filtro_campo = ANY(public._maria_conf_campos(p_tabela))) THEN
    RAISE EXCEPTION 'filtro campo nao permitido: %', p_filtro_campo;
  END IF;
  v_sql := format(
    'SELECT count(*)::bigint, count(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM %I l WHERE l.%I = t.id))::bigint
       FROM %I t WHERE t.%I >= (current_date - $1) AND coalesce(t.status::text,%L) <> %L AND t.%I::text = $2',
    p_ligadora, p_fk, p_tabela, v_win, '', 'cancelado', p_filtro_campo);
  RETURN QUERY EXECUTE v_sql USING p_janela_dias, p_filtro_valor;
END; $_$;


ALTER FUNCTION "public"."maria_conformidade_tem_vinculo"("p_tabela" "text", "p_ligadora" "text", "p_fk" "text", "p_filtro_campo" "text", "p_filtro_valor" "text", "p_janela_dias" integer) OWNER TO "postgres";


