CREATE OR REPLACE FUNCTION "public"."maria_contas_alterar_vencimento"("p_conta_id" "uuid", "p_data_vencimento" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_before public.contas_pagar%rowtype; v_after public.contas_pagar%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  if p_data_vencimento is null or p_data_vencimento < date '2000-01-01' or p_data_vencimento > date '2100-12-31' then raise exception 'data de vencimento fora da faixa operacional permitida.'; end if;
  select * into v_before from public.contas_pagar where id=p_conta_id for update; if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  update public.contas_pagar set data_vencimento=p_data_vencimento, competencia=date_trunc('month',p_data_vencimento)::date, updated_at=now() where id=p_conta_id returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar','conta_pagar',p_conta_id,'alterar_vencimento',to_jsonb(v_before),to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'conta',public.maria_conta_pagar_public_json(v_after.id));
end; $$;


