CREATE OR REPLACE FUNCTION "public"."maria_contas_anexar_comprovante"("p_conta_id" "uuid", "p_storage_ref" "text", "p_hash" "text", "p_nome_arquivo" "text", "p_mime_type" "text", "p_tamanho_bytes" bigint, "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_canal_origem" "text" DEFAULT NULL::"text", "p_chat_id" "text" DEFAULT NULL::"text", "p_enviado_por" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_conta public.contas_pagar%rowtype;
  v_existing public.financeiro_documentos%rowtype;
  v_doc public.financeiro_documentos%rowtype;
  v_audit_id uuid;
  v_storage_ref text;
  v_hash text;
  v_confirmado_por_nome text;
  v_canal_origem text;
  v_status text;
  v_metadata jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_storage_ref := nullif(trim(p_storage_ref), '');
  if v_storage_ref is null then
    raise exception 'storage_ref obrigatorio para anexar comprovante.';
  end if;

  v_hash := nullif(trim(p_hash), '');
  if v_hash is null then
    raise exception 'hash obrigatorio para anexar comprovante.';
  end if;

  if p_tamanho_bytes is not null and p_tamanho_bytes < 0 then
    raise exception 'tamanho_bytes invalido.';
  end if;

  if p_conta_id is not null then
    select * into v_conta
      from public.contas_pagar
     where id = p_conta_id
     for update;

    if not found then
      raise exception 'conta_pagar nao encontrada para anexar comprovante.';
    end if;

    v_status := 'ativo';
  else
    v_status := 'pendente_vinculo';
  end if;

  select * into v_existing
    from public.financeiro_documentos
   where hash = v_hash
     and status_documento <> 'rejeitado'
   order by created_at asc
   limit 1;

  if found then
    if p_conta_id is not null
       and v_existing.vinculo_tipo = 'conta_pagar'
       and v_existing.vinculo_id = p_conta_id then
      return jsonb_build_object(
        'ok', true,
        'success', true,
        'duplicate', true,
        'documento_id', v_existing.id,
        'conta_id', p_conta_id,
        'descricao', v_conta.descricao,
        'message', 'comprovante_ja_estava_anexado_a_esta_conta'
      );
    end if;

    return jsonb_build_object(
      'ok', false,
      'success', false,
      'duplicate', true,
      'needs_human', true,
      'reason', 'mesmo_hash_ja_existe_em_outro_documento',
      'documento_existente_id', v_existing.id,
      'vinculo_tipo_existente', v_existing.vinculo_tipo,
      'vinculo_id_existente', v_existing.vinculo_id,
      'status_documento_existente', v_existing.status_documento
    );
  end if;

  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal_origem := coalesce(nullif(trim(p_canal_origem), ''), nullif(trim(p_canal), ''), 'whatsapp');
  v_metadata := jsonb_strip_nulls(jsonb_build_object(
    'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), ''),
    'canal_origem', v_canal_origem,
    'chat_id', nullif(trim(p_chat_id), ''),
    'enviado_por', nullif(trim(p_enviado_por), ''),
    'confirmado_por', v_confirmado_por_nome,
    'registrado_por', 'Maria',
    'pagamento_executado_pela_maria', false
  ));

  insert into public.financeiro_documentos (
    tipo,
    storage_ref,
    origem,
    vinculo_tipo,
    vinculo_id,
    hash,
    observacoes,
    status_documento,
    nome_arquivo,
    mime_type,
    tamanho_bytes,
    metadata
  ) values (
    'comprovante',
    v_storage_ref,
    'whatsapp',
    case when p_conta_id is null then null else 'conta_pagar' end,
    p_conta_id,
    v_hash,
    public.maria_contas_observacao_sanitizada(p_motivo),
    v_status,
    nullif(trim(p_nome_arquivo), ''),
    nullif(trim(p_mime_type), ''),
    p_tamanho_bytes,
    v_metadata
  ) returning * into v_doc;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal_origem,
    'financeiro_documentos',
    'financeiro_documento',
    v_doc.id,
    case when p_conta_id is null then 'registrar_comprovante_pendente' else 'anexar_comprovante_conta_pagar' end,
    null,
    to_jsonb(v_doc),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'documento_id', v_doc.id,
    'status_documento', v_doc.status_documento,
    'conta_id', p_conta_id,
    'descricao', case when p_conta_id is null then null else v_conta.descricao end,
    'unidade', case when p_conta_id is null then null else v_conta.unidade end,
    'valor', case when p_conta_id is null then null else v_conta.valor end,
    'vencimento', case when p_conta_id is null then null else v_conta.data_vencimento end,
    'storage_ref', v_doc.storage_ref,
    'hash', v_doc.hash,
    'audit_id', v_audit_id,
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_anexar_comprovante"("p_conta_id" "uuid", "p_storage_ref" "text", "p_hash" "text", "p_nome_arquivo" "text", "p_mime_type" "text", "p_tamanho_bytes" bigint, "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text", "p_chat_id" "text", "p_enviado_por" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_atualizar_status"("p_conta_id" "uuid", "p_status" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.contas_pagar%rowtype;
  v_after public.contas_pagar%rowtype;
  v_audit_id uuid;
  v_status text;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_status := lower(nullif(trim(p_status), ''));
  if v_status not in ('pendente', 'pago', 'finalizado') then
    raise exception 'status operacional nao permitido. Para cancelar, use maria_contas_cancelar.';
  end if;

  select * into v_before
    from public.contas_pagar
   where id = p_conta_id
   for update;

  if not found then
    raise exception 'conta_pagar nao encontrada.';
  end if;

  update public.contas_pagar
     set status = v_status,
         updated_at = now()
   where id = p_conta_id
   returning * into v_after;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    p_canal,
    'contas_pagar',
    'conta_pagar',
    p_conta_id,
    'atualizar_status',
    to_jsonb(v_before),
    to_jsonb(v_after),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'audit_id', v_audit_id,
    'conta', to_jsonb(v_after)
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_atualizar_status"("p_conta_id" "uuid", "p_status" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_atualizar_status"("p_conta_id" "uuid", "p_status" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: atualiza somente status operacional permitido, sem mover dinheiro.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_cancelar"("p_conta_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_motivo" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.contas_pagar%rowtype;
  v_after public.contas_pagar%rowtype;
  v_centro public.centros_custo%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_motivo text;
  v_canal text;
  v_cancelado_em timestamptz;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  v_motivo := public.maria_contas_observacao_sanitizada(p_motivo);
  if v_motivo is null then
    raise exception 'motivo obrigatorio para cancelar conta.';
  end if;

  select * into v_before
    from public.contas_pagar
   where id = p_conta_id
   for update;

  if not found then
    raise exception 'conta_pagar nao encontrada para cancelamento.';
  end if;

  if v_before.status = 'pago' then
    raise exception 'conta ja paga nao pode ser cancelada.';
  end if;

  if v_before.status = 'cancelado' then
    raise exception 'conta ja estava cancelada.';
  end if;

  v_cancelado_em := now();
  v_canal := coalesce(nullif(trim(p_canal), ''), 'whatsapp');

  update public.contas_pagar
     set status = 'cancelado',
         observacoes = nullif(concat_ws(E'\n',
           nullif(v_before.observacoes, ''),
           concat(
             'Conta cancelada pela Maria apos confirmacao de ',
             v_actor.nome,
             ' em ',
             to_char(v_cancelado_em at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
             '. Motivo: ',
             v_motivo,
             '.'
           )
         ), ''),
         updated_at = now()
   where id = p_conta_id
   returning * into v_after;

  select * into v_centro
    from public.centros_custo
   where id = v_after.centro_custo_id;

  select * into v_empresa
    from public.financeiro_empresas
   where id = v_after.empresa_id;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal,
    'contas_pagar',
    'conta_pagar',
    p_conta_id,
    'cancelar_conta_pagar',
    to_jsonb(v_before),
    to_jsonb(v_after),
    v_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'descricao', v_after.descricao,
    'valor', v_after.valor,
    'unidade', coalesce(v_centro.codigo, v_after.unidade),
    'centro', v_centro.nome,
    'empresa', coalesce(v_empresa.label_operacional, v_empresa.nome_fantasia, v_empresa.razao_social),
    'status_anterior', v_before.status,
    'status_novo', v_after.status,
    'motivo', v_motivo,
    'cancelado_por', v_actor.nome,
    'cancelado_em', v_cancelado_em,
    'mensagem_origem_registrada', nullif(trim(p_mensagem_origem_id), '') is not null,
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_cancelar"("p_conta_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_motivo" "text", "p_texto_original" "text", "p_mensagem_origem_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_cancelar"("p_conta_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_motivo" "text", "p_texto_original" "text", "p_mensagem_origem_id" "text") IS 'Cancela conta por status, preserva evidencias e registra auditoria. Nao executa DELETE nem pagamento.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_codigo_mes_marcar_indisponivel"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_competencia date; v_before public.contas_pagar_codigo_mes%rowtype; v_after public.contas_pagar_codigo_mes%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  if not exists (select 1 from public.contas_pagar where id=p_conta_pagar_id) then raise exception 'conta_pagar nao encontrada.'; end if;
  -- fase 2 debito automatico (02/09/2026)
  if exists (select 1 from public.contas_pagar where id=p_conta_pagar_id and debito_automatico) then raise exception 'conta em débito automático: não há código do mês para coletar.' using errcode = 'P0001'; end if;
  v_competencia := date_trunc('month',p_competencia)::date;
  select * into v_before from public.contas_pagar_codigo_mes where conta_pagar_id=p_conta_pagar_id and competencia=v_competencia for update;
  insert into public.contas_pagar_codigo_mes(conta_pagar_id,competencia,coletado_em,coletado_por,status_coleta)
  values(p_conta_pagar_id,v_competencia,now(),v_actor.nome,'indisponivel')
  on conflict (conta_pagar_id,competencia) do update set coletado_em=excluded.coletado_em,coletado_por=excluded.coletado_por,status_coleta=excluded.status_coleta,updated_at=now()
  returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar_codigo_mes','codigo_mes',v_after.id,'marcar_codigo_mes_indisponivel',case when v_before.id is null then null else to_jsonb(v_before) end,to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'codigo_mes',public.maria_codigo_mes_public_json(v_after.id));
end; $$;


ALTER FUNCTION "public"."maria_contas_codigo_mes_marcar_indisponivel"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_codigo_mes_marcar_indisponivel"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: marca codigo mensal como indisponivel.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_codigo_mes_registrar"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_codigo_barras" "text", "p_chave_pix" "text", "p_qr_pix_payload" "text", "p_valor_coletado" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_agente_nome" "text" DEFAULT 'Maria'::"text", "p_confirmado_por_nome" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_canal_origem" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_conta public.contas_pagar%rowtype;
  v_competencia date;
  v_before public.contas_pagar_codigo_mes%rowtype;
  v_after public.contas_pagar_codigo_mes%rowtype;
  v_audit_id uuid;
  v_confirmado_por_nome text;
  v_confirmado_por_actor text;
  v_canal_origem text;
  v_observacao text;
  v_codigo_barras text;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  select * into v_conta
    from public.contas_pagar
   where id = p_conta_pagar_id;

  if not found then
    raise exception 'conta_pagar nao encontrada.';
  end if;

  -- fase 2 debito automatico (02/09/2026)
  if v_conta.debito_automatico then
    raise exception 'conta em débito automático: não há código do mês para coletar.' using errcode = 'P0001';
  end if;

  v_codigo_barras := nullif(trim(p_codigo_barras), '');

  if v_codigo_barras is not null then
    if not public.maria_codigo_barras_texto_valido(v_codigo_barras) then
      raise exception 'codigo de barras invalido. Informe apenas linha digitavel/codigo de barras, sem texto livre.';
    end if;
  end if;

  if coalesce(v_codigo_barras, nullif(trim(p_chave_pix), ''), nullif(trim(p_qr_pix_payload), '')) is null then
    raise exception 'informe codigo de barras, chave pix ou payload pix.';
  end if;

  if p_valor_coletado is not null and (p_valor_coletado <= 0 or p_valor_coletado > 9999999.99) then
    raise exception 'valor coletado fora da faixa operacional permitida.';
  end if;

  v_competencia := date_trunc('month', p_competencia)::date;
  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_confirmado_por_actor := public.maria_normalizar_numero(p_ator_numero);
  v_canal_origem := coalesce(nullif(trim(p_canal_origem), ''), nullif(trim(p_canal), ''), 'whatsapp');
  v_observacao := coalesce(
    public.maria_contas_observacao_sanitizada(p_motivo),
    'Documento registrado pela Maria apos confirmacao humana.'
  );

  select * into v_before
    from public.contas_pagar_codigo_mes
   where conta_pagar_id = p_conta_pagar_id
     and competencia = v_competencia
   for update;

  insert into public.contas_pagar_codigo_mes (
    conta_pagar_id,
    competencia,
    codigo_barras,
    chave_pix,
    qr_pix_payload,
    valor_coletado,
    coletado_em,
    coletado_por,
    status_coleta,
    registrado_por_agente,
    agente_nome,
    agente_actor,
    confirmado_por_nome,
    confirmado_por_actor,
    canal_origem,
    mensagem_origem_id,
    registrado_via,
    registrado_em,
    observacao_operacional
  )
  values (
    p_conta_pagar_id,
    v_competencia,
    v_codigo_barras,
    nullif(trim(p_chave_pix), ''),
    nullif(trim(p_qr_pix_payload), ''),
    p_valor_coletado,
    now(),
    v_actor.nome,
    'coletado',
    true,
    coalesce(nullif(trim(p_agente_nome), ''), 'Maria'),
    v_confirmado_por_actor,
    v_confirmado_por_nome,
    v_confirmado_por_actor,
    v_canal_origem,
    nullif(trim(p_mensagem_origem_id), ''),
    'maria_contas_codigo_mes_registrar',
    now(),
    v_observacao
  )
  on conflict (conta_pagar_id, competencia) do update
    set codigo_barras = excluded.codigo_barras,
        chave_pix = excluded.chave_pix,
        qr_pix_payload = excluded.qr_pix_payload,
        valor_coletado = excluded.valor_coletado,
        coletado_em = excluded.coletado_em,
        coletado_por = excluded.coletado_por,
        status_coleta = excluded.status_coleta,
        registrado_por_agente = excluded.registrado_por_agente,
        agente_nome = excluded.agente_nome,
        agente_actor = excluded.agente_actor,
        confirmado_por_nome = excluded.confirmado_por_nome,
        confirmado_por_actor = excluded.confirmado_por_actor,
        canal_origem = excluded.canal_origem,
        mensagem_origem_id = excluded.mensagem_origem_id,
        registrado_via = excluded.registrado_via,
        registrado_em = excluded.registrado_em,
        observacao_operacional = excluded.observacao_operacional,
        updated_at = now()
  returning * into v_after;

  v_audit_id := public.maria_audit_insert(
    v_actor, p_ator_numero, v_canal_origem, 'contas_pagar_codigo_mes', 'codigo_mes', v_after.id,
    'registrar_codigo_mes', case when v_before.id is null then null else to_jsonb(v_before) end,
    to_jsonb(v_after), p_motivo, p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'conta_id', v_conta.id,
    'descricao', v_conta.descricao,
    'competencia', v_competencia,
    'valor', v_conta.valor,
    'valor_coletado', p_valor_coletado,
    'vencimento', v_conta.data_vencimento,
    'status_coleta', 'COLETADO',
    'registrado_por', v_after.agente_nome,
    'confirmado_por', v_after.confirmado_por_nome,
    'canal', v_after.canal_origem
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_codigo_mes_registrar"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_codigo_barras" "text", "p_chave_pix" "text", "p_qr_pix_payload" "text", "p_valor_coletado" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_agente_nome" "text", "p_confirmado_por_nome" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_codigo_mes_registrar"("p_conta_pagar_id" "uuid", "p_competencia" "date", "p_codigo_barras" "text", "p_chave_pix" "text", "p_qr_pix_payload" "text", "p_valor_coletado" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_agente_nome" "text", "p_confirmado_por_nome" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text") IS 'Maria operational RPC: registra documento mensal com carimbo visivel e retorna status_coleta COLETADO, sem codigo bruto e sem executar pagamento.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_corrigir_valor"("p_conta_id" "uuid", "p_valor" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_before public.contas_pagar%rowtype; v_after public.contas_pagar%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  if p_valor is null or p_valor <= 0 or p_valor > 9999999.99 then raise exception 'valor fora da faixa operacional permitida.'; end if;
  select * into v_before from public.contas_pagar where id=p_conta_id for update; if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  update public.contas_pagar set valor=round(p_valor,2), updated_at=now() where id=p_conta_id returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar','conta_pagar',p_conta_id,'corrigir_valor',to_jsonb(v_before),to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'conta',public.maria_conta_pagar_public_json(v_after.id));
end; $$;


ALTER FUNCTION "public"."maria_contas_corrigir_valor"("p_conta_id" "uuid", "p_valor" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_corrigir_valor"("p_conta_id" "uuid", "p_valor" numeric, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: corrige somente o valor de uma conta_pagar, com validacao e audit log.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_dar_baixa"("p_conta_id" "uuid", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text", "p_conta_pagadora_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.contas_pagar%rowtype;
  v_after public.contas_pagar%rowtype;
  v_audit_id uuid;
  v_metodo text;
  v_confirmado_por_nome text;
  v_canal_origem text;
  v_obs text;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_data_pagamento is null then
    raise exception 'data_pagamento obrigatoria para baixa.';
  end if;

  if p_data_pagamento > ((now() at time zone 'America/Sao_Paulo')::date + 1) then
    raise exception 'data_pagamento futura nao permitida para baixa operacional.';
  end if;

  v_metodo := nullif(trim(p_metodo_pagamento), '');
  -- fase 2 debito automatico (02/09/2026): conta flagada dispensa o metodo — assume o canonico.
  if v_metodo is null and exists (select 1 from public.contas_pagar c where c.id = p_conta_id and c.debito_automatico) then
    v_metodo := 'Débito Automático';
  end if;
  if v_metodo is null then
    raise exception 'metodo_pagamento obrigatorio para baixa.';
  end if;
  if lower(v_metodo) in (lower('Débito Automático'), lower('Debito Automatico')) then
    v_metodo := 'Débito Automático';
  end if;

  if lower(v_metodo) not in (
    lower('PIX'),
    lower('Transferência Bancária'),
    lower('Transferencia Bancaria'),
    lower('Cartão de Crédito'),
    lower('Cartao de Credito'),
    lower('Cartão de Débito'),
    lower('Cartao de Debito'),
    lower('Débito Automático'),
    lower('Debito Automatico'),
    lower('Boleto'),
    lower('Cheque'),
    lower('Dinheiro'),
    lower('Comprovante')
  ) then
    raise exception 'metodo_pagamento nao permitido para baixa operacional.';
  end if;

  if p_conta_pagadora_id is not null then
    select * into v_conta_pagadora
      from public.financeiro_contas_bancarias
     where id = p_conta_pagadora_id;

    if not found then
      raise exception 'conta_pagadora nao encontrada.';
    end if;

    if v_conta_pagadora.ativo is not true then
      raise exception 'conta_pagadora inativa nao pode receber baixa: %', v_conta_pagadora.apelido;
    end if;
  end if;

  select * into v_before
    from public.contas_pagar
   where id = p_conta_id
   for update;

  if not found then
    raise exception 'conta_pagar nao encontrada.';
  end if;

  if v_before.status = 'pago' then
    raise exception 'conta ja esta paga; confirmacao explicita de rebaixa/substituicao exige fluxo separado.';
  end if;

  if v_before.status not in ('pendente', 'finalizado') then
    raise exception 'status atual nao permite baixa operacional: %', v_before.status;
  end if;

  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal_origem := coalesce(nullif(trim(p_canal_origem), ''), nullif(trim(p_canal), ''), 'whatsapp');
  v_obs := concat_ws(E'\n',
    nullif(v_before.observacoes, ''),
    concat('Baixa registrada pela Maria apos confirmacao de ', v_confirmado_por_nome, ' em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '. Sem pagamento real executado pela Maria.'),
    public.maria_contas_observacao_sanitizada(p_motivo)
  );

  update public.contas_pagar
     set status = 'pago',
         data_pagamento = p_data_pagamento::timestamptz,
         metodo_pagamento = v_metodo,
         conta_pagadora_id = coalesce(p_conta_pagadora_id, conta_pagadora_id),
         observacoes = v_obs,
         updated_at = now()
   where id = p_conta_id
   returning * into v_after;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal_origem,
    'contas_pagar',
    'conta_pagar',
    p_conta_id,
    'dar_baixa_conta_pagar',
    to_jsonb(v_before),
    to_jsonb(v_after),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'conta_id', v_after.id,
    'descricao', v_after.descricao,
    'unidade', v_after.unidade,
    'valor', v_after.valor,
    'vencimento', v_after.data_vencimento,
    'status', 'pago',
    'data_pagamento', p_data_pagamento,
    'metodo_pagamento', v_metodo,
    'conta_pagadora', v_conta_pagadora.apelido,
    'conta_pagadora_registrada', (v_after.conta_pagadora_id is not null),
    'conta_pagadora_pendente', (v_after.conta_pagadora_id is null),
    'registrado_por', 'Maria',
    'confirmado_por', v_confirmado_por_nome,
    'canal', v_canal_origem,
    'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), ''),
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_dar_baixa"("p_conta_id" "uuid", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text", "p_conta_pagadora_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_dar_baixa_com_comprovante"("p_conta_id" "uuid", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_storage_ref" "text", "p_hash" "text", "p_nome_arquivo" "text", "p_mime_type" "text", "p_tamanho_bytes" bigint, "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text", "p_chat_id" "text", "p_enviado_por" "text", "p_conta_pagadora_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_existing public.financeiro_documentos%rowtype;
  v_baixa jsonb;
  v_doc jsonb;
  v_canal_origem text;
begin
  -- Asserção antecipada para evitar baixa se o comprovante já conflita.
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_hash), '') is null then
    raise exception 'hash obrigatorio para baixa com comprovante.';
  end if;

  select * into v_existing
    from public.financeiro_documentos
   where hash = nullif(trim(p_hash), '')
     and status_documento <> 'rejeitado'
   order by created_at asc
   limit 1;

  if found then
    if v_existing.vinculo_tipo = 'conta_pagar'
       and v_existing.vinculo_id = p_conta_id then
      raise exception 'comprovante_ja_anexado_a_esta_conta; baixa_com_anexo_exige_fluxo_de_revisao';
    end if;
    raise exception 'mesmo_comprovante_ja_existe_em_outro_documento; revisar_antes_de_baixar';
  end if;

  v_canal_origem := coalesce(nullif(trim(p_canal_origem), ''), nullif(trim(p_canal), ''), 'whatsapp');

  -- Se qualquer passo abaixo falhar, a transação inteira da função é revertida.
  v_baixa := public.maria_contas_dar_baixa(
    p_conta_id,
    p_data_pagamento,
    p_metodo_pagamento,
    p_confirmado_por_nome,
    p_ator_numero,
    p_papel,
    p_canal,
    p_texto_original,
    p_motivo,
    p_mensagem_origem_id,
    v_canal_origem,
    p_conta_pagadora_id
  );

  v_doc := public.maria_contas_anexar_comprovante(
    p_conta_id,
    p_storage_ref,
    p_hash,
    p_nome_arquivo,
    p_mime_type,
    p_tamanho_bytes,
    p_confirmado_por_nome,
    p_ator_numero,
    p_papel,
    p_canal,
    p_texto_original,
    p_motivo,
    p_mensagem_origem_id,
    v_canal_origem,
    p_chat_id,
    p_enviado_por
  );

  if coalesce((v_doc->>'ok')::boolean, false) is not true then
    raise exception 'falha_ao_anexar_comprovante: %', v_doc::text;
  end if;

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'baixa', v_baixa,
    'documento', v_doc,
    'conta_pagadora_pendente', coalesce((v_baixa->>'conta_pagadora_pendente')::boolean, true),
    'pagamento_executado_pela_maria', false,
    'atomic', true
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_dar_baixa_com_comprovante"("p_conta_id" "uuid", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_storage_ref" "text", "p_hash" "text", "p_nome_arquivo" "text", "p_mime_type" "text", "p_tamanho_bytes" bigint, "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_canal_origem" "text", "p_chat_id" "text", "p_enviado_por" "text", "p_conta_pagadora_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_definir_centro_custo"("p_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_before public.contas_pagar%rowtype; v_after public.contas_pagar%rowtype; v_centro public.centros_custo%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  select * into v_centro from public.centros_custo where id=p_centro_custo_id and ativo=true and tipo='unidade'; if not found then raise exception 'centro_custo_id nao e uma unidade ativa.'; end if;
  select * into v_before from public.contas_pagar where id=p_conta_id for update; if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  update public.contas_pagar set centro_custo_id=p_centro_custo_id, unidade=v_centro.codigo, updated_at=now() where id=p_conta_id returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar','conta_pagar',p_conta_id,'definir_centro_custo',to_jsonb(v_before),to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'conta',public.maria_conta_pagar_public_json(v_after.id));
end; $$;


ALTER FUNCTION "public"."maria_contas_definir_centro_custo"("p_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_definir_centro_custo"("p_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: define centro_custo_id validando unidade ativa e sincroniza unidade.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_definir_debito_automatico"("p_conta_id" "uuid", "p_debito_automatico" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_aplicar_futuros" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.contas_pagar%rowtype;
  v_after public.contas_pagar%rowtype;
  v_modelo_id uuid;
  v_prop uuid[] := '{}'::uuid[];
  v_audit_id uuid;
  v_flag boolean := coalesce(p_debito_automatico, false);
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);

  select * into v_before from public.contas_pagar where id = p_conta_id for update;
  if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  if v_before.status = 'cancelado' then
    raise exception 'conta cancelada nao se altera.' using errcode = 'P0001';
  end if;
  if v_flag and v_before.tipo_lancamento = 'eventual' then
    raise exception 'conta eventual nao aceita debito automatico: eventual e gasto avulso; a flag e para conta recorrente, unica ou parcelada.' using errcode = 'P0001';
  end if;

  update public.contas_pagar set debito_automatico = v_flag, updated_at = now() where id = p_conta_id returning * into v_after;

  if coalesce(p_aplicar_futuros, true) then
    if v_before.tipo_lancamento = 'recorrente' then
      -- modelo = a propria conta (recorrente_modelo_id nulo) ou o modelo dela; instancias pendentes desta competencia em diante.
      v_modelo_id := coalesce(v_before.recorrente_modelo_id, v_before.id);
      with u as (
        update public.contas_pagar c set debito_automatico = v_flag, updated_at = now()
         where c.id <> p_conta_id and c.debito_automatico is distinct from v_flag
           and (c.id = v_modelo_id
                or (c.recorrente_modelo_id = v_modelo_id and c.status = 'pendente' and c.competencia >= v_before.competencia))
        returning c.id)
      select coalesce(array_agg(u.id), '{}'::uuid[]) into v_prop from u;
    elsif v_before.tipo_lancamento = 'parcelada' and v_before.parcelamento_id is not null then
      with u as (
        update public.contas_pagar c set debito_automatico = v_flag, updated_at = now()
         where c.id <> p_conta_id and c.parcelamento_id = v_before.parcelamento_id and c.status = 'pendente'
           and c.data_vencimento >= v_before.data_vencimento and c.debito_automatico is distinct from v_flag
        returning c.id)
      select coalesce(array_agg(u.id), '{}'::uuid[]) into v_prop from u;
    end if;
  end if;

  v_audit_id := public.maria_audit_insert(
    v_actor, p_ator_numero, coalesce(nullif(trim(p_canal), ''), 'whatsapp'), 'contas_pagar', 'conta_pagar', p_conta_id,
    case when v_flag then 'ligar_debito_automatico' else 'desligar_debito_automatico' end,
    jsonb_build_object('conta', to_jsonb(v_before)),
    jsonb_build_object('conta', to_jsonb(v_after), 'propagadas', to_jsonb(v_prop)),
    p_motivo, p_texto_original);

  return jsonb_build_object(
    'ok', true, 'success', true, 'audit_id', v_audit_id,
    'conta_id', v_after.id, 'descricao', v_after.descricao, 'tipo_lancamento', v_after.tipo_lancamento,
    'antes', v_before.debito_automatico, 'debito_automatico', v_after.debito_automatico,
    'mudou', (v_before.debito_automatico is distinct from v_after.debito_automatico),
    'propagadas', coalesce(array_length(v_prop, 1), 0), 'propagadas_ids', to_jsonb(v_prop),
    'resumo', format('Débito automático %s em "%s"%s.%s',
       case when v_flag then 'ligado' else 'desligado' end, v_after.descricao,
       case when coalesce(array_length(v_prop, 1), 0) > 0 then format(' e em %s conta(s) da mesma série', array_length(v_prop, 1)) else '' end,
       case when v_flag then ' O espelho "Pagar:" da agenda sai sozinho em até 10 min; a conta segue na lista do dia marcada como débito automático.'
            else ' O espelho "Pagar:" volta pra agenda em até 10 min.' end),
    'registrado_por', 'Maria', 'pagamento_executado_pela_maria', false);
end $$;


ALTER FUNCTION "public"."maria_contas_definir_debito_automatico"("p_conta_id" "uuid", "p_debito_automatico" boolean, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_aplicar_futuros" boolean) OWNER TO "postgres";


