    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_before public.contas_pagar%rowtype; v_after public.contas_pagar%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  if not exists (select 1 from public.plano_contas where id=p_plano_conta_id and ativo=true and natureza='saida' and nivel=3) then raise exception 'plano_conta_id nao e uma folha de saida ativa.'; end if;
  select * into v_before from public.contas_pagar where id=p_conta_id for update; if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  update public.contas_pagar set plano_conta_id=p_plano_conta_id, updated_at=now() where id=p_conta_id returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar','conta_pagar',p_conta_id,'definir_plano_conta',to_jsonb(v_before),to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'conta',public.maria_conta_pagar_public_json(v_after.id));
end; $$;


