CREATE OR REPLACE FUNCTION "public"."maria_contas_documento_status"("p_conta_id" "uuid", "p_competencia" "date") RETURNS TABLE("conta_id" "uuid", "competencia" "date", "status_coleta" "text", "tem_documento_registrado" boolean, "tipo_documento_registrado" "text", "registrado_por_agente" boolean, "agente_nome" "text", "confirmado_por_nome" "text", "registrado_em" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      cp.id as conta_id,
      cp.status as conta_status,
      cp.data_vencimento,
      c.id as codigo_id,
      c.codigo_barras,
      c.chave_pix,
      c.qr_pix_payload,
      c.status_coleta as status_coleta_interno,
      c.registrado_por_agente,
      c.agente_nome,
      c.confirmado_por_nome,
      c.registrado_em,
      (
        nullif(btrim(c.codigo_barras), '') is not null
        or nullif(btrim(c.chave_pix), '') is not null
        or nullif(btrim(c.qr_pix_payload), '') is not null
        or c.status_coleta = 'coletado'
      ) as tem_documento
    from public.contas_pagar cp
    left join public.contas_pagar_codigo_mes c
      on c.conta_pagar_id = cp.id
     and c.competencia = date_trunc('month', p_competencia)::date
    where cp.id = p_conta_id
  )
  select
    p_conta_id as conta_id,
    date_trunc('month', p_competencia)::date as competencia,
    case
      when coalesce(b.tem_documento, false) then 'COLETADO'
      when b.status_coleta_interno = 'indisponivel' then 'SEM CÓDIGO'
      when b.conta_status = 'pendente'
       and b.data_vencimento <= ((now() at time zone 'America/Sao_Paulo')::date + 7)
        then 'COLETAR'
      else 'SEM CÓDIGO'
    end as status_coleta,
    coalesce(b.tem_documento, false) as tem_documento_registrado,
    case
      when b.codigo_id is null then null
      when (nullif(btrim(b.codigo_barras), '') is not null)
        and (nullif(btrim(b.chave_pix), '') is not null or nullif(btrim(b.qr_pix_payload), '') is not null)
        then 'ambos'
      when nullif(btrim(b.codigo_barras), '') is not null then 'boleto'
      when nullif(btrim(b.chave_pix), '') is not null or nullif(btrim(b.qr_pix_payload), '') is not null then 'pix'
      when b.status_coleta_interno = 'coletado' then 'desconhecido'
      else null
    end as tipo_documento_registrado,
    coalesce(b.registrado_por_agente, false) as registrado_por_agente,
    b.agente_nome,
    b.confirmado_por_nome,
    b.registrado_em
  from (select 1) seed
  left join base b on true;
$$;


ALTER FUNCTION "public"."maria_contas_documento_status"("p_conta_id" "uuid", "p_competencia" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_documento_status"("p_conta_id" "uuid", "p_competencia" "date") IS 'Maria read RPC: retorna status_coleta COLETADO/COLETAR/SEM CODIGO sem codigo bruto.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_eventual_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_status" "text", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_documento_id" "uuid" DEFAULT NULL::"uuid", "p_observacoes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_plano public.plano_contas%rowtype;
  v_centro public.centros_custo%rowtype;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_after public.contas_pagar%rowtype;
  v_audit_id uuid;
  v_status text;
  v_metodo text;
  v_data_pagamento timestamptz;
  v_confirmado_por_nome text;
  v_canal_origem text;
  v_obs text;
  v_valor_centavos integer;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_descricao), '') is null then
    raise exception 'descricao obrigatoria para conta eventual.';
  end if;

  v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor);
  if v_valor_centavos is null or v_valor_centavos <= 0 or v_valor_centavos > 999999999 then
    raise exception 'valor fora da faixa operacional permitida.';
  end if;

  if p_data_vencimento is null then
    raise exception 'data_vencimento obrigatoria para conta eventual.';
  end if;

  select * into v_plano
    from public.plano_contas
   where id = p_plano_conta_id
     and ativo = true
     and natureza = 'saida'
     and nivel = 3;

  if not found then
    raise exception 'plano_conta_id nao e uma folha de saida ativa.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = p_centro_custo_id
     and ativo = true
     and tipo = 'unidade';

  if not found then
    raise exception 'centro_custo_id nao e uma unidade ativa.';
  end if;

  select * into v_conta_pagadora
    from public.financeiro_contas_bancarias
   where id = p_conta_pagadora_id
     and ativo = true;

  if not found then
    raise exception 'conta_pagadora_id nao encontrada ou inativa.';
  end if;

  select * into v_empresa
    from public.financeiro_empresas
   where id = v_conta_pagadora.empresa_id
     and ativo = true;

  if not found then
    raise exception 'empresa da conta pagadora nao encontrada ou inativa.';
  end if;

  if v_empresa.unidade_id <> p_centro_custo_id then
    raise exception 'centro_custo_id nao corresponde a unidade da conta pagadora.';
  end if;

  v_status := lower(coalesce(nullif(trim(p_status), ''), 'pago'));
  if v_status not in ('pendente', 'pago') then
    raise exception 'status permitido para eventual: pendente ou pago.';
  end if;

  v_metodo := nullif(trim(p_metodo_pagamento), '');
  if v_status = 'pago' then
    if p_data_pagamento is null then
      raise exception 'data_pagamento obrigatoria para eventual ja pago.';
    end if;

    if p_data_pagamento > ((now() at time zone 'America/Sao_Paulo')::date + 1) then
      raise exception 'data_pagamento futura nao permitida para conta eventual.';
    end if;

    if v_metodo is null then
      raise exception 'metodo_pagamento obrigatorio para eventual ja pago.';
    end if;

    if lower(v_metodo) not in (
      lower('PIX'),
      lower('Transferência Bancária'),
      lower('Transferencia Bancaria'),
      lower('Cartão de Crédito'),
      lower('Cartao de Credito'),
      lower('Cartão de Débito'),
      lower('Cartao de Debito'),
      lower('Débito Automático'),
      lower('Debito Automatico'),
      lower('Boleto'),
      lower('Dinheiro'),
      lower('Comprovante')
    ) then
      raise exception 'metodo_pagamento nao permitido para conta eventual.';
    end if;

    v_data_pagamento := p_data_pagamento::timestamptz;
  else
    v_metodo := null;
    v_data_pagamento := null;
  end if;

  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal_origem := coalesce(nullif(trim(p_canal), ''), 'whatsapp');
  v_obs := concat_ws(E'\n',
    public.maria_contas_observacao_sanitizada(p_observacoes),
    concat('Conta eventual registrada pela Maria apos confirmacao de ', v_confirmado_por_nome, ' em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '. Sem pagamento real executado pela Maria.'),
    public.maria_contas_observacao_sanitizada(p_motivo)
  );

  insert into public.contas_pagar (
    descricao,
    unidade,
    valor,
    data_lancamento,
    data_vencimento,
    competencia,
    status,
    data_pagamento,
    metodo_pagamento,
    tipo_lancamento,
    parcela_atual,
    total_parcelas,
    observacoes,
    fonte_tipo,
    plano_conta_id,
    centro_custo_id,
    empresa_id,
    conta_pagadora_id
  ) values (
    trim(p_descricao),
    v_centro.codigo,
    round(p_valor, 2),
    (now() at time zone 'America/Sao_Paulo')::date,
    p_data_vencimento,
    date_trunc('month', p_data_vencimento)::date,
    v_status,
    v_data_pagamento,
    v_metodo,
    'eventual',
    null,
    null,
    nullif(v_obs, ''),
    'whatsapp',
    p_plano_conta_id,
    p_centro_custo_id,
    v_conta_pagadora.empresa_id,
    p_conta_pagadora_id
  )
  returning * into v_after;

  if p_documento_id is not null then
    update public.financeiro_documentos
       set vinculo_tipo = 'conta_pagar',
           vinculo_id = v_after.id
     where id = p_documento_id;
  end if;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal_origem,
    'contas_pagar',
    'conta_pagar',
    v_after.id,
    'criar_conta_pagar_eventual',
    null,
    to_jsonb(v_after),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'conta', public.maria_conta_pagar_public_json(v_after.id),
    'conta_id', v_after.id,
    'status', v_after.status,
    'status_coleta', null,
    'tipo_lancamento', 'eventual',
    'empresa_label', v_empresa.label_operacional,
    'centro_custo', v_centro.nome,
    'plano', concat_ws(' ', v_plano.codigo, v_plano.nome),
    'valor', v_after.valor,
    'valor_centavos', v_valor_centavos,
    'registrado_por', 'Maria',
    'confirmado_por', v_confirmado_por_nome,
    'canal', v_canal_origem,
    'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), ''),
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_eventual_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_status" "text", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_documento_id" "uuid", "p_observacoes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_eventual_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_status" "text", "p_data_pagamento" "date", "p_metodo_pagamento" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_documento_id" "uuid", "p_observacoes" "text") IS 'Maria operational RPC: cria conta_pagar eventual confirmada por humano, infere empresa pela conta pagadora e nao executa pagamento real.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_observacao_sanitizada"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select nullif(
    left(
      btrim(
        regexp_replace(
          regexp_replace(coalesce(p_texto, ''), '[0-9]{12,}', '[codigo]', 'g'),
          '\s+',
          ' ',
          'g'
        )
      ),
      280
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."maria_contas_observacao_sanitizada"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_parcelada_criar"("p_descricao" "text", "p_valor_parcela" numeric, "p_valor_total" numeric, "p_quantidade_parcelas" integer, "p_primeira_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_observacoes" "text" DEFAULT NULL::"text", "p_periodicidade" "text" DEFAULT 'mensal'::"text", "p_confirmar_duplicidade" boolean DEFAULT false, "p_debito_automatico" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_plano public.plano_contas%rowtype;
  v_centro public.centros_custo%rowtype;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_after public.contas_pagar%rowtype;
  v_duplicate record;
  v_parcelamento_id uuid;
  v_descricao_norm text;
  v_confirmado_por text;
  v_canal text;
  v_obs text;
  v_month_start date;
  v_due date;
  v_last_due date;
  v_anchor_day integer;
  v_days_in_month integer;
  v_i integer;
  v_parcela_centavos bigint;
  v_ultima_centavos bigint;
  v_total_centavos bigint;
  v_valor_centavos integer;
  v_valor numeric;
  v_parcelas_audit jsonb := '[]'::jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_descricao), '') is null then
    raise exception 'descricao obrigatoria para conta parcelada.';
  end if;

  if p_quantidade_parcelas is null then
    raise exception 'quantidade_parcelas obrigatoria para conta parcelada.';
  end if;

  if p_quantidade_parcelas <= 1 or p_quantidade_parcelas > 120 then
    raise exception 'quantidade_parcelas deve ser maior que 1 e no maximo 120.';
  end if;

  if p_primeira_data_vencimento is null then
    raise exception 'primeira_data_vencimento obrigatoria para conta parcelada.';
  end if;

  if lower(coalesce(nullif(trim(p_periodicidade), ''), 'mensal')) <> 'mensal' then
    raise exception 'periodicidade permitida nesta fatia: mensal.';
  end if;

  if (p_valor_parcela is null) = (p_valor_total is null) then
    raise exception 'informe exatamente um modo de valor: valor_parcela ou valor_total.';
  end if;

  if p_plano_conta_id is null then
    raise exception 'plano_conta_id obrigatorio para conta parcelada.';
  end if;

  if p_centro_custo_id is null then
    raise exception 'centro_custo_id obrigatorio para conta parcelada.';
  end if;

  if p_conta_pagadora_id is null then
    raise exception 'conta_pagadora_id obrigatoria para conta parcelada.';
  end if;

  select * into v_plano
    from public.plano_contas
   where id = p_plano_conta_id
     and ativo = true
     and natureza = 'saida'
     and nivel = 3;

  if not found then
    raise exception 'plano_conta_id nao e uma folha de saida ativa.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = p_centro_custo_id
     and ativo = true
     and tipo = 'unidade';

  if not found then
    raise exception 'centro_custo_id nao e uma unidade ativa.';
  end if;

  select * into v_conta_pagadora
    from public.financeiro_contas_bancarias
   where id = p_conta_pagadora_id
     and ativo = true;

  if not found then
    raise exception 'conta_pagadora_id nao encontrada ou inativa.';
  end if;

  select * into v_empresa
    from public.financeiro_empresas
   where id = v_conta_pagadora.empresa_id
     and ativo = true;

  if not found then
    raise exception 'empresa da conta pagadora nao encontrada ou inativa.';
  end if;

  if v_empresa.unidade_id <> p_centro_custo_id then
    raise exception 'centro_custo_id nao corresponde a unidade da conta pagadora.';
  end if;

  if p_valor_total is not null then
    v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor_total);
    if v_valor_centavos is null or v_valor_centavos <= 0 or v_valor_centavos > 999999999 then
      raise exception 'valor_total fora da faixa operacional permitida.';
    end if;
    v_total_centavos := v_valor_centavos;
    v_parcela_centavos := public.maria_fluxo_valor_para_centavos(
      round(p_valor_total / p_quantidade_parcelas, 2)
    );
    v_ultima_centavos := v_total_centavos - ((p_quantidade_parcelas - 1) * v_parcela_centavos);
  else
    v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor_parcela);
    if v_valor_centavos is null or v_valor_centavos <= 0 or v_valor_centavos > 999999999 then
      raise exception 'valor_parcela fora da faixa operacional permitida.';
    end if;
    v_parcela_centavos := v_valor_centavos;
    v_ultima_centavos := v_parcela_centavos;
    v_total_centavos := v_parcela_centavos * p_quantidade_parcelas;
  end if;

  if v_parcela_centavos <= 0 or v_ultima_centavos <= 0 or v_total_centavos > 999999999 then
    raise exception 'valores das parcelas fora da faixa operacional permitida.';
  end if;

  v_descricao_norm := public.maria_cartoes_normalizar_texto(trim(p_descricao));
  select c.descricao, c.data_vencimento
    into v_duplicate
    from public.contas_pagar c
   where c.plano_conta_id = p_plano_conta_id
     and c.centro_custo_id = p_centro_custo_id
     and c.parcelamento_id is not null
     and c.status not in ('cancelado', 'finalizado')
     and c.data_vencimento between p_primeira_data_vencimento - 3 and p_primeira_data_vencimento + 3
     and position(v_descricao_norm in public.maria_cartoes_normalizar_texto(c.descricao)) = 1
   order by c.data_vencimento, c.created_at
   limit 1;

  if found and not coalesce(p_confirmar_duplicidade, false) then
    raise exception 'possivel parcelamento duplicado: "%" com vencimento em %. Confirme explicitamente para continuar.',
      v_duplicate.descricao,
      to_char(v_duplicate.data_vencimento, 'DD/MM/YYYY');
  end if;

  v_parcelamento_id := gen_random_uuid();
  v_confirmado_por := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal := coalesce(nullif(trim(p_canal), ''), 'whatsapp');
  v_obs := concat_ws(E'\n',
    public.maria_contas_observacao_sanitizada(p_observacoes),
    concat(
      'Conta parcelada registrada pela Maria apos confirmacao de ',
      v_confirmado_por,
      ' em ',
      to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
      '. Sem pagamento real executado pela Maria.'
    ),
    public.maria_contas_observacao_sanitizada(p_motivo)
  );
  v_anchor_day := extract(day from p_primeira_data_vencimento)::integer;

  for v_i in 1..p_quantidade_parcelas loop
    v_month_start := (date_trunc('month', p_primeira_data_vencimento)::date + ((v_i - 1) * interval '1 month'))::date;
    v_days_in_month := extract(day from (date_trunc('month', v_month_start) + interval '1 month - 1 day'))::integer;
    v_due := make_date(
      extract(year from v_month_start)::integer,
      extract(month from v_month_start)::integer,
      least(v_anchor_day, v_days_in_month)
    );
    v_last_due := v_due;
    v_valor := (case when v_i = p_quantidade_parcelas then v_ultima_centavos else v_parcela_centavos end)::numeric / 100;

    insert into public.contas_pagar (
      descricao,
      unidade,
      valor,
      data_lancamento,
      data_vencimento,
      competencia,
      status,
      data_pagamento,
      metodo_pagamento,
      tipo_lancamento,
      parcelamento_id,
      parcela_atual,
      total_parcelas,
      observacoes,
      fonte_tipo,
      plano_conta_id,
      centro_custo_id,
      empresa_id,
      conta_pagadora_id, debito_automatico
    ) values (
      concat(trim(p_descricao), ' (', v_i, '/', p_quantidade_parcelas, ')'),
      v_centro.codigo,
      v_valor,
      (now() at time zone 'America/Sao_Paulo')::date,
      v_due,
      date_trunc('month', v_due)::date,
      'pendente',
      null,
      null,
      'parcelada',
      v_parcelamento_id,
      v_i,
      p_quantidade_parcelas,
      nullif(v_obs, ''),
      'whatsapp',
      p_plano_conta_id,
      p_centro_custo_id,
      v_conta_pagadora.empresa_id,
      p_conta_pagadora_id, coalesce(p_debito_automatico, false)
    )
    returning * into v_after;

    v_parcelas_audit := v_parcelas_audit || jsonb_build_array(jsonb_build_object(
      'id', v_after.id,
      'parcela_atual', v_after.parcela_atual,
      'total_parcelas', v_after.total_parcelas,
      'valor', v_after.valor,
      'data_vencimento', v_after.data_vencimento
    ));
  end loop;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal,
    'contas_pagar',
    'parcelamento_conta_pagar',
    v_parcelamento_id,
    'criar_conta_pagar_parcelada',
    null,
    jsonb_build_object(
      'parcelamento_id', v_parcelamento_id,
      'descricao', trim(p_descricao),
      'quantidade_parcelas', p_quantidade_parcelas,
      'valor_total', v_total_centavos::numeric / 100,
      'parcelas', v_parcelas_audit,
      'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), '')
    ),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'descricao', trim(p_descricao),
    'quantidade_parcelas', p_quantidade_parcelas,
    'valor_parcela', v_parcela_centavos::numeric / 100,
    'valor_ultima_parcela', case
      when v_ultima_centavos <> v_parcela_centavos then v_ultima_centavos::numeric / 100
      else null
    end,
    'primeiro_vencimento', p_primeira_data_vencimento,
    'ultimo_vencimento', v_last_due,
    'valor_total', v_total_centavos::numeric / 100,
    'plano', concat_ws(' ', v_plano.codigo, v_plano.nome),
    'centro', v_centro.nome,
    'empresa', coalesce(v_empresa.label_operacional, v_empresa.nome_fantasia, v_empresa.razao_social),
    'conta_pagadora', concat_ws(' - ',
      coalesce(v_conta_pagadora.apelido, v_conta_pagadora.banco),
      concat('agencia ', v_conta_pagadora.agencia),
      concat('conta ', v_conta_pagadora.conta)
    ),
    'status', 'pendente',
    'registrado_por', 'Maria',
    'confirmado_por', v_confirmado_por,
    'canal', v_canal,
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_parcelada_criar"("p_descricao" "text", "p_valor_parcela" numeric, "p_valor_total" numeric, "p_quantidade_parcelas" integer, "p_primeira_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_observacoes" "text", "p_periodicidade" "text", "p_confirmar_duplicidade" boolean, "p_debito_automatico" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_parcelamento_renumerar"("p_parcelamento_id" "uuid", "p_parcela_inicial" integer, "p_total_parcelas_real" integer, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_motivo text;
  v_canal text;
  v_count integer;
  v_bad_tipo integer;
  v_canceladas integer;
  v_distinct_plano integer;
  v_distinct_centro integer;
  v_distinct_empresa integer;
  v_distinct_conta integer;
  v_before jsonb;
  v_after jsonb := '[]'::jsonb;
  v_audit_id uuid;
  v_idx integer := 0;
  v_new_parcela integer;
  v_base_desc text;
  v_new_desc text;
  r public.contas_pagar%rowtype;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_parcelamento_id is null then
    raise exception 'parcelamento_id obrigatorio para renumerar parcelas.';
  end if;

  if p_parcela_inicial is null or p_parcela_inicial < 1 then
    raise exception 'parcela_inicial deve ser maior ou igual a 1.';
  end if;

  if p_total_parcelas_real is null or p_total_parcelas_real < p_parcela_inicial then
    raise exception 'total_parcelas_real deve ser maior ou igual a parcela_inicial.';
  end if;

  v_motivo := public.maria_contas_observacao_sanitizada(p_motivo);
  if v_motivo is null then
    raise exception 'motivo obrigatorio para renumerar parcelamento.';
  end if;

  v_canal := coalesce(nullif(trim(p_canal), ''), 'whatsapp');

  perform 1
    from public.contas_pagar
   where parcelamento_id = p_parcelamento_id
   for update;

  select count(*) filter (where status <> 'cancelado'),
         count(*) filter (where coalesce(tipo_lancamento, '') <> 'parcelada' and status <> 'cancelado'),
         count(*) filter (where status = 'cancelado'),
         count(distinct plano_conta_id) filter (where status <> 'cancelado'),
         count(distinct centro_custo_id) filter (where status <> 'cancelado'),
         count(distinct empresa_id) filter (where status <> 'cancelado'),
         count(distinct conta_pagadora_id) filter (where status <> 'cancelado')
    into v_count,
         v_bad_tipo,
         v_canceladas,
         v_distinct_plano,
         v_distinct_centro,
         v_distinct_empresa,
         v_distinct_conta
    from public.contas_pagar
   where parcelamento_id = p_parcelamento_id;

  if v_count = 0 then
    raise exception 'parcelamento nao encontrado.';
  end if;

  if p_parcela_inicial + v_count - 1 > p_total_parcelas_real then
    raise exception 'faixa de parcelas invalida: % linhas a partir da parcela % ultrapassam o total %.',
      v_count, p_parcela_inicial, p_total_parcelas_real;
  end if;

  if v_bad_tipo > 0 then
    raise exception 'parcelamento contem lancamento que nao e do tipo parcelada.';
  end if;

  -- parcela cancelada NAO bloqueia mais (01/09/2026): ela fica fora da serie e o
  -- total ignorado e registrado no audit. O bloqueio antigo transformava qualquer
  -- excedente cancelado em pendencia tecnica eterna (caso Kids CG, aberta em 15/08).

  if v_distinct_plano > 1 or v_distinct_centro > 1 or v_distinct_empresa > 1 or v_distinct_conta > 1 then
    raise exception 'parcelamento contem mistura de plano/centro/empresa/conta pagadora; ajuste tecnico manual necessario.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'descricao', descricao,
           'valor', valor,
           'status', status,
           'data_vencimento', data_vencimento,
           'parcela_atual', parcela_atual,
           'total_parcelas', total_parcelas
         ) order by data_vencimento, created_at, id), '[]'::jsonb)
    into v_before
    from public.contas_pagar
   where parcelamento_id = p_parcelamento_id
     and status <> 'cancelado';

  for r in
    select *
      from public.contas_pagar
     where parcelamento_id = p_parcelamento_id
       and status <> 'cancelado'
     order by data_vencimento, created_at, id
  loop
    v_idx := v_idx + 1;
    v_new_parcela := p_parcela_inicial + v_idx - 1;
    v_base_desc := trim(regexp_replace(r.descricao, '\s*\([0-9]+/[0-9]+\)\s*$', ''));
    v_new_desc := concat(v_base_desc, ' (', v_new_parcela, '/', p_total_parcelas_real, ')');

    update public.contas_pagar
       set descricao = v_new_desc,
           parcela_atual = v_new_parcela,
           total_parcelas = p_total_parcelas_real,
           observacoes = nullif(concat_ws(E'\n',
             nullif(r.observacoes, ''),
             concat(
               'Parcelamento renumerado pela Maria apos confirmacao de ',
               v_actor.nome,
               ' em ',
               to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'),
               ': parcela ',
               v_new_parcela,
               '/',
               p_total_parcelas_real,
               '. Motivo: ',
               v_motivo,
               '.'
             )
           ), ''),
           updated_at = now()
     where id = r.id
     returning * into r;

    v_after := v_after || jsonb_build_array(jsonb_build_object(
      'descricao', r.descricao,
      'valor', r.valor,
      'status', r.status,
      'data_vencimento', r.data_vencimento,
      'parcela_atual', r.parcela_atual,
      'total_parcelas', r.total_parcelas
    ));
  end loop;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal,
    'contas_pagar',
    'parcelamento_conta_pagar',
    p_parcelamento_id,
    'renumerar_parcelamento_conta_pagar',
    v_before,
    jsonb_build_object(
      'parcela_inicial', p_parcela_inicial,
      'total_parcelas_real', p_total_parcelas_real,
      'quantidade_linhas_ajustadas', v_count,
      'canceladas_ignoradas', v_canceladas,
      'parcelas', v_after,
      'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), '')
    ),
    v_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'quantidade_linhas_ajustadas', v_count,
      'canceladas_ignoradas', v_canceladas,
    'primeira_parcela', p_parcela_inicial,
    'ultima_parcela', p_parcela_inicial + v_count - 1,
    'total_parcelas_real', p_total_parcelas_real,
    'parcelas', v_after,
    'motivo', v_motivo,
    'renumerado_por', v_actor.nome,
    'pagamento_executado_pela_maria', false
  );
end;
$_$;


ALTER FUNCTION "public"."maria_contas_parcelamento_renumerar"("p_parcelamento_id" "uuid", "p_parcela_inicial" integer, "p_total_parcelas_real" integer, "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_recorrente_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_fonte_tipo" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_observacoes" "text" DEFAULT NULL::"text", "p_frequencia" "text" DEFAULT 'mensal'::"text", "p_debito_automatico" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_plano public.plano_contas%rowtype;
  v_centro public.centros_custo%rowtype;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_after public.contas_pagar%rowtype;
  v_duplicada public.contas_pagar%rowtype;
  v_audit_id uuid;
  v_confirmado_por_nome text;
  v_canal_origem text;
  v_obs text;
  v_valor_centavos integer;
  v_fonte_tipo text;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_descricao), '') is null then
    raise exception 'descricao obrigatoria para conta recorrente.';
  end if;

  v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor);
  if v_valor_centavos is null or v_valor_centavos <= 0 or v_valor_centavos > 999999999 then
    raise exception 'valor fora da faixa operacional permitida.';
  end if;

  if p_data_vencimento is null then
    raise exception 'data_vencimento obrigatoria para conta recorrente.';
  end if;

  if p_frequencia is null or p_frequencia not in ('mensal','semanal') then
    raise exception 'frequencia invalida (use mensal ou semanal).';
  end if;

  select * into v_plano
    from public.plano_contas
   where id = p_plano_conta_id
     and ativo = true
     and natureza = 'saida'
     and nivel = 3;

  if not found then
    raise exception 'plano_conta_id nao e uma folha de saida ativa.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = p_centro_custo_id
     and ativo = true
     and tipo = 'unidade';

  if not found then
    raise exception 'centro_custo_id nao e uma unidade ativa.';
  end if;

  v_fonte_tipo := lower(nullif(trim(p_fonte_tipo), ''));
  if v_fonte_tipo is not null and v_fonte_tipo not in ('site','email','pix_fixo','banco','whatsapp','manual','cartao') then
    raise exception 'fonte_tipo nao permitido para conta recorrente.';
  end if;

  if p_conta_pagadora_id is not null then
    select * into v_conta_pagadora
      from public.financeiro_contas_bancarias
     where id = p_conta_pagadora_id
       and ativo = true;

    if not found then
      raise exception 'conta_pagadora_id nao encontrada ou inativa.';
    end if;

    select * into v_empresa
      from public.financeiro_empresas
     where id = v_conta_pagadora.empresa_id
       and ativo = true;

    if not found then
      raise exception 'empresa da conta pagadora nao encontrada ou inativa.';
    end if;

    if v_empresa.unidade_id <> p_centro_custo_id then
      raise exception 'centro_custo_id nao corresponde a unidade da conta pagadora.';
    end if;
  end if;

  select * into v_duplicada
    from public.contas_pagar
   where tipo_lancamento = 'recorrente'
     and status <> 'cancelado'
     and lower(trim(descricao)) = lower(trim(p_descricao))
     and centro_custo_id = p_centro_custo_id
     and plano_conta_id = p_plano_conta_id
     and competencia = date_trunc('month', p_data_vencimento)::date
   order by created_at desc
   limit 1;

  if found then
    raise exception 'possivel duplicidade: ja existe conta recorrente semelhante nesta competencia (conta_id=%).', v_duplicada.id;
  end if;

  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal_origem := coalesce(nullif(trim(p_canal), ''), 'whatsapp');
  v_obs := concat_ws(E'\n',
    public.maria_contas_observacao_sanitizada(p_observacoes),
    concat('Conta recorrente criada pela Maria apos confirmacao de ', v_confirmado_por_nome, ' em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '. Status pendente. Sem pagamento real executado pela Maria.'),
    public.maria_contas_observacao_sanitizada(p_motivo)
  );

  insert into public.contas_pagar (
    descricao,
    unidade,
    valor,
    data_lancamento,
    data_vencimento,
    competencia,
    status,
    data_pagamento,
    metodo_pagamento,
    tipo_lancamento,
    recorrente_frequencia,
    parcela_atual,
    total_parcelas,
    observacoes,
    fonte_tipo,
    plano_conta_id,
    centro_custo_id,
    empresa_id,
    conta_pagadora_id, debito_automatico
  ) values (
    trim(p_descricao),
    v_centro.codigo,
    round(p_valor, 2),
    (now() at time zone 'America/Sao_Paulo')::date,
    p_data_vencimento,
    date_trunc('month', p_data_vencimento)::date,
    'pendente',
    null,
    null,
    'recorrente',
    p_frequencia,
    null,
    null,
    nullif(v_obs, ''),
    coalesce(v_fonte_tipo, 'whatsapp'),
    p_plano_conta_id,
    p_centro_custo_id,
    case when p_conta_pagadora_id is null then null else v_conta_pagadora.empresa_id end,
    p_conta_pagadora_id, coalesce(p_debito_automatico, false)
  )
  returning * into v_after;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    v_canal_origem,
    'contas_pagar',
    'conta_pagar',
    v_after.id,
    'criar_conta_pagar_recorrente',
    null,
    to_jsonb(v_after),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'conta', public.maria_conta_pagar_public_json(v_after.id),
    'conta_id', v_after.id,
    'status', v_after.status,
    'tipo_lancamento', 'recorrente',
    'frequencia', p_frequencia,
    'empresa_label', case when p_conta_pagadora_id is null then null else v_empresa.label_operacional end,
    'centro_custo', v_centro.nome,
    'plano', concat_ws(' ', v_plano.codigo, v_plano.nome),
    'valor', v_after.valor,
    'valor_centavos', v_valor_centavos,
    'data_vencimento', v_after.data_vencimento,
    'competencia', v_after.competencia,
    'registrado_por', 'Maria',
    'confirmado_por', v_confirmado_por_nome,
    'canal', v_canal_origem,
    'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), ''),
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_recorrente_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_fonte_tipo" "text", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_observacoes" "text", "p_frequencia" "text", "p_debito_automatico" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_registrar_observacao"("p_conta_id" "uuid", "p_observacoes" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_actor public.maria_whatsapp_atores%rowtype; v_before public.contas_pagar%rowtype; v_after public.contas_pagar%rowtype; v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['finance_ops_write_safe','finance_assistant_write_safe']);
  if p_observacoes is null or length(p_observacoes)>5000 then raise exception 'observacao ausente ou maior que o limite operacional.'; end if;
  select * into v_before from public.contas_pagar where id=p_conta_id for update; if not found then raise exception 'conta_pagar nao encontrada.'; end if;
  update public.contas_pagar set observacoes=p_observacoes, updated_at=now() where id=p_conta_id returning * into v_after;
  v_audit_id := public.maria_audit_insert(v_actor,p_ator_numero,p_canal,'contas_pagar','conta_pagar',p_conta_id,'registrar_observacao',to_jsonb(v_before),to_jsonb(v_after),p_motivo,p_texto_original);
  return jsonb_build_object('success',true,'audit_id',v_audit_id,'conta',public.maria_conta_pagar_public_json(v_after.id));
end; $$;


ALTER FUNCTION "public"."maria_contas_registrar_observacao"("p_conta_id" "uuid", "p_observacoes" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_contas_registrar_observacao"("p_conta_id" "uuid", "p_observacoes" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text") IS 'Maria operational RPC: substitui observacoes de uma conta_pagar, com audit log.';



CREATE OR REPLACE FUNCTION "public"."maria_contas_situacao_mes"("p_ano" integer DEFAULT NULL::integer, "p_mes" integer DEFAULT NULL::integer, "p_unidade" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with ref as (
    select make_date(
             coalesce(p_ano,  extract(year  from (now() at time zone 'America/Sao_Paulo'))::int),
             coalesce(p_mes,  extract(month from (now() at time zone 'America/Sao_Paulo'))::int),
             1) as ini,
           (now() at time zone 'America/Sao_Paulo')::date as hoje
  ),
  base_mes as (
    select c.*, r.hoje
      from public.vw_maria_contas_pagar c cross join ref r
     where (p_unidade is null or c.unidade = p_unidade)
       and (c.competencia between r.ini and (r.ini + interval '1 month - 1 day')::date
            or c.data_vencimento between r.ini and (r.ini + interval '1 month - 1 day')::date
            or c.data_pagamento::date between r.ini and (r.ini + interval '1 month - 1 day')::date)
  ),
  classificada as (
    -- vencida: ESTADO, fora do filtro de mes — toda conta nao paga com vencimento < hoje
    select c.*, r.hoje, 'vencida'::text as situacao
      from public.vw_maria_contas_pagar c cross join ref r
     where (p_unidade is null or c.unidade = p_unidade)
       and c.status = 'pendente'
       and c.data_vencimento < r.hoje
    union all
    select b.*, case
        when b.status = 'cancelado' then 'cancelada'
        when b.status = 'pago'      then 'paga'
        when b.data_vencimento =  b.hoje then 'vence_hoje'
        else 'a_vencer'
      end as situacao
    from base_mes b
    where not (b.status = 'pendente' and b.data_vencimento < b.hoje)
  ),
  itens as (
    select situacao,
           jsonb_agg(jsonb_build_object(
             'descricao', descricao, 'unidade', unidade, 'valor', valor,
             'vencimento', data_vencimento, 'pago_em', data_pagamento::date,
             'metodo', metodo_pagamento, 'debito_automatico', debito_automatico, 'parcela', parcela_atual,
             'total_parcelas', total_parcelas
           ) order by data_vencimento, descricao) as lista,
           count(*)::int as qtd,
           round(sum(valor)::numeric, 2) as total
      from classificada
     group by situacao
  )
  select jsonb_build_object(
    'competencia', to_char((select ini from ref), 'MM/YYYY'),
    'hoje_brt',    (select hoje from ref),
    'unidade',     coalesce(p_unidade, 'todas'),
    'resumo', (
      select coalesce(jsonb_object_agg(situacao,
                jsonb_build_object('quantidade', qtd, 'total', total)), '{}'::jsonb)
        from itens),
    'itens', (
      select coalesce(jsonb_object_agg(situacao, lista), '{}'::jsonb) from itens),
    'aviso', 'VENCIDA aqui e ESTADO: toda conta nao paga com vencimento passado, de '
          || 'QUALQUER mes — nao so do mes consultado. Os demais baldes sao do mes. '
          || 'Isto e pendencia de PAGAMENTO (a conta existe). Para "o dinheiro saiu '
          || 'mas nao ha conta lancada", use maria_fluxo_eventos_sem_superfolha.'
  );
$$;


ALTER FUNCTION "public"."maria_contas_situacao_mes"("p_ano" integer, "p_mes" integer, "p_unidade" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_contas_unica_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_mensagem_origem_id" "text" DEFAULT NULL::"text", "p_observacoes" "text" DEFAULT NULL::"text", "p_fonte_tipo" "text" DEFAULT 'whatsapp'::"text", "p_confirmar_duplicidade" boolean DEFAULT false, "p_debito_automatico" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_plano public.plano_contas%rowtype;
  v_centro public.centros_custo%rowtype;
  v_conta_pagadora public.financeiro_contas_bancarias%rowtype;
  v_empresa public.financeiro_empresas%rowtype;
  v_after public.contas_pagar%rowtype;
  v_duplicada public.contas_pagar%rowtype;
  v_audit_id uuid;
  v_confirmado_por_nome text;
  v_canal_origem text;
  v_obs text;
  v_valor_centavos integer;
  v_fonte_tipo text;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if nullif(trim(p_descricao), '') is null then
    raise exception 'descricao obrigatoria para conta unica.';
  end if;

  v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor);
  if v_valor_centavos is null or v_valor_centavos <= 0 or v_valor_centavos > 999999999 then
    raise exception 'valor fora da faixa operacional permitida.';
  end if;

  if p_data_vencimento is null then
    raise exception 'data_vencimento obrigatoria para conta unica.';
  end if;

  if p_plano_conta_id is null then
    raise exception 'plano_conta_id obrigatorio para conta unica.';
  end if;

  if p_centro_custo_id is null then
    raise exception 'centro_custo_id obrigatorio para conta unica.';
  end if;

  if p_conta_pagadora_id is null then
    raise exception 'conta_pagadora_id obrigatoria para conta unica.';
  end if;

  select * into v_plano
    from public.plano_contas
   where id = p_plano_conta_id
     and ativo = true
     and natureza = 'saida'
     and nivel = 3;
  if not found then
    raise exception 'plano_conta_id nao e uma folha de saida ativa.';
  end if;

  select * into v_centro
    from public.centros_custo
   where id = p_centro_custo_id
     and ativo = true
     and tipo = 'unidade';
  if not found then
    raise exception 'centro_custo_id nao e uma unidade ativa.';
  end if;

  select * into v_conta_pagadora
    from public.financeiro_contas_bancarias
   where id = p_conta_pagadora_id
     and ativo = true;
  if not found then
    raise exception 'conta_pagadora_id nao encontrada ou inativa.';
  end if;

  select * into v_empresa
    from public.financeiro_empresas
   where id = v_conta_pagadora.empresa_id
     and ativo = true;
  if not found then
    raise exception 'empresa da conta pagadora nao encontrada ou inativa.';
  end if;

  if v_empresa.unidade_id <> p_centro_custo_id then
    raise exception 'centro_custo_id nao corresponde a unidade da conta pagadora.';
  end if;

  v_fonte_tipo := lower(nullif(trim(p_fonte_tipo), ''));
  if v_fonte_tipo is not null and v_fonte_tipo not in ('site','email','pix_fixo','banco','whatsapp','manual','cartao') then
    raise exception 'fonte_tipo nao permitido para conta unica.';
  end if;

  select * into v_duplicada
    from public.contas_pagar
   where status <> 'cancelado'
     and lower(trim(descricao)) = lower(trim(p_descricao))
     and centro_custo_id = p_centro_custo_id
     and plano_conta_id = p_plano_conta_id
     and competencia = date_trunc('month', p_data_vencimento)::date
   order by created_at desc
   limit 1;

  if found and not coalesce(p_confirmar_duplicidade, false) then
    raise exception 'possivel duplicidade: ja existe conta semelhante nesta competencia (tipo %, vencimento %, status %). Confirme explicitamente para continuar.',
      v_duplicada.tipo_lancamento,
      to_char(v_duplicada.data_vencimento, 'DD/MM/YYYY'),
      v_duplicada.status;
  end if;

  v_confirmado_por_nome := coalesce(nullif(trim(p_confirmado_por_nome), ''), v_actor.nome);
  v_canal_origem := coalesce(nullif(trim(p_canal), ''), 'whatsapp');
  v_obs := concat_ws(E'\n',
    public.maria_contas_observacao_sanitizada(p_observacoes),
    concat('Conta unica criada pela Maria apos confirmacao de ', v_confirmado_por_nome, ' em ', to_char(now() at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'), '. Status pendente. Sem pagamento real executado pela Maria.'),
    public.maria_contas_observacao_sanitizada(p_motivo)
  );

  insert into public.contas_pagar (
    descricao, unidade, valor, data_lancamento, data_vencimento, competencia,
    status, data_pagamento, metodo_pagamento, tipo_lancamento, parcela_atual, total_parcelas,
    observacoes, fonte_tipo, plano_conta_id, centro_custo_id, empresa_id, conta_pagadora_id, debito_automatico
  ) values (
    trim(p_descricao), v_centro.codigo, round(p_valor, 2), (now() at time zone 'America/Sao_Paulo')::date,
    p_data_vencimento, date_trunc('month', p_data_vencimento)::date,
    'pendente', null, null, 'unica', null, null,
    nullif(v_obs, ''), coalesce(v_fonte_tipo, 'whatsapp'), p_plano_conta_id, p_centro_custo_id,
    v_conta_pagadora.empresa_id, p_conta_pagadora_id, coalesce(p_debito_automatico, false)
  ) returning * into v_after;

  v_audit_id := public.maria_audit_insert(
    v_actor, p_ator_numero, v_canal_origem,
    'contas_pagar', 'conta_pagar', v_after.id,
    'criar_conta_pagar_unica',
    null, to_jsonb(v_after), p_motivo, p_texto_original
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'audit_id', v_audit_id,
    'conta', public.maria_conta_pagar_public_json(v_after.id),
    'conta_id', v_after.id,
    'status', v_after.status,
    'tipo_lancamento', 'unica',
    'empresa_label', v_empresa.label_operacional,
    'centro_custo', v_centro.nome,
    'plano', concat_ws(' ', v_plano.codigo, v_plano.nome),
    'valor', v_after.valor,
    'valor_centavos', v_valor_centavos,
    'data_vencimento', v_after.data_vencimento,
    'competencia', v_after.competencia,
    'registrado_por', 'Maria',
    'confirmado_por', v_confirmado_por_nome,
    'canal', v_canal_origem,
    'mensagem_origem_id', nullif(trim(p_mensagem_origem_id), ''),
    'pagamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_contas_unica_criar"("p_descricao" "text", "p_valor" numeric, "p_data_vencimento" "date", "p_plano_conta_id" "uuid", "p_centro_custo_id" "uuid", "p_conta_pagadora_id" "uuid", "p_confirmado_por_nome" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text", "p_texto_original" "text", "p_motivo" "text", "p_mensagem_origem_id" "text", "p_observacoes" "text", "p_fonte_tipo" "text", "p_confirmar_duplicidade" boolean, "p_debito_automatico" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_corretor_aplicar_regra"("p_palavra_chave" "text", "p_plano_conta_id" "uuid", "p_unidade" "text", "p_prioridade" integer, "p_confianca" numeric, "p_observacao" "text" DEFAULT NULL::"text", "p_supersedes" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  if exists (select 1 from maria_classificacao_regras
             where palavra_chave=p_palavra_chave and plano_conta_id=p_plano_conta_id
               and coalesce(unidade,'')=coalesce(p_unidade,'') and ativo) then
    return 'idempotente';
  end if;
  if p_supersedes is not null then
    update maria_classificacao_regras set ativo=false, updated_at=now() where id=p_supersedes and ativo;
  end if;
  insert into maria_classificacao_regras(palavra_chave, plano_conta_id, unidade, escopo, prioridade,
      confianca_base, ativo, origem, aprovado_por, aprovado_em, supersedes, observacao)
    values (p_palavra_chave, p_plano_conta_id, p_unidade, 'geral', p_prioridade,
      p_confianca, true, 'corretor-v1', 'corretor-v1', now(), p_supersedes, p_observacao)
    returning id into v_id;
  return 'aplicada';
end $$;


ALTER FUNCTION "public"."maria_corretor_aplicar_regra"("p_palavra_chave" "text", "p_plano_conta_id" "uuid", "p_unidade" "text", "p_prioridade" integer, "p_confianca" numeric, "p_observacao" "text", "p_supersedes" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_corretor_corpus_humano"() RETURNS TABLE("descricao" "text", "plano_codigo" "text", "unidade" "text", "item_id" "uuid", "conferencia_id" "uuid", "criado_em" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with vigente as (
    select c.id
    from maria_conferencias_lancamento c
    where c.status <> 'cancelada'
      and not exists (
        select 1 from maria_conferencias_lancamento c2
        where c2.parent_conferencia_id = c.id and c2.status <> 'cancelada'
      )
  )
  select i.descricao, i.plano_codigo, i.unidade, i.id, i.conferencia_id, i.created_at
  from maria_conferencia_lancamento_itens i
  join vigente v on v.id = i.conferencia_id
  where i.plano_origem = 'humano' and i.plano_codigo is not null;
$$;


ALTER FUNCTION "public"."maria_corretor_corpus_humano"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_corretor_desativar_regra"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  update public.maria_classificacao_regras
     set ativo = false, updated_at = now()
   where id = p_id
  returning id;
$$;


