CREATE OR REPLACE FUNCTION "public"."maria_email_nome_fornecedor_limpo"("p_nome" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  with base as (select coalesce(trim(p_nome), '') as s),
  -- rotulo colado ANTES do nome: remove o rotulo e preserva o que vem depois
  semrotulo1 as (
    select btrim(regexp_replace(s,
      '^\s*(?:ag[eê]ncia\s*/?\s*c[oó]digo\s+benefici[áa]rio|c[oó]digo\s+benefici[áa]rio|vencimento|benefici[áa]rio'
      '|cedente|sacado|pagador|fornecedor|favorecido|emitente)\s*[:\-–—]?\s+', '', 'i'), ' -–—|:;,]/()') as s from base),
  -- o nome termina onde o formulario do boleto comeca (sem \b: no Postgres e \y, e aqui nem precisa)
  corta as (
    select regexp_replace(s,
      '\s*(?:c[oó]digo\s+de\s+baixa|valor\s+do\s+documento|valor\s+documento|valor\s+cobrado|outras\s+dedu'
      '|mora\s*/?\s*multa|juros|desconto|abat\.|n\.?\s*doc|nosso\s+n[uú]mero|ag[eê]ncia\s*/?\s*c[oó]digo'
      '|carteira|esp[eé]cie|aceite|data\s+do\s+documento|uso\s+do\s+banco|instru[çc][õo]es|institui[cç][aãÃ]o'
      '|com\s+pix|cnpj\s*:|cpf\s*:|motivos\s+de).*$', '', 'i') as s from semrotulo1),
  semdoc as (
    select btrim(regexp_replace(regexp_replace(regexp_replace(s,
      '\(?\s*(?:\d{3}\.\d{3}\.\d{3}-\d{2}|\d{2}\.\d{3}\.\d{3}/\d{4}-\d{2}|\d{11,14})\s*\)?', ' ', 'g'),
      '\[(?:cpf|cnpj|telefone)\]', ' ', 'gi'),
      '^\s*\d{2}\.\d{3}\.\d{3}\s+', ''), ' -–—|:;,]/()') as s from corta)
  select case
    when s = '' then null
    when s !~ '^[A-Za-zÀ-ÿ]' or s !~ '[A-Za-zÀ-ÿ]{2,}' then null
    when lower(regexp_replace(s, '\s+', ' ', 'g')) in ('cpf','cnpj','cpf/cnpj','beneficiario','pagador','sacado','fornecedor') then null
    else left(regexp_replace(s, '\s+', ' ', 'g'), 90)
  end from semdoc;
$_$;


ALTER FUNCTION "public"."maria_email_nome_fornecedor_limpo"("p_nome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_payable_atualizar_classificacao"("p_ator_numero" "text", "p_papel" "text", "p_payable_id" "uuid", "p_centro_custo_id" "uuid" DEFAULT NULL::"uuid", "p_plano_conta_id" "uuid" DEFAULT NULL::"uuid", "p_empresa_id" "uuid" DEFAULT NULL::"uuid", "p_unidade_snapshot" "text" DEFAULT NULL::"text", "p_plano_snapshot" "text" DEFAULT NULL::"text", "p_confidence" numeric DEFAULT NULL::numeric, "p_motivo" "text" DEFAULT NULL::"text", "p_texto_original" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.maria_email_extracted_payables%rowtype;
  v_after public.maria_email_extracted_payables%rowtype;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);

  select * into v_before from public.maria_email_extracted_payables where id = p_payable_id for update;
  if not found then
    raise exception 'payable nao encontrado' using errcode = '22023';
  end if;

  if (p_centro_custo_id is not null and p_centro_custo_id is distinct from v_before.centro_custo_id)
     or (p_empresa_id is not null and p_empresa_id is distinct from v_before.empresa_id)
     or (nullif(trim(p_unidade_snapshot), '') is not null and nullif(trim(p_unidade_snapshot), '') is distinct from v_before.unidade_snapshot) then
    raise exception 'MARIA_EMAIL_DEDUPE_VERSIONAR: centro_custo, empresa ou unidade podem alterar a base de dedupe; crie novo payable e marque o anterior como substituido'
      using errcode = '42501';
  end if;

  perform set_config('app.maria_email_rpc', 'on', true);
  update public.maria_email_extracted_payables
     set plano_conta_id = coalesce(p_plano_conta_id, plano_conta_id),
         plano_snapshot = coalesce(nullif(trim(p_plano_snapshot), ''), plano_snapshot),
         confidence = coalesce(p_confidence, confidence),
         review_reason = coalesce(nullif(trim(p_motivo), ''), review_reason)
   where id = p_payable_id
   returning * into v_after;

  perform public.maria_audit_insert(
    v_actor, p_ator_numero, 'whatsapp', 'maria_email_extracted_payables', 'maria_email_payable',
    p_payable_id, 'atualizar_classificacao_email', to_jsonb(v_before), to_jsonb(v_after), p_motivo, p_texto_original
  );

  return jsonb_build_object('success', true, 'payable_id', p_payable_id);
end;
$$;


ALTER FUNCTION "public"."maria_email_payable_atualizar_classificacao"("p_ator_numero" "text", "p_papel" "text", "p_payable_id" "uuid", "p_centro_custo_id" "uuid", "p_plano_conta_id" "uuid", "p_empresa_id" "uuid", "p_unidade_snapshot" "text", "p_plano_snapshot" "text", "p_confidence" numeric, "p_motivo" "text", "p_texto_original" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_payable_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rpc boolean := public.maria_email_is_rpc();
  v_redaction boolean := public.maria_email_is_redaction();
begin
  if tg_op = 'DELETE' then
    raise exception 'MARIA_EMAIL_IMUTAVEL: payable nunca pode ser apagado' using errcode = '42501';
  end if;

  if v_rpc and v_redaction then
    raise exception 'MARIA_EMAIL_FLAG_INVALIDA: operacao e redacao nao podem compartilhar a mesma transacao' using errcode = '42501';
  end if;

  if not (v_rpc or v_redaction) then
    raise exception 'MARIA_EMAIL_ESCRITA_DIRETA: use as RPCs autorizadas' using errcode = '42501';
  end if;

  if v_rpc then
    if (to_jsonb(new) - array[
          'status','review_reason','plano_conta_id','plano_snapshot','confidence','supersedes_payable_id','updated_at'
        ])
       is distinct from
       (to_jsonb(old) - array[
          'status','review_reason','plano_conta_id','plano_snapshot','confidence','supersedes_payable_id','updated_at'
        ]) then
      raise exception 'MARIA_EMAIL_IMUTAVEL: fato financeiro/dedupe nao pode mudar pela trilha operacional' using errcode = '42501';
    end if;
  end if;

  if v_redaction then
    if (to_jsonb(new) - array['fornecedor_nome','payer_name_masked','payer_name_hash','raw_extraction_sanitized','person_data_redaction_status','updated_at'])
       is distinct from
       (to_jsonb(old) - array['fornecedor_nome','payer_name_masked','payer_name_hash','raw_extraction_sanitized','person_data_redaction_status','updated_at']) then
      raise exception 'MARIA_EMAIL_REDACAO_ESCOPO: expurgo so toca campos pessoais do payable' using errcode = '42501';
    end if;

    if new.person_data_redaction_status not in ('mascarado','expurgado','nao_aplicavel') then
      raise exception 'MARIA_EMAIL_REDACAO_ESCOPO: status de redacao invalido' using errcode = '42501';
    end if;

    if new.person_data_redaction_status = 'expurgado'
       and (new.fornecedor_nome is not null or new.payer_name_masked is not null or new.payer_name_hash is not null or new.raw_extraction_sanitized is not null) then
      raise exception 'MARIA_EMAIL_REDACAO_INCOMPLETA: expurgo deve anular campos pessoais do payable' using errcode = '42501';
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."maria_email_payable_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_payable_marcar_status"("p_ator_numero" "text", "p_papel" "text", "p_payable_id" "uuid", "p_status" "text", "p_review_reason" "text" DEFAULT NULL::"text", "p_motivo" "text" DEFAULT NULL::"text", "p_texto_original" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_before public.maria_email_extracted_payables%rowtype;
  v_after public.maria_email_extracted_payables%rowtype;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);

  if p_status not in ('pendente_conferencia','ignorado','vinculado','divergente','substituido') then
    raise exception 'status nao autorizado por esta RPC' using errcode = '22023';
  end if;

  select * into v_before from public.maria_email_extracted_payables where id = p_payable_id for update;
  if not found then
    raise exception 'payable nao encontrado' using errcode = '22023';
  end if;

  perform set_config('app.maria_email_rpc', 'on', true);
  update public.maria_email_extracted_payables
     set status = p_status,
         review_reason = coalesce(nullif(trim(p_review_reason), ''), review_reason)
   where id = p_payable_id
   returning * into v_after;

  perform public.maria_audit_insert(
    v_actor, p_ator_numero, 'whatsapp', 'maria_email_extracted_payables', 'maria_email_payable',
    p_payable_id, 'marcar_status_email', to_jsonb(v_before), to_jsonb(v_after), p_motivo, p_texto_original
  );

  return jsonb_build_object('success', true, 'payable_id', p_payable_id, 'status', v_after.status);
end;
$$;


ALTER FUNCTION "public"."maria_email_payable_marcar_status"("p_ator_numero" "text", "p_papel" "text", "p_payable_id" "uuid", "p_status" "text", "p_review_reason" "text", "p_motivo" "text", "p_texto_original" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_payable_registrar"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_message public.maria_email_messages%rowtype;
  v_id uuid;
  v_run_id uuid := nullif(p_payload->>'processing_run_id', '')::uuid;
  v_dedupe_key text := public.maria_email_payload_text(p_payload, 'dedupe_group_key', 240);
  v_payer_hash text := public.maria_email_payload_text(p_payload, 'payer_name_hash', 80);
  v_fornecedor_hash text := public.maria_email_payload_text(p_payload, 'fornecedor_documento_hash', 80);
  v_barcode_hash text := public.maria_email_payload_text(p_payload, 'barcode_hash', 80);
  v_pix_hash text := public.maria_email_payload_text(p_payload, 'pix_payload_hash', 80);
  v_link_hash text := public.maria_email_payload_text(p_payload, 'payment_link_hash', 80);
  v_redaction_status text;
begin
  if nullif(p_payload->>'message_id', '') is null or v_dedupe_key is null then
    raise exception 'message_id e dedupe_group_key sao obrigatorios' using errcode = '22023';
  end if;

  perform public.maria_email_assert_hmac_hex(v_payer_hash, 'payer_name_hash');
  perform public.maria_email_assert_hmac_hex(v_fornecedor_hash, 'fornecedor_documento_hash');
  perform public.maria_email_assert_hmac_hex(v_barcode_hash, 'barcode_hash');
  perform public.maria_email_assert_hmac_hex(v_pix_hash, 'pix_payload_hash');
  perform public.maria_email_assert_hmac_hex(v_link_hash, 'payment_link_hash');

  select * into v_message from public.maria_email_messages where id = (p_payload->>'message_id')::uuid;
  if not found then
    raise exception 'mensagem nao encontrada' using errcode = '22023';
  end if;

  if v_run_id is null then
    v_run_id := v_message.processing_run_id;
  end if;

  if v_run_id is not null and not exists (
    select 1 from public.maria_email_processing_runs where id = v_run_id and source_id = v_message.source_id
  ) then
    raise exception 'processing_run_id nao pertence a fonte da mensagem' using errcode = '22023';
  end if;

  v_redaction_status := coalesce(public.maria_email_payload_text(p_payload, 'person_data_redaction_status', 40),
    case when public.maria_email_payload_text(p_payload, 'payer_name_masked', 180) is null and v_payer_hash is null
         then 'nao_aplicavel' else 'pendente' end);

  insert into public.maria_email_extracted_payables (
    message_id, processing_run_id, financeiro_documento_id, document_kind, fornecedor_nome, fornecedor_documento_hash,
    hash_version, payer_name_masked, payer_name_hash, document_number, competencia, emissao, vencimento,
    valor_centavos, moeda, centro_custo_id, unidade_snapshot, plano_conta_id, plano_snapshot, empresa_id,
    extraction_method, confidence, status, review_reason, barcode_hash, pix_payload_hash, payment_link_domain,
    payment_link_hash, dedupe_group_key, dedupe_group_quality, supersedes_payable_id,
    person_data_redaction_status, raw_extraction_sanitized
  ) values (
    v_message.id,
    v_run_id,
    nullif(p_payload->>'financeiro_documento_id', '')::uuid,
    coalesce(public.maria_email_payload_text(p_payload, 'document_kind', 30), 'outro'),
    public.maria_email_payload_text(p_payload, 'fornecedor_nome', 180),
    v_fornecedor_hash,
    'hmac-sha256-v1',
    public.maria_email_payload_text(p_payload, 'payer_name_masked', 180),
    v_payer_hash,
    public.maria_email_payload_text(p_payload, 'document_number', 120),
    nullif(p_payload->>'competencia', '')::date,
    nullif(p_payload->>'emissao', '')::date,
    nullif(p_payload->>'vencimento', '')::date,
    nullif(p_payload->>'valor_centavos', '')::integer,
    coalesce(public.maria_email_payload_text(p_payload, 'moeda', 3), 'BRL'),
    nullif(p_payload->>'centro_custo_id', '')::uuid,
    public.maria_email_payload_text(p_payload, 'unidade_snapshot', 80),
    nullif(p_payload->>'plano_conta_id', '')::uuid,
    public.maria_email_payload_text(p_payload, 'plano_snapshot', 160),
    nullif(p_payload->>'empresa_id', '')::uuid,
    coalesce(public.maria_email_payload_text(p_payload, 'extraction_method', 30), 'body'),
    coalesce(nullif(p_payload->>'confidence', '')::numeric, 0),
    coalesce(public.maria_email_payload_text(p_payload, 'status', 40), 'extraido'),
    public.maria_email_payload_text(p_payload, 'review_reason', 240),
    v_barcode_hash,
    v_pix_hash,
    lower(public.maria_email_payload_text(p_payload, 'payment_link_domain', 180)),
    v_link_hash,
    v_dedupe_key,
    coalesce(public.maria_email_payload_text(p_payload, 'dedupe_group_quality', 20), 'fraca'),
    nullif(p_payload->>'supersedes_payable_id', '')::uuid,
    v_redaction_status,
    case when p_payload ? 'raw_extraction_sanitized' then p_payload->'raw_extraction_sanitized' else null end
  ) returning id into v_id;

  return jsonb_build_object('success', true, 'payable_id', v_id);
end;
$$;


ALTER FUNCTION "public"."maria_email_payable_registrar"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_payable_versionar"("p_ator_numero" "text", "p_papel" "text", "p_payable_antigo_id" "uuid", "p_payload_novo" "jsonb", "p_motivo" "text" DEFAULT NULL::"text", "p_texto_original" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_old public.maria_email_extracted_payables%rowtype;
  v_old_after public.maria_email_extracted_payables%rowtype;
  v_new_payload jsonb;
  v_new_id uuid;
  v_new public.maria_email_extracted_payables%rowtype;
  v_result jsonb;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array['owner_full','finance_ops_write_safe','finance_assistant_write_safe']);

  if p_payable_antigo_id is null then
    raise exception 'p_payable_antigo_id obrigatorio' using errcode = '22023';
  end if;

  if coalesce(jsonb_typeof(p_payload_novo), '') <> 'object' then
    raise exception 'p_payload_novo deve ser objeto jsonb' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtext('maria_email_payable_versionar'), hashtext(p_payable_antigo_id::text));

  select * into v_old
    from public.maria_email_extracted_payables
   where id = p_payable_antigo_id
   for update;

  if not found then
    raise exception 'payable antigo nao encontrado' using errcode = '22023';
  end if;

  if v_old.status = 'substituido' then
    raise exception 'payable antigo ja esta substituido' using errcode = '22023';
  end if;

  if not (p_payload_novo ? 'dedupe_group_key') then
    raise exception 'versionamento exige dedupe_group_key recalculada no runtime' using errcode = '22023';
  end if;

  if not (p_payload_novo ? 'dedupe_group_quality') then
    raise exception 'versionamento exige dedupe_group_quality recalculada no runtime' using errcode = '22023';
  end if;

  if public.maria_email_payload_text(p_payload_novo, 'dedupe_group_quality', 20) not in ('forte', 'media', 'fraca') then
    raise exception 'dedupe_group_quality invalida no versionamento' using errcode = '22023';
  end if;

  v_new_payload := jsonb_build_object(
    'message_id', v_old.message_id,
    'processing_run_id', v_old.processing_run_id,
    'financeiro_documento_id', v_old.financeiro_documento_id,
    'document_kind', v_old.document_kind,
    'fornecedor_nome', v_old.fornecedor_nome,
    'fornecedor_documento_hash', v_old.fornecedor_documento_hash,
    'payer_name_masked', v_old.payer_name_masked,
    'payer_name_hash', v_old.payer_name_hash,
    'document_number', v_old.document_number,
    'competencia', v_old.competencia,
    'emissao', v_old.emissao,
    'vencimento', v_old.vencimento,
    'valor_centavos', v_old.valor_centavos,
    'moeda', v_old.moeda,
    'centro_custo_id', v_old.centro_custo_id,
    'unidade_snapshot', v_old.unidade_snapshot,
    'plano_conta_id', v_old.plano_conta_id,
    'plano_snapshot', v_old.plano_snapshot,
    'empresa_id', v_old.empresa_id,
    'extraction_method', v_old.extraction_method,
    'confidence', v_old.confidence,
    'status', 'pendente_conferencia',
    'review_reason', coalesce(nullif(trim(p_motivo), ''), 'versionamento_payable'),
    'barcode_hash', v_old.barcode_hash,
    'pix_payload_hash', v_old.pix_payload_hash,
    'payment_link_domain', v_old.payment_link_domain,
    'payment_link_hash', v_old.payment_link_hash,
    'dedupe_group_key', v_old.dedupe_group_key,
    'dedupe_group_quality', v_old.dedupe_group_quality,
    'supersedes_payable_id', v_old.id,
    'person_data_redaction_status', v_old.person_data_redaction_status,
    'raw_extraction_sanitized', v_old.raw_extraction_sanitized
  ) || p_payload_novo || jsonb_build_object(
    'message_id', v_old.message_id,
    'processing_run_id', v_old.processing_run_id,
    'status', 'pendente_conferencia',
    'supersedes_payable_id', v_old.id
  );

  perform set_config('app.maria_email_rpc', 'on', true);

  update public.maria_email_extracted_payables
     set status = 'substituido',
         review_reason = coalesce(nullif(trim(p_motivo), ''), review_reason)
   where id = v_old.id
   returning * into v_old_after;

  perform set_config('app.maria_email_rpc', '', true);

  v_result := public.maria_email_payable_registrar(v_new_payload);
  v_new_id := (v_result->>'payable_id')::uuid;

  select * into v_new
    from public.maria_email_extracted_payables
   where id = v_new_id;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    'whatsapp',
    'maria_email_extracted_payables',
    'maria_email_payable',
    v_old.id,
    'versionar_payable_email',
    to_jsonb(v_old),
    jsonb_build_object('antigo', to_jsonb(v_old_after), 'novo', to_jsonb(v_new)),
    p_motivo,
    p_texto_original
  );

  return jsonb_build_object(
    'success', true,
    'payable_antigo_id', v_old.id,
    'payable_novo_id', v_new.id,
    'status_antigo', v_old_after.status,
    'dedupe_group_key_novo', v_new.dedupe_group_key,
    'dedupe_group_quality_novo', v_new.dedupe_group_quality
  );
end;
$$;


ALTER FUNCTION "public"."maria_email_payable_versionar"("p_ator_numero" "text", "p_papel" "text", "p_payable_antigo_id" "uuid", "p_payload_novo" "jsonb", "p_motivo" "text", "p_texto_original" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_email_payable_versionar"("p_ator_numero" "text", "p_papel" "text", "p_payable_antigo_id" "uuid", "p_payload_novo" "jsonb", "p_motivo" "text", "p_texto_original" "text") IS 'Versiona um payable do Maria Email Ledger em uma transacao: substitui o antigo e cria o novo com supersedes_payable_id, auditado via Maria.';



CREATE OR REPLACE FUNCTION "public"."maria_email_payload_text"("p_payload" "jsonb", "p_key" "text", "p_max" integer DEFAULT 500) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v text;
begin
  v := nullif(trim(coalesce(p_payload->>p_key, '')), '');
  if v is null then
    return null;
  end if;
  return left(v, greatest(1, p_max));
end;
$$;


ALTER FUNCTION "public"."maria_email_payload_text"("p_payload" "jsonb", "p_key" "text", "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_pendencias_operacionais"("p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source_key text := nullif(public.maria_email_payload_text(coalesce(p_payload, '{}'::jsonb), 'source_key', 80), '');
  v_days integer := least(greatest(coalesce(nullif(p_payload->>'days', '')::integer, 30), 1), 365);
  v_limit integer := least(greatest(coalesce(nullif(p_payload->>'limit', '')::integer, 12), 1), 80);
  v_mode text := coalesce(nullif(public.maria_email_payload_text(coalesce(p_payload, '{}'::jsonb), 'mode', 40), ''), 'unlaunched');
  v_items jsonb;
begin
  with base as (
    select
      p.email_payable_id,
      p.message_id,
      p.source_key,
      p.received_at,
      p.fornecedor_nome,
      p.document_kind,
      p.vencimento,
      p.valor_centavos,
      p.status,
      p.review_reason,
      p.dedupe_group_key,
      p.dedupe_group_quality,
      p.melhor_match_score,
      p.prioridade_conferencia,
      m.subject,
      m.from_name,
      e.extraction_method,
      e.unidade_snapshot,
      e.plano_snapshot,
      (e.barcode_hash is not null) as email_has_barcode,
      (e.pix_payload_hash is not null) as email_has_pix,
      e.payment_link_domain,
      public.maria_email_match_text_norm(concat_ws(' ', p.fornecedor_nome, m.subject, e.unidade_snapshot, e.plano_snapshot)) as search_text,
      public.maria_email_match_text_norm(concat_ws(' ', p.fornecedor_nome, m.subject)) as supplier_subject_norm
    from public.vw_maria_email_pendencias p
    left join public.maria_email_messages m on m.id = p.message_id
    left join public.maria_email_extracted_payables e on e.id = p.email_payable_id
    where p.received_at >= now() - make_interval(days => v_days)
      and (v_source_key is null or p.source_key = v_source_key)
      and not (public.maria_email_match_text_norm(coalesce(m.subject, '')) like any (array['%mercado pago%','%cartao de credito%','%cartão de crédito%','%cart%cr%dito%','%busca de pagamento%']))
      and (
        e.barcode_hash is not null
        or e.pix_payload_hash is not null
        or (
          p.valor_centavos is not null
          and p.valor_centavos >= 1000
          and p.document_kind in ('boleto', 'link_cobranca')
        )
      )
  ), with_match as (
    select
      b.*,
      mt.id as match_id,
      mt.match_status,
      mt.match_score,
      mt.match_reason,
      mt.conta_pagar_id as matched_conta_pagar_id
    from base b
    left join lateral (
      select mt.*
      from public.maria_email_payable_matches mt
      where mt.email_payable_id = b.email_payable_id
        and mt.match_status in ('confirmado_humano', 'sugerido')
      order by case mt.match_status when 'confirmado_humano' then 0 else 1 end,
               mt.match_score desc,
               mt.created_at desc
      limit 1
    ) mt on true
  ), with_account as (
    select
      wm.*,
      c.id as conta_pagar_id,
      c.descricao as conta_descricao,
      c.unidade as conta_unidade,
      c.status as conta_status,
      c.data_pagamento as conta_data_pagamento,
      round((c.valor * 100)::numeric)::integer as conta_valor_centavos,
      c.data_vencimento as conta_vencimento,
      case
        when wm.matched_conta_pagar_id is not null and c.id = wm.matched_conta_pagar_id then 'match_formal'
        when c.id is not null then 'conta_provavel'
        else null
      end as conta_match_kind
    from with_match wm
    left join lateral (
      select c.*
      from public.contas_pagar c
      where
        (wm.matched_conta_pagar_id is not null and c.id = wm.matched_conta_pagar_id)
        or (
          wm.valor_centavos is not null
          and round((c.valor * 100)::numeric)::integer = wm.valor_centavos
          and (
            (wm.vencimento is not null and c.data_vencimento = wm.vencimento)
            or (
              wm.vencimento is null
              and c.data_vencimento between (wm.received_at::date - interval '45 days') and (wm.received_at::date + interval '45 days')
              and (
                (wm.supplier_subject_norm like '%erbe%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%erbe%','%condominio%','%aluguel%','%iptu%']))
                or (wm.supplier_subject_norm like '%pjbank%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%pjbank%','%pj bank%','%superlogica%','%parcelamento%']))
                or (wm.supplier_subject_norm like '%emusys%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like '%emusys%')
                or ((wm.supplier_subject_norm like '%citta%' or wm.supplier_subject_norm like '%citt%') and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%citta%','%citt%']))
                or (wm.supplier_subject_norm like '%claro%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like '%claro%')
                or (wm.supplier_subject_norm like '%light%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like '%light%')
                or (wm.supplier_subject_norm like '%vertix%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like '%vertix%')
                or (wm.supplier_subject_norm like '%music leads%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%music leads%','%marketing%','%trafego%']))
                or (wm.supplier_subject_norm like '%mercado pago%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%mercado pago%','%cartao%','%cartão%']))
                or (wm.supplier_subject_norm like '%clube unir%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like '%clube unir%')
                or (wm.supplier_subject_norm like '%lucas pereira%' and public.maria_email_match_text_norm(concat_ws(' ', c.descricao, c.observacoes)) like any (array['%lucas pereira%','%wpp escolas%','%sistema de comunicacao%','%sistema de comunicação%']))
              )
            )
          )
        )
      order by
        case when wm.matched_conta_pagar_id is not null and c.id = wm.matched_conta_pagar_id then 0 else 1 end,
        case when wm.vencimento is not null and c.data_vencimento = wm.vencimento then 0 else 1 end,
        case when c.status = 'pago' or c.data_pagamento is not null then 0 else 1 end,
        c.data_vencimento desc,
        c.created_at desc
      limit 1
    ) c on true
  ), with_code as (
    select
      wa.*,
      cm.status_coleta,
      cm.valor_coletado,
      cm.coletado_em,
      (cm.codigo_barras is not null and length(cm.codigo_barras) > 0) as superfolha_has_barcode,
      (cm.chave_pix is not null and length(cm.chave_pix) > 0) as superfolha_has_pix_key,
      (cm.qr_pix_payload is not null and length(cm.qr_pix_payload) > 0) as superfolha_has_qr_pix
    from with_account wa
    left join lateral (
      select cm.*
      from public.contas_pagar_codigo_mes cm
      where cm.conta_pagar_id = wa.conta_pagar_id
      order by cm.coletado_em desc nulls last, cm.updated_at desc
      limit 1
    ) cm on true
  ), actionable as (
    select wc.*
    from with_code wc
    where (
      (v_mode = 'launched' and wc.conta_pagar_id is not null)
      or (
        v_mode <> 'launched'
        and wc.conta_pagar_id is null
        and not exists (
          select 1
          from with_code sib
          where sib.message_id = wc.message_id
            and sib.conta_pagar_id is not null
            and (
              (wc.supplier_subject_norm like '%vertix%' and sib.supplier_subject_norm like '%vertix%')
              or (wc.supplier_subject_norm like '%valorcafe%' and sib.supplier_subject_norm like '%valorcafe%')
              or (wc.supplier_subject_norm like '%emusys%' and sib.supplier_subject_norm like '%emusys%')
              or ((wc.supplier_subject_norm like '%citta%' or wc.supplier_subject_norm like '%citt%') and (sib.supplier_subject_norm like '%citta%' or sib.supplier_subject_norm like '%citt%'))
              or (wc.supplier_subject_norm like '%claro%' and sib.supplier_subject_norm like '%claro%')
              or (wc.supplier_subject_norm like '%light%' and sib.supplier_subject_norm like '%light%')
              or (wc.supplier_subject_norm like '%pjbank%' and sib.supplier_subject_norm like '%pjbank%')
              or (wc.supplier_subject_norm like '%music leads%' and sib.supplier_subject_norm like '%music leads%')
            )
        )
      )
    )
  ), limited as (
    select *
    from actionable
    order by prioridade_conferencia desc, received_at desc
    limit v_limit
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'email_payable_id', email_payable_id,
    'message_id', message_id,
    'source_key', source_key,
    'received_at', received_at,
    'fornecedor_nome', fornecedor_nome,
    'subject', subject,
    'from_name', from_name,
    'document_kind', document_kind,
    'vencimento', vencimento,
    'valor_centavos', valor_centavos,
    'status', status,
    'review_reason', review_reason,
    'dedupe_group_key', dedupe_group_key,
    'dedupe_group_quality', dedupe_group_quality,
    'melhor_match_score', melhor_match_score,
    'prioridade_conferencia', prioridade_conferencia,
    'extraction_method', extraction_method,
    'unidade_snapshot', unidade_snapshot,
    'plano_snapshot', plano_snapshot,
    'email_has_barcode', email_has_barcode,
    'email_has_pix', email_has_pix,
    'email_has_code', coalesce(email_has_barcode, false) or coalesce(email_has_pix, false),
    'payment_link_domain', payment_link_domain,
    'match_status', match_status,
    'match_score', match_score,
    'match_reason', match_reason,
    'conta_pagar_id', conta_pagar_id,
    'conta_match_kind', conta_match_kind,
    'conta_descricao', conta_descricao,
    'conta_unidade', conta_unidade,
    'conta_status', conta_status,
    'conta_data_pagamento', conta_data_pagamento,
    'conta_valor_centavos', conta_valor_centavos,
    'conta_vencimento', conta_vencimento,
    'status_coleta', status_coleta,
    'valor_coletado', case when valor_coletado is null then null else round((valor_coletado * 100)::numeric)::integer end,
    'coletado_em', coletado_em,
    'superfolha_has_barcode', superfolha_has_barcode,
    'superfolha_has_pix_key', superfolha_has_pix_key,
    'superfolha_has_qr_pix', superfolha_has_qr_pix
  ) order by prioridade_conferencia desc, received_at desc), '[]'::jsonb)
  into v_items
  from limited;

  return jsonb_build_object(
    'success', true,
    'source', 'email_unlaunched_ledger',
    'source_key', coalesce(v_source_key, ''),
    'days', v_days,
    'count', jsonb_array_length(v_items),
    'mode', v_mode,
    'items', v_items
  );
end;
$$;


ALTER FUNCTION "public"."maria_email_pendencias_operacionais"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_processing_run_finish"("p_run_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_run public.maria_email_processing_runs%rowtype;
  v_status text := coalesce(public.maria_email_payload_text(p_payload, 'status', 20), 'success');
  v_uidvalidity_after bigint := nullif(p_payload->>'uidvalidity_after', '')::bigint;
  v_uidnext bigint := nullif(p_payload->>'uidnext_observed', '')::bigint;
begin
  select * into v_run from public.maria_email_processing_runs where id = p_run_id for update;
  if not found then
    raise exception 'run nao encontrado' using errcode = '22023';
  end if;

  perform set_config('app.maria_email_rpc', 'on', true);

  update public.maria_email_processing_runs
     set status = v_status,
         finished_at = now(),
         uidvalidity_after = v_uidvalidity_after,
         uidvalidity_changed = coalesce(v_uidvalidity_after is distinct from v_run.uidvalidity_before, false),
         uidnext_observed = v_uidnext,
         messages_seen = coalesce(nullif(p_payload->>'messages_seen', '')::integer, messages_seen),
         messages_processed = coalesce(nullif(p_payload->>'messages_processed', '')::integer, messages_processed),
         messages_ignored = coalesce(nullif(p_payload->>'messages_ignored', '')::integer, messages_ignored),
         payables_extracted = coalesce(nullif(p_payload->>'payables_extracted', '')::integer, payables_extracted),
         error_summary = public.maria_email_payload_text(p_payload, 'error_summary', 500)
   where id = p_run_id;

  if v_uidvalidity_after is not null then
    update public.maria_email_sources
       set last_known_uidvalidity = v_uidvalidity_after
     where id = v_run.source_id;
  end if;

  return jsonb_build_object('success', true, 'run_id', p_run_id, 'status', v_status);
end;
$$;


ALTER FUNCTION "public"."maria_email_processing_run_finish"("p_run_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_processing_run_start"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_source_key text := lower(trim(coalesce(p_payload->>'source_key', '')));
  v_source public.maria_email_sources%rowtype;
  v_id uuid;
  v_run_kind text := coalesce(public.maria_email_payload_text(p_payload, 'run_kind', 40), 'autopush');
begin
  if v_source_key = '' then
    raise exception 'source_key obrigatorio' using errcode = '22023';
  end if;

  select * into v_source from public.maria_email_sources where source_key = v_source_key and ativo = true;
  if not found then
    raise exception 'fonte de email nao encontrada ou inativa: %', v_source_key using errcode = '22023';
  end if;

  insert into public.maria_email_processing_runs (
    source_id, run_kind, uidvalidity_before, parser_version, code_version
  ) values (
    v_source.id,
    v_run_kind,
    v_source.last_known_uidvalidity,
    public.maria_email_payload_text(p_payload, 'parser_version', 80),
    public.maria_email_payload_text(p_payload, 'code_version', 80)
  ) returning id into v_id;

  return jsonb_build_object('success', true, 'run_id', v_id, 'source_id', v_source.id, 'source_key', v_source.source_key);
end;
$$;


ALTER FUNCTION "public"."maria_email_processing_run_start"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_email_retencao_aplicar"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 5000);
  v_source record;
  v_run_id uuid;
  v_messages integer;
  v_payables integer;
  v_total_messages integer := 0;
  v_total_payables integer := 0;
begin
  for v_source in
    select s.id as source_id, s.source_key, s.last_known_uidvalidity
      from public.maria_email_sources s
     where exists (
       select 1
         from public.maria_email_messages m
        where m.source_id = s.id
          and m.person_data_redaction_status = 'pendente'
          and (
            m.created_at < now() - interval '90 days'
            or exists (
              select 1
                from public.maria_email_extracted_payables p
                join public.maria_email_payable_matches mt on mt.email_payable_id = p.id
               where p.message_id = m.id
                 and mt.match_status = 'confirmado_humano'
            )
          )
     )
     or exists (
       select 1
         from public.maria_email_extracted_payables p
         join public.maria_email_messages m on m.id = p.message_id
        where m.source_id = s.id
          and p.person_data_redaction_status = 'pendente'
          and (
            p.created_at < now() - interval '90 days'
            or exists (
              select 1
                from public.maria_email_payable_matches mt
               where mt.email_payable_id = p.id
                 and mt.match_status = 'confirmado_humano'
            )
          )
     )
  loop
    insert into public.maria_email_processing_runs (
      source_id, run_kind, uidvalidity_before, parser_version, code_version
    ) values (
      v_source.source_id, 'retention', v_source.last_known_uidvalidity, 'maria_email_retencao_aplicar', 'sql-migration-20260724_1'
    ) returning id into v_run_id;

    perform set_config('app.maria_email_redaction', 'on', true);

    with alvo as (
      select m.id
        from public.maria_email_messages m
       where m.source_id = v_source.source_id
         and m.person_data_redaction_status = 'pendente'
         and (
           m.created_at < now() - interval '90 days'
           or exists (
             select 1
               from public.maria_email_extracted_payables p
               join public.maria_email_payable_matches mt on mt.email_payable_id = p.id
              where p.message_id = m.id
                and mt.match_status = 'confirmado_humano'
           )
         )
       order by m.created_at
       limit v_limit
    ), upd as (
      update public.maria_email_messages m
         set subject = null,
             snippet = null,
             from_name = null,
             from_email_masked = null,
             person_data_redaction_status = 'expurgado'
        from alvo
       where m.id = alvo.id
       returning m.id
    ) select count(*) into v_messages from upd;

    with alvo as (
      select p.id
        from public.maria_email_extracted_payables p
        join public.maria_email_messages m on m.id = p.message_id
       where m.source_id = v_source.source_id
         and p.person_data_redaction_status = 'pendente'
         and (
           p.created_at < now() - interval '90 days'
           or exists (
             select 1
               from public.maria_email_payable_matches mt
              where mt.email_payable_id = p.id
                and mt.match_status = 'confirmado_humano'
           )
         )
       order by p.created_at
       limit v_limit
    ), upd as (
      update public.maria_email_extracted_payables p
         set fornecedor_nome = null,
             payer_name_masked = null,
             payer_name_hash = null,
             raw_extraction_sanitized = null,
             person_data_redaction_status = 'expurgado'
        from alvo
       where p.id = alvo.id
       returning p.id
    ) select count(*) into v_payables from upd;

    perform set_config('app.maria_email_redaction', '', true);
    perform set_config('app.maria_email_rpc', 'on', true);

    update public.maria_email_processing_runs
       set status = 'success',
           finished_at = now(),
           uidvalidity_after = v_source.last_known_uidvalidity,
           uidvalidity_changed = false,
           messages_seen = v_messages,
           messages_processed = v_messages,
           messages_ignored = 0,
           payables_extracted = v_payables,
           error_summary = null
     where id = v_run_id;

    perform set_config('app.maria_email_rpc', '', true);
    v_total_messages := v_total_messages + v_messages;
    v_total_payables := v_total_payables + v_payables;
  end loop;

  return jsonb_build_object('success', true, 'messages_expurgadas', v_total_messages, 'payables_expurgados', v_total_payables);
end;
$$;


