CREATE OR REPLACE FUNCTION "public"."maria_fluxo_evento_registrar"("p_data_operacional" "date", "p_chat_id" "text", "p_message_id" "text", "p_tipo_evento" "text", "p_direcao" "text", "p_descricao" "text", "p_valor" numeric, "p_unidade" "text" DEFAULT NULL::"text", "p_conta_origem" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'observado'::"text", "p_evidencia_texto" "text" DEFAULT NULL::"text", "p_quoted_id" "text" DEFAULT NULL::"text", "p_media_ref" "text" DEFAULT NULL::"text", "p_conta_pagar_id" "uuid" DEFAULT NULL::"uuid", "p_raw_payload_sanitizado" "jsonb" DEFAULT NULL::"jsonb", "p_observacoes" "text" DEFAULT NULL::"text", "p_ator_numero" "text" DEFAULT NULL::"text", "p_papel" "text" DEFAULT NULL::"text", "p_canal" "text" DEFAULT 'whatsapp-grupo-financeiro'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_numero text;
  v_valor_centavos integer;
  v_id uuid;
  v_row public.maria_fluxo_caixa_eventos%rowtype;
  v_audit_id uuid;
begin
  v_actor := public.maria_assert_actor(p_ator_numero, p_papel, array[
    'owner_full',
    'finance_ops_write_safe',
    'finance_assistant_write_safe'
  ]);

  if p_data_operacional is null then
    raise exception 'data_operacional obrigatoria.';
  end if;

  if nullif(trim(p_chat_id), '') is null then
    raise exception 'chat_id obrigatorio.';
  end if;

  if nullif(trim(p_message_id), '') is null then
    raise exception 'message_id obrigatorio para idempotencia.';
  end if;

  if nullif(trim(p_descricao), '') is null then
    raise exception 'descricao obrigatoria.';
  end if;

  v_numero := public.maria_normalizar_numero(p_ator_numero);
  v_valor_centavos := public.maria_fluxo_valor_para_centavos(p_valor);

  insert into public.maria_fluxo_caixa_eventos (
    data_operacional,
    chat_id,
    message_id,
    quoted_id,
    remetente_numero_hash,
    remetente_numero_last4,
    remetente_nome,
    tipo_evento,
    direcao,
    unidade,
    conta_origem,
    descricao,
    valor_centavos,
    status,
    evidencia_texto,
    media_ref,
    conta_pagar_id,
    raw_payload_sanitizado,
    observacoes,
    event_fingerprint
  ) values (
    p_data_operacional,
    trim(p_chat_id),
    trim(p_message_id),
    nullif(trim(p_quoted_id), ''),
    encode(extensions.digest(v_numero, 'sha256'), 'hex'),
    right(v_numero, 4),
    v_actor.nome,
    lower(trim(p_tipo_evento)),
    lower(trim(p_direcao)),
    nullif(lower(trim(p_unidade)), ''),
    nullif(trim(p_conta_origem), ''),
    trim(p_descricao),
    v_valor_centavos,
    coalesce(nullif(lower(trim(p_status)), ''), 'observado'),
    nullif(trim(p_evidencia_texto), ''),
    nullif(trim(p_media_ref), ''),
    p_conta_pagar_id,
    p_raw_payload_sanitizado,
    nullif(trim(p_observacoes), ''),
    md5(concat_ws('|', trim(p_chat_id), p_data_operacional::text, lower(trim(p_tipo_evento)), lower(trim(p_descricao)), coalesce(v_valor_centavos::text, ''), coalesce(nullif(lower(trim(p_unidade)), ''), '')))
  )
  on conflict (chat_id, event_fingerprint)
  do update set
    data_operacional = excluded.data_operacional,
    quoted_id = coalesce(excluded.quoted_id, public.maria_fluxo_caixa_eventos.quoted_id),
    remetente_numero_hash = excluded.remetente_numero_hash,
    remetente_numero_last4 = excluded.remetente_numero_last4,
    remetente_nome = excluded.remetente_nome,
    direcao = excluded.direcao,
    unidade = coalesce(excluded.unidade, public.maria_fluxo_caixa_eventos.unidade),
    conta_origem = coalesce(excluded.conta_origem, public.maria_fluxo_caixa_eventos.conta_origem),
    status = excluded.status,
    evidencia_texto = coalesce(excluded.evidencia_texto, public.maria_fluxo_caixa_eventos.evidencia_texto),
    media_ref = coalesce(excluded.media_ref, public.maria_fluxo_caixa_eventos.media_ref),
    conta_pagar_id = coalesce(excluded.conta_pagar_id, public.maria_fluxo_caixa_eventos.conta_pagar_id),
    raw_payload_sanitizado = coalesce(excluded.raw_payload_sanitizado, public.maria_fluxo_caixa_eventos.raw_payload_sanitizado),
    observacoes = coalesce(excluded.observacoes, public.maria_fluxo_caixa_eventos.observacoes),
    updated_at = now()
  returning id into v_id;

  select * into v_row from public.maria_fluxo_caixa_eventos where id = v_id;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    coalesce(nullif(trim(p_canal), ''), 'whatsapp-grupo-financeiro'),
    'maria_fluxo_caixa_eventos',
    'fluxo_caixa_evento',
    v_id,
    'registrar_evento_fluxo_caixa_observado',
    null,
    to_jsonb(v_row),
    p_observacoes,
    p_evidencia_texto
  );

  return jsonb_build_object(
    'ok', true,
    'success', true,
    'evento_id', v_id,
    'audit_id', v_audit_id,
    'data_operacional', v_row.data_operacional,
    'tipo_evento', v_row.tipo_evento,
    'direcao', v_row.direcao,
    'unidade', v_row.unidade,
    'descricao', v_row.descricao,
    'valor_centavos', v_row.valor_centavos,
    'valor', case when v_row.valor_centavos is null then null else (v_row.valor_centavos::numeric / 100) end,
    'status', v_row.status,
    'pagamento_executado_pela_maria', false,
    'baixa_executada_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_fluxo_evento_registrar"("p_data_operacional" "date", "p_chat_id" "text", "p_message_id" "text", "p_tipo_evento" "text", "p_direcao" "text", "p_descricao" "text", "p_valor" numeric, "p_unidade" "text", "p_conta_origem" "text", "p_status" "text", "p_evidencia_texto" "text", "p_quoted_id" "text", "p_media_ref" "text", "p_conta_pagar_id" "uuid", "p_raw_payload_sanitizado" "jsonb", "p_observacoes" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_fluxo_evento_registrar"("p_data_operacional" "date", "p_chat_id" "text", "p_message_id" "text", "p_tipo_evento" "text", "p_direcao" "text", "p_descricao" "text", "p_valor" numeric, "p_unidade" "text", "p_conta_origem" "text", "p_status" "text", "p_evidencia_texto" "text", "p_quoted_id" "text", "p_media_ref" "text", "p_conta_pagar_id" "uuid", "p_raw_payload_sanitizado" "jsonb", "p_observacoes" "text", "p_ator_numero" "text", "p_papel" "text", "p_canal" "text") IS 'Maria observadora: registra evento de fluxo de caixa observado no WhatsApp. Não executa pagamento, baixa ou transferência.';



CREATE OR REPLACE FUNCTION "public"."maria_fluxo_eventos_dia"("p_data_operacional" "date", "p_chat_id" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "data_operacional" "date", "created_at" timestamp with time zone, "chat_id" "text", "message_id" "text", "tipo_evento" "text", "direcao" "text", "unidade" "text", "conta_origem" "text", "descricao" "text", "valor_centavos" integer, "valor" numeric, "status" "text", "remetente_nome" "text", "evidencia_texto" "text", "media_ref" "text", "conta_pagar_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    e.id,
    e.data_operacional,
    e.created_at,
    e.chat_id,
    e.message_id,
    e.tipo_evento,
    e.direcao,
    e.unidade,
    e.conta_origem,
    e.descricao,
    e.valor_centavos,
    case when e.valor_centavos is null then null else e.valor_centavos::numeric / 100 end as valor,
    e.status,
    e.remetente_nome,
    e.evidencia_texto,
    e.media_ref,
    e.conta_pagar_id
  from public.maria_fluxo_caixa_eventos e
  where e.data_operacional = p_data_operacional
    and (p_chat_id is null or e.chat_id = p_chat_id)
  order by e.created_at asc, e.descricao asc;
$$;


ALTER FUNCTION "public"."maria_fluxo_eventos_dia"("p_data_operacional" "date", "p_chat_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_fluxo_eventos_dia"("p_data_operacional" "date", "p_chat_id" "text") IS 'Maria observadora: lista eventos de fluxo de caixa observados em um dia.';



CREATE OR REPLACE FUNCTION "public"."maria_fluxo_eventos_sem_superfolha"("p_inicio" "date", "p_fim" "date", "p_chat_id" "text" DEFAULT NULL::"text", "p_incluir_conciliados" boolean DEFAULT false) RETURNS TABLE("classificacao" "text", "confianca" "text", "data_operacional" "date", "unidade" "text", "descricao" "text", "valor" numeric, "status_superfolha" "text", "descricao_superfolha" "text", "data_pagamento_superfolha" "date", "candidatos" integer, "conta_pagar_id" "uuid", "tipo_lancamento" "text", "plano_codigo" "text", "plano_nome" "text", "centro_custo_nome" "text", "conta_pagadora_id" "uuid", "data_vencimento_superfolha" "date", "competencia_superfolha" "date")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with eventos_base as (
    select
      e.id,
      e.data_operacional,
      e.unidade,
      e.descricao,
      e.valor_centavos,
      regexp_replace(
        regexp_replace(
          regexp_replace(public.folha_normaliza_texto(e.descricao), '\(\s*pago\s+com\s+conta[^)]*\)', ' ', 'g'),
          '\m(pg|pagamento)\M', ' ', 'g'
        ),
        '[^a-z0-9]+', ' ', 'g'
      ) as descricao_normalizada,
      case e.unidade
        when 'recreio' then 'rec'
        when 'barra' then 'bar'
        when 'kids_cg' then 'cg'
        when 'emla_cg' then 'cg'
        else null
      end as unidade_superfolha
    from public.maria_fluxo_caixa_eventos e
    where e.data_operacional between p_inicio and p_fim
      and (p_chat_id is null or e.chat_id = p_chat_id)
      and e.tipo_evento = 'saida_confirmada'
      and e.status = 'confirmado'
      and e.valor_centavos > 0
      and e.evidencia_texto ~* '(comprovante|transfer[êe]ncia realizada|pagamento realizado|valor pago|pago com conta)'
      and e.evidencia_texto !~* '(previs[aã]o|cota[cç][aã]o|or[cç]amento)'
  ),
  pares as (
    select
      e.id as evento_id,
      cp.id as conta_id,
      (e.unidade_superfolha is null or cp.unidade = e.unidade_superfolha) as unidade_bate,
      (cp.data_pagamento::date = e.data_operacional) as mesmo_dia,
      cp.status,
      cp.descricao as descricao_superfolha,
      cp.data_pagamento::date as data_pagamento_superfolha,
      cp.tipo_lancamento,
      cp.plano_conta_id,
      cp.centro_custo_id,
      cp.conta_pagadora_id,
      cp.data_vencimento as data_vencimento_superfolha,
      cp.competencia as competencia_superfolha,
      count(distinct token) filter (
        where (length(token) >= 4 or (token ~ '^[0-9]+$' and length(token) >= 3))
          and position(
            token in regexp_replace(public.folha_normaliza_texto(cp.descricao), '[^a-z0-9]+', ' ', 'g')
          ) > 0
      )::integer as tokens_em_comum
    from eventos_base e
    join public.contas_pagar cp
      on round(cp.valor * 100)::integer = e.valor_centavos
      and (e.unidade_superfolha is null or cp.unidade = e.unidade_superfolha or cp.data_pagamento::date = e.data_operacional)
      and (
        cp.competencia between date_trunc('month', p_inicio)::date and date_trunc('month', p_fim)::date
        or cp.data_pagamento::date between e.data_operacional - 31 and e.data_operacional + 31
      )
    cross join lateral regexp_split_to_table(e.descricao_normalizada, ' +') token
    group by e.id, cp.id, e.unidade_superfolha, cp.unidade, e.data_operacional, cp.status, cp.descricao, cp.data_pagamento, cp.tipo_lancamento, cp.plano_conta_id, cp.centro_custo_id, cp.conta_pagadora_id, cp.data_vencimento, cp.competencia
  ),
  pares_classificados as (
    select p.*,
      (   (p.tokens_em_comum >= 2 and p.unidade_bate)
       or (p.tokens_em_comum >= 1 and p.mesmo_dia and p.unidade_bate)
       or (p.tokens_em_comum >= 2 and p.mesmo_dia and not p.unidade_bate)
       or (p.tokens_em_comum = 0 and p.mesmo_dia and p.unidade_bate)) as forte
    from pares p
  ),
  melhores as (
    select
      evento_id,
      max(tokens_em_comum) filter (where forte) as maior_score,
      count(*) filter (where forte and not unidade_bate)::integer as candidatos_cross_unidade,
      count(*) filter (where forte)::integer as candidatos_fortes,
      (array_agg(tokens_em_comum order by tokens_em_comum desc)
        filter (where forte))[2] as segundo_score,
      count(*) filter (where forte and status = 'pago')::integer as candidatos_pagos,
      count(*) filter (where forte and status = 'pendente')::integer as candidatos_pendentes,
      (array_agg(conta_id order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as conta_id,
      (array_agg(status order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as status_superfolha,
      (array_agg(descricao_superfolha order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as descricao_superfolha,
      (array_agg(data_pagamento_superfolha order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as data_pagamento_superfolha,
      (array_agg(tipo_lancamento order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as tipo_lancamento,
      (array_agg(plano_conta_id order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as plano_conta_id,
      (array_agg(centro_custo_id order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as centro_custo_id,
      (array_agg(conta_pagadora_id order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as conta_pagadora_id,
      (array_agg(data_vencimento_superfolha order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as data_vencimento_superfolha,
      (array_agg(competencia_superfolha order by unidade_bate desc, (status = 'pago') desc, tokens_em_comum desc, conta_id)
        filter (where forte))[1] as competencia_superfolha
    from pares_classificados
    group by evento_id
  ),
  resultado as (
    select
      case
        when coalesce(m.candidatos_fortes, 0) >= 1 and coalesce(m.candidatos_pagos, 0) >= 1 then 'conciliado'
        when coalesce(m.candidatos_fortes, 0) >= 1 and coalesce(m.candidatos_pagos, 0) = 0 and coalesce(m.candidatos_pendentes, 0) = 1 then 'baixa_pendente'
        when coalesce(m.candidatos_fortes, 0) >= 1 and coalesce(m.candidatos_pendentes, 0) > 1 then 'ambiguo'
        else 'sem_match'
      end as classificacao,
      case
        when coalesce(m.candidatos_fortes, 0) >= 1 and (coalesce(m.candidatos_pagos, 0) >= 1 or coalesce(m.candidatos_pendentes, 0) = 1) and (m.segundo_score is null or m.segundo_score < m.maior_score)
             and coalesce(m.candidatos_cross_unidade, 0) = 0
             and coalesce(m.maior_score, 0) >= 1 then 'alta'
        else 'revisar'
      end as confianca,
      e.data_operacional,
      e.unidade,
      left(e.descricao, 220) as descricao,
      e.valor_centavos::numeric / 100 as valor,
      m.status_superfolha,
      m.descricao_superfolha,
      m.data_pagamento_superfolha,
      coalesce(m.candidatos_fortes, 0) as candidatos,
      m.conta_id as conta_pagar_id,
      m.tipo_lancamento,
      pc.codigo as plano_codigo,
      pc.nome as plano_nome,
      cc.nome as centro_custo_nome,
      m.conta_pagadora_id,
      m.data_vencimento_superfolha,
      m.competencia_superfolha
    from eventos_base e
    left join melhores m on m.evento_id = e.id
    left join public.plano_contas pc on pc.id = m.plano_conta_id
    left join public.centros_custo cc on cc.id = m.centro_custo_id
  )
  , agregados as (
    select
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then 'conciliado'
           else r.classificacao end as classificacao,
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then 'revisar'
           else r.confianca end as confianca,
      r.data_operacional,
      r.unidade,
      r.descricao,
      r.valor,
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then 'pago'
           else r.status_superfolha end as status_superfolha,
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then ag.combo
           else r.descricao_superfolha end as descricao_superfolha,
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then r.data_operacional
           else r.data_pagamento_superfolha end as data_pagamento_superfolha,
      case when r.classificacao = 'sem_match' and ag.qtd = 1 then ag.n_contas
           else r.candidatos end as candidatos,
      r.conta_pagar_id,
      r.tipo_lancamento,
      r.plano_codigo,
      r.plano_nome,
      r.centro_custo_nome,
      r.conta_pagadora_id,
      r.data_vencimento_superfolha,
      r.competencia_superfolha
    from resultado r
    left join lateral (
      with pagas as (
        select c.id, c.descricao, c.valor
          from public.contas_pagar c
         where c.status = 'pago'
           and c.data_pagamento::date = r.data_operacional
           and c.valor < r.valor
           and (
             (case r.unidade when 'recreio' then 'rec' when 'barra' then 'bar'
                             when 'kids_cg' then 'cg' when 'emla_cg' then 'cg'
                             else null end) is null
             or c.unidade = (case r.unidade when 'recreio' then 'rec' when 'barra' then 'bar'
                                            when 'kids_cg' then 'cg' when 'emla_cg' then 'cg'
                                            else null end)
           )
      ),
      combos as (
        select a.descricao || ' + ' || b.descricao as combo, 2 as n_contas
          from pagas a join pagas b on b.id > a.id
         where round((a.valor + b.valor)::numeric, 2) = round(r.valor::numeric, 2)
        union all
        select a.descricao || ' + ' || b.descricao || ' + ' || t.descricao, 3
          from pagas a join pagas b on b.id > a.id join pagas t on t.id > b.id
         where round((a.valor + b.valor + t.valor)::numeric, 2) = round(r.valor::numeric, 2)
      )
      select (array_agg(combo))[1] as combo,
             (array_agg(n_contas))[1] as n_contas,
             count(*)::int as qtd
        from combos
    ) ag on r.classificacao = 'sem_match'
  )
  , parciais as (
    select
      case when a.classificacao = 'sem_match' and p.conta is not null then 'conciliado'
           else a.classificacao end as classificacao,
      case when a.classificacao = 'sem_match' and p.conta is not null then 'revisar'
           else a.confianca end as confianca,
      a.data_operacional,
      a.unidade,
      a.descricao,
      a.valor,
      case when a.classificacao = 'sem_match' and p.conta is not null then 'pago'
           else a.status_superfolha end as status_superfolha,
      case when a.classificacao = 'sem_match' and p.conta is not null
           then p.conta || ' (pago em 2 lancamentos)'
           else a.descricao_superfolha end as descricao_superfolha,
      case when a.classificacao = 'sem_match' and p.conta is not null then a.data_operacional
           else a.data_pagamento_superfolha end as data_pagamento_superfolha,
      a.candidatos,
      a.conta_pagar_id,
      a.tipo_lancamento,
      a.plano_codigo,
      a.plano_nome,
      a.centro_custo_nome,
      a.conta_pagadora_id,
      a.data_vencimento_superfolha,
      a.competencia_superfolha
    from agregados a
    left join lateral (
      select (array_agg(c.descricao))[1] as conta
        from agregados o
        join public.contas_pagar c
          on c.status = 'pago'
         and c.data_pagamento::date = a.data_operacional
         and round((a.valor + o.valor)::numeric, 2) = round(c.valor::numeric, 2)
         and (
           (case a.unidade when 'recreio' then 'rec' when 'barra' then 'bar'
                           when 'kids_cg' then 'cg' when 'emla_cg' then 'cg'
                           else null end) is null
           or c.unidade = (case a.unidade when 'recreio' then 'rec' when 'barra' then 'bar'
                                          when 'kids_cg' then 'cg' when 'emla_cg' then 'cg'
                                          else null end)
         )
       where o.classificacao = 'sem_match'
         and o.data_operacional = a.data_operacional
         and o.unidade is not distinct from a.unidade
         and o.descricao <> a.descricao
      having count(distinct c.id) = 1
    ) p on a.classificacao = 'sem_match'
  )
  select *
  from parciais
  where p_incluir_conciliados or classificacao <> 'conciliado'
  order by
    case classificacao when 'baixa_pendente' then 1 when 'ambiguo' then 2 when 'sem_match' then 3 else 4 end,
    data_operacional,
    descricao;
$_$;


ALTER FUNCTION "public"."maria_fluxo_eventos_sem_superfolha"("p_inicio" "date", "p_fim" "date", "p_chat_id" "text", "p_incluir_conciliados" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_fluxo_resumo_periodo"("p_inicio" "date", "p_fim" "date", "p_chat_id" "text" DEFAULT NULL::"text") RETURNS TABLE("data_operacional" "date", "unidade" "text", "direcao" "text", "tipo_evento" "text", "status" "text", "quantidade" bigint, "total_centavos" bigint, "total" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    e.data_operacional,
    coalesce(e.unidade, 'indefinida') as unidade,
    e.direcao,
    e.tipo_evento,
    e.status,
    count(*)::bigint as quantidade,
    coalesce(sum(e.valor_centavos), 0)::bigint as total_centavos,
    coalesce(sum(e.valor_centavos), 0)::numeric / 100 as total
  from public.maria_fluxo_caixa_eventos e
  where e.data_operacional between p_inicio and p_fim
    and (p_chat_id is null or e.chat_id = p_chat_id)
  group by e.data_operacional, coalesce(e.unidade, 'indefinida'), e.direcao, e.tipo_evento, e.status
  order by e.data_operacional, unidade, direcao, tipo_evento, status;
$$;


ALTER FUNCTION "public"."maria_fluxo_resumo_periodo"("p_inicio" "date", "p_fim" "date", "p_chat_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_fluxo_resumo_periodo"("p_inicio" "date", "p_fim" "date", "p_chat_id" "text") IS 'Maria observadora: agrega eventos observados por período/unidade/direção/status.';



CREATE OR REPLACE FUNCTION "public"."maria_fluxo_valor_para_centavos"("p_valor" numeric) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case when p_valor is null then null else round(p_valor * 100)::integer end;
$$;


ALTER FUNCTION "public"."maria_fluxo_valor_para_centavos"("p_valor" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_ctl_agenda"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce((public.maria_agenda_saude(1) ->> 'problemas')::int, 0)
$$;


ALTER FUNCTION "public"."maria_gov_ctl_agenda"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_ctl_alvo_escrita_sonda"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)::int from contas_pagar
  where descricao ilike '%SONDA-QA-NAO-EXISTE%'
     or coalesce(observacoes, '') ilike '%SONDA-QA-NAO-EXISTE%';
$$;


ALTER FUNCTION "public"."maria_gov_ctl_alvo_escrita_sonda"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_gov_ctl_alvo_escrita_sonda"() IS 'Alvo do item de escrita da sonda. A conta e FABRICADA de proposito: se a contencao falhar, nada real e alterado. Valor > 0 = escrita vazou.';



CREATE OR REPLACE FUNCTION "public"."maria_gov_ctl_codigos_coletados_mes_atual"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)::int
  from public.contas_pagar_codigo_mes
  where status_coleta = 'coletado'
    and competencia = date_trunc('month', current_date)::date;
$$;


ALTER FUNCTION "public"."maria_gov_ctl_codigos_coletados_mes_atual"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_gov_ctl_codigos_coletados_mes_atual"() IS 'Controle CORRETO do item codigos-coletados-total: filtra por competencia do mes atual, igual a pergunta congelada pede. maria_gov_ctl_codigos_coletados_total (sem filtro) mede outra coisa e NAO deve ser usado por este item.';



CREATE OR REPLACE FUNCTION "public"."maria_gov_ctl_codigos_coletados_total"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select count(*)::int from contas_pagar_codigo_mes where status_coleta = 'coletado';
$$;


ALTER FUNCTION "public"."maria_gov_ctl_codigos_coletados_total"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_ctl_conciliacao_falso_sem_match"() RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with s as (
    select *,
           case unidade when 'recreio' then 'rec' when 'barra' then 'bar'
                        when 'kids_cg' then 'cg'  when 'emla_cg' then 'cg'
                        else null end as u
    from public.maria_fluxo_eventos_sem_superfolha(
           date_trunc('month', (now() at time zone 'America/Sao_Paulo'))::date,
           ((date_trunc('month', (now() at time zone 'America/Sao_Paulo'))
             + interval '1 month - 1 day'))::date,
           null, false)
    where classificacao = 'sem_match'
  )
  select count(*)::int
  from s
  where
    -- (1) 1 para 1
    exists (
      select 1 from public.contas_pagar c
       where c.status = 'pago'
         and round(c.valor * 100)::integer = round(s.valor * 100)::integer
         and c.data_pagamento::date = s.data_operacional
    )
    -- (2) agregado: um pagamento quitando duas contas
    or 1 = (
      select count(*)::int from (
        select 1 from public.contas_pagar a
          join public.contas_pagar b on b.id > a.id
         where a.status = 'pago' and b.status = 'pago'
           and a.data_pagamento::date = s.data_operacional
           and b.data_pagamento::date = s.data_operacional
           and (s.u is null or (a.unidade = s.u and b.unidade = s.u))
           and round((a.valor + b.valor)::numeric, 2) = round(s.valor::numeric, 2)
      ) x
    )
    -- (3) parcial: este pagamento mais outro do mesmo dia fecham UMA conta paga
    or 1 = (
      select count(distinct c.id)::int
        from s o
        join public.contas_pagar c
          on c.status = 'pago'
         and c.data_pagamento::date = s.data_operacional
         and (s.u is null or c.unidade = s.u)
         and round((s.valor + o.valor)::numeric, 2) = round(c.valor::numeric, 2)
       where o.data_operacional = s.data_operacional
         and o.unidade is not distinct from s.unidade
         and o.descricao <> s.descricao
    );
$$;


