CREATE OR REPLACE FUNCTION "public"."maria_gov_definir_criterio"("p_finding_id" "uuid", "p_criterio" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_rows int;
begin
  -- WRITE-ONCE: só grava onde ainda está null/vazio. Critério existente é congelado.
  update public.maria_gov_findings
     set criterio_aceite = p_criterio
   where id = p_finding_id
     and (criterio_aceite is null or criterio_aceite = '');
  get diagnostics v_rows = row_count;
  return v_rows > 0;   -- true = preencheu agora; false = já tinha (não sobrescreve) ou id inexistente
end $$;


