    "area" "text",
    "severidade" "text",
    "status" "text" DEFAULT 'corrigido'::"text" NOT NULL,
    "causa_raiz" "text",
    "fix_resumo" "text" NOT NULL,
    "corrigido_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "primeira_vez" timestamp with time zone,
    "ultima_vez" timestamp with time zone,
    "ocorrencias" integer DEFAULT 1 NOT NULL
);


ALTER TABLE "public"."maria_gov_known_issues" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_known_issue_registrar"("p_codigo" "text", "p_titulo" "text", "p_area" "text" DEFAULT NULL::"text", "p_severidade" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'corrigido'::"text", "p_causa_raiz" "text" DEFAULT NULL::"text", "p_fix_resumo" "text" DEFAULT 'registrado sem fix_resumo detalhado'::"text", "p_primeira_vez" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "public"."maria_gov_known_issues"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.maria_gov_known_issues;
begin
  if p_codigo is null or btrim(p_codigo) = '' then
    raise exception 'p_codigo obrigatorio';
  end if;
  if p_titulo is null or btrim(p_titulo) = '' then
    raise exception 'p_titulo obrigatorio';
  end if;

  insert into public.maria_gov_known_issues
    (codigo, titulo, area, severidade, status, causa_raiz, fix_resumo, corrigido_em, primeira_vez, ultima_vez, ocorrencias)
  values
    (p_codigo, p_titulo, p_area, p_severidade, coalesce(p_status, 'corrigido'), p_causa_raiz,
     coalesce(p_fix_resumo, 'registrado sem fix_resumo detalhado'),
     now(), coalesce(p_primeira_vez, now()), now(), 1)
  on conflict (codigo) do update set
    titulo = excluded.titulo,
    area = excluded.area,
    severidade = excluded.severidade,
    status = excluded.status,
    causa_raiz = excluded.causa_raiz,
    fix_resumo = excluded.fix_resumo,
    corrigido_em = now(),
    ultima_vez = now(),
    ocorrencias = public.maria_gov_known_issues.ocorrencias + 1
  returning * into v_row;

  return v_row;
end;
$$;


ALTER FUNCTION "public"."maria_gov_known_issue_registrar"("p_codigo" "text", "p_titulo" "text", "p_area" "text", "p_severidade" "text", "p_status" "text", "p_causa_raiz" "text", "p_fix_resumo" "text", "p_primeira_vez" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_licao_aprovar_humano"("p_licao_id" "uuid", "p_aprovado_por" "text", "p_nota" "text" DEFAULT NULL::"text", "p_nivel" "text" DEFAULT 'soft'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_assin text; v_nivel_atual text;
begin
  if coalesce(p_aprovado_por,'') = '' then raise exception 'p_aprovado_por obrigatorio'; end if;
  if p_nivel not in ('soft','guard') then raise exception 'nivel destino invalido: %', p_nivel; end if;
  select assinatura, nivel into v_assin, v_nivel_atual
    from public.maria_licoes where id = p_licao_id for update;
  if v_assin is null then raise exception 'licao % nao encontrada', p_licao_id; end if;
  if v_nivel_atual <> 'candidata' then
    raise exception 'licao % nao e candidata (nivel=%)', p_licao_id, v_nivel_atual;
  end if;
  update public.maria_licoes set ativo = false
    where assinatura = v_assin and ativo and id <> p_licao_id;      -- supersede
  update public.maria_licoes
    set nivel = p_nivel, ativo = true, promovido_por = p_aprovado_por, promovido_em = now()
    where id = p_licao_id;
  return v_assin;
end $$;


ALTER FUNCTION "public"."maria_gov_licao_aprovar_humano"("p_licao_id" "uuid", "p_aprovado_por" "text", "p_nota" "text", "p_nivel" "text") OWNER TO "postgres";


