    AS $$
declare v_n int;
begin
  update public.maria_licoes set ativo=false where assinatura=p_assinatura and ativo;
  get diagnostics v_n = row_count;
  return v_n;
end $$;


ALTER FUNCTION "public"."maria_gov_licao_desativar"("p_assinatura" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_licao_promover"("p_licao_id" "uuid", "p_probe_id" "uuid", "p_promovido_por" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_lic public.maria_licoes; v_verde boolean; v_probe_fid uuid; v_fin boolean; v_old uuid; v_maxver int;
begin
  select * into v_lic from public.maria_licoes where id = p_licao_id for update;
  if v_lic.id is null then raise exception 'licao % inexistente', p_licao_id; end if;

  -- gate (#2): probe VERDE persistido E do MESMO finding da licao (nunca prova alheia, nunca conversa)
  select (veredito='verde'), finding_id into v_verde, v_probe_fid
    from public.maria_gov_probes where id = p_probe_id;
  if v_verde is distinct from true then
    raise exception 'promocao negada: probe % nao e verde', p_probe_id;
  end if;
  if v_lic.finding_id is null or v_probe_fid is distinct from v_lic.finding_id then
    raise exception 'promocao negada: probe % nao pertence ao finding da licao (%)', p_probe_id, v_lic.finding_id;
  end if;

  -- financeiro/comportamental -> financeiro_hold (nasce inativa; nao vira soft sem OK do Alf)
  v_fin := coalesce(v_lic.escopo,'') in ('financeiro','comportamental');
  if v_fin then
    update public.maria_licoes set nivel='financeiro_hold', ativo=false, probe_id=p_probe_id where id=p_licao_id;
    return 'financeiro_hold';
  end if;

  -- supersede a versao ativa anterior (append-only: desativa, nao apaga)
  select id into v_old from public.maria_licoes
    where assinatura=v_lic.assinatura and ativo and id<>p_licao_id order by versao desc limit 1;
  if v_old is not null then update public.maria_licoes set ativo=false where id=v_old; end if;

  select coalesce(max(versao),0) into v_maxver from public.maria_licoes where assinatura=v_lic.assinatura;
  update public.maria_licoes
     set nivel='soft', ativo=true, probe_id=p_probe_id, versao=v_maxver+1,
         promovido_em=now(), promovido_por=p_promovido_por, supersedes=v_old
   where id=p_licao_id;
  return 'soft';
end $$;


ALTER FUNCTION "public"."maria_gov_licao_promover"("p_licao_id" "uuid", "p_probe_id" "uuid", "p_promovido_por" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_licao_registrar_candidata"("p_assinatura" "text", "p_fonte" "text", "p_gatilho" "text", "p_regra_texto" "text", "p_escopo" "text" DEFAULT NULL::"text", "p_finding_id" "uuid" DEFAULT NULL::"uuid", "p_alvo_runtime" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  -- idempotente (#3): nao duplica candidata igual, nem recria se ja virou soft ativa
  select id into v_id from public.maria_licoes
   where assinatura = p_assinatura and (nivel='candidata' or ativo)
   order by created_at desc limit 1;
  if v_id is not null then return v_id; end if;
  insert into public.maria_licoes(assinatura, fonte, gatilho, regra_texto, escopo, finding_id, alvo_runtime, nivel, ativo)
    values (p_assinatura, p_fonte, p_gatilho, p_regra_texto, p_escopo, p_finding_id, p_alvo_runtime, 'candidata', false)
    returning id into v_id;
  return v_id;
end $$;


