CREATE OR REPLACE FUNCTION "public"."maria_gov_licoes_candidatas"("p_escopo" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "assinatura" "text", "escopo" "text", "fonte" "text", "gatilho" "text", "regra_texto" "text", "ocorrencias" integer, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
