CREATE OR REPLACE FUNCTION "public"."maria_gov_listar_para_corretor"("p_categorias" "text"[], "p_limite" integer DEFAULT 100) RETURNS SETOF "public"."maria_gov_findings"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- regra sagrada do Alf: financeiro fora do corretor (defesa no próprio DB, não só no caller)
  if p_categorias && array['contas_pendentes','pendencias_vencidas'] then
    raise exception 'financeiro fora do corretor: %', p_categorias;
  end if;

  return query
    select * from public.maria_gov_findings
     where status = 'novo' and categoria = any(p_categorias)
     order by categoria, incident_at
     limit p_limite;
end $$;


