    SET "search_path" TO 'public'
    AS $$
  select p.id, p.finding_id, f.categoria
  from public.maria_gov_probes p
  join public.maria_gov_findings f on f.id = p.finding_id
  where p.veredito = 'verde' and p.finding_id is not null
  order by p.criado_em desc;
$$;


