CREATE OR REPLACE FUNCTION "public"."maria_gov_registrar_finding"("p_categoria" "text", "p_severidade" "text", "p_resumo" "text", "p_assinatura" "text", "p_incident_at" timestamp with time zone, "p_evidencia" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare v_id uuid;
begin
  insert into maria_gov_findings (categoria, severidade, resumo, evidencia,
                                  incident_at, assinatura)
  values (p_categoria, p_severidade, p_resumo, p_evidencia,
          p_incident_at, p_assinatura)
  on conflict do nothing
  returning id into v_id;

  if v_id is null then
    -- ja existia hoje: nao duplica, mas conta a recorrencia
    update maria_gov_findings
       set ocorrencias = ocorrencias + 1, ultima_vez = now()
     where assinatura = p_assinatura
       and date_trunc('day', incident_at at time zone 'America/Sao_Paulo')
         = date_trunc('day', p_incident_at at time zone 'America/Sao_Paulo');
    return false;
  end if;

  -- a foto de ontem nao e item aberto quando a de hoje chega
  update maria_gov_findings
     set status = 'superseded'
   where assinatura = p_assinatura
     and id <> v_id
     and status = 'novo'
     and incident_at < p_incident_at
     and criterio_aceite is null      -- alguem definiu criterio: virou trabalho
     and promoted_code is null        -- virou codigo: nao e mais foto
     and verificado_em is null;       -- alguem conferiu: respeita

  return true;
end $$;


ALTER FUNCTION "public"."maria_gov_registrar_finding"("p_categoria" "text", "p_severidade" "text", "p_resumo" "text", "p_assinatura" "text", "p_incident_at" timestamp with time zone, "p_evidencia" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_registrar_papel_run"("p_reference_date" "date", "p_papel" "text", "p_ator" "text", "p_finding_id" "uuid" DEFAULT NULL::"uuid", "p_probe_id" "uuid" DEFAULT NULL::"uuid", "p_modelo" "text" DEFAULT 'deterministico'::"text", "p_tipo" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT 'ok'::"text", "p_detalhe" "text" DEFAULT NULL::"text", "p_custo_usd" numeric DEFAULT NULL::numeric, "p_assinatura" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.maria_gov_papel_runs
    (reference_date, papel, ator, modelo, finding_id, probe_id, tipo, status, detalhe, custo_usd, assinatura)
  values
    (p_reference_date, p_papel, p_ator, p_modelo, p_finding_id, p_probe_id, p_tipo, p_status, p_detalhe, p_custo_usd, p_assinatura)
  on conflict (assinatura) do update set   -- assinatura null nunca conflita (nulls distinct) => append
    status = excluded.status, detalhe = excluded.detalhe, probe_id = excluded.probe_id,
    custo_usd = excluded.custo_usd, criado_em = now()
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."maria_gov_registrar_papel_run"("p_reference_date" "date", "p_papel" "text", "p_ator" "text", "p_finding_id" "uuid", "p_probe_id" "uuid", "p_modelo" "text", "p_tipo" "text", "p_status" "text", "p_detalhe" "text", "p_custo_usd" numeric, "p_assinatura" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_registrar_probe"("p_run_id" "uuid", "p_pergunta_congelada" "text", "p_redacao_usada" "text", "p_sql_controle" "text", "p_modelo_verificador" "text", "p_provedor_verificador" "text", "p_versao_protocolo" "text", "p_resposta_literal" "text" DEFAULT NULL::"text", "p_resultado_controle" "jsonb" DEFAULT NULL::"jsonb", "p_veredito" "text" DEFAULT NULL::"text", "p_pass_k_total" integer DEFAULT NULL::integer, "p_pass_k_ok" integer DEFAULT NULL::integer, "p_modelo_efetivo_maria" "text" DEFAULT NULL::"text", "p_custo_usd" numeric DEFAULT NULL::numeric, "p_duracao_s" numeric DEFAULT NULL::numeric, "p_duracao_motor_s" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare v_id uuid;
begin
  -- Sem on conflict de proposito: cada invocacao e um fato proprio. Deduplicar por
  -- pergunta apagaria justamente o que o pass^k mede — a variacao entre tentativas.
  insert into maria_gov_probes (
    run_id, pergunta_congelada, redacao_usada, resposta_literal, sql_controle,
    resultado_controle, veredito, pass_k_total, pass_k_ok, modelo_verificador,
    provedor_verificador, modelo_efetivo_maria, versao_protocolo,
    custo_usd, duracao_s, duracao_motor_s)
  values (
    p_run_id, p_pergunta_congelada, p_redacao_usada, p_resposta_literal, p_sql_controle,
    p_resultado_controle, p_veredito, p_pass_k_total, p_pass_k_ok, p_modelo_verificador,
    p_provedor_verificador, p_modelo_efetivo_maria, p_versao_protocolo,
    p_custo_usd, p_duracao_s, p_duracao_motor_s)
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."maria_gov_registrar_probe"("p_run_id" "uuid", "p_pergunta_congelada" "text", "p_redacao_usada" "text", "p_sql_controle" "text", "p_modelo_verificador" "text", "p_provedor_verificador" "text", "p_versao_protocolo" "text", "p_resposta_literal" "text", "p_resultado_controle" "jsonb", "p_veredito" "text", "p_pass_k_total" integer, "p_pass_k_ok" integer, "p_modelo_efetivo_maria" "text", "p_custo_usd" numeric, "p_duracao_s" numeric, "p_duracao_motor_s" numeric) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_gov_registrar_probe"("p_run_id" "uuid", "p_pergunta_congelada" "text", "p_redacao_usada" "text", "p_sql_controle" "text", "p_modelo_verificador" "text", "p_provedor_verificador" "text", "p_versao_protocolo" "text", "p_resposta_literal" "text", "p_resultado_controle" "jsonb", "p_veredito" "text", "p_pass_k_total" integer, "p_pass_k_ok" integer, "p_modelo_efetivo_maria" "text", "p_custo_usd" numeric, "p_duracao_s" numeric, "p_duracao_motor_s" numeric) IS 'Registra UMA invocacao da sonda. Uma linha por tentativa: o pass^k mede a variacao entre tentativas, entao deduplicar por pergunta apagaria a medida.';



CREATE OR REPLACE FUNCTION "public"."maria_gov_registrar_probe_ctl"("p_finding_id" "uuid", "p_pergunta_congelada" "text", "p_sql_controle" "text", "p_resultado_controle" "jsonb", "p_veredito" "text", "p_pass_k_total" integer, "p_pass_k_ok" integer, "p_fase" "text", "p_modelo_verificador" "text" DEFAULT 'controle-sql-v1'::"text", "p_provedor_verificador" "text" DEFAULT 'deterministico'::"text", "p_versao_protocolo" "text" DEFAULT 'corretor-v1'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  if p_fase is null or p_fase not in ('baseline','reversao') then
    raise exception 'p_fase invalido: %', p_fase; end if;
  if p_veredito is null or p_veredito not in ('verde','vermelho') then
    raise exception 'p_veredito invalido: %', p_veredito; end if;
  if p_pass_k_total is null or p_pass_k_total <= 0 then
    raise exception 'p_pass_k_total deve ser > 0: %', p_pass_k_total; end if;
  if p_pass_k_ok is null or p_pass_k_ok < 0 or p_pass_k_ok > p_pass_k_total then
    raise exception 'p_pass_k_ok fora de [0,%]: %', p_pass_k_total, p_pass_k_ok; end if;

  insert into public.maria_gov_probes
    (finding_id, run_id, pergunta_congelada, redacao_usada, sql_controle, resultado_controle,
     veredito, pass_k_total, pass_k_ok, fase,
     modelo_verificador, provedor_verificador, versao_protocolo)
  values
    (p_finding_id, null, p_pergunta_congelada, p_pergunta_congelada, p_sql_controle, p_resultado_controle,
     p_veredito, p_pass_k_total, p_pass_k_ok, p_fase,
     p_modelo_verificador, p_provedor_verificador, p_versao_protocolo)
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."maria_gov_registrar_probe_ctl"("p_finding_id" "uuid", "p_pergunta_congelada" "text", "p_sql_controle" "text", "p_resultado_controle" "jsonb", "p_veredito" "text", "p_pass_k_total" integer, "p_pass_k_ok" integer, "p_fase" "text", "p_modelo_verificador" "text", "p_provedor_verificador" "text", "p_versao_protocolo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_registrar_run"("p_reference_date" "date", "p_status" "text", "p_detalhe" "text" DEFAULT NULL::"text", "p_modelo_efetivo" "text" DEFAULT NULL::"text", "p_tipo" "text" DEFAULT 'laudo_v1a'::"text", "p_custo_usd" numeric DEFAULT NULL::numeric, "p_enviado_em" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare v_id uuid;
begin
  insert into maria_gov_runs (reference_date, tipo, status, detalhe,
                              modelo_efetivo_maria, custo_usd, enviado_em)
  values (p_reference_date, p_tipo, p_status, p_detalhe,
          p_modelo_efetivo, p_custo_usd, p_enviado_em)
  on conflict (reference_date, tipo) do update
    set status = excluded.status,
        detalhe = excluded.detalhe,
        modelo_efetivo_maria = excluded.modelo_efetivo_maria,
        custo_usd = excluded.custo_usd,
        enviado_em = excluded.enviado_em
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."maria_gov_registrar_run"("p_reference_date" "date", "p_status" "text", "p_detalhe" "text", "p_modelo_efetivo" "text", "p_tipo" "text", "p_custo_usd" numeric, "p_enviado_em" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_gov_transicionar_finding"("p_finding_id" "uuid", "p_novo_status" "text", "p_nota" "text" DEFAULT NULL::"text", "p_probe_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_atual text; v_criterio text;
begin
  select status, criterio_aceite into v_atual, v_criterio
    from public.maria_gov_findings where id = p_finding_id for update;
  if v_atual is null then raise exception 'finding % inexistente', p_finding_id; end if;

  -- transições permitidas na Fatia 1
  if not (
     (v_atual='novo'        and p_novo_status='em_correcao') or
     (v_atual='em_correcao' and p_novo_status in ('refutado','bloqueado')) or
     (v_atual='refutado'    and p_novo_status='resolvido')
  ) then
     raise exception 'transicao ilegal % -> %', v_atual, p_novo_status;
  end if;

  -- guarda dura (freio #5): novo->em_correcao exige criterio_aceite preenchido
  if p_novo_status='em_correcao' and (v_criterio is null or v_criterio='') then
     raise exception 'sem criterio_aceite: nao pode ir a em_correcao (finding %)', p_finding_id;
  end if;

  update public.maria_gov_findings
     set status = p_novo_status,
         verificado_em = case when p_probe_id is not null then now() else verificado_em end,
         verificado_nota = coalesce(p_nota, verificado_nota)
   where id = p_finding_id;
  return p_novo_status;
end $$;


ALTER FUNCTION "public"."maria_gov_transicionar_finding"("p_finding_id" "uuid", "p_novo_status" "text", "p_nota" "text", "p_probe_id" "uuid") OWNER TO "postgres";


