CREATE OR REPLACE FUNCTION "public"."maria_lancamento_eventual_resolver_ids"("p_unidade" "text" DEFAULT NULL::"text", "p_conta_origem" "text" DEFAULT NULL::"text", "p_plano_codigo" "text" DEFAULT NULL::"text", "p_plano_nome" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_unidade_norm text;
  v_conta_norm text;
  v_plano_codigo text;
  v_plano_nome text;
  v_centro_codigo text;
  v_plano_count integer;
  v_centro_count integer;
  v_conta_count integer;
  v_plano jsonb;
  v_centro jsonb;
  v_conta jsonb;
  v_contas jsonb;
  v_bloqueios text[] := array[]::text[];
begin
  v_unidade_norm := lower(trim(coalesce(p_unidade, '')));
  v_conta_norm := lower(trim(coalesce(p_conta_origem, '')));
  v_plano_codigo := nullif(trim(p_plano_codigo), '');
  v_plano_nome := nullif(trim(p_plano_nome), '');

  v_centro_codigo := case
    when v_unidade_norm in ('rec', 'recreio', 'la kids recreio') then 'rec'
    when v_unidade_norm in ('bar', 'barra') then 'bar'
    when v_unidade_norm in ('cg', 'campo grande', 'campo_grande', 'emla cg', 'emla_cg', 'kids cg', 'kids_cg') then 'cg'
    else null
  end;

  select count(*), jsonb_agg(jsonb_build_object(
    'plano_conta_id', id,
    'codigo', codigo,
    'nome', nome,
    'natureza', natureza,
    'nivel', nivel
  ) order by codigo)
  into v_plano_count, v_plano
  from public.plano_contas
  where ativo = true
    and natureza = 'saida'
    and nivel = 3
    and (
      (v_plano_codigo is not null and codigo = v_plano_codigo)
      or (
        v_plano_codigo is null
        and v_plano_nome is not null
        and lower(nome) like '%' || lower(v_plano_nome) || '%'
      )
    );

  if coalesce(v_plano_count, 0) = 0 then
    v_bloqueios := array_append(v_bloqueios, 'plano_conta_id nao resolvido');
  elsif v_plano_count > 1 then
    v_bloqueios := array_append(v_bloqueios, 'plano_conta ambiguo');
  end if;

  if v_centro_codigo is not null then
    select count(*), jsonb_agg(jsonb_build_object(
      'centro_custo_id', id,
      'codigo', codigo,
      'nome', nome,
      'tipo', tipo
    ) order by codigo)
    into v_centro_count, v_centro
    from public.centros_custo
    where ativo = true and tipo = 'unidade' and codigo = v_centro_codigo;
  else
    v_centro_count := 0;
    v_centro := '[]'::jsonb;
  end if;

  if coalesce(v_centro_count, 0) = 0 then
    v_bloqueios := array_append(v_bloqueios, 'centro_custo_id nao resolvido');
  end if;

  select count(*), jsonb_agg(jsonb_build_object(
    'conta_pagadora_id', b.id,
    'empresa_id', e.id,
    'empresa_label', e.label_operacional,
    'empresa_nome', e.nome_fantasia,
    'centro_codigo', cc.codigo,
    'centro_nome', cc.nome,
    'banco', b.banco,
    'agencia', b.agencia,
    'conta', b.conta,
    'apelido', b.apelido
  ) order by e.label_operacional, b.apelido)
  into v_conta_count, v_contas
  from public.financeiro_contas_bancarias b
  join public.financeiro_empresas e on e.id = b.empresa_id
  left join public.centros_custo cc on cc.id = e.unidade_id
  where b.ativo = true and e.ativo = true
    and (
      (
        v_conta_norm <> ''
        and (
          lower(e.label_operacional) like '%' || v_conta_norm || '%'
          or lower(e.nome_fantasia) like '%' || v_conta_norm || '%'
          or lower(coalesce(b.apelido, '')) like '%' || v_conta_norm || '%'
          or lower(coalesce(b.banco, '')) || ' ' || lower(coalesce(b.agencia, '')) || ' ' || lower(coalesce(b.conta, '')) like '%' || v_conta_norm || '%'
          or (v_conta_norm like '%music school l%' and e.label_operacional = 'Barra')
          or (v_conta_norm like '%escola de música la kids%' and e.label_operacional = 'Recreio')
          or (v_conta_norm like '%escola de musica la kids%' and e.label_operacional = 'Recreio')
          or (v_conta_norm like '%escola de música la%' and v_conta_norm not like '%kids%' and e.label_operacional = 'EMLA CG')
          or (v_conta_norm like '%escola de musica la%' and v_conta_norm not like '%kids%' and e.label_operacional = 'EMLA CG')
          or (v_conta_norm like '%kids cg%' and e.label_operacional = 'Kids CG')
          or (v_conta_norm like '%emla cg%' and e.label_operacional = 'EMLA CG')
        )
      )
      or (
        v_conta_norm = ''
        and v_centro_codigo is not null
        and cc.codigo = v_centro_codigo
      )
    );

  if coalesce(v_conta_count, 0) = 0 then
    v_bloqueios := array_append(v_bloqueios, 'conta_pagadora_id nao resolvida');
  elsif v_conta_count > 1 then
    v_bloqueios := array_append(v_bloqueios, 'conta_pagadora ambigua');
  end if;

  return jsonb_build_object(
    'ok', cardinality(v_bloqueios) = 0,
    'bloqueios', v_bloqueios,
    'input', jsonb_build_object(
      'unidade', p_unidade,
      'conta_origem', p_conta_origem,
      'plano_codigo', p_plano_codigo,
      'plano_nome', p_plano_nome
    ),
    'plano', case when v_plano_count = 1 then v_plano->0 else null end,
    'plano_candidatos', coalesce(v_plano, '[]'::jsonb),
    'centro_custo', case when v_centro_count = 1 then v_centro->0 else null end,
    'centro_custo_candidatos', coalesce(v_centro, '[]'::jsonb),
    'conta_pagadora', case when v_conta_count = 1 then v_contas->0 else null end,
    'conta_pagadora_candidatos', coalesce(v_contas, '[]'::jsonb),
    'pagamento_executado_pela_maria', false,
    'lancamento_executado_pela_maria', false
  );
end;
$$;


ALTER FUNCTION "public"."maria_lancamento_eventual_resolver_ids"("p_unidade" "text", "p_conta_origem" "text", "p_plano_codigo" "text", "p_plano_nome" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maria_lancamento_eventual_resolver_ids"("p_unidade" "text", "p_conta_origem" "text", "p_plano_codigo" "text", "p_plano_nome" "text") IS 'Maria read resolver: resolve/candidata plano_conta_id, centro_custo_id e conta_pagadora_id para lancamento eventual. Nao cria conta, nao lanca e nao move dinheiro.';



CREATE OR REPLACE FUNCTION "public"."maria_ledger_suspeitos"("p_dias" integer DEFAULT 60, "p_valor_atipico" numeric DEFAULT 20000) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  with base as (
    select e.id, e.data_operacional, e.valor_centavos/100.0 as valor, e.unidade, e.descricao, e.conta_pagar_id,
           coalesce(trim(e.descricao), '') as d
      from public.maria_fluxo_caixa_eventos e
     where e.status = 'confirmado'
       and e.valor_centavos is not null
       and e.data_operacional >= (now() at time zone 'America/Sao_Paulo')::date - greatest(coalesce(p_dias, 60), 1)
  ),
  classificada as (
    select b.*,
      case
        -- mencao do WhatsApp virou descricao: nunca e nome de pagamento
        when b.d ~ '^@[0-9]{6,}' then 'mencao_whatsapp'
        -- descricao vazia ou minuscula demais para nomear um pagamento (OCR corrompido)
        when length(b.d) < 4 then 'descricao_vazia'
        -- OCR corrompido: sequencia de maiusculas soltas sem nenhuma palavra reconhecivel
        when (select count(*) from regexp_split_to_table(b.d, '\s+') t where t ~ '[A-Za-zÀ-ÿ]{4,}') = 0 then 'descricao_sem_palavra'
        -- pedido dirigido a Maria (mesma classe fechada no bridge em 02/09)
        when b.d ~* '(^|[[:space:],;:])maria\y' and b.d ~* '\m(prepar|mont|separ|confer|list|verific|mostr|traz|organiz|calcul|corrig|marc|diz|acha)' then 'pedido_para_maria'
        -- frase de conversa: gente falando sobre pagamento, nao declarando um
        when b.d ~* '(entendi|conclui|deixei essa tela|n[aã]o deixa salvar|j[aá] fez tudo|precisa repassar|teve diverg[eê]ncia|lan[cç]amento a mais|n[aã]o achei|pode marcar|seria (distribui|poupan|prolabore)|o que seria|ela j[aá]|ele j[aá])' then 'frase_de_conversa'
        -- termina em pergunta: quem pergunta nao esta declarando pagamento
        when b.d ~ '\?\s*[🤗😊]?\s*$' then 'pergunta'
        else null
      end as motivo
      from base b
  )
  select jsonb_build_object(
    'success', true,
    'janela_dias', greatest(coalesce(p_dias, 60), 1),
    'suspeitos', jsonb_build_object(
      'n', (select count(*) from classificada where motivo is not null),
      'total', (select round(coalesce(sum(valor), 0), 2) from classificada where motivo is not null),
      'por_motivo', coalesce((select jsonb_object_agg(motivo, jsonb_build_object('n', n, 'total', total))
                                from (select motivo, count(*) n, round(sum(valor), 2) total
                                        from classificada where motivo is not null group by motivo) m), '{}'::jsonb),
      'itens', coalesce((select jsonb_agg(jsonb_build_object('id', id, 'data', data_operacional, 'valor', valor,
                                  'unidade', unidade, 'motivo', motivo, 'descricao', left(descricao, 90)) order by valor desc)
                           from (select * from classificada where motivo is not null order by valor desc limit 20) i), '[]'::jsonb)),
    -- valor alto CONFIRMADO sem vinculo com conta a pagar: nao e erro por si so, e o lugar onde o erro mora
    'atipicos', jsonb_build_object(
      'limiar', p_valor_atipico,
      'n', (select count(*) from classificada where motivo is null and valor > p_valor_atipico and conta_pagar_id is null),
      'total', (select round(coalesce(sum(valor), 0), 2) from classificada where motivo is null and valor > p_valor_atipico and conta_pagar_id is null),
      'itens', coalesce((select jsonb_agg(jsonb_build_object('data', data_operacional, 'valor', valor, 'unidade', unidade,
                                  'descricao', left(descricao, 90)) order by valor desc)
                           from (select * from classificada where motivo is null and valor > p_valor_atipico and conta_pagar_id is null
                                  order by valor desc limit 10) a), '[]'::jsonb)),
    'aviso', 'Mede o que esta CONFIRMADO (valendo no caixa), nao o que ja foi marcado como ignorado. '
          || 'Suspeito = a descricao nao nomeia um pagamento (mencao, pedido, frase de conversa, OCR corrompido). '
          || 'Cada item precisa de olho humano antes de virar ignorado: em 03/09 a triagem por regex deu falso '
          || 'positivo em 13 linhas de "Simples Nacional", que eram imposto de verdade.'
  );
$_$;


ALTER FUNCTION "public"."maria_ledger_suspeitos"("p_dias" integer, "p_valor_atipico" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_licoes_imutavel"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.assinatura is distinct from old.assinatura
     or new.gatilho is distinct from old.gatilho
     or new.regra_texto is distinct from old.regra_texto then
    raise exception 'maria_licoes: assinatura/gatilho/regra_texto sao imutaveis (versionar por supersede, sem edit)';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."maria_licoes_imutavel"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_ml_consulta"("p_data_ini" "date", "p_data_fim" "date", "p_filtro" "text" DEFAULT NULL::"text", "p_limite" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select p.*
    from ml_pedidos p
    where p.data_pedido between p_data_ini and p_data_fim
      and (
        nullif(btrim(coalesce(p_filtro,'')),'') is null
        or p.produto_titulo ilike '%'||btrim(p_filtro)||'%'
        or p.seller_nome    ilike '%'||btrim(p_filtro)||'%'
      )
  ),
  agg as (
    select count(*) as n,
           coalesce(round(sum(valor_total),2),0) as v,
           count(*) filter (where coalesce(match_status,'pendente') <> 'pendente') as n_em_fatura
    from base
  ),
  plano as (
    select coalesce(b.plano_sugerido,'—') as cod,
           (select nome from plano_contas pc
             where pc.codigo = b.plano_sugerido and pc.nivel = 3 and pc.natureza = 'saida' limit 1) as nome,
           count(*) as qtd, round(sum(b.valor_total),2) as valor
    from base b group by b.plano_sugerido
  ),
  itens as (
    select b.data_pedido, b.produto_titulo, b.seller_nome, b.quantidade, b.valor_total,
           b.status, b.match_status, b.plano_sugerido,
           (select nome from plano_contas pc
             where pc.codigo = b.plano_sugerido and pc.nivel = 3 and pc.natureza = 'saida' limit 1) as plano_nome
    from base b
    order by b.data_pedido desc, b.valor_total desc
    limit greatest(coalesce(p_limite,40),1)
  )
  select jsonb_build_object(
    'periodo', jsonb_build_object('ini', p_data_ini, 'fim', p_data_fim),
    'total_pedidos', (select n from agg),
    'total_valor', (select v from agg),
    'em_fatura', (select n_em_fatura from agg),
    'por_plano', coalesce((select jsonb_agg(jsonb_build_object('plano',cod,'nome',nome,'qtd',qtd,'valor',valor) order by valor desc) from plano), '[]'::jsonb),
    'itens', coalesce((select jsonb_agg(jsonb_build_object(
        'data',data_pedido,'produto',produto_titulo,'seller',seller_nome,'qtd',quantidade,
        'valor',valor_total,'status',status,'match_status',match_status,
        'plano_sugerido',plano_sugerido,'plano_nome',plano_nome
      ) order by data_pedido desc, valor_total desc) from itens), '[]'::jsonb),
    'itens_truncado', ((select n from agg) > greatest(coalesce(p_limite,40),1))
  );
$$;


ALTER FUNCTION "public"."maria_ml_consulta"("p_data_ini" "date", "p_data_fim" "date", "p_filtro" "text", "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_ml_identificar_compra"("p_texto" "text" DEFAULT NULL::"text", "p_valor" numeric DEFAULT NULL::numeric, "p_data" "date" DEFAULT NULL::"date", "p_cartao_id" "uuid" DEFAULT 'd4264a77-e7eb-48e0-bdae-d16c0d8bcd8e'::"uuid", "p_limite" integer DEFAULT 5, "p_limiar" numeric DEFAULT 0.80) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tag text; v_parc_tot int; v_valor_full numeric;
  v_best ml_pedidos%rowtype; v_conf text := null; v_n int;
  v_texto_norm text; v_cod text; v_nome text; v_origem text; v_regra record;
  v_plano_cat text; v_cluster text; v_prod text;
begin
  v_tag := upper(regexp_replace(split_part(split_part(coalesce(p_texto,''),'*',2),' ',1),'[^a-zA-Z0-9]','','g'));
  if v_tag='MERCADOLIVRE' or v_tag='' then v_tag := null; end if;
  -- Fix 25/08: fatura MP escreve "Parcela N de M" (nao so "Parcela N/M"). Aceita ambos.
  v_parc_tot := nullif(substring(coalesce(p_texto,'') from '[Pp]arcela\s+\d+\s*(?:/|de)\s*(\d+)'),'')::int;
  v_valor_full := case when v_parc_tot is not null and p_valor is not null then round(p_valor*v_parc_tot,2) else null end;
  if v_tag is not null then
    select * into v_best from ml_pedidos p where upper(regexp_replace(p.seller_nome,'[^a-zA-Z0-9]','','g')) like v_tag||'%'
     order by (case when p_valor is not null and round(p.valor_total,2)=round(p_valor,2) then 0 else 1 end),
              (case when p_data is not null then abs(p.data_pedido-p_data) else 999 end) limit 1;
    if found then v_conf := case when p_valor is not null and round(v_best.valor_total,2)=round(p_valor,2) then 'alta' else 'media_vendedor' end; end if;
  end if;
  if v_conf is null and p_valor is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) and (p_data is null or abs(p.data_pedido-p_data)<=2);
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) and (p_data is null or abs(p.data_pedido-p_data)<=2) limit 1; v_conf := 'alta_valor_data'; end if;
  end if;
  if v_conf is null and v_valor_full is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=v_valor_full;
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=v_valor_full limit 1; v_conf := 'alta_parcelado'; end if;
  end if;
  if v_conf is null and p_valor is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2);
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) limit 1; v_conf := 'media_valor'; end if;
  end if;
  if v_conf is null then return jsonb_build_object('apelido_extraido',v_tag,'total_candidatos',0,'produto',null,'plano_provavel',null); end if;
  v_prod := v_best.produto_titulo; v_plano_cat := v_best.plano_sugerido; v_cluster := v_best.cluster;
  v_texto_norm := public.maria_cartoes_normalizar_texto(coalesce(v_prod,'')||' '||coalesce(p_texto,''));
  select p.codigo, p.nome into v_regra from public.maria_classificacao_regras r join public.plano_contas p on p.id=r.plano_conta_id
   where r.ativo and r.escopo in ('cartao','geral') and r.plano_conta_id is not null and position(r.palavra_chave in v_texto_norm)>0
   order by r.prioridade desc, r.confianca_base desc limit 1;
  if found then v_cod:=v_regra.codigo; v_nome:=v_regra.nome; v_origem:='regra';
  elsif v_plano_cat is not null then v_cod:=v_plano_cat; v_origem:='categoria';
    select nome into v_nome from public.plano_contas where codigo=v_plano_cat and nivel=3 and natureza='saida' limit 1; end if;
  return jsonb_build_object('apelido_extraido',v_tag,'total_candidatos',1,
    'produto', jsonb_build_object('produto_titulo',v_best.produto_titulo,'seller_nome',v_best.seller_nome,'valor_total',v_best.valor_total,
       'data_pedido',v_best.data_pedido,'order_id',v_best.order_id,'status',v_best.status,'confianca',v_conf,'cluster',v_best.cluster,'category_path',v_best.category_path),
    'plano_provavel', case when v_cod is not null then jsonb_build_object('codigo',v_cod,'nome',v_nome,'origem',v_origem,'categoria',v_cluster,'confianca_match',v_conf) else null end);
end $$;


ALTER FUNCTION "public"."maria_ml_identificar_compra"("p_texto" "text", "p_valor" numeric, "p_data" "date", "p_cartao_id" "uuid", "p_limite" integer, "p_limiar" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_ml_identificar_compra"("p_texto" "text" DEFAULT NULL::"text", "p_valor" numeric DEFAULT NULL::numeric, "p_data" "date" DEFAULT NULL::"date", "p_cartao_id" "uuid" DEFAULT 'd4264a77-e7eb-48e0-bdae-d16c0d8bcd8e'::"uuid", "p_limite" integer DEFAULT 5, "p_limiar" numeric DEFAULT 0.80, "p_valor_parcelado_total" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_tag text; v_parc_tot int; v_valor_full numeric;
  v_best ml_pedidos%rowtype; v_conf text := null; v_n int;
  v_texto_norm text; v_cod text; v_nome text; v_origem text; v_regra record;
  v_plano_cat text; v_cluster text; v_prod text;
begin
  v_tag := upper(regexp_replace(split_part(split_part(coalesce(p_texto,''),'*',2),' ',1),'[^a-zA-Z0-9]','','g'));
  if v_tag='MERCADOLIVRE' or v_tag='' then v_tag := null; end if;
  if p_valor_parcelado_total is not null then
    v_valor_full := round(p_valor_parcelado_total,2);
  else
    v_parc_tot := nullif(substring(coalesce(p_texto,'') from '[Pp]arcela\s+\d+\s*(?:/|de)\s*(\d+)'),'')::int;
    v_valor_full := case when v_parc_tot is not null and p_valor is not null then round(p_valor*v_parc_tot,2) else null end;
  end if;
  if v_tag is not null then
    select * into v_best from ml_pedidos p where upper(regexp_replace(p.seller_nome,'[^a-zA-Z0-9]','','g')) like v_tag||'%'
     order by (case when p_valor is not null and round(p.valor_total,2)=round(p_valor,2) then 0 else 1 end),
              (case when p_data is not null then abs(p.data_pedido-p_data) else 999 end) limit 1;
    if found then v_conf := case when p_valor is not null and round(v_best.valor_total,2)=round(p_valor,2) then 'alta' else 'media_vendedor' end; end if;
  end if;
  if v_conf is null and p_valor is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) and (p_data is null or abs(p.data_pedido-p_data)<=2);
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) and (p_data is null or abs(p.data_pedido-p_data)<=2) limit 1; v_conf := 'alta_valor_data'; end if;
  end if;
  if v_conf is null and v_valor_full is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=v_valor_full;
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=v_valor_full limit 1; v_conf := 'alta_parcelado'; end if;
  end if;
  if v_conf is null and p_valor is not null then
    select count(*) into v_n from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2);
    if v_n=1 then select * into v_best from ml_pedidos p where round(p.valor_total,2)=round(p_valor,2) limit 1; v_conf := 'media_valor'; end if;
  end if;
  if v_conf is null then return jsonb_build_object('apelido_extraido',v_tag,'total_candidatos',0,'produto',null,'plano_provavel',null); end if;
  v_prod := v_best.produto_titulo; v_plano_cat := v_best.plano_sugerido; v_cluster := v_best.cluster;
  v_texto_norm := public.maria_cartoes_normalizar_texto(coalesce(v_prod,'')||' '||coalesce(p_texto,''));
  select p.codigo, p.nome into v_regra from public.maria_classificacao_regras r join public.plano_contas p on p.id=r.plano_conta_id
   where r.ativo and r.escopo in ('cartao','geral') and r.plano_conta_id is not null and position(r.palavra_chave in v_texto_norm)>0
   order by r.prioridade desc, r.confianca_base desc limit 1;
  if found then v_cod:=v_regra.codigo; v_nome:=v_regra.nome; v_origem:='regra';
  elsif v_plano_cat is not null then v_cod:=v_plano_cat; v_origem:='categoria';
    select nome into v_nome from public.plano_contas where codigo=v_plano_cat and nivel=3 and natureza='saida' limit 1; end if;
  return jsonb_build_object('apelido_extraido',v_tag,'total_candidatos',1,
    'produto', jsonb_build_object('produto_titulo',v_best.produto_titulo,'seller_nome',v_best.seller_nome,'valor_total',v_best.valor_total,
       'data_pedido',v_best.data_pedido,'order_id',v_best.order_id,'status',v_best.status,'confianca',v_conf,'cluster',v_best.cluster,'category_path',v_best.category_path),
    'plano_provavel', case when v_cod is not null then jsonb_build_object('codigo',v_cod,'nome',v_nome,'origem',v_origem,'categoria',v_cluster,'confianca_match',v_conf) else null end);
end $$;


