CREATE OR REPLACE FUNCTION "public"."maria_snapshot_assert_correction_target_v31"("p_corrigido_de_snapshot_id" "uuid", "p_chat_id" "text", "p_data_referencia" "date", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_target public.maria_whatsapp_daily_snapshots%rowtype;
begin
  if p_corrigido_de_snapshot_id is null then
    return;
  end if;

  if p_status <> 'finalizado' then
    raise exception 'correcao so pode ser registrada como snapshot finalizado';
  end if;

  select *
    into v_target
  from public.maria_whatsapp_daily_snapshots
  where id = p_corrigido_de_snapshot_id;

  if not found then
    raise exception 'snapshot alvo de correcao nao existe';
  end if;

  if v_target.chat_id <> p_chat_id or v_target.data_referencia <> p_data_referencia then
    raise exception 'snapshot alvo de correcao pertence a outro chat ou data';
  end if;

  if v_target.status <> 'finalizado' then
    raise exception 'snapshot alvo de correcao precisa estar finalizado';
  end if;

  -- Como o modelo e append-only e a nova linha ainda nao existe, ciclo direto nao e possivel
  -- se somente a RPC puder inserir. Por isso nao ha check falso de ciclo aqui.
end;
$$;


ALTER FUNCTION "public"."maria_snapshot_assert_correction_target_v31"("p_corrigido_de_snapshot_id" "uuid", "p_chat_id" "text", "p_data_referencia" "date", "p_status" "text") OWNER TO "postgres";


