CREATE OR REPLACE FUNCTION "public"."maria_snapshot_has_forbidden_key"("p_value" "jsonb", "p_forbidden" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with recursive walk(value, key_name) as (
    select p_value, null::text
    union all
    select child.value, child.key_name
    from walk w
    cross join lateral (
      select e.key as key_name, e.value
      from jsonb_each(
        case when jsonb_typeof(w.value) = 'object' then w.value else '{}'::jsonb end
      ) e
      union all
      select null::text as key_name, a.value
      from jsonb_array_elements(
        case when jsonb_typeof(w.value) = 'array' then w.value else '[]'::jsonb end
      ) a
    ) child
  )
  select exists (
    select 1
    from walk
    where key_name = any(p_forbidden)
  );
$$;


ALTER FUNCTION "public"."maria_snapshot_has_forbidden_key"("p_value" "jsonb", "p_forbidden" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_snapshot_normalize_payload_v31"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_payload jsonb;
begin
  v_payload := public.maria_snapshot_sanitize_jsonb(p_payload);

  v_payload := v_payload
    || jsonb_build_object('tags_assunto', public.maria_snapshot_sort_strings(coalesce(v_payload->'tags_assunto', '[]'::jsonb)))
    || jsonb_build_object('referencias_mensagens', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'referencias_mensagens', '[]'::jsonb), array['chat_id','message_id','data_hora']))
    || jsonb_build_object('referencias_entidades', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'referencias_entidades', '[]'::jsonb), array['tipo','referencia_id']))
    || jsonb_build_object('fontes', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'fontes', '[]'::jsonb), array['tipo','referencia_id','consultado_em']))
    || jsonb_build_object('decisoes', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'decisoes', '[]'::jsonb), array['ordem_origem','titulo']))
    || jsonb_build_object('pendencias', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'pendencias', '[]'::jsonb), array['ordem_origem','titulo']))
    || jsonb_build_object('aprendizados', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'aprendizados', '[]'::jsonb), array['ordem_origem','titulo']))
    || jsonb_build_object('fatos_confirmados', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'fatos_confirmados', '[]'::jsonb), array['ordem_origem','titulo']))
    || jsonb_build_object('incertezas', public.maria_snapshot_sort_array_by_keys(coalesce(v_payload->'incertezas', '[]'::jsonb), array['ordem_origem','titulo']));

  return v_payload;
end;
$$;


ALTER FUNCTION "public"."maria_snapshot_normalize_payload_v31"("p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_snapshot_object_keys_allowed"("p_item" "jsonb", "p_allowed" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_typeof(p_item) = 'object', false)
    and not exists (
      select 1
      from jsonb_object_keys(
        case when jsonb_typeof(p_item) = 'object' then p_item else '{}'::jsonb end
      ) k
      where not (k = any(p_allowed))
    );
$$;


ALTER FUNCTION "public"."maria_snapshot_object_keys_allowed"("p_item" "jsonb", "p_allowed" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_snapshot_sanitize_jsonb"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_result jsonb;
  v_item jsonb;
  v_key text;
  v_val jsonb;
begin
  if p_value is null then
    return 'null'::jsonb;
  end if;

  case jsonb_typeof(p_value)
    when 'string' then
      return to_jsonb(public.maria_agent_memory_sanitize_text(p_value #>> '{}'));
    when 'array' then
      v_result := '[]'::jsonb;
      for v_item in select value from jsonb_array_elements(p_value)
      loop
        v_result := v_result || jsonb_build_array(public.maria_snapshot_sanitize_jsonb(v_item));
      end loop;
      return v_result;
    when 'object' then
      v_result := '{}'::jsonb;
      for v_key, v_val in select key, value from jsonb_each(p_value)
      loop
        v_result := v_result || jsonb_build_object(v_key, public.maria_snapshot_sanitize_jsonb(v_val));
      end loop;
      return v_result;
    else
      return p_value;
  end case;
end;
$$;


ALTER FUNCTION "public"."maria_snapshot_sanitize_jsonb"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_snapshot_sort_array_by_keys"("p_items" "jsonb", "p_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_sql text;
  v_result jsonb;
begin
  v_sql := (
    select string_agg(format('coalesce(item.value->>%L, '''')', key), ', ')
    from unnest(p_keys) key
  );

  execute format(
    'select coalesce(jsonb_agg(item.value order by %s, item.value::text), ''[]''::jsonb)
       from jsonb_array_elements(coalesce($1, ''[]''::jsonb)) item(value)',
    v_sql
  )
  into v_result
  using p_items;

  return v_result;
end;
$_$;


ALTER FUNCTION "public"."maria_snapshot_sort_array_by_keys"("p_items" "jsonb", "p_keys" "text"[]) OWNER TO "postgres";


