CREATE OR REPLACE FUNCTION "public"."maria_snapshot_validate_fontes"("p_items" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_typeof(p_items) = 'array', false)
    and jsonb_array_length(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) <= 120
    and not exists (
      select 1
      from jsonb_array_elements(
        case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end
      ) item
      where jsonb_typeof(item) <> 'object'
         or not public.maria_snapshot_object_keys_allowed(
           item,
           array['tipo','referencia_id','consultado_em','resumo_curto','confianca','exige_consulta_canonica']
         )
         or not coalesce(item->>'tipo' in ('mensagem','conta','fluxo_caixa','email','cartao','outro'), false)
         or not public.maria_snapshot_text_len_ok(item->>'referencia_id', 1, 160)
         or not public.maria_snapshot_text_len_ok(item->>'consultado_em', 10, 80)
         or not public.maria_snapshot_confidence_ok(item->>'confianca')
         or jsonb_typeof(item->'exige_consulta_canonica') is distinct from 'boolean'
         or coalesce(length(item->>'resumo_curto'), 0) > 300
    );
$$;


