CREATE OR REPLACE FUNCTION "public"."maria_snapshot_validate_payload_v31"("p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_allowed_root text[] := array[
    'chat_id','data_referencia','tipo_de_snapshot','status','corrigido_de_snapshot_id',
    'idempotency_key','resumo_operacional','decisoes','pendencias','aprendizados',
    'fatos_confirmados','incertezas','tags_assunto','referencias_mensagens',
    'referencias_entidades','fontes','gerado_por','modelo_resumo'
  ];
  v_forbidden text[] := array[
    'organizacao_id','dominio_operacional','janela_inicio','janela_fim',
    'conteudo_hash','source_fingerprint','sanitizado',
    'responsavel_sugerido','prazo_sugerido'
  ];
begin
  if jsonb_typeof(p_payload) is distinct from 'object' then
    raise exception 'payload deve ser objeto JSON';
  end if;

  if public.maria_snapshot_has_forbidden_key(p_payload, v_forbidden) then
    raise exception 'payload contem chave proibida';
  end if;

  if not public.maria_snapshot_object_keys_allowed(p_payload, v_allowed_root) then
    raise exception 'payload contem chave raiz desconhecida';
  end if;

  if not public.maria_snapshot_text_len_ok(p_payload->>'chat_id', 1, 120) then
    raise exception 'chat_id invalido';
  end if;

  if not coalesce((p_payload->>'data_referencia') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$', false) then
    raise exception 'data_referencia invalida';
  end if;

  if coalesce(p_payload->>'tipo_de_snapshot', 'grupo') <> 'grupo' then
    raise exception 'tipo_de_snapshot invalido';
  end if;

  if not coalesce(p_payload->>'status' in ('rascunho', 'finalizado', 'invalidado'), false) then
    raise exception 'status invalido';
  end if;

  if not public.maria_snapshot_text_len_ok(p_payload->>'idempotency_key', 8, 200) then
    raise exception 'idempotency_key invalida';
  end if;

  if not public.maria_snapshot_text_len_ok(p_payload->>'resumo_operacional', 1, 4000) then
    raise exception 'resumo_operacional invalido';
  end if;

  if not public.maria_snapshot_text_len_ok(p_payload->>'gerado_por', 1, 120) then
    raise exception 'gerado_por invalido';
  end if;

  if not public.maria_snapshot_validate_tags(coalesce(p_payload->'tags_assunto', '[]'::jsonb)) then
    raise exception 'tags_assunto invalidas';
  end if;

  if not public.maria_snapshot_validate_fontes(coalesce(p_payload->'fontes', '[]'::jsonb)) then
    raise exception 'fontes invalidas';
  end if;

  if not public.maria_snapshot_validate_referencias_mensagens(coalesce(p_payload->'referencias_mensagens', '[]'::jsonb)) then
    raise exception 'referencias_mensagens invalidas';
  end if;

  if not public.maria_snapshot_validate_referencias_entidades(coalesce(p_payload->'referencias_entidades', '[]'::jsonb)) then
    raise exception 'referencias_entidades invalidas';
  end if;

  if not public.maria_snapshot_validate_simple_items(
    coalesce(p_payload->'decisoes', '[]'::jsonb),
    25,
    array['titulo','resumo','confianca','ordem_origem','fontes_ref'],
    false
  ) then
    raise exception 'decisoes invalidas';
  end if;

  if not public.maria_snapshot_validate_pendencias(coalesce(p_payload->'pendencias', '[]'::jsonb)) then
    raise exception 'pendencias invalidas';
  end if;

  if not public.maria_snapshot_validate_simple_items(
    coalesce(p_payload->'aprendizados', '[]'::jsonb),
    25,
    array['titulo','resumo','confianca','ordem_origem','fontes_ref'],
    false
  ) then
    raise exception 'aprendizados invalidos';
  end if;

  if not public.maria_snapshot_validate_simple_items(
    coalesce(p_payload->'fatos_confirmados', '[]'::jsonb),
    60,
    array['titulo','resumo','confianca','exige_consulta_canonica','ordem_origem','fontes_ref'],
    true
  ) then
    raise exception 'fatos_confirmados invalidos';
  end if;

  if not public.maria_snapshot_validate_simple_items(
    coalesce(p_payload->'incertezas', '[]'::jsonb),
    40,
    array['titulo','resumo','confianca','exige_consulta_canonica','ordem_origem','fontes_ref'],
    true
  ) then
    raise exception 'incertezas invalidas';
  end if;
end;
$_$;


