CREATE OR REPLACE FUNCTION "public"."maria_snapshot_validate_pendencias"("p_items" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(jsonb_typeof(p_items) = 'array', false)
    and jsonb_array_length(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) <= 40
    and not exists (
      select 1
      from jsonb_array_elements(
        case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end
      ) item
      where jsonb_typeof(item) <> 'object'
         or not public.maria_snapshot_object_keys_allowed(
           item,
           array[
             'titulo','descricao','responsavel_declarado','prazo_declarado',
             'pendencia_sem_responsavel','pendencia_sem_prazo','confianca',
             'ordem_origem','fontes_ref'
           ]
         )
         or not public.maria_snapshot_text_len_ok(item->>'titulo', 1, 180)
         or not public.maria_snapshot_text_len_ok(item->>'descricao', 1, 1000)
         or not public.maria_snapshot_confidence_ok(item->>'confianca')
         or jsonb_typeof(item->'pendencia_sem_responsavel') is distinct from 'boolean'
         or jsonb_typeof(item->'pendencia_sem_prazo') is distinct from 'boolean'
         or coalesce(length(item->>'responsavel_declarado'), 0) > 120
         or coalesce(length(item->>'prazo_declarado'), 0) > 80
         or (item ? 'ordem_origem' and jsonb_typeof(item->'ordem_origem') <> 'number')
         or (item ? 'fontes_ref' and not public.maria_snapshot_validate_ref_strings(item->'fontes_ref'))
    );
$$;


ALTER FUNCTION "public"."maria_snapshot_validate_pendencias"("p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_snapshot_validate_ref_strings"("p_items" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select coalesce(jsonb_typeof(p_items) = 'array', false)
    and jsonb_array_length(case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end) <= 120
    and not exists (
      select 1
      from jsonb_array_elements(
        case when jsonb_typeof(p_items) = 'array' then p_items else '[]'::jsonb end
      ) item
      where jsonb_typeof(item) <> 'string'
         or (item #>> '{}') !~ '^[a-z_]+:[A-Za-z0-9._:@/+-]{1,180}$'
    );
$_$;


