CREATE OR REPLACE FUNCTION "public"."maria_superfolha_professores_custo_catalogo"("p_ano" integer, "p_mes" integer) RETURNS TABLE("colaborador_id" integer, "nome" "text", "nome_completo" "text", "departamento" "text", "funcao" "text", "is_rateado" boolean, "ativo" boolean, "unidade" "text", "custo_aula_mes" numeric, "flag_dual_papel" boolean, "custo_staff_mes" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with professores as (
    select
      c.id,
      c.nome,
      c.nome_completo,
      c.departamento,
      c.funcao,
      c.is_rateado,
      c.ativo,
      (coalesce(c.departamento,'') <> 'professores') as flag_dual_papel
    from public.colaboradores c
    where c.ativo is true
      and (
        c.departamento = 'professores'
        or c.funcao ilike '%prof%'
      )
  ), custos as (
    select
      lf.colaborador_id,
      lf.unidade,
      coalesce(sum(lf.total) filter (where lf.categoria = 'professores'), 0)::numeric as custo_aula_mes,
      coalesce(sum(lf.total) filter (where lf.categoria <> 'professores' or lf.categoria is null), 0)::numeric as custo_staff_mes
    from public.lancamentos_folha lf
    join public.folhas_mensais fm on fm.id = lf.folha_id
    where fm.ano = p_ano
      and fm.mes = p_mes
    group by lf.colaborador_id, lf.unidade
  )
  select
    p.id as colaborador_id,
    p.nome::text,
    p.nome_completo::text,
    p.departamento::text,
    p.funcao::text,
    p.is_rateado,
    p.ativo,
    c.unidade::text,
    coalesce(c.custo_aula_mes, 0)::numeric as custo_aula_mes,
    p.flag_dual_papel,
    coalesce(c.custo_staff_mes, 0)::numeric as custo_staff_mes
  from professores p
  left join custos c on c.colaborador_id = p.id
  where coalesce(c.custo_aula_mes, 0) <> 0
     or coalesce(c.custo_staff_mes, 0) <> 0
     or c.colaborador_id is null
  order by p.nome, c.unidade nulls last;
$$;


ALTER FUNCTION "public"."maria_superfolha_professores_custo_catalogo"("p_ano" integer, "p_mes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_superfolha_roi_custo_por_la_professor"("p_ano" integer, "p_mes" integer) RETURNS TABLE("la_report_professor_id" integer, "la_report_nome" "text", "superfolha_colaborador_id" integer, "superfolha_nome" "text", "unidade" "text", "unidade_id" "uuid", "custo_aula_mes" numeric, "flag_dual_papel" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    m.la_report_professor_id,
    m.la_report_nome,
    m.superfolha_colaborador_id,
    cat.nome::text as superfolha_nome,
    cat.unidade,
    case lower(trim(cat.unidade))
      when 'cg'  then '2ec861f6-023f-4d7b-9927-3960ad8c2a92'::uuid
      when 'rec' then '95553e96-971b-4590-a6eb-0201d013c14d'::uuid
      when 'bar' then '368d47f5-2d88-4475-bc14-ba084a9a348e'::uuid
      else null
    end as unidade_id,
    cat.custo_aula_mes,
    cat.flag_dual_papel
  from public.maria_professor_financeiro_map m
  join public.maria_superfolha_professores_custo_catalogo(p_ano, p_mes) cat
    on cat.colaborador_id = m.superfolha_colaborador_id
  where m.superfolha_colaborador_id is not null
    and (m.confianca = 'alta' or m.validado_por is not null);
$$;


