COMMENT ON FUNCTION "public"."maria_superfolha_roi_custo_por_la_professor"("p_ano" integer, "p_mes" integer) IS 'Junta mapa professor (LA<->SF) com catalogo de custo. Custo-aula por (la_report_professor_id, unidade_id). Cruzar com MRR do LA Report por (la_report_professor_id, unidade_id) <- UUID canonico, mesmo nos dois bancos. So mapeamentos usaveis. custo_aula_mes=0/ausente => custo nao lancado, nunca ROI infinito.';



CREATE OR REPLACE FUNCTION "public"."maria_vera_concluir"("p_id" "uuid", "p_resultado" "jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  update public.maria_delegacao_jobs
     set status = 'concluido', resultado_json = p_resultado, concluido_em = now()
   where id = p_id;
$$;


