CREATE OR REPLACE FUNCTION "public"."maria_vera_reivindicar_proximo"() RETURNS SETOF "public"."maria_delegacao_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  select id into v_id
    from public.maria_delegacao_jobs
   where status = 'stamped'
   order by criado_em
   limit 1
   for update skip locked;
  if v_id is null then
    return;
  end if;
  update public.maria_delegacao_jobs
     set status = 'processando', reivindicado_em = now()
   where id = v_id;
  return query select * from public.maria_delegacao_jobs where id = v_id;
end $$;


