CREATE OR REPLACE FUNCTION "public"."maria_whatsapp_snapshot_finalizar_v31"("p_snapshot_id" "uuid", "p_finalizacao_idempotency_key" "text", "p_ator_numero" "text", "p_papel" "text", "p_motivo" "text" DEFAULT 'finalizacao manual de snapshot operacional'::"text") RETURNS TABLE("snapshot_id" "uuid", "versao" integer, "status" "text", "finalized" boolean, "reused" boolean, "outcome" "text", "finalizado_em" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_snapshot public.maria_whatsapp_daily_snapshots%rowtype;
  v_registry public.maria_whatsapp_chat_registry%rowtype;
  v_key_hash text;
  v_audit_id uuid;
begin
  if p_snapshot_id is null then
    raise exception 'snapshot_id obrigatorio';
  end if;

  if p_finalizacao_idempotency_key is null
     or length(trim(p_finalizacao_idempotency_key)) < 8
     or length(trim(p_finalizacao_idempotency_key)) > 200 then
    raise exception 'finalizacao_idempotency_key invalida';
  end if;

  v_key_hash := encode(extensions.digest(trim(p_finalizacao_idempotency_key), 'sha256'), 'hex');

  v_actor := public.maria_assert_actor(
    p_ator_numero,
    p_papel,
    array['owner_full','finance_ops_write_safe','finance_assistant_write_safe','strategic_read_prepare','gov_agent_tecnico']
  );

  if p_papel <> 'owner_full' then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      'whatsapp',
      'maria_whatsapp_daily_snapshots',
      'snapshot_operacional_diario',
      p_snapshot_id,
      'finalize_denied',
      null::jsonb,
      jsonb_build_object(
        'snapshot_id', p_snapshot_id,
        'resultado', 'negado',
        'motivo_sanitizado', 'ator_sem_permissao_para_finalizar',
        'papel', p_papel,
        'finalizacao_key_hash', v_key_hash
      ),
      'tentativa de finalizacao negada',
      null::text
    );
    snapshot_id := p_snapshot_id;
    versao := null;
    status := null;
    finalized := false;
    reused := false;
    outcome := 'negado_ator_sem_permissao';
    finalizado_em := null;
    return next;
    return;
  end if;

  select *
    into v_snapshot
  from public.maria_whatsapp_daily_snapshots
  where id = p_snapshot_id
  for update;

  if not found then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      'whatsapp',
      'maria_whatsapp_daily_snapshots',
      'snapshot_operacional_diario',
      p_snapshot_id,
      'finalize_failed',
      null::jsonb,
      jsonb_build_object(
        'snapshot_id', p_snapshot_id,
        'resultado', 'falha',
        'motivo_sanitizado', 'snapshot_nao_encontrado',
        'finalizacao_key_hash', v_key_hash
      ),
      'tentativa de finalizacao falhou',
      null::text
    );
    snapshot_id := p_snapshot_id;
    versao := null;
    status := null;
    finalized := false;
    reused := false;
    outcome := 'snapshot_nao_encontrado';
    finalizado_em := null;
    return next;
    return;
  end if;

  select *
    into v_registry
  from public.maria_whatsapp_chat_registry
  where chat_id = v_snapshot.chat_id
    and organizacao_id = v_snapshot.organizacao_id
    and dominio_operacional = v_snapshot.dominio_operacional
    and ativo is true;

  if not found then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      'whatsapp',
      'maria_whatsapp_daily_snapshots',
      'snapshot_operacional_diario',
      v_snapshot.id,
      'finalize_denied',
      null::jsonb,
      jsonb_build_object(
        'snapshot_id', v_snapshot.id,
        'chat_id', v_snapshot.chat_id,
        'data_referencia', v_snapshot.data_referencia,
        'versao', v_snapshot.versao,
        'resultado', 'negado',
        'motivo_sanitizado', 'chat_inativo_ou_fora_do_registry',
        'finalizacao_key_hash', v_key_hash
      ),
      'tentativa de finalizacao negada',
      null::text
    );
    snapshot_id := v_snapshot.id;
    versao := v_snapshot.versao;
    status := v_snapshot.status;
    finalized := false;
    reused := false;
    outcome := 'chat_inativo_ou_fora_do_registry';
    finalizado_em := v_snapshot.finalizado_em;
    return next;
    return;
  end if;

  if v_snapshot.status = 'finalizado' then
    snapshot_id := v_snapshot.id;
    versao := v_snapshot.versao;
    status := v_snapshot.status;
    finalized := false;
    reused := true;
    outcome := case
      when v_snapshot.finalizacao_idempotency_key = trim(p_finalizacao_idempotency_key)
        then 'finalizacao_reutilizada'
      else 'ja_finalizado'
    end;
    finalizado_em := v_snapshot.finalizado_em;
    return next;
    return;
  end if;

  if v_snapshot.status <> 'rascunho' then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      'whatsapp',
      'maria_whatsapp_daily_snapshots',
      'snapshot_operacional_diario',
      v_snapshot.id,
      'finalize_denied',
      jsonb_build_object(
        'snapshot_id', v_snapshot.id,
        'status', v_snapshot.status
      ),
      jsonb_build_object(
        'snapshot_id', v_snapshot.id,
        'resultado', 'negado',
        'motivo_sanitizado', 'status_nao_finalizavel',
        'status_atual', v_snapshot.status,
        'finalizacao_key_hash', v_key_hash
      ),
      'tentativa de finalizacao negada',
      null::text
    );
    snapshot_id := v_snapshot.id;
    versao := v_snapshot.versao;
    status := v_snapshot.status;
    finalized := false;
    reused := false;
    outcome := 'status_nao_finalizavel';
    finalizado_em := v_snapshot.finalizado_em;
    return next;
    return;
  end if;

  if v_snapshot.idempotency_key = trim(p_finalizacao_idempotency_key) then
    perform public.maria_audit_insert(
      v_actor,
      p_ator_numero,
      'whatsapp',
      'maria_whatsapp_daily_snapshots',
      'snapshot_operacional_diario',
      v_snapshot.id,
      'finalize_denied',
      null::jsonb,
      jsonb_build_object(
        'snapshot_id', v_snapshot.id,
        'chat_id', v_snapshot.chat_id,
        'data_referencia', v_snapshot.data_referencia,
        'versao', v_snapshot.versao,
        'resultado', 'negado',
        'motivo_sanitizado', 'finalizacao_sem_idempotencia_propria',
        'finalizacao_key_hash', v_key_hash
      ),
      'tentativa de finalizacao negada',
      null::text
    );
    snapshot_id := v_snapshot.id;
    versao := v_snapshot.versao;
    status := v_snapshot.status;
    finalized := false;
    reused := false;
    outcome := 'finalizacao_sem_idempotencia_propria';
    finalizado_em := v_snapshot.finalizado_em;
    return next;
    return;
  end if;

  update public.maria_whatsapp_daily_snapshots s
     set status = 'finalizado',
         finalizado_em = now(),
         finalizacao_idempotency_key = trim(p_finalizacao_idempotency_key)
   where s.id = v_snapshot.id
     and s.status = 'rascunho'
  returning s.id, s.versao, s.status, s.finalizado_em
    into snapshot_id, versao, status, finalizado_em;

  if not found then
    raise exception 'snapshot nao finalizado por estado concorrente';
  end if;

  v_audit_id := public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    'whatsapp',
    'maria_whatsapp_daily_snapshots',
    'snapshot_operacional_diario',
    snapshot_id,
    'finalize',
    jsonb_build_object(
      'snapshot_id', snapshot_id,
      'status', 'rascunho',
      'versao', versao
    ),
    jsonb_build_object(
      'snapshot_id', snapshot_id,
      'organizacao_id', v_snapshot.organizacao_id,
      'chat_id', v_snapshot.chat_id,
      'data_referencia', v_snapshot.data_referencia,
      'versao', versao,
      'status', status,
      'resultado', 'finalizado',
      'finalizado_em', finalizado_em,
      'finalizacao_key_hash', v_key_hash,
      'conteudo_hash', v_snapshot.conteudo_hash,
      'source_fingerprint', v_snapshot.source_fingerprint
    ),
    p_motivo,
    null::text
  );

  if v_audit_id is null then
    raise exception 'audit de finalizacao nao gravado';
  end if;

  finalized := true;
  reused := false;
  outcome := 'finalizado';
  return next;
end;
$$;


ALTER FUNCTION "public"."maria_whatsapp_snapshot_finalizar_v31"("p_snapshot_id" "uuid", "p_finalizacao_idempotency_key" "text", "p_ator_numero" "text", "p_papel" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."maria_whatsapp_daily_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organizacao_id" "text" NOT NULL,
    "chat_id" "text" NOT NULL,
    "dominio_operacional" "text" NOT NULL,
    "tipo_de_snapshot" "text" DEFAULT 'grupo'::"text" NOT NULL,
    "data_referencia" "date" NOT NULL,
    "janela_inicio" timestamp with time zone NOT NULL,
    "janela_fim" timestamp with time zone NOT NULL,
    "versao" integer NOT NULL,
    "status" "text" NOT NULL,
    "corrigido_de_snapshot_id" "uuid",
    "idempotency_key" "text" NOT NULL,
    "conteudo_hash" "text" NOT NULL,
    "source_fingerprint" "text" NOT NULL,
    "resumo_operacional" "text" NOT NULL,
    "decisoes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "pendencias" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "aprendizados" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "fatos_confirmados" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "incertezas" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "tags_assunto" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "referencias_mensagens" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "referencias_entidades" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "fontes" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "gerado_por" "text" NOT NULL,
    "modelo_resumo" "text",
    "criado_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalizado_em" timestamp with time zone,
    "finalizacao_idempotency_key" "text",
    CONSTRAINT "maria_whatsapp_daily_snapshots_hash_chk" CHECK (("conteudo_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "maria_whatsapp_daily_snapshots_idem_chk" CHECK ((("length"(TRIM(BOTH FROM "idempotency_key")) >= 8) AND ("length"(TRIM(BOTH FROM "idempotency_key")) <= 200))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_janela_duracao_chk" CHECK (("janela_fim" <= ("janela_inicio" + '24:00:00'::interval))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_janela_ordem_chk" CHECK (("janela_fim" > "janela_inicio")),
    CONSTRAINT "maria_whatsapp_daily_snapshots_json_arrays_chk" CHECK ((("jsonb_typeof"("decisoes") = 'array'::"text") AND ("jsonb_typeof"("pendencias") = 'array'::"text") AND ("jsonb_typeof"("aprendizados") = 'array'::"text") AND ("jsonb_typeof"("fatos_confirmados") = 'array'::"text") AND ("jsonb_typeof"("incertezas") = 'array'::"text") AND ("jsonb_typeof"("tags_assunto") = 'array'::"text") AND ("jsonb_typeof"("referencias_mensagens") = 'array'::"text") AND ("jsonb_typeof"("referencias_entidades") = 'array'::"text") AND ("jsonb_typeof"("fontes") = 'array'::"text"))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_json_len_chk" CHECK ((("jsonb_array_length"("decisoes") <= 25) AND ("jsonb_array_length"("pendencias") <= 40) AND ("jsonb_array_length"("aprendizados") <= 25) AND ("jsonb_array_length"("fatos_confirmados") <= 60) AND ("jsonb_array_length"("incertezas") <= 40) AND ("jsonb_array_length"("tags_assunto") <= 30) AND ("jsonb_array_length"("referencias_mensagens") <= 120) AND ("jsonb_array_length"("referencias_entidades") <= 120) AND ("jsonb_array_length"("fontes") <= 120))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_resumo_chk" CHECK ((("length"(TRIM(BOTH FROM "resumo_operacional")) >= 1) AND ("length"(TRIM(BOTH FROM "resumo_operacional")) <= 4000))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_source_fp_chk" CHECK (("source_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "maria_whatsapp_daily_snapshots_status_chk" CHECK (("status" = ANY (ARRAY['rascunho'::"text", 'finalizado'::"text", 'invalidado'::"text"]))),
    CONSTRAINT "maria_whatsapp_daily_snapshots_tipo_chk" CHECK (("tipo_de_snapshot" = 'grupo'::"text")),
    CONSTRAINT "maria_whatsapp_daily_snapshots_versao_chk" CHECK (("versao" > 0))
);


ALTER TABLE "public"."maria_whatsapp_daily_snapshots" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_whatsapp_snapshot_historico_v31"("p_chat_id" "text", "p_data_referencia" "date", "p_ator_numero" "text", "p_papel" "text") RETURNS SETOF "public"."maria_whatsapp_daily_snapshots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
begin
  v_actor := public.maria_assert_actor(
    p_ator_numero,
    p_papel,
    array['owner_full','strategic_read_prepare']
  );

  -- Escopo organizacao/chat nao existe em maria_assert_actor hoje; EXECUTE deve ficar no backend privado Maria.

  if nullif(trim(p_chat_id), '') is null then
    raise exception 'chat_id obrigatorio';
  end if;

  if p_data_referencia is null then
    raise exception 'data_referencia obrigatoria';
  end if;

  if not exists (
    select 1
    from public.maria_whatsapp_chat_registry r
    where r.chat_id = p_chat_id
      and r.ativo is true
  ) then
    raise exception 'chat_id nao cadastrado ou inativo';
  end if;

  return query
  select s.*
  from public.maria_whatsapp_daily_snapshots s
  where s.chat_id = p_chat_id
    and s.data_referencia = p_data_referencia
  order by s.versao desc;
end;
$$;


ALTER FUNCTION "public"."maria_whatsapp_snapshot_historico_v31"("p_chat_id" "text", "p_data_referencia" "date", "p_ator_numero" "text", "p_papel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_whatsapp_snapshot_registrar_v31"("p_payload" "jsonb", "p_ator_numero" "text", "p_papel" "text", "p_motivo" "text" DEFAULT 'snapshot operacional diario'::"text") RETURNS TABLE("snapshot_id" "uuid", "versao" integer, "status" "text", "reused" boolean, "conteudo_hash" "text", "source_fingerprint" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
  v_chat public.maria_whatsapp_chat_registry%rowtype;
  v_payload jsonb;
  v_hash_payload jsonb;
  v_data date;
  v_janela_inicio timestamptz;
  v_janela_fim timestamptz;
  v_status text;
  v_conteudo_hash text;
  v_source_fingerprint text;
  v_existing public.maria_whatsapp_daily_snapshots%rowtype;
  v_next_version integer;
  v_corrigido uuid;
  v_lock_key bigint;
begin
  v_actor := public.maria_assert_actor(
    p_ator_numero,
    p_papel,
    array['owner_full','finance_ops_write_safe','finance_assistant_write_safe','strategic_read_prepare','gov_agent_tecnico']
  );
  perform public.maria_snapshot_validate_payload_v31(p_payload);

  v_data := (p_payload->>'data_referencia')::date;
  v_status := p_payload->>'status';
  v_corrigido := nullif(p_payload->>'corrigido_de_snapshot_id', '')::uuid;

  select *
    into v_chat
  from public.maria_whatsapp_chat_registry
  where chat_id = p_payload->>'chat_id'
    and ativo is true;

  if not found then
    raise exception 'chat_id nao cadastrado ou inativo no registry';
  end if;

  -- Confirmado em 2026-08-11: maria_assert_actor valida numero + papel + allowlist,
  -- mas nao valida organizacao/chat. V1 deve restringir EXECUTE ao role privado do backend Maria.

  v_lock_key := hashtextextended(v_chat.chat_id || ':' || v_data::text, 421102);
  perform pg_advisory_xact_lock(v_lock_key);

  select janela_inicio, janela_fim
    into v_janela_inicio, v_janela_fim
  from public.maria_snapshot_day_bounds_brt(v_data);

  v_payload := public.maria_snapshot_normalize_payload_v31(p_payload);
  v_payload := v_payload - 'chat_id' - 'data_referencia' - 'corrigido_de_snapshot_id';

  perform public.maria_snapshot_assert_correction_target_v31(
    v_corrigido,
    v_chat.chat_id,
    v_data,
    v_status
  );

  v_hash_payload := v_payload
    - 'idempotency_key'
    - 'gerado_por'
    - 'modelo_resumo';

  v_conteudo_hash := encode(extensions.digest(v_hash_payload::text, 'sha256'), 'hex');
  v_source_fingerprint := encode(
    extensions.digest(
      jsonb_build_object(
        'fontes', coalesce(v_payload->'fontes', '[]'::jsonb),
        'referencias_mensagens', coalesce(v_payload->'referencias_mensagens', '[]'::jsonb),
        'referencias_entidades', coalesce(v_payload->'referencias_entidades', '[]'::jsonb)
      )::text,
      'sha256'
    ),
    'hex'
  );

  select *
    into v_existing
  from public.maria_whatsapp_daily_snapshots s
  where s.chat_id = v_chat.chat_id
    and s.data_referencia = v_data
    and s.idempotency_key = p_payload->>'idempotency_key';

  if found then
    return query select
      v_existing.id,
      v_existing.versao,
      v_existing.status,
      true,
      v_existing.conteudo_hash,
      v_existing.source_fingerprint;
    return;
  end if;

  select *
    into v_existing
  from public.maria_whatsapp_daily_snapshots s
  where s.chat_id = v_chat.chat_id
    and s.data_referencia = v_data
    and s.conteudo_hash = v_conteudo_hash
    and s.source_fingerprint = v_source_fingerprint
  order by s.versao desc
  limit 1;

  if found and v_corrigido is null then
    return query select
      v_existing.id,
      v_existing.versao,
      v_existing.status,
      true,
      v_existing.conteudo_hash,
      v_existing.source_fingerprint;
    return;
  end if;

  select coalesce(max(s.versao), 0) + 1
    into v_next_version
  from public.maria_whatsapp_daily_snapshots s
  where s.chat_id = v_chat.chat_id
    and s.data_referencia = v_data;

  insert into public.maria_whatsapp_daily_snapshots (
    organizacao_id,
    chat_id,
    dominio_operacional,
    tipo_de_snapshot,
    data_referencia,
    janela_inicio,
    janela_fim,
    versao,
    status,
    corrigido_de_snapshot_id,
    idempotency_key,
    conteudo_hash,
    source_fingerprint,
    resumo_operacional,
    decisoes,
    pendencias,
    aprendizados,
    fatos_confirmados,
    incertezas,
    tags_assunto,
    referencias_mensagens,
    referencias_entidades,
    fontes,
    gerado_por,
    modelo_resumo
  ) values (
    v_chat.organizacao_id,
    v_chat.chat_id,
    v_chat.dominio_operacional,
    'grupo',
    v_data,
    v_janela_inicio,
    v_janela_fim,
    v_next_version,
    v_status,
    v_corrigido,
    p_payload->>'idempotency_key',
    v_conteudo_hash,
    v_source_fingerprint,
    v_payload->>'resumo_operacional',
    coalesce(v_payload->'decisoes', '[]'::jsonb),
    coalesce(v_payload->'pendencias', '[]'::jsonb),
    coalesce(v_payload->'aprendizados', '[]'::jsonb),
    coalesce(v_payload->'fatos_confirmados', '[]'::jsonb),
    coalesce(v_payload->'incertezas', '[]'::jsonb),
    coalesce(v_payload->'tags_assunto', '[]'::jsonb),
    coalesce(v_payload->'referencias_mensagens', '[]'::jsonb),
    coalesce(v_payload->'referencias_entidades', '[]'::jsonb),
    coalesce(v_payload->'fontes', '[]'::jsonb),
    p_payload->>'gerado_por',
    nullif(p_payload->>'modelo_resumo', '')
  )
  returning id, maria_whatsapp_daily_snapshots.versao, maria_whatsapp_daily_snapshots.status,
            maria_whatsapp_daily_snapshots.conteudo_hash, maria_whatsapp_daily_snapshots.source_fingerprint
    into snapshot_id, versao, status, conteudo_hash, source_fingerprint;

  perform public.maria_audit_insert(
    v_actor,
    p_ator_numero,
    'whatsapp',
    'maria_whatsapp_daily_snapshots',
    'snapshot_operacional_diario',
    snapshot_id,
    'insert',
    null::jsonb,
    jsonb_build_object(
      'snapshot_id', snapshot_id,
      'organizacao_id', v_chat.organizacao_id,
      'chat_id', v_chat.chat_id,
      'dominio_operacional', v_chat.dominio_operacional,
      'data_referencia', v_data,
      'versao', versao,
      'status', status,
      'conteudo_hash', conteudo_hash,
      'source_fingerprint', source_fingerprint,
      'qtd_decisoes', jsonb_array_length(coalesce(v_payload->'decisoes', '[]'::jsonb)),
      'qtd_pendencias', jsonb_array_length(coalesce(v_payload->'pendencias', '[]'::jsonb)),
      'qtd_fontes', jsonb_array_length(coalesce(v_payload->'fontes', '[]'::jsonb))
    ),
    p_motivo,
    null::text
  );

  reused := false;
  return next;
end;
$$;


ALTER FUNCTION "public"."maria_whatsapp_snapshot_registrar_v31"("p_payload" "jsonb", "p_ator_numero" "text", "p_papel" "text", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_whatsapp_snapshot_ultimo_v31"("p_chat_id" "text", "p_ator_numero" "text", "p_papel" "text") RETURNS SETOF "public"."maria_whatsapp_daily_snapshots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
begin
  v_actor := public.maria_assert_actor(
    p_ator_numero,
    p_papel,
    array['owner_full','finance_ops_write_safe','finance_assistant_write_safe','strategic_read_prepare']
  );
  -- Escopo organizacao/chat nao existe em maria_assert_actor hoje; EXECUTE deve ficar no backend privado Maria.

  if nullif(trim(p_chat_id), '') is null then
    raise exception 'chat_id obrigatorio';
  end if;

  if not exists (
    select 1
    from public.maria_whatsapp_chat_registry r
    where r.chat_id = p_chat_id
      and r.ativo is true
  ) then
    raise exception 'chat_id nao cadastrado ou inativo';
  end if;

  return query
  select s.*
  from public.maria_whatsapp_daily_snapshots s
  join public.maria_whatsapp_chat_registry r on r.chat_id = s.chat_id
  where s.chat_id = p_chat_id
    and r.ativo is true
    and s.status = 'finalizado'
  order by s.data_referencia desc, s.versao desc
  limit 1;
end;
$$;


ALTER FUNCTION "public"."maria_whatsapp_snapshot_ultimo_v31"("p_chat_id" "text", "p_ator_numero" "text", "p_papel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maria_whatsapp_snapshots_periodo_todos_v31"("p_organizacao_id" "text", "p_data_inicio" "date", "p_data_fim" "date", "p_ator_numero" "text", "p_papel" "text") RETURNS SETOF "public"."maria_whatsapp_daily_snapshots"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor public.maria_whatsapp_atores%rowtype;
begin
  v_actor := public.maria_assert_actor(
    p_ator_numero, p_papel,
    array['owner_full','finance_ops_write_safe','finance_assistant_write_safe','strategic_read_prepare']
  );
  if nullif(trim(p_organizacao_id), '') is null then raise exception 'organizacao_id obrigatorio'; end if;
  if p_data_inicio is null or p_data_fim is null then raise exception 'periodo obrigatorio'; end if;
  if p_data_inicio > p_data_fim then raise exception 'periodo invalido: data_inicio posterior a data_fim'; end if;
  if not exists (
    select 1 from public.maria_whatsapp_chat_registry r
    where r.organizacao_id = p_organizacao_id and r.ativo is true and r.pode_entrar_em_relatorio_consolidado is true
  ) then raise exception 'organizacao_id sem chats ativos elegiveis para consolidado'; end if;

  return query
  with ranked as (
    select s, row_number() over (partition by s.chat_id, s.data_referencia order by s.versao desc) as rn
    from public.maria_whatsapp_daily_snapshots s
    join public.maria_whatsapp_chat_registry r on r.chat_id = s.chat_id
    where s.organizacao_id = p_organizacao_id
      and s.data_referencia between p_data_inicio and p_data_fim
      and r.ativo is true
      and r.pode_entrar_em_relatorio_consolidado is true
  )
  select (ranked.s).* from ranked where rn = 1
  order by (ranked.s).data_referencia, (ranked.s).chat_id;
end;
$$;


ALTER FUNCTION "public"."maria_whatsapp_snapshots_periodo_todos_v31"("p_organizacao_id" "text", "p_data_inicio" "date", "p_data_fim" "date", "p_ator_numero" "text", "p_papel" "text") OWNER TO "postgres";


