  );
  -- Escopo organizacao nao existe em maria_assert_actor hoje; EXECUTE deve ficar no backend privado Maria.

  if nullif(trim(p_organizacao_id), '') is null then
    raise exception 'organizacao_id obrigatorio';
  end if;

  if p_data_inicio is null or p_data_fim is null then
    raise exception 'periodo obrigatorio';
  end if;

  if p_data_inicio > p_data_fim then
    raise exception 'periodo invalido: data_inicio posterior a data_fim';
  end if;

  if not exists (
    select 1
    from public.maria_whatsapp_chat_registry r
    where r.organizacao_id = p_organizacao_id
      and r.ativo is true
      and r.pode_entrar_em_relatorio_consolidado is true
  ) then
    raise exception 'organizacao_id sem chats ativos elegiveis para consolidado';
  end if;

  return query
  with ranked as (
    select
      s,
      row_number() over (
        partition by s.chat_id, s.data_referencia
        order by s.versao desc
      ) as rn
    from public.maria_whatsapp_daily_snapshots s
    join public.maria_whatsapp_chat_registry r on r.chat_id = s.chat_id
    where s.organizacao_id = p_organizacao_id
      and s.data_referencia between p_data_inicio and p_data_fim
      and s.status = 'finalizado'
      and r.ativo is true
      and r.pode_entrar_em_relatorio_consolidado is true
  )
  select (ranked.s).*
  from ranked
  where rn = 1
  order by (ranked.s).data_referencia, (ranked.s).chat_id;
