CREATE OR REPLACE FUNCTION "public"."recalc_folha_totais"("p_folha_id" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE folhas_mensais f
  SET
    total_cg = COALESCE((SELECT SUM(total) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'cg'), 0),
    total_rec = COALESCE((SELECT SUM(total) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'rec'), 0),
    total_bar = COALESCE((SELECT SUM(total) FROM lancamentos_folha WHERE folha_id = p_folha_id AND unidade = 'bar'), 0),
    total_geral = COALESCE((SELECT SUM(total) FROM lancamentos_folha WHERE folha_id = p_folha_id), 0),
    updated_at = now()
  WHERE f.id = p_folha_id;
END;
$$;


ALTER FUNCTION "public"."recalc_folha_totais"("p_folha_id" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rh_agenda_excluir_espelho_removido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_table_name = 'rh_processos' then
    delete from public.tarefas
    where vinculo_tipo = 'rh_processo'
      and vinculo_id = old.id;
  elsif tg_table_name = 'rh_processo_etapas' then
    delete from public.tarefas
    where vinculo_tipo = 'rh_etapa'
      and vinculo_id = old.id;
  end if;
  return old;
end;
$$;


