CREATE OR REPLACE FUNCTION "public"."rh_storage_process_id"("p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_match text;
begin
  v_match := substring(coalesce(p_name, '') from '^processos/([0-9a-fA-F-]{36})/');
  if v_match is null then
    return null;
  end if;
  return v_match::uuid;
exception
  when others then
    return null;
end;
$$;


