CREATE OR REPLACE FUNCTION "public"."set_vault_secret"("secret_name" "text", "secret_value" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'vault'
    AS $$
declare
  existing_id uuid;
  new_id uuid;
begin
  if secret_name is null or trim(secret_name) = '' then
    raise exception 'secret_name is required';
  end if;
  if secret_value is null or secret_value = '' then
    raise exception 'secret_value is required';
  end if;

  select id into existing_id
  from vault.secrets
  where name = secret_name
  limit 1;

  if existing_id is not null then
    perform vault.update_secret(existing_id, secret_value, secret_name);
    return existing_id;
  end if;

  select vault.create_secret(secret_value, secret_name) into new_id;
  return new_id;
end;
$$;


ALTER FUNCTION "public"."set_vault_secret"("secret_name" "text", "secret_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tarefas_guard_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if exists (
    select 1 from public.tarefas
     where parent_id = old.id and status in ('pendente', 'em_andamento', 'adiada')
  ) then
    raise exception 'pai com filha ativa nao pode ser excluido.' using errcode = 'P0001';
  end if;
  return old;
end $$;


ALTER FUNCTION "public"."tarefas_guard_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tarefas_guard_parent"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare v_pai_parent uuid;
begin
  if new.parent_id is null then return new; end if;
  if new.parent_id = new.id then
    raise exception 'tarefa nao pode ser pai de si mesma.' using errcode = 'P0001';
  end if;
  select parent_id into v_pai_parent from public.tarefas where id = new.parent_id;
  if not found then
    raise exception 'pai nao encontrado.' using errcode = 'P0001';
  end if;
  if v_pai_parent is not null then
    raise exception 'profundidade maxima 1: filha nao pode ter filha.' using errcode = 'P0001';
  end if;
  if exists (select 1 from public.tarefas where parent_id = new.id) then
    raise exception 'profundidade maxima 1: tarefa com filhas nao pode virar filha.' using errcode = 'P0001';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."tarefas_guard_parent"() OWNER TO "postgres";


