CREATE OR REPLACE FUNCTION "public"."update_ferias_periodos_before_write"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  NEW.esta_vencido = (NEW.concessivo_fim < CURRENT_DATE AND (NEW.dias_direito - NEW.dias_gozados - NEW.dias_vendidos) > 0);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_ferias_periodos_before_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_periodo_aquisitivo_saldos"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Quando criar ou atualizar programação, recalcular saldos do período
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF NEW.status NOT IN ('cancelado') THEN
      UPDATE public.ferias_periodos_aquisitivos
      SET
        dias_gozados = (
          SELECT COALESCE(SUM(dias_corridos), 0)
          FROM public.ferias_programacoes
          WHERE periodo_aquisitivo_id = NEW.periodo_aquisitivo_id
            AND status NOT IN ('cancelado')
            AND vendeu_abono = FALSE
        ),
        dias_vendidos = (
          SELECT COALESCE(SUM(dias_abono), 0)
          FROM public.ferias_programacoes
          WHERE periodo_aquisitivo_id = NEW.periodo_aquisitivo_id
            AND status NOT IN ('cancelado')
            AND vendeu_abono = TRUE
        )
      WHERE id = NEW.periodo_aquisitivo_id;
    END IF;
  END IF;

  -- Quando deletar ou cancelar, recalcular
  IF TG_OP = 'DELETE' OR (TG_OP = 'UPDATE' AND NEW.status = 'cancelado') THEN
    UPDATE public.ferias_periodos_aquisitivos
    SET
      dias_gozados = (
        SELECT COALESCE(SUM(dias_corridos), 0)
        FROM public.ferias_programacoes
        WHERE periodo_aquisitivo_id = COALESCE(NEW.periodo_aquisitivo_id, OLD.periodo_aquisitivo_id)
          AND status NOT IN ('cancelado')
          AND id != COALESCE(NEW.id, OLD.id)
          AND vendeu_abono = FALSE
      ),
      dias_vendidos = (
        SELECT COALESCE(SUM(dias_abono), 0)
        FROM public.ferias_programacoes
        WHERE periodo_aquisitivo_id = COALESCE(NEW.periodo_aquisitivo_id, OLD.periodo_aquisitivo_id)
          AND status NOT IN ('cancelado')
          AND id != COALESCE(NEW.id, OLD.id)
          AND vendeu_abono = TRUE
      )
    WHERE id = COALESCE(NEW.periodo_aquisitivo_id, OLD.periodo_aquisitivo_id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_periodo_aquisitivo_saldos"() OWNER TO "postgres";


