CREATE TABLE IF NOT EXISTS "public"."contas_pagar" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "descricao" "text" NOT NULL,
    "unidade" "text",
    "valor" numeric(12,2) NOT NULL,
    "data_lancamento" "date" DEFAULT CURRENT_DATE NOT NULL,
    "data_vencimento" "date" NOT NULL,
    "competencia" "date" NOT NULL,
    "status" "text" DEFAULT 'pendente'::"text" NOT NULL,
    "data_pagamento" timestamp with time zone,
    "metodo_pagamento" "text",
    "tipo_lancamento" "text" DEFAULT 'unica'::"text",
    "parcela_atual" integer,
    "total_parcelas" integer,
    "observacoes" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid",
    "recorrente_modelo_id" "uuid",
    "fonte_tipo" "text",
    "fonte_url" "text",
    "fonte_instrucoes" "text",
    "fonte_identificador" "text",
    "credencial_id" "uuid",
    "pix_chave_fixa" "text",
    "email_pagamento" "text",
    "plano_conta_id" "uuid",
    "centro_custo_id" "uuid",
    "emusys_lancamento_id" "text",
    "parcelamento_id" "uuid",
    "empresa_id" "uuid",
    "conta_pagadora_id" "uuid",
    "recorrente_frequencia" "text" DEFAULT 'mensal'::"text" NOT NULL,
    "debito_automatico" boolean DEFAULT false NOT NULL,
    CONSTRAINT "contas_pagar_fonte_tipo_check" CHECK ((("fonte_tipo" IS NULL) OR ("fonte_tipo" = ANY (ARRAY['site'::"text", 'email'::"text", 'pix_fixo'::"text", 'banco'::"text", 'whatsapp'::"text", 'manual'::"text", 'cartao'::"text", 'folha_pagamento'::"text"])))),
    CONSTRAINT "contas_pagar_recorrente_frequencia_check" CHECK (("recorrente_frequencia" = ANY (ARRAY['mensal'::"text", 'semanal'::"text"]))),
    CONSTRAINT "contas_pagar_status_check" CHECK (("status" = ANY (ARRAY['pendente'::"text", 'pago'::"text", 'cancelado'::"text", 'finalizado'::"text"]))),
    CONSTRAINT "contas_pagar_tipo_lancamento_check" CHECK (("tipo_lancamento" = ANY (ARRAY['unica'::"text", 'recorrente'::"text", 'parcelada'::"text", 'eventual'::"text", 'fatura_cartao'::"text", 'folha_pagamento'::"text"]))),
    CONSTRAINT "contas_pagar_unidade_check" CHECK (("unidade" = ANY (ARRAY['cg'::"text", 'rec'::"text", 'bar'::"text", 'todas'::"text"]))),
