    "funcao_usada" "text" NOT NULL,
    "unidade_usada" "text" NOT NULL,
    "conta_pagadora_id_usada" "uuid",
    "componente" "text" NOT NULL,
    "tipo_efeito" "text" NOT NULL,
    "valor_original" numeric NOT NULL,
    "valor_assinado" numeric NOT NULL,
    "plano_conta_id" "uuid",
    "plano_codigo_usado" "text",
    "plano_nome_usado" "text",
    "tratamento" "text" NOT NULL,
    "escopo_dre" "text" NOT NULL,
    "regra_id" "uuid",
    "ruleset_version" integer NOT NULL,
    "motivo" "text" NOT NULL,
    "bistro_competencia_id" "uuid",
    "bistro_ref_ym" "text" NOT NULL,
    "classificado_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "classificado_por" "text" NOT NULL,
    "hash_origem" "text" NOT NULL,
    CONSTRAINT "folha_classificacao_dre_bistro_ref_ym_check" CHECK (("bistro_ref_ym" ~ '^\d{4}-\d{2}$'::"text")),
    CONSTRAINT "folha_classificacao_dre_componente_check" CHECK (("componente" = ANY (ARRAY['salario'::"text", 'bonus'::"text", 'comissao'::"text", 'passagem'::"text", 'reembolso'::"text", 'inss'::"text", 'descontos'::"text"]))),
    CONSTRAINT "folha_classificacao_dre_escopo_dre_check" CHECK (("escopo_dre" = ANY (ARRAY['operacional'::"text", 'fora_operacional'::"text", 'nenhum'::"text"]))),
    CONSTRAINT "folha_classificacao_dre_sequencia_check" CHECK (("sequencia" > 0)),
    CONSTRAINT "folha_classificacao_dre_tipo_efeito_check" CHECK (("tipo_efeito" = ANY (ARRAY['provento'::"text", 'deducao'::"text", 'liquidacao'::"text", 'excluido'::"text"]))),
    CONSTRAINT "folha_classificacao_dre_tratamento_check" CHECK (("tratamento" = ANY (ARRAY['automatico'::"text", 'excluido'::"text", 'liquidacao'::"text", 'pendente'::"text"])))
);


