COMMENT ON COLUMN "public"."notificacao_config"."ferias_alerta_aquisitivo_prox" IS 'Alertar quando período aquisitivo próximo de completar';



COMMENT ON COLUMN "public"."notificacao_config"."ferias_alerta_concessivo_critico" IS 'Alertar quando período concessivo próximo de vencer';



COMMENT ON COLUMN "public"."notificacao_config"."ferias_alerta_vencimento_multa" IS 'Alertar férias vencidas (CRÍTICO - multa em dobro)';



COMMENT ON COLUMN "public"."notificacao_config"."ferias_resumo_mensal_ativo" IS 'Enviar resumo mensal de situação de férias';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_processos_ativo" IS 'Ativa lembrete automatico para processos da Jornada RH espelhados na Agenda';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_processos_minutos" IS 'Antecedencia em minutos para lembretes de processos RH na Agenda';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_etapas_ativo" IS 'Ativa lembrete automatico para etapas da Jornada RH espelhadas na Agenda';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_etapas_minutos" IS 'Antecedencia em minutos para lembretes de etapas RH na Agenda';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_pdi_ativo" IS 'Ativa lembrete automatico para checkpoints de PDI espelhados na Agenda';



COMMENT ON COLUMN "public"."notificacao_config"."rh_agenda_lembrete_pdi_minutos" IS 'Antecedencia em minutos para lembretes de checkpoints de PDI na Agenda';



CREATE TABLE IF NOT EXISTS "public"."plano_contas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "codigo" "text" NOT NULL,
    "nome" "text" NOT NULL,
    "nome_completo" "text" NOT NULL,
    "parent_id" "uuid",
    "nivel" integer NOT NULL,
    "grupo_plano" "text",
    "natureza" "text" NOT NULL,
    "label_educativo" "text",
    "inclui_ebitda" boolean DEFAULT false NOT NULL,
    "inclui_margem" boolean DEFAULT false NOT NULL,
    "inclui_capex" boolean DEFAULT false NOT NULL,
    "emusys_id" "text",
    "ativo" boolean DEFAULT true NOT NULL,
    "ordem" integer,
    "icone" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tipo_custo" "text",
    CONSTRAINT "plano_contas_grupo_plano_check" CHECK ((("grupo_plano" IS NULL) OR ("grupo_plano" = ANY (ARRAY['receita'::"text", 'custo_variavel'::"text", 'despesa_fixa'::"text", 'investimento'::"text", 'nao_operacional'::"text"])))),
    CONSTRAINT "plano_contas_natureza_check" CHECK (("natureza" = ANY (ARRAY['entrada'::"text", 'saida'::"text"]))),
    CONSTRAINT "plano_contas_nivel_check" CHECK (("nivel" = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT "plano_contas_tipo_custo_chk" CHECK ((("tipo_custo" IS NULL) OR ("tipo_custo" = ANY (ARRAY['fixo'::"text", 'variavel'::"text"]))))
);


ALTER TABLE "public"."plano_contas" OWNER TO "postgres";


