    CONSTRAINT "rh_avaliacoes_tipo_check" CHECK (("tipo" = ANY (ARRAY['entrevista'::"text", 'aula_teste'::"text", 'feedback_7d'::"text", 'feedback_30d'::"text", 'feedback_45d'::"text", 'feedback_90d'::"text", 'entrevista_saida'::"text"])))
);


ALTER TABLE "public"."rh_avaliacoes" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."rh_candidatos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nome" "text" NOT NULL,
    "email" "text",
    "telefone" "text",
    "cpf" "text",
    "cargo_pretendido" "text",
    "tipo_vinculo_pretendido" "text",
    "origem" "text",
    "status" "text" NOT NULL,
    "questionario_resumo" "text",
    "questionario_respostas" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "curriculo_storage_path" "text",
    "curriculo_texto_extraido" "text",
    "observacoes" "text",
    "aprovado_em" timestamp with time zone,
    "reprovado_em" timestamp with time zone,
    "colaborador_convertido_id" integer,
    "arquivado_em" timestamp with time zone,
    "arquivado_por" "uuid",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ficha_token" "text",
    "la_colaborador_id" integer,
    "ficha_importada_em" timestamp with time zone,
    "perguntas_entrevista" "jsonb",
    "perguntas_geradas_em" timestamp with time zone,
    "ficha_snapshot_hash" "text",
    "perguntas_desatualizadas" boolean DEFAULT false NOT NULL,
    "unidade" "text",
    "ficha_link" "text",
    "ficha_link_gerado_em" timestamp with time zone,
    CONSTRAINT "chk_rh_candidatos_unidade" CHECK ((("unidade" IS NULL) OR ("unidade" = ANY (ARRAY['bar'::"text", 'cg'::"text", 'rec'::"text"])))),
    CONSTRAINT "rh_candidatos_status_check" CHECK (("status" = ANY (ARRAY['novo'::"text", 'questionario_pendente'::"text", 'questionario_recebido'::"text", 'entrevista'::"text", 'aula_teste'::"text", 'aprovado'::"text", 'reprovado'::"text", 'arquivado'::"text"])))
);


ALTER TABLE "public"."rh_candidatos" OWNER TO "postgres";


COMMENT ON COLUMN "public"."rh_candidatos"."ficha_token" IS 'Token da Ficha Tecnica no LA Report. Fonte da verdade e la; aqui e so o ponteiro.';



COMMENT ON COLUMN "public"."rh_candidatos"."ficha_importada_em" IS 'Quando o retrato da ficha foi trazido para questionario_respostas. Reimportar atualiza.';



COMMENT ON COLUMN "public"."rh_candidatos"."perguntas_entrevista" IS 'Roteiro de perguntas gerado a partir da Ficha Tecnica. Insumo de conversa, nao criterio de aprovacao.';



COMMENT ON COLUMN "public"."rh_candidatos"."ficha_snapshot_hash" IS 'SHA-256 do snapshot canônico recebido do LA Report.';



COMMENT ON COLUMN "public"."rh_candidatos"."perguntas_desatualizadas" IS 'Roteiro preservado, mas gerado antes da última mudança da Ficha Técnica.';



COMMENT ON COLUMN "public"."rh_candidatos"."unidade" IS 'Codigo canonico: bar, cg, rec. A Edge Function traduz para Barra, Campo Grande e Recreio.';



COMMENT ON COLUMN "public"."rh_candidatos"."ficha_link" IS 'Link completo da Ficha Tecnica. Credencial de acesso — nao registrar em log nem em mensagem de erro.';



