CREATE OR REPLACE VIEW "public"."v_ferias_colaboradores_status" WITH ("security_invoker"='true') AS
 WITH "periodos_agregados" AS (
         SELECT "pa_1"."colaborador_id",
            "count"("pa_1"."id") FILTER (WHERE ("pa_1"."status" = 'ativo'::"text")) AS "periodos_ativos",
            "count"("pa_1"."id") FILTER (WHERE ("pa_1"."status" = 'vencido'::"text")) AS "periodos_vencidos",
            "sum"("pa_1"."dias_saldo") FILTER (WHERE ("pa_1"."status" = ANY (ARRAY['ativo'::"text", 'em_gozo'::"text"]))) AS "total_dias_saldo",
            "bool_or"("pa_1"."esta_vencido") AS "tem_ferias_vencidas",
            "min"("pa_1"."concessivo_fim") FILTER (WHERE (("pa_1"."status" = 'ativo'::"text") AND ("pa_1"."dias_saldo" > 0))) AS "proxima_expiracao"
           FROM "public"."ferias_periodos_aquisitivos" "pa_1"
          GROUP BY "pa_1"."colaborador_id"
        ), "programacoes_agregadas" AS (
         SELECT "fp_1"."colaborador_id",
            "count"("fp_1"."id") FILTER (WHERE ("fp_1"."status" = ANY (ARRAY['programado'::"text", 'aprovado'::"text"]))) AS "ferias_programadas",
            "min"("fp_1"."data_inicio") FILTER (WHERE (("fp_1"."status" = ANY (ARRAY['programado'::"text", 'aprovado'::"text"])) AND ("fp_1"."data_inicio" >= CURRENT_DATE))) AS "proximas_ferias_inicio"
           FROM "public"."ferias_programacoes" "fp_1"
          GROUP BY "fp_1"."colaborador_id"
        )
 SELECT "c"."id" AS "colaborador_id",
    "c"."nome",
    "c"."nome_completo",
    "c"."foto_url",
    "c"."funcao",
    "c"."departamento",
    "c"."data_admissao",
    "c"."status" AS "colaborador_status",
    "c"."salario_base",
    COALESCE("pa"."periodos_ativos", (0)::bigint) AS "periodos_ativos",
    COALESCE("pa"."periodos_vencidos", (0)::bigint) AS "periodos_vencidos",
    "pa"."total_dias_saldo",
    "pa"."tem_ferias_vencidas",
    "pa"."proxima_expiracao",
    COALESCE("fp"."ferias_programadas", (0)::bigint) AS "ferias_programadas",
    "fp"."proximas_ferias_inicio",
        CASE
            WHEN "pa"."tem_ferias_vencidas" THEN 'critico'::"text"
            WHEN ("pa"."proxima_expiracao" < (CURRENT_DATE + '30 days'::interval)) THEN 'alerta'::"text"
            WHEN ("pa"."proxima_expiracao" < (CURRENT_DATE + '60 days'::interval)) THEN 'atencao'::"text"
            ELSE 'ok'::"text"
        END AS "status_ferias"
   FROM (("public"."colaboradores" "c"
     LEFT JOIN "periodos_agregados" "pa" ON (("pa"."colaborador_id" = "c"."id")))
     LEFT JOIN "programacoes_agregadas" "fp" ON (("fp"."colaborador_id" = "c"."id")))
  WHERE ((("c"."tipo")::"text" = 'clt'::"text") AND ("c"."status" = 'active'::"text"));


ALTER VIEW "public"."v_ferias_colaboradores_status" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_ferias_colaboradores_status" IS 'Status consolidado de ferias por colaborador CLT ativo, sem fanout entre periodos e programacoes';



CREATE OR REPLACE VIEW "public"."v_rh_alertas_criticos" WITH ("security_invoker"='true') AS
 SELECT "pe"."id" AS "etapa_id",
    "pe"."processo_id",
    "p"."tipo" AS "processo_tipo",
    "p"."titulo" AS "processo_titulo",
    "pe"."titulo" AS "etapa_titulo",
    "pe"."status" AS "etapa_status",
    "pe"."data_limite",
        CASE
            WHEN ("pe"."data_limite" IS NULL) THEN NULL::integer
            ELSE ("pe"."data_limite" - CURRENT_DATE)
        END AS "dias_para_vencimento"
   FROM ("public"."rh_processo_etapas" "pe"
     JOIN "public"."rh_processos" "p" ON (("p"."id" = "pe"."processo_id")))
  WHERE (("p"."arquivado_em" IS NULL) AND ("pe"."status" = ANY (ARRAY['nao_iniciada'::"text", 'em_andamento'::"text", 'atrasada'::"text"])) AND ("pe"."data_limite" IS NOT NULL) AND ("pe"."data_limite" <= (CURRENT_DATE + 5)));


