CREATE OR REPLACE VIEW "public"."v_rh_dashboard_kpis" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE (("tipo" = 'recrutamento'::"text") AND ("status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'aguardando_documentos'::"text", 'aguardando_avaliacao'::"text", 'aguardando_aprovacao'::"text"])) AND ("arquivado_em" IS NULL))) AS "recrutamentos_ativos",
    "count"(*) FILTER (WHERE (("tipo" = 'onboarding'::"text") AND ("status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'aguardando_documentos'::"text", 'aguardando_avaliacao'::"text", 'aguardando_aprovacao'::"text"])) AND ("arquivado_em" IS NULL))) AS "onboardings_ativos",
    "count"(*) FILTER (WHERE (("tipo" = 'desligamento'::"text") AND ("status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'aguardando_documentos'::"text", 'aguardando_avaliacao'::"text", 'aguardando_aprovacao'::"text"])) AND ("arquivado_em" IS NULL))) AS "desligamentos_ativos",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."rh_documentos" "d"
             JOIN "public"."rh_processos" "p2" ON (("p2"."id" = "d"."processo_id")))
          WHERE (("p2"."arquivado_em" IS NULL) AND ("d"."status" = ANY (ARRAY['pendente'::"text", 'rejeitado'::"text"])))) AS "documentos_pendentes",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."rh_processo_etapas" "pe"
             JOIN "public"."rh_processos" "p3" ON (("p3"."id" = "pe"."processo_id")))
          WHERE (("p3"."arquivado_em" IS NULL) AND ("pe"."data_limite" IS NOT NULL) AND ("pe"."data_limite" < CURRENT_DATE) AND ("pe"."status" = ANY (ARRAY['nao_iniciada'::"text", 'em_andamento'::"text", 'atrasada'::"text"])))) AS "etapas_atrasadas"
   FROM "public"."rh_processos";


ALTER VIEW "public"."v_rh_dashboard_kpis" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_rh_documentos_pendentes" WITH ("security_invoker"='true') AS
