    "p"."titulo" AS "processo_titulo",
    "d"."tipo_documento",
    "d"."status",
    "d"."obrigatorio",
    "d"."candidato_id",
    "d"."colaborador_id",
    "d"."created_at",
    "d"."updated_at"
   FROM ("public"."rh_documentos" "d"
     JOIN "public"."rh_processos" "p" ON (("p"."id" = "d"."processo_id")))
  WHERE (("p"."arquivado_em" IS NULL) AND ("d"."status" = ANY (ARRAY['pendente'::"text", 'rejeitado'::"text"])));


