CREATE OR REPLACE VIEW "public"."v_rh_pdi_dashboard_kpis" WITH ("security_invoker"='true') AS
 SELECT "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'em_revisao'::"text"]))) AS "pdis_ativos",
    "count"(*) FILTER (WHERE ("status" = 'concluido'::"text")) AS "pdis_concluidos",
    ( SELECT "count"(*) AS "count"
           FROM ("public"."rh_pdi_checkpoints" "cp"
             JOIN "public"."rh_pdi_planos" "p" ON (("p"."id" = "cp"."plano_id")))
          WHERE (("cp"."status" = ANY (ARRAY['agendado'::"text", 'atrasado'::"text"])) AND ("cp"."data_prevista" < CURRENT_DATE) AND ("p"."status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'em_revisao'::"text"])))) AS "checkpoints_atrasados",
    ( SELECT "count"(*) AS "count"
           FROM "public"."rh_colaborador_conquistas"
          WHERE ("rh_colaborador_conquistas"."concedida_em" >= (CURRENT_DATE - 30))) AS "conquistas_mes"
   FROM "public"."rh_pdi_planos";


ALTER VIEW "public"."v_rh_pdi_dashboard_kpis" OWNER TO "postgres";


