CREATE OR REPLACE VIEW "public"."vw_financeiro_documentos_conta_pagar" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "documento_id",
    "d"."vinculo_id" AS "conta_pagar_id",
    "c"."descricao" AS "conta_descricao",
    "c"."unidade",
    "c"."valor" AS "conta_valor",
    "c"."data_vencimento",
    "c"."competencia",
    "d"."tipo",
    "d"."origem",
    "d"."status_documento",
    "d"."nome_arquivo",
    "d"."mime_type",
    "d"."tamanho_bytes",
    "d"."created_at",
    "d"."rejeitado_em",
    "d"."rejeitado_por",
    "d"."rejeitado_motivo",
        CASE
            WHEN ("d"."hash" IS NULL) THEN NULL::"text"
            WHEN ("length"("d"."hash") <= 12) THEN "d"."hash"
            ELSE ("left"("d"."hash", 12) || '…'::"text")
        END AS "hash_parcial",
    "d"."storage_ref" AS "storage_path",
    ("d"."metadata" ->> 'mensagem_origem_id'::"text") AS "mensagem_origem_id",
    ("d"."metadata" ->> 'canal_origem'::"text") AS "canal_origem",
    ("d"."metadata" ->> 'chat_id'::"text") AS "chat_id",
    ("d"."metadata" ->> 'enviado_por'::"text") AS "enviado_por",
    ("d"."metadata" ->> 'confirmado_por'::"text") AS "confirmado_por",
    COALESCE((("d"."metadata" ->> 'pagamento_executado_pela_maria'::"text"))::boolean, false) AS "pagamento_executado_pela_maria"
   FROM ("public"."financeiro_documentos" "d"
     LEFT JOIN "public"."contas_pagar" "c" ON (("c"."id" = "d"."vinculo_id")))
  WHERE ("d"."vinculo_tipo" = 'conta_pagar'::"text");


ALTER VIEW "public"."vw_financeiro_documentos_conta_pagar" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_financeiro_documentos_conta_pagar" IS 'Listagem sanitizada de comprovantes financeiros vinculados a contas_pagar. storage_path é para createSignedUrl, não para exibição.';



CREATE OR REPLACE VIEW "public"."vw_folha_dre_analitico" WITH ("security_invoker"='true') AS
 SELECT "folha_id",
    "lancamento_folha_id",
    "sequencia",
    "colaborador_id",
    "competencia",
    "categoria_usada",
    "tipo_usado",
    "funcao_usada",
    "unidade_usada",
    "conta_pagadora_id_usada",
    "componente",
    "tipo_efeito",
    "valor_original",
    "valor_assinado",
    "plano_conta_id",
    "plano_codigo_usado",
    "plano_nome_usado",
    "tratamento",
    "escopo_dre",
    "regra_id",
    "ruleset_version",
    "motivo",
    "bistro_competencia_id",
    "bistro_ref_ym",
    "classificado_em",
    "classificado_por",
    "hash_origem",
        CASE
            WHEN ("escopo_dre" = 'operacional'::"text") THEN "valor_assinado"
            ELSE (0)::numeric
        END AS "valor_dre_operacional",
        CASE
            WHEN ("escopo_dre" = 'fora_operacional'::"text") THEN "valor_assinado"
            ELSE (0)::numeric
        END AS "valor_dre_fora_operacional",
        CASE
            WHEN ("tipo_efeito" = 'liquidacao'::"text") THEN "valor_original"
            ELSE (0)::numeric
        END AS "valor_liquidacao",
        CASE
            WHEN ("tipo_efeito" = 'excluido'::"text") THEN "valor_original"
            ELSE (0)::numeric
        END AS "valor_excluido"
   FROM "public"."folha_classificacao_dre" "s";


ALTER VIEW "public"."vw_folha_dre_analitico" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_folha_dre_analitico" IS 'Snapshot analitico da folha. A unidade representa a conta pagadora (visao de caixa), nao a lotacao gerencial.';



