CREATE OR REPLACE VIEW "public"."vw_maria_conferencias_pendentes_lancamento" AS
 WITH "ultima_por_grupo" AS (
         SELECT DISTINCT ON ("maria_conferencias_lancamento"."chat_id", "maria_conferencias_lancamento"."titulo") "maria_conferencias_lancamento"."id",
            "maria_conferencias_lancamento"."chat_id",
            "maria_conferencias_lancamento"."titulo",
            "maria_conferencias_lancamento"."status",
            "maria_conferencias_lancamento"."versao",
            "maria_conferencias_lancamento"."aprovado_por_nome",
            "maria_conferencias_lancamento"."aprovado_at",
            "maria_conferencias_lancamento"."created_at"
           FROM "public"."maria_conferencias_lancamento"
          ORDER BY "maria_conferencias_lancamento"."chat_id", "maria_conferencias_lancamento"."titulo", "maria_conferencias_lancamento"."created_at" DESC
        )
 SELECT "id" AS "conferencia_id",
    "chat_id",
    "titulo",
    "status",
    "aprovado_por_nome",
    "aprovado_at",
    "created_at",
    ( SELECT "count"(*) AS "count"
           FROM "public"."maria_conferencia_lancamento_itens" "i"
          WHERE ("i"."conferencia_id" = "u"."id")) AS "n_itens",
    ( SELECT "sum"(COALESCE("i"."valor_centavos", 0)) AS "sum"
           FROM "public"."maria_conferencia_lancamento_itens" "i"
          WHERE ("i"."conferencia_id" = "u"."id")) AS "valor_total_centavos"
   FROM "ultima_por_grupo" "u"
  WHERE ("status" = 'aprovada'::"text");


ALTER VIEW "public"."vw_maria_conferencias_pendentes_lancamento" OWNER TO "postgres";


