CREATE OR REPLACE VIEW "public"."vw_maria_email_pendencias_resumo" AS
 SELECT ("count"(*))::integer AS "total",
    ("count"(*) FILTER (WHERE ("received_at" < ("now"() - '48:00:00'::interval))))::integer AS "ha_mais_de_48h",
    ("count"(*) FILTER (WHERE ("status" = 'pendente_dado'::"text")))::integer AS "pendente_dado",
    ("count"(*) FILTER (WHERE ("status" = 'extraido'::"text")))::integer AS "extraido",
    ("min"("received_at"))::"date" AS "mais_antigo",
    ("max"("received_at"))::"date" AS "mais_recente"
   FROM "public"."vw_maria_email_pendencias";


ALTER VIEW "public"."vw_maria_email_pendencias_resumo" OWNER TO "postgres";


