CREATE OR REPLACE VIEW "public"."vw_maria_openfinance_cartoes_resumo" AS
 SELECT "fe"."label_operacional",
    "fc"."apelido" AS "cartao",
    "fc"."final",
    "fc"."bandeira",
    "fcs"."limite",
    "fcs"."disponivel",
    "fcs"."usado",
    "fcs"."vencimento",
    "fcs"."pagamento_minimo",
    "fcs"."data_referencia",
    "fcs"."capturado_em"
   FROM (("public"."financeiro_cartao_saldos_diarios" "fcs"
     JOIN "public"."financeiro_cartoes" "fc" ON (("fc"."id" = "fcs"."cartao_id")))
     JOIN "public"."financeiro_empresas" "fe" ON (("fe"."id" = "fc"."empresa_id")))
  WHERE ("fcs"."data_referencia" = CURRENT_DATE);


ALTER VIEW "public"."vw_maria_openfinance_cartoes_resumo" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_maria_openfinance_cartoes_resumo" IS 'Snapshot de hoje por cartão (limite/disponível/usado/vencimento/mínimo), sanitizado para maria_leitura. Fonte: financeiro_cartao_saldos_diarios (sem expor payload bruto).';



CREATE OR REPLACE VIEW "public"."vw_maria_openfinance_saldos_resumo" AS
 SELECT "fe"."label_operacional",
    "fcs"."saldo",
    "fcs"."data_referencia",
    "fcs"."capturado_em"
   FROM (("public"."financeiro_conta_saldos_diarios" "fcs"
     JOIN "public"."financeiro_contas_bancarias" "fcb" ON (("fcb"."id" = "fcs"."conta_bancaria_id")))
     JOIN "public"."financeiro_empresas" "fe" ON (("fe"."id" = "fcb"."empresa_id")))
  WHERE ("fcs"."data_referencia" = ( SELECT "max"("s"."data_referencia") AS "max"
           FROM "public"."financeiro_conta_saldos_diarios" "s"
          WHERE ("s"."data_referencia" <= CURRENT_DATE)));


ALTER VIEW "public"."vw_maria_openfinance_saldos_resumo" OWNER TO "postgres";


COMMENT ON VIEW "public"."vw_maria_openfinance_saldos_resumo" IS 'Saldo de hoje por unidade (label_operacional), sanitizado para a role maria_leitura e outros consumidores restritos. Fonte: financeiro_conta_saldos_diarios.';



CREATE OR REPLACE VIEW "public"."vw_maria_plano_contas" AS
 SELECT "id",
    "codigo",
    "nome",
    "nome_completo",
    "parent_id",
    "parent_codigo",
    "parent_nome",
    "nivel",
    "grupo_plano",
    "natureza",
    "emusys_id",
    "ordem",
    "ativo",
    "linha_formatada"
   FROM "public"."maria_plano_contas_arvore"(true, NULL::"text") "maria_plano_contas_arvore"("id", "codigo", "nome", "nome_completo", "parent_id", "parent_codigo", "parent_nome", "nivel", "grupo_plano", "natureza", "emusys_id", "ordem", "ativo", "linha_formatada");


