CREATE OR REPLACE VIEW "public"."vw_maria_reacao_status_resumo" AS
 SELECT "max"("enviado_em") AS "ultima_reacao_em",
    "count"(*) FILTER (WHERE ("enviado_em" >= ("now"() - '24:00:00'::interval))) AS "reacoes_24h",
    "count"(*) FILTER (WHERE ("enviado_em" >= ("now"() - '7 days'::interval))) AS "reacoes_7d"
   FROM "public"."maria_reacao_eventos";


ALTER VIEW "public"."vw_maria_reacao_status_resumo" OWNER TO "postgres";


