   FROM "public"."contas_pagar_relatorio_dia";


ALTER VIEW "public"."vw_maria_relatorio_dia" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_resumo_unidade" WITH ("security_invoker"='true') AS
 SELECT "fm"."id" AS "folha_id",
    "fm"."ano",
    "fm"."mes",
    "lf"."unidade",
    "lf"."categoria",
    "count"(DISTINCT "lf"."colaborador_id") AS "qtd_colaboradores",
    "sum"("lf"."salario") AS "total_salario",
    "sum"("lf"."bonus") AS "total_bonus",
    "sum"("lf"."comissao") AS "total_comissao",
    "sum"("lf"."passagem") AS "total_passagem",
    "sum"("lf"."reembolso") AS "total_reembolso",
    "sum"("lf"."inss") AS "total_inss",
    "sum"("lf"."descontos") AS "total_descontos",
    "sum"("lf"."total") AS "total_liquido"
   FROM ("public"."folhas_mensais" "fm"
     JOIN "public"."lancamentos_folha" "lf" ON (("lf"."folha_id" = "fm"."id")))
  GROUP BY "fm"."id", "fm"."ano", "fm"."mes", "lf"."unidade", "lf"."categoria"
  ORDER BY "fm"."ano" DESC, "fm"."mes" DESC, "lf"."unidade", "lf"."categoria";


ALTER VIEW "public"."vw_resumo_unidade" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_destinos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "nome" "text" NOT NULL,
    "tipo" "text" DEFAULT 'grupo'::"text" NOT NULL,
    "jid" "text" NOT NULL,
    "finalidade" "text",
    "unidade" "text",
    "ativo" boolean DEFAULT true NOT NULL,
    "observacao" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_destinos_tipo_check" CHECK (("tipo" = ANY (ARRAY['grupo'::"text", 'pessoa'::"text"])))
);


ALTER TABLE "public"."whatsapp_destinos" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_destinos" IS 'Catálogo de destinos de WhatsApp (grupos/pessoas) para envio via whatsapp-send. Maria e o sistema roteiam por finalidade em vez de JID cru.';



CREATE TABLE IF NOT EXISTS "public"."whatsapp_grupo_notificacoes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "destino_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "frequencia" "text" NOT NULL,
    "horario" time without time zone DEFAULT '09:00:00'::time without time zone NOT NULL,
    "dia_semana" smallint,
    "dia_mes" smallint,
    "ativo" boolean DEFAULT false NOT NULL,
    "ultima_execucao" timestamp with time zone,
    "observacao" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_grupo_notificacoes_dia_mes_check" CHECK ((("dia_mes" >= 1) AND ("dia_mes" <= 31))),
    CONSTRAINT "whatsapp_grupo_notificacoes_dia_semana_check" CHECK ((("dia_semana" >= 0) AND ("dia_semana" <= 6))),
    CONSTRAINT "whatsapp_grupo_notificacoes_frequencia_check" CHECK (("frequencia" = ANY (ARRAY['diario'::"text", 'semanal'::"text", 'mensal'::"text"]))),
    CONSTRAINT "whatsapp_grupo_notificacoes_tipo_check" CHECK (("tipo" = ANY (ARRAY['contas_a_pagar_dia'::"text", 'resumo_financeiro_semanal'::"text", 'resumo_financeiro_mensal'::"text"])))
);


ALTER TABLE "public"."whatsapp_grupo_notificacoes" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_grupo_notificacoes" IS 'Agendador de notificacoes por grupo (intencao). O cron le isto pra saber o que disparar; a UI (aba Grupos) edita. horario = hora local America/Sao_Paulo. dia_semana: 0=domingo..6=sabado (convencao Postgres DOW), usado so em semanal. dia_mes: usado so em mensal. ativo NASCE OFF.';



COMMENT ON COLUMN "public"."whatsapp_grupo_notificacoes"."ativo" IS 'Liga/desliga do envio automatico. Nasce false: as meninas seguem gerando/copiando manual ate o relatorio estar 100%.';



