    "j"."etapa_atual",
    "j"."gestor_user_id",
    "j"."mentor_user_id",
    "j"."data_inicio",
    "j"."data_fim",
    "j"."proximo_checkpoint",
    "j"."score_jornada",
    "j"."badges_count",
    COALESCE("count"(DISTINCT "p"."id") FILTER (WHERE ("p"."status" = ANY (ARRAY['rascunho'::"text", 'em_andamento'::"text", 'em_revisao'::"text"]))), (0)::bigint) AS "pdis_ativos",
    COALESCE("count"(DISTINCT "m"."id"), (0)::bigint) AS "marcos_total",
    COALESCE("count"(DISTINCT "q"."id"), (0)::bigint) AS "conquistas_total"
   FROM (((("public"."rh_colaborador_jornadas" "j"
     JOIN "public"."colaboradores" "c" ON (("c"."id" = "j"."colaborador_id")))
     LEFT JOIN "public"."rh_pdi_planos" "p" ON (("p"."jornada_id" = "j"."id")))
     LEFT JOIN "public"."rh_colaborador_marcos" "m" ON (("m"."jornada_id" = "j"."id")))
     LEFT JOIN "public"."rh_colaborador_conquistas" "q" ON (("q"."jornada_id" = "j"."id")))
  GROUP BY "j"."id", "c"."nome", "c"."funcao", "c"."tipo";



CREATE OR REPLACE VIEW "public"."v_rh_processos_resumo" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."tipo",
    "p"."status",
    "p"."titulo",
    "p"."candidato_id",
    "p"."colaborador_id",
    "p"."owner_user_id",
    "p"."mentor_user_id",
    "p"."prioridade",
    "p"."data_inicio",
    "p"."data_fim_prevista",
    "p"."data_fim_real",
    COALESCE("count"("pe"."id"), (0)::bigint) AS "total_etapas",
    COALESCE("count"("pe"."id") FILTER (WHERE ("pe"."status" = 'concluida'::"text")), (0)::bigint) AS "etapas_concluidas",
        CASE
            WHEN ("count"("pe"."id") = 0) THEN (0)::numeric
            ELSE "round"(((("count"("pe"."id") FILTER (WHERE ("pe"."status" = 'concluida'::"text")))::numeric / ("count"("pe"."id"))::numeric) * (100)::numeric), 2)
        END AS "percentual_conclusao"
   FROM ("public"."rh_processos" "p"
     LEFT JOIN "public"."rh_processo_etapas" "pe" ON (("pe"."processo_id" = "p"."id")))
  WHERE ("p"."arquivado_em" IS NULL)
  GROUP BY "p"."id";



CREATE OR REPLACE VIEW "public"."vw_maria_conferencias_lancamento" AS
 SELECT "c"."id" AS "conferencia_id",
    "c"."parent_conferencia_id",
    "c"."chat_id",
    "c"."titulo",
    "c"."status",
    "c"."versao",
    "c"."origem",
    "c"."criado_por_nome",
    "c"."aprovado_por_nome",
    "c"."aprovado_at",
    "c"."created_at",
    "c"."updated_at",
    ("count"("i"."id"))::integer AS "itens_total",
    (COALESCE("sum"("i"."valor_centavos"), (0)::bigint))::integer AS "total_centavos",
    "round"(((COALESCE("sum"("i"."valor_centavos"), (0)::bigint))::numeric / (100)::numeric), 2) AS "total_valor"
   FROM ("public"."maria_conferencias_lancamento" "c"
     LEFT JOIN "public"."maria_conferencia_lancamento_itens" "i" ON (("i"."conferencia_id" = "c"."id")))
  GROUP BY "c"."id";



CREATE OR REPLACE VIEW "public"."vw_maria_email_pendencias" AS
 SELECT "p"."id" AS "email_payable_id",
    "m"."id" AS "message_id",
    "m"."source_key",
    "m"."received_at",
    "public"."maria_email_nome_fornecedor_limpo"("p"."fornecedor_nome") AS "fornecedor_nome",
    "p"."document_kind",
    "p"."vencimento",
    "p"."valor_centavos",
    "p"."status",
    "p"."review_reason",
    "p"."dedupe_group_key",
    "p"."dedupe_group_quality",
    (COALESCE("max"("mt"."match_score"), (0)::numeric))::numeric(5,4) AS "melhor_match_score",
        CASE
            WHEN ("p"."review_reason" = 'possivel_segunda_via'::"text") THEN 100
            WHEN ("p"."status" = ANY (ARRAY['pendente_conferencia'::"text", 'divergente'::"text"])) THEN 90
            WHEN (COALESCE("max"("mt"."match_score"), (0)::numeric) >= 0.85) THEN 70
            ELSE 50
        END AS "prioridade_conferencia"
   FROM (("public"."maria_email_extracted_payables" "p"
     JOIN "public"."maria_email_messages" "m" ON (("m"."id" = "p"."message_id")))
     LEFT JOIN "public"."maria_email_payable_matches" "mt" ON ((("mt"."email_payable_id" = "p"."id") AND ("mt"."match_status" = 'sugerido'::"text"))))
  WHERE (("p"."status" = ANY (ARRAY['extraido'::"text", 'pendente_dado'::"text", 'pendente_conferencia'::"text", 'divergente'::"text"])) AND ("m"."received_at" >= '2026-08-19 03:00:00+00'::timestamp with time zone))
  GROUP BY "p"."id", "m"."id", "m"."source_key", "m"."received_at";



